package com.wikipeek;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Draws one of the game's bitmap fonts pixel for pixel. Glyph data comes from RuneStar's
 * recreation of the game fonts (github.com/RuneStar/fonts, CC0).
 */
class BitmapFont implements CardFont
{
	/**
	 * Matches RuneStar's JSON layout.
	 */
	static class Data
	{
		int ascent;
		int maxDescent;
		List<GlyphData> glyphs;
	}

	static class GlyphData
	{
		int codePoint;
		int topBearing;
		int leftBearing;
		int width;
		int height;
		int advance;
		int[] pixels;
	}

	private final int ascent;
	private final int lineHeight;
	private final Map<Integer, GlyphData> glyphs = new HashMap<>();
	private final GlyphData fallback;
	/**
	 * Glyph images per colour, built on first use. Card text uses only a few colours.
	 */
	private final Map<Integer, Map<Integer, BufferedImage>> coloured = new HashMap<>();

	BitmapFont(Data data, int lineSpacing)
	{
		this.ascent = data.ascent;
		this.lineHeight = data.ascent + lineSpacing;
		for (GlyphData glyph : data.glyphs)
		{
			glyphs.put(glyph.codePoint, glyph);
		}
		// The wiki's ticks and crosses (quest and league tables) are drawn as marks of their
		// own, as the game font has neither
		final GlyphData zero = glyphs.get((int) '0');
		final int h = zero != null && zero.height > 4 ? zero.height : Math.max(6, data.ascent * 2 / 3);
		final int top = zero != null ? zero.topBearing : data.ascent - h;
		final GlyphData tick = mark(0x2713, h, top, true);
		final GlyphData cross = mark(0x2717, h, top, false);
		for (int c : new int[]{0x2713, 0x2714, 0x2705})
		{
			glyphs.put(c, tick);
		}
		for (int c : new int[]{0x2717, 0x2718, 0x2715, 0x2716, 0x274C})
		{
			glyphs.put(c, cross);
		}
		// Anything else the font lacks (a word in another alphabet) is left out rather than
		// shown as question marks
		this.fallback = null;
	}

	private static GlyphData mark(int codePoint, int h, int top, boolean tick)
	{
		final GlyphData g = new GlyphData();
		g.codePoint = codePoint;
		g.width = h + 1;
		g.height = h;
		g.topBearing = top;
		g.leftBearing = 1;
		g.advance = h + 3;
		g.pixels = new int[g.width * g.height];
		if (tick)
		{
			// A short stroke down to the bottom, then a long one up to the top right
			final int knee = g.width / 3;
			line(g, 0, h * 11 / 20, knee, h - 1);
			line(g, knee, h - 1, g.width - 1, 0);
		}
		else
		{
			line(g, 0, 0, g.width - 1, h - 1);
			line(g, 0, h - 1, g.width - 1, 0);
		}
		return g;
	}

	/**
	 * A line two pixels thick into a mark's pixels.
	 */
	private static void line(GlyphData g, int x0, int y0, int x1, int y1)
	{
		final int steps = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0));
		for (int i = 0; i <= steps; i++)
		{
			final int x = x0 + (steps == 0 ? 0 : (x1 - x0) * i / steps);
			final int y = y0 + (steps == 0 ? 0 : (y1 - y0) * i / steps);
			for (int dx = 0; dx < 2; dx++)
			{
				if (x + dx < g.width && y >= 0 && y < g.height)
				{
					g.pixels[y * g.width + x + dx] = 1;
				}
			}
		}
	}

	private GlyphData glyph(char c)
	{
		switch (c)
		{
			// The wiki uses typographic punctuation the game font doesn't have
			case '‘':
			case '’':
				c = '\'';
				break;
			case '“':
			case '”':
				c = '"';
				break;
			case '–':
			case '—':
				c = '-';
				break;
			case ' ':
				c = ' ';
				break;
			default:
				break;
		}
		GlyphData glyph = glyphs.get((int) c);
		return glyph != null ? glyph : fallback;
	}

	@Override
	public int width(String s)
	{
		int w = 0;
		for (int i = 0; i < s.length(); i++)
		{
			GlyphData glyph = glyph(s.charAt(i));
			if (glyph != null)
			{
				w += glyph.advance;
			}
		}
		return w;
	}

	@Override
	public int ascent()
	{
		return ascent;
	}

	@Override
	public int lineHeight()
	{
		return lineHeight;
	}

	@Override
	public int digitMiddle()
	{
		final GlyphData zero = glyphs.get((int) '0');
		return zero == null ? ascent / 3 : ascent - zero.topBearing - zero.height / 2;
	}

	@Override
	public void draw(Graphics2D g, String s, int x, int y, Color colour)
	{
		final int top = y - ascent;
		int pen = x;
		for (int i = 0; i < s.length(); i++)
		{
			GlyphData glyph = glyph(s.charAt(i));
			if (glyph == null)
			{
				continue;
			}
			BufferedImage image = image(glyph, colour);
			if (image != null)
			{
				g.drawImage(image, pen + glyph.leftBearing, top + glyph.topBearing, null);
			}
			pen += glyph.advance;
		}
	}

	private synchronized BufferedImage image(GlyphData glyph, Color colour)
	{
		if (glyph.width <= 0 || glyph.height <= 0 || glyph.pixels == null)
		{
			return null;
		}
		Map<Integer, BufferedImage> byGlyph = coloured.computeIfAbsent(colour.getRGB(), k -> new HashMap<>());
		return byGlyph.computeIfAbsent(glyph.codePoint, k ->
		{
			BufferedImage img = new BufferedImage(glyph.width, glyph.height, BufferedImage.TYPE_INT_ARGB);
			int argb = colour.getRGB();
			for (int i = 0; i < glyph.pixels.length && i < glyph.width * glyph.height; i++)
			{
				if (glyph.pixels[i] == 1)
				{
					img.setRGB(i % glyph.width, i / glyph.width, argb);
				}
			}
			return img;
		});
	}
}

package com.wikipeek;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;

/**
 * A font the card can measure and draw with: either a normal AWT font or the game's
 * bitmap Quill font.
 */
interface CardFont
{
	int width(String s);

	int ascent();

	int lineHeight();

	/**
	 * How far above the baseline the middle of a digit sits, so small pictures beside
	 * numbers (coins) can line up with them.
	 */
	default int digitMiddle()
	{
		return ascent() / 3;
	}

	/**
	 * Draws text with its baseline at y.
	 */
	void draw(Graphics2D g, String s, int x, int y, Color colour);

	static CardFont of(Font font)
	{
		// Measuring needs a Graphics, so borrow one from a 1x1 image
		final BufferedImage scratch = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D sg = scratch.createGraphics();
		final FontMetrics fm = sg.getFontMetrics(font);
		final java.awt.geom.Rectangle2D zero = font.createGlyphVector(sg.getFontRenderContext(), "0").getVisualBounds();
		sg.dispose();
		final int middle = (int) Math.round(-(zero.getY() + zero.getHeight() / 2));

		return new CardFont()
		{
			@Override
			public int width(String s)
			{
				return fm.stringWidth(s);
			}

			@Override
			public int ascent()
			{
				return fm.getAscent();
			}

			@Override
			public int lineHeight()
			{
				return fm.getHeight();
			}

			@Override
			public int digitMiddle()
			{
				return middle;
			}

			@Override
			public void draw(Graphics2D g, String s, int x, int y, Color colour)
			{
				g.setFont(font);
				g.setColor(colour);
				g.drawString(s, x, y);
			}
		};
	}
}

package com.wikipeek;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;

/**
 * Prepares a wiki picture for a card's art window: trims the empty transparent border, then
 * scales it so it fills the window edge to edge. Pictures are only ever scaled down from the
 * large wiki renders, so they stay sharp.
 */
final class CardPicture
{
	/**
	 * Gap between the picture and the window edge, in pixels.
	 */
	static final int PAD = 3;
	/**
	 * How far a standing figure may be enlarged past a full fit, cropping from the bottom, so
	 * the head and upper body fill the window. Objects and items are always shown whole.
	 */
	private static final double TALL_ZOOM = 1.6;
	/**
	 * Height to width ratio from which an NPC counts as a tall standing figure.
	 */
	private static final double TALL_FIGURE = 1.9;
	/**
	 * Small pictures are never enlarged more than this, to avoid blur.
	 */
	private static final double MAX_UPSCALE = 2.0;

	private CardPicture()
	{
	}

	/**
	 * The trimmed picture scaled for a window, and where to draw it relative to the window.
	 * The window should be clipped when drawing, since tall pictures run off the bottom.
	 */
	static final class Fitted
	{
		final BufferedImage image;
		final int x;
		final int y;

		Fitted(BufferedImage image, int x, int y)
		{
			this.image = image;
			this.x = x;
			this.y = y;
		}
	}

	static Fitted fit(BufferedImage source, int windowW, int windowH, boolean figure)
	{
		return fit(source, windowW, windowH, figure, PAD);
	}

	/**
	 * As above, with a chosen border around the picture.
	 */
	static Fitted fit(BufferedImage source, int windowW, int windowH, boolean figure, int pad)
	{
		BufferedImage art = trim(source);
		int w = art.getWidth();
		int h = art.getHeight();
		int boxW = Math.max(1, windowW - pad * 2);
		int boxH = Math.max(1, windowH - pad * 2);

		double fit = Math.min((double) boxW / w, (double) boxH / h);
		double scale = fit;
		// Only tall standing figures, like people, are zoomed so their faces aren't tiny.
		// Squat creatures (imps, chickens, goblins), objects and items are always shown whole.
		boolean tall = figure && (double) h / w >= TALL_FIGURE && (double) h / w > (double) boxH / boxW * 1.4;
		if (tall)
		{
			// Fill more of the width, keeping the top in view
			scale = Math.min((double) boxW / w, fit * TALL_ZOOM);
		}
		scale = Math.min(scale, MAX_UPSCALE);

		int sw = Math.max(1, (int) Math.round(w * scale));
		int sh = Math.max(1, (int) Math.round(h * scale));
		BufferedImage scaled = resize(art, sw, sh);
		int x = (windowW - sw) / 2;
		int y = tall && sh > boxH ? pad : (windowH - sh) / 2;
		return new Fitted(scaled, x, y);
	}

	/**
	 * Crops away fully (or almost fully) transparent rows and columns around the picture.
	 */
	static BufferedImage trim(BufferedImage src)
	{
		int w = src.getWidth();
		int h = src.getHeight();
		if (!src.getColorModel().hasAlpha())
		{
			return src;
		}
		int top = 0;
		int bottom = h - 1;
		int left = 0;
		int right = w - 1;
		while (top < bottom && rowEmpty(src, top))
		{
			top++;
		}
		while (bottom > top && rowEmpty(src, bottom))
		{
			bottom--;
		}
		while (left < right && columnEmpty(src, left, top, bottom))
		{
			left++;
		}
		while (right > left && columnEmpty(src, right, top, bottom))
		{
			right--;
		}
		if (top == 0 && left == 0 && bottom == h - 1 && right == w - 1)
		{
			return src;
		}
		Rectangle r = new Rectangle(left, top, right - left + 1, bottom - top + 1);
		return src.getSubimage(r.x, r.y, r.width, r.height);
	}

	private static boolean rowEmpty(BufferedImage img, int y)
	{
		for (int x = 0; x < img.getWidth(); x++)
		{
			if ((img.getRGB(x, y) >>> 24) > 16)
			{
				return false;
			}
		}
		return true;
	}

	private static boolean columnEmpty(BufferedImage img, int x, int top, int bottom)
	{
		for (int y = top; y <= bottom; y++)
		{
			if ((img.getRGB(x, y) >>> 24) > 16)
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Resizes smoothly. Big reductions are done in halving steps, which keeps fine detail clean
	 * where a single large jump would turn it grainy.
	 */
	private static BufferedImage resize(BufferedImage src, int w, int h)
	{
		BufferedImage current = src;
		int cw = src.getWidth();
		int ch = src.getHeight();
		while (cw / 2 >= w && ch / 2 >= h)
		{
			cw /= 2;
			ch /= 2;
			current = draw(current, cw, ch);
		}
		return draw(current, w, h);
	}

	private static BufferedImage draw(BufferedImage src, int w, int h)
	{
		BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
		g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		g.setRenderingHint(RenderingHints.KEY_ALPHA_INTERPOLATION, RenderingHints.VALUE_ALPHA_INTERPOLATION_QUALITY);
		g.drawImage(src, 0, 0, w, h, null);
		g.dispose();
		return out;
	}
}

package com.wikipeek;

/**
 * How a click on a row or picture in the pop-out opens its page.
 */
public enum ClickKey
{
	OFF("Off"),
	CLICK("Click"),
	SHIFT("Shift+click"),
	CTRL("Ctrl+click");

	private final String label;

	ClickKey(String label)
	{
		this.label = label;
	}

	boolean matches(boolean shift, boolean ctrl)
	{
		switch (this)
		{
			case CLICK:
				return !shift && !ctrl;
			case SHIFT:
				return shift && !ctrl;
			case CTRL:
				return ctrl && !shift;
			default:
				return false;
		}
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.wikipeek;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Wiki pages and pictures saved in the plugin's own folder for about a week, so the same
 * monster doesn't need fetching again each session. Kept under a size cap, oldest first out.
 * Never call this on the client thread.
 */
class DiskCache
{
	private static final Logger log = LoggerFactory.getLogger(DiskCache.class);

	static final long MAX_AGE_MS = 7L * 24 * 60 * 60 * 1000;
	static final long MAX_BYTES = 40L * 1024 * 1024;
	/**
	 * When over the cap, files are removed until the folder is back down to this.
	 */
	private static final long TRIM_TO = MAX_BYTES * 3 / 4;

	private volatile Filepath root;
	private long written;

	/**
	 * Sets the folder to use, creating it if needed, and clears out anything expired.
	 */
	synchronized void init(Filepath dir)
	{
		try
		{
			dir.createDirectories();
			root = dir;
			prune();
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("WikiPeek can't use its data folder, so nothing will be saved between sessions", e);
			root = null;
		}
	}

	/**
	 * The saved file's bytes, or null if it isn't saved or is over a week old.
	 */
	byte[] read(String name)
	{
		final Filepath dir = root;
		if (dir == null)
		{
			return null;
		}
		try
		{
			Filepath file = dir.joinSegment(name);
			if (!file.isFile())
			{
				return null;
			}
			if (System.currentTimeMillis() - file.getLastModifiedTime().toMillis() > MAX_AGE_MS)
			{
				file.deleteIfExists();
				return null;
			}
			try (InputStream in = file.openInputStream())
			{
				return in.readAllBytes();
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Could not read saved {}", name, e);
			return null;
		}
	}

	String readText(String name)
	{
		byte[] bytes = read(name);
		return bytes == null ? null : new String(bytes, StandardCharsets.UTF_8);
	}

	synchronized void write(String name, byte[] bytes)
	{
		final Filepath dir = root;
		if (dir == null || bytes == null || bytes.length > MAX_BYTES / 4)
		{
			return;
		}
		try
		{
			dir.joinSegment(name).write(bytes);
			written += bytes.length;
			// Check the cap now and then rather than walking the folder on every save
			if (written > MAX_BYTES / 10)
			{
				written = 0;
				prune();
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Could not save {}", name, e);
		}
	}

	void writeText(String name, String text)
	{
		write(name, text.getBytes(StandardCharsets.UTF_8));
	}

	/**
	 * Deletes everything saved.
	 */
	synchronized void clear()
	{
		final Filepath dir = root;
		if (dir == null)
		{
			return;
		}
		for (Filepath file : files(dir))
		{
			try
			{
				file.deleteIfExists();
			}
			catch (IOException | RuntimeException e)
			{
				log.debug("Could not delete {}", file, e);
			}
		}
	}

	/**
	 * Removes files over a week old, then the oldest files while over the size cap.
	 */
	private void prune()
	{
		final Filepath dir = root;
		if (dir == null)
		{
			return;
		}
		final long now = System.currentTimeMillis();
		final List<Object[]> kept = new ArrayList<>();
		long total = 0;
		for (Filepath file : files(dir))
		{
			try
			{
				long modified = file.getLastModifiedTime().toMillis();
				if (now - modified > MAX_AGE_MS)
				{
					file.deleteIfExists();
					continue;
				}
				long size = file.size();
				total += size;
				kept.add(new Object[]{file, modified, size});
			}
			catch (IOException | RuntimeException e)
			{
				log.debug("Could not check {}", file, e);
			}
		}
		if (total <= MAX_BYTES)
		{
			return;
		}
		kept.sort((a, b) -> Long.compare((Long) a[1], (Long) b[1]));
		for (Object[] entry : kept)
		{
			if (total <= TRIM_TO)
			{
				break;
			}
			try
			{
				((Filepath) entry[0]).deleteIfExists();
				total -= (Long) entry[2];
			}
			catch (IOException | RuntimeException e)
			{
				log.debug("Could not delete {}", entry[0], e);
			}
		}
	}

	private static List<Filepath> files(Filepath dir)
	{
		try (Stream<Filepath> walk = dir.walk(1))
		{
			return walk.filter(Filepath::isFile).collect(Collectors.toList());
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("Could not list {}", dir, e);
			return new ArrayList<>();
		}
	}

	/**
	 * A short file-safe name for a URL.
	 */
	static String hash(String text)
	{
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-1").digest(text.getBytes(StandardCharsets.UTF_8));
			StringBuilder sb = new StringBuilder();
			for (int i = 0; i < 12; i++)
			{
				sb.append(String.format("%02x", digest[i]));
			}
			return sb.toString();
		}
		catch (NoSuchAlgorithmException e)
		{
			return Integer.toHexString(text.hashCode()) + "-" + text.length();
		}
	}
}

package com.wikipeek;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * An NPC's drop table, read from the wiki's own rendered page, so drops that come from shared
 * templates (the human drop table, herb and seed tables, clue scroll lines and so on) appear
 * exactly as the wiki shows them. Pages that cover several NPCs with different drops, such as
 * Barbarian or Goblin, are narrowed down to the tables for the NPC that was clicked.
 */
final class Drops
{
	/**
	 * A row as the wiki shows it: item, quantity and rarity.
	 */
	static final class Row
	{
		String name;
		String quantity;
		String rarity;
	}

	/**
	 * One drop table from the page, with the headings it sits under.
	 */
	static final class Table
	{
		/**
		 * The drops heading it's under ("Drops", "Level 8, 9, and 10 drops"), or null for a
		 * table above the page's first heading.
		 */
		String top;
		/**
		 * The sub-heading ("100%", "Tertiary"), or null.
		 */
		String sub;
		List<Row> rows = new ArrayList<>();
	}

	static final class Item
	{
		final String name;
		final String quantity;
		final String rarity;
		/**
		 * Grand Exchange price for one, or 0 if unknown or untradeable.
		 */
		volatile long price;
		/**
		 * The item's picture from the game, once loaded, or null.
		 */
		volatile java.awt.image.BufferedImage icon;

		Item(String name, String quantity, String rarity, long price)
		{
			this.name = name;
			this.quantity = quantity;
			this.rarity = rarity;
			this.price = price;
		}
	}

	static final class Group
	{
		final String heading;
		final List<Item> items = new ArrayList<>();

		Group(String heading)
		{
			this.heading = heading;
		}
	}

	private static final Pattern HTML_TOKEN = Pattern.compile(
		"<h([2-6])[^>]*>(.*?)</h\\1>|<table[^>]*class=\"[^\"]*item-drops[^\"]*\"[^>]*>(.*?)</table>", Pattern.DOTALL);
	private static final Pattern ROW_SPLIT = Pattern.compile("<tr[\\s>]");
	private static final Pattern CELL = Pattern.compile("<td([^>]*)>(.*?)</td>", Pattern.DOTALL);
	private static final Pattern ANCHOR = Pattern.compile("<a [^>]*>(.*?)</a>", Pattern.DOTALL);
	private static final Pattern SUP = Pattern.compile("<sup[^>]*>.*?</sup>", Pattern.DOTALL);
	private static final Pattern REFERENCE = Pattern.compile("<span[^>]*class=\"[^\"]*reference[^\"]*\"[^>]*>.*?</span>", Pattern.DOTALL);
	private static final Pattern STYLE = Pattern.compile("<style.*?</style>", Pattern.DOTALL);
	private static final Pattern TAG = Pattern.compile("<[^>]+>");

	private static final Pattern WIKI_HEADING = Pattern.compile("^(={2,})\\s*(.+?)\\s*\\1\\s*$");
	private static final Pattern TABLE_HEAD = Pattern.compile("\\{\\{\\s*DropsTableHead\\s*(\\|[^{}]*)?\\}\\}", Pattern.CASE_INSENSITIVE);
	private static final Pattern DROPVERSION = Pattern.compile("\\|\\s*dropversion\\s*=\\s*([^|}]*)", Pattern.CASE_INSENSITIVE);
	private static final Pattern LEVEL_RANGE = Pattern.compile("(\\d+)\\s*[–—-]\\s*(\\d+)");
	private static final Pattern NUMBER = Pattern.compile("\\d+");
	private static final Pattern LEVEL_HEADING = Pattern.compile("^levels?\\s+\\d");
	private static final Set<String> FILLER = new HashSet<>(java.util.Arrays.asList(
		"drop", "drops", "table", "tables", "and", "the", "of", "a", "level", "levels", "only", "s"));

	private Drops()
	{
	}

	/**
	 * Every drop table in a page's rendered HTML that sits under a drops heading ("Drops",
	 * "Drop table 1", "Level 15 and 17 drops" and so on), or above the first heading. Tables
	 * under other headings, such as pickpocketing loot, are left out.
	 */
	static List<Table> fromHtml(String html)
	{
		final List<Table> tables = new ArrayList<>();
		if (html == null)
		{
			return tables;
		}
		boolean inDrops = false;
		boolean seenTop = false;
		int dropsLevel = 0;
		String top = null;
		String sub = null;
		final Matcher m = HTML_TOKEN.matcher(html);
		while (m.find())
		{
			if (m.group(1) != null)
			{
				final int level = Integer.parseInt(m.group(1));
				final String text = text(m.group(2));
				final String lower = text.toLowerCase(Locale.ROOT);
				if (level == 2)
				{
					seenTop = true;
				}
				if ((isDropsHeading(lower) && (!inDrops || level <= dropsLevel))
					|| (inDrops && level == dropsLevel && isLevelHeading(lower)))
				{
					inDrops = true;
					dropsLevel = level;
					top = text;
					sub = null;
				}
				else if (inDrops && level <= dropsLevel)
				{
					inDrops = false;
					top = null;
					sub = null;
				}
				else if (inDrops)
				{
					sub = text;
				}
				continue;
			}
			if (!inDrops && seenTop)
			{
				continue;
			}
			final Table table = new Table();
			table.top = inDrops ? top : null;
			table.sub = inDrops ? sub : null;
			for (String tr : ROW_SPLIT.split(m.group(3)))
			{
				Row row = row(tr);
				if (row != null)
				{
					table.rows.add(row);
				}
			}
			if (!table.rows.isEmpty())
			{
				tables.add(table);
			}
		}
		return tables;
	}

	private static boolean isDropsHeading(String lower)
	{
		return lower.contains("drop") && !lower.startsWith("drop sources");
	}

	/**
	 * A heading like "Levels 81-100" next to "Level 61-80 drops": another level's drops.
	 */
	private static boolean isLevelHeading(String lower)
	{
		return LEVEL_HEADING.matcher(lower).find();
	}

	/**
	 * A table row: the item column, then quantity and rarity.
	 */
	private static Row row(String tr)
	{
		if (!tr.contains("class=\"item-col\""))
		{
			return null;
		}
		final List<String[]> cells = new ArrayList<>();
		Matcher c = CELL.matcher(tr);
		while (c.find())
		{
			cells.add(new String[]{c.group(1), c.group(2)});
		}
		int itemCol = -1;
		for (int i = 0; i < cells.size(); i++)
		{
			if (cells.get(i)[0].contains("class=\"item-col\""))
			{
				itemCol = i;
				break;
			}
		}
		if (itemCol < 0)
		{
			return null;
		}
		final Row row = new Row();
		final String itemHtml = cells.get(itemCol)[1];
		final Matcher a = ANCHOR.matcher(itemHtml);
		row.name = text(a.find() ? a.group(1) : itemHtml);
		row.quantity = itemCol + 1 < cells.size() ? text(cells.get(itemCol + 1)[1]) : "";
		row.rarity = itemCol + 2 < cells.size() ? text(cells.get(itemCol + 2)[1]) : "";
		return row.name.isEmpty() ? null : row;
	}

	/**
	 * Visible text of a piece of HTML, without reference marks or notes.
	 */
	static String text(String html)
	{
		String s = SUP.matcher(html).replaceAll("");
		s = REFERENCE.matcher(s).replaceAll("");
		s = STYLE.matcher(s).replaceAll("");
		s = TAG.matcher(s).replaceAll("");
		s = MathText.plain(Infobox.decodeEntities(s.replace("&#160;", " ").replace("&#39;", "'")));
		return s.replaceAll("\\s+", " ").trim();
	}

	/**
	 * The tables for one NPC, as groups ready to show. Where a page covers several NPCs with
	 * different drops, the wiki tags each table with a drop version and each NPC version in
	 * the infobox with the drop versions it uses, so those are matched first. Tables without
	 * a tag are matched by their heading: a heading with levels must include the NPC's
	 * combat level, and one naming a variant ("Armed", "Wilderness Slayer Cave") must name
	 * this NPC's version, or at least not another's. If nothing is left, everything is shown.
	 */
	static List<Group> forNpc(List<Table> tables, String wikitext, Infobox box, int combat, String npcName)
	{
		if (tables == null || tables.isEmpty())
		{
			return new ArrayList<>();
		}
		final Map<String, List<String>> versions = tableVersions(wikitext);
		final Set<String> ours = box == null ? Collections.<String>emptySet() : split(box.get("dropversion"));
		final String ourLabel = box == null ? "" : box.get("version");
		final List<String> otherLabels = box == null ? Collections.<String>emptyList() : box.otherVersionLabels();
		final Set<String> nameWords = words(npcName);

		// Drop versions the infobox knows about. Tags it doesn't use (a typo, or a name only
		// the tables use) are ignored, so those tables go by their headings instead.
		final Set<String> known = split(String.join(",", Infobox.pageDropVersions(wikitext)));

		// Every known tag used on the page, and under each drops heading
		final Set<String> pageTags = new HashSet<>();
		final Map<String, Set<String>> topTags = new HashMap<>();
		for (Map.Entry<String, List<String>> e : versions.entrySet())
		{
			final String top = e.getKey().substring(0, e.getKey().indexOf('|'));
			for (String tag : e.getValue())
			{
				final Set<String> tags = knownOnly(split(tag), known);
				pageTags.addAll(tags);
				topTags.computeIfAbsent(top, x -> new HashSet<>()).addAll(tags);
			}
		}
		// Drop versions the infobox uses that no table is tagged with: the untagged tables
		// must be theirs ("Regular" for Spiritual mage, whose "Zaros" table is tagged)
		final Set<String> implicit = new HashSet<>();
		if (!pageTags.isEmpty())
		{
			implicit.addAll(known);
		}
		implicit.removeAll(pageTags);

		// How many tables sit under each heading, to line them up with the wikitext's
		final Map<String, Integer> counts = new HashMap<>();
		for (Table t : tables)
		{
			counts.merge(key(t.top, t.sub), 1, Integer::sum);
		}

		final List<Table> byTag = new ArrayList<>();
		final List<Table> byHeading = new ArrayList<>();
		final Map<String, Integer> seen = new HashMap<>();
		for (Table t : tables)
		{
			final String k = key(t.top, t.sub);
			final int index = seen.merge(k, 1, Integer::sum) - 1;
			final boolean fits = headingFits(t.top, combat, ourLabel, ours, otherLabels, nameWords);
			if (fits)
			{
				byHeading.add(t);
			}
			Set<String> tags = knownOnly(split(tagFor(versions.get(k), counts.get(k), index)), known);
			if (tags.isEmpty())
			{
				// An untagged table under a tagged heading shares that heading's tags
				tags = topTags.getOrDefault(norm(t.top), Collections.<String>emptySet());
			}
			if (tags.isEmpty())
			{
				tags = implicit;
			}
			final boolean keep = !ours.isEmpty() && !tags.isEmpty() ? intersects(tags, ours) : fits;
			if (keep)
			{
				byTag.add(t);
			}
		}
		// If the tags don't line up with the infobox at all, go by the headings alone
		if (!byTag.isEmpty())
		{
			return group(byTag);
		}
		return group(byHeading.isEmpty() ? tables : byHeading);
	}

	/**
	 * The drop version of the index'th table under a heading, from the wikitext's
	 * DropsTableHead lines. Null when the table has no tag.
	 */
	private static String tagFor(List<String> tags, Integer count, int index)
	{
		if (tags == null || tags.isEmpty())
		{
			return null;
		}
		if (count != null && tags.size() == count)
		{
			return tags.get(index);
		}
		// Not lined up one to one (a template added tables): use the tags only if they agree
		final Set<String> distinct = new HashSet<>(tags);
		return distinct.size() == 1 ? tags.get(0) : null;
	}

	/**
	 * For each heading in the wikitext's drops sections, the drop version of each
	 * DropsTableHead under it, in order (null for one without).
	 */
	static Map<String, List<String>> tableVersions(String wikitext)
	{
		final Map<String, List<String>> out = new HashMap<>();
		if (wikitext == null)
		{
			return out;
		}
		boolean inDrops = false;
		boolean seenTop = false;
		int dropsLevel = 0;
		String top = null;
		String sub = null;
		for (String line : wikitext.split("\n"))
		{
			Matcher h = WIKI_HEADING.matcher(line.trim());
			if (h.matches())
			{
				final int level = h.group(1).length();
				final String text = Infobox.clean(h.group(2));
				final String lower = text.toLowerCase(Locale.ROOT);
				if (level == 2)
				{
					seenTop = true;
				}
				if ((isDropsHeading(lower) && (!inDrops || level <= dropsLevel))
					|| (inDrops && level == dropsLevel && isLevelHeading(lower)))
				{
					inDrops = true;
					dropsLevel = level;
					top = text;
					sub = null;
				}
				else if (inDrops && level <= dropsLevel)
				{
					inDrops = false;
					top = null;
					sub = null;
				}
				else if (inDrops)
				{
					sub = text;
				}
				continue;
			}
			if (!inDrops && seenTop)
			{
				continue;
			}
			Matcher t = TABLE_HEAD.matcher(line);
			while (t.find())
			{
				String version = null;
				if (t.group(1) != null)
				{
					Matcher v = DROPVERSION.matcher(t.group(1));
					if (v.find() && !Infobox.clean(v.group(1)).isEmpty())
					{
						version = Infobox.clean(v.group(1));
					}
				}
				out.computeIfAbsent(key(inDrops ? top : null, inDrops ? sub : null), x -> new ArrayList<>()).add(version);
			}
		}
		// A heading whose tables have no tags at all says nothing
		out.values().removeIf(list -> list.stream().allMatch(v -> v == null));
		for (List<String> list : out.values())
		{
			// Untagged tables under a tagged heading count as untagged
			list.replaceAll(v -> v == null ? "" : v);
		}
		return out;
	}

	/**
	 * Whether a drops heading fits this NPC, for tables the wiki hasn't tagged.
	 */
	private static boolean headingFits(String top, int combat, String ourLabel, Set<String> ours,
		List<String> otherLabels, Set<String> nameWords)
	{
		if (top == null)
		{
			return true;
		}
		final String lower = top.toLowerCase(Locale.ROOT);
		// "Level 8, 9, and 10 drops", "Drops (level 74)", "Level 40-56 drops"
		if (lower.contains("level") && combat > 0)
		{
			final Set<Integer> levels = levels(lower);
			if (!levels.isEmpty())
			{
				return levels.contains(combat);
			}
		}
		final Set<String> q = new HashSet<>(words(top));
		q.removeAll(FILLER);
		q.removeAll(nameWords);
		q.removeIf(w -> NUMBER.matcher(w).matches());
		if (q.isEmpty())
		{
			return true;
		}
		final Set<String> ourWords = words(ourLabel);
		for (String v : ours)
		{
			ourWords.addAll(words(v));
		}
		if (ourWords.containsAll(q))
		{
			return true;
		}
		// A heading that names another version belongs to that one
		for (String other : otherLabels)
		{
			if (words(other).containsAll(q))
			{
				return false;
			}
		}
		return true;
	}

	private static Set<Integer> levels(String heading)
	{
		final Set<Integer> levels = new HashSet<>();
		String rest = heading;
		Matcher r = LEVEL_RANGE.matcher(heading);
		while (r.find())
		{
			int from = Integer.parseInt(r.group(1));
			int to = Integer.parseInt(r.group(2));
			for (int i = from; i <= to && i - from < 1000; i++)
			{
				levels.add(i);
			}
		}
		rest = LEVEL_RANGE.matcher(rest).replaceAll(" ");
		Matcher n = NUMBER.matcher(rest);
		while (n.find())
		{
			levels.add(Integer.parseInt(n.group()));
		}
		return levels;
	}

	/**
	 * Tables as display groups. Tables under the same headings go together. When more than
	 * one drops heading is left, each group says which it's from ("Drop table 1: 100%").
	 */
	private static List<Group> group(List<Table> tables)
	{
		final Set<String> tops = new HashSet<>();
		for (Table t : tables)
		{
			tops.add(t.top == null ? "" : t.top);
		}
		final boolean label = tops.size() > 1;
		final Map<String, Group> groups = new LinkedHashMap<>();
		for (Table t : tables)
		{
			final String heading = heading(t, label);
			final Group g = groups.computeIfAbsent(heading, Group::new);
			for (Row r : t.rows)
			{
				// Prices come from RuneLite per item; the wiki's column is the value of the whole stack
				g.items.add(new Item(r.name, r.quantity == null ? "" : r.quantity, r.rarity == null ? "" : r.rarity, 0));
			}
		}
		return new ArrayList<>(groups.values());
	}

	private static String heading(Table t, boolean label)
	{
		final String top = t.top == null ? "" : t.top;
		final boolean plain = top.isEmpty() || top.equalsIgnoreCase("drops") || top.equalsIgnoreCase("drop table")
			|| top.equalsIgnoreCase("drop tables");
		if (t.sub == null)
		{
			return plain ? "Drops" : top;
		}
		return label && !plain ? top + ": " + t.sub : t.sub;
	}

	private static String key(String top, String sub)
	{
		return norm(top) + "|" + norm(sub);
	}

	private static String norm(String s)
	{
		return s == null ? "" : s.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
	}

	private static Set<String> split(String list)
	{
		final Set<String> out = new HashSet<>();
		if (list == null)
		{
			return out;
		}
		for (String part : list.split(","))
		{
			String n = norm(part);
			if (!n.isEmpty())
			{
				out.add(n);
			}
		}
		return out;
	}

	private static Set<String> knownOnly(Set<String> tags, Set<String> known)
	{
		tags.retainAll(known);
		return tags;
	}

	private static boolean intersects(Set<String> a, Set<String> b)
	{
		for (String s : a)
		{
			if (b.contains(s))
			{
				return true;
			}
		}
		return false;
	}

	private static Set<String> words(String s)
	{
		final Set<String> out = new HashSet<>();
		if (s == null)
		{
			return out;
		}
		for (String w : s.toLowerCase(Locale.ROOT).split("[^a-z0-9]+"))
		{
			if (!w.isEmpty())
			{
				out.add(w);
			}
		}
		return out;
	}

	/**
	 * The most of an item that can drop at once, for picking the right stack picture (a pile
	 * of coins rather than one). 1 if the quantity isn't a number.
	 */
	static int maxQuantity(String quantity)
	{
		int best = 1;
		Matcher m = Pattern.compile("[0-9][0-9,]*").matcher(quantity == null ? "" : quantity);
		while (m.find())
		{
			try
			{
				best = Math.max(best, Integer.parseInt(m.group().replace(",", "")));
			}
			catch (NumberFormatException e)
			{
				// Too big to be a real stack; keep what we have
			}
		}
		return best;
	}

	/**
	 * A short price: 950, 11.2k, 3.4m.
	 */
	static String shortPrice(long price)
	{
		if (price >= 10_000_000)
		{
			return (price / 1_000_000) + "m";
		}
		if (price >= 1_000_000)
		{
			return String.format(Locale.ROOT, "%.1fm", price / 1_000_000.0);
		}
		if (price >= 10_000)
		{
			return (price / 1000) + "k";
		}
		if (price >= 1000)
		{
			return String.format(Locale.ROOT, "%.1fk", price / 1000.0);
		}
		return Long.toString(price);
	}
}

package com.wikipeek;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The parameters of a page's {{Infobox Monster}}, read from its wikitext, with one version
 * chosen for pages that cover several (version1, hitpoints1 and so on).
 */
final class Infobox
{
	private static final Pattern START = start("Monster");
	private static final Pattern ITEM_START = start("Item");
	private static final Pattern BONUSES_START = start("Bonuses");
	private static final Pattern IMAGE_FILE = Pattern.compile("\\[\\[\\s*(?:File|Image):([^|\\]]+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern NUMBERED = Pattern.compile("^(.*?)(\\d+)$");
	private static final Pattern ID_TOKEN = Pattern.compile("(\\d+)(?:\\s*-\\s*(\\d+))?");
	private static final Pattern COMMENT = Pattern.compile("<!--.*?-->", Pattern.DOTALL);
	private static final Pattern REF = Pattern.compile("<ref[^>]*?(/>|>.*?</ref>)", Pattern.DOTALL | Pattern.CASE_INSENSITIVE);
	private static final Pattern BREAK = Pattern.compile("<br\\s*/?>", Pattern.CASE_INSENSITIVE);
	private static final Pattern INNER_TEMPLATE = Pattern.compile("\\{\\{([^{}]*)\\}\\}");
	private static final Pattern FILE_LINK = Pattern.compile("\\[\\[\\s*(?:File|Image):[^\\]]*\\]\\]", Pattern.CASE_INSENSITIVE);
	private static final Pattern PIPED_LINK = Pattern.compile("\\[\\[[^\\]|]*\\|([^\\]]*)\\]\\]");
	private static final Pattern LINK = Pattern.compile("\\[\\[([^\\]]*)\\]\\]");
	private static final Pattern EXTERNAL = Pattern.compile("\\[https?://\\S+\\s+([^\\]]*)\\]");
	private static final Pattern TAG = Pattern.compile("<[^>]+>");
	private static final Pattern NUMERIC_ENTITY = Pattern.compile("&#(x?)([0-9a-fA-F]+);");

	/**
	 * Parameter names in lower case, as written (so "hitpoints1", "max hit"), to raw values.
	 */
	private final Map<String, String> params;
	/**
	 * The chosen version's number, or null for a page with one version.
	 */
	private final String version;

	private Infobox(Map<String, String> params, String version)
	{
		this.params = params;
		this.version = version;
	}

	String getVersion()
	{
		return version;
	}

	/**
	 * One of the monsters a page covers: an infobox, and a version within it if it has any.
	 */
	static final class Choice
	{
		final int box;
		final String version;
		final String label;

		Choice(int box, String version, String label)
		{
			this.box = box;
			this.version = version;
			this.label = label;
		}
	}

	/**
	 * Every monster a page covers, in the wiki's order, like the tabs above its infobox:
	 * each version of each infobox ("Level 9 (Sieglinde)", "Level 10").
	 */
	static List<Choice> choices(String wikitext)
	{
		return choices(wikitext, START);
	}

	/**
	 * The versions of any other page's infoboxes (an object's, an NPC you can't fight).
	 */
	static List<Choice> choicesAny(String wikitext)
	{
		return choices(wikitext, ANY_START);
	}

	private static List<Choice> choices(String wikitext, Pattern start)
	{
		final List<Choice> out = new ArrayList<>();
		if (wikitext == null)
		{
			return out;
		}
		final Matcher m = start.matcher(wikitext);
		int box = 0;
		while (m.find())
		{
			if (start == ANY_START && m.group(1).trim().equalsIgnoreCase("bonuses"))
			{
				continue;
			}
			final Map<String, String> params = params(templateBody(wikitext, m.end()));
			final List<String> versions = new ArrayList<>();
			for (String key : params.keySet())
			{
				Matcher n = NUMBERED.matcher(key);
				if (n.matches() && n.group(1).equals("version"))
				{
					versions.add(n.group(2));
				}
			}
			if (versions.isEmpty())
			{
				String label = clean(params.get("name"));
				final String level = clean(params.get("combat"));
				if (!level.isEmpty())
				{
					label = (label.isEmpty() ? "" : label + " ") + "(level " + level + ")";
				}
				out.add(new Choice(box, null, label.isEmpty() ? "Version " + (out.size() + 1) : label));
			}
			for (String v : versions)
			{
				final String label = clean(params.get("version" + v));
				out.add(new Choice(box, v, label.isEmpty() ? "Version " + v : label));
			}
			box++;
		}
		return out;
	}

	/**
	 * The monster infobox for one choice from {@link #choices}.
	 */
	static Infobox read(String wikitext, Choice choice)
	{
		return read(wikitext, choice, START);
	}

	static Infobox readAny(String wikitext, Choice choice)
	{
		final Infobox out = read(wikitext, choice, ANY_START);
		return out;
	}

	private static Infobox read(String wikitext, Choice choice, Pattern start)
	{
		final Matcher m = start.matcher(wikitext);
		int box = 0;
		while (m.find())
		{
			if (start == ANY_START && m.group(1).trim().equalsIgnoreCase("bonuses"))
			{
				continue;
			}
			if (box++ == choice.box)
			{
				final Infobox out = new Infobox(params(templateBody(wikitext, m.end())), choice.version);
				out.box = choice.box;
				return out;
			}
		}
		return null;
	}

	/**
	 * Which infobox on the page this is, counting from 0.
	 */
	private int box;

	/**
	 * Where this infobox and version sit in {@link #choices}, or -1.
	 */
	int choiceIndex(List<Choice> choices)
	{
		for (int i = 0; i < choices.size(); i++)
		{
			final Choice c = choices.get(i);
			if (c.box == box && java.util.Objects.equals(c.version, version))
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * The infobox on a page, with the version that matches the NPC's ID, or else its combat
	 * level, or else the page's default. Null if the page has no Infobox Monster.
	 */
	/**
	 * Whether a page has a monster infobox.
	 */
	static boolean has(String wikitext)
	{
		return wikitext != null && START.matcher(wikitext).find();
	}

	/**
	 * Whether a page has an item infobox.
	 */
	static boolean hasItem(String wikitext)
	{
		return wikitext != null && ITEM_START.matcher(wikitext).find();
	}

	private static final Pattern ANY_START = Pattern.compile("\\{\\{\\s*Infobox[ _]([A-Za-z][A-Za-z ]*?)\\s*(?=[|}\\n])", Pattern.CASE_INSENSITIVE);

	/**
	 * The kind of infobox this is ("NPC", "Shop", "Scenery"), for an infobox read with
	 * {@link #readAny}; null otherwise.
	 */
	private String type;

	String getType()
	{
		return type;
	}

	/**
	 * The page's first infobox of any kind other than bonuses, at its default version. For
	 * pages that aren't monsters or items: NPCs you can't fight, shops, places, scenery.
	 */
	static Infobox readAny(String wikitext)
	{
		return readAny(wikitext, -1);
	}

	/**
	 * The page's infobox listing this ID (an object's), at that ID's version; else its first
	 * infobox at the default version.
	 */
	static Infobox readAny(String wikitext, int id)
	{
		if (wikitext == null)
		{
			return null;
		}
		final Matcher m = ANY_START.matcher(wikitext);
		Infobox first = null;
		int box = 0;
		while (m.find())
		{
			final String type = m.group(1).trim();
			if (type.equalsIgnoreCase("bonuses"))
			{
				continue;
			}
			final Map<String, String> params = params(templateBody(wikitext, m.end()));
			final Infobox made = new Infobox(params, chooseVersion(params, id, 0));
			made.type = type;
			made.box = box++;
			if (first == null)
			{
				first = made;
			}
			if (id > 0)
			{
				for (Map.Entry<String, String> e : params.entrySet())
				{
					if (e.getKey().matches("id\\d*") && ids(e.getValue()).contains(id))
					{
						return made;
					}
				}
			}
		}
		return first;
	}

	private static Pattern start(String name)
	{
		return Pattern.compile("\\{\\{\\s*Infobox[ _]" + name + "\\s*(?=[|}\\n])", Pattern.CASE_INSENSITIVE);
	}

	/**
	 * A page's item infobox, with the version that lists this item's ID, else the default.
	 */
	static Infobox readItem(String wikitext, int id)
	{
		return read(ITEM_START, wikitext, id, 0, null);
	}

	/**
	 * A page's equipment bonuses, for the same version number as its item infobox where it
	 * has one. Null for things that aren't worn.
	 */
	static Infobox readBonuses(String wikitext, String version)
	{
		return read(BONUSES_START, wikitext, -1, 0, version);
	}

	static Infobox read(String wikitext, int id, int combat)
	{
		return read(START, wikitext, id, combat, null);
	}

	private static Infobox read(Pattern start, String wikitext, int id, int combat, String forcedVersion)
	{
		if (wikitext == null)
		{
			return null;
		}
		// Some pages have an infobox for each of several monsters (Skeleton, Guard): use the
		// one that lists this NPC's ID, else one with its combat level, else the first
		final List<Map<String, String>> boxes = new ArrayList<>();
		final Matcher m = start.matcher(wikitext);
		while (m.find())
		{
			boxes.add(params(templateBody(wikitext, m.end())));
		}
		if (boxes.isEmpty())
		{
			return null;
		}
		Map<String, String> chosen = null;
		Infobox made;
		for (Map<String, String> box : boxes)
		{
			for (Map.Entry<String, String> e : box.entrySet())
			{
				if (e.getKey().matches("id\\d*") && ids(e.getValue()).contains(id))
				{
					chosen = box;
					break;
				}
			}
			if (chosen != null)
			{
				break;
			}
		}
		if (chosen == null && combat > 0)
		{
			for (Map<String, String> box : boxes)
			{
				for (Map.Entry<String, String> e : box.entrySet())
				{
					if (e.getKey().matches("combat\\d*") && clean(e.getValue()).equals(Integer.toString(combat)))
					{
						chosen = box;
						break;
					}
				}
				if (chosen != null)
				{
					break;
				}
			}
		}
		if (chosen == null)
		{
			chosen = boxes.get(0);
		}
		if (forcedVersion != null && chosen.containsKey("version" + forcedVersion))
		{
			made = new Infobox(chosen, forcedVersion);
		}
		else
		{
			made = new Infobox(chosen, chooseVersion(chosen, id, combat));
		}
		made.box = boxes.indexOf(chosen);
		return made;
	}

	private static Map<String, String> params(String body)
	{
		final Map<String, String> params = new LinkedHashMap<>();
		for (String part : splitTop(body))
		{
			int eq = part.indexOf('=');
			if (eq <= 0)
			{
				continue;
			}
			String key = part.substring(0, eq).trim().toLowerCase(Locale.ROOT).replace('_', ' ');
			params.put(key, part.substring(eq + 1).trim());
		}
		return params;
	}

	/**
	 * The names of the infobox's other versions ("Level 15 (Aitan)"), for telling apart
	 * drop tables meant for them.
	 */
	List<String> otherVersionLabels()
	{
		final List<String> out = new ArrayList<>();
		for (Map.Entry<String, String> e : params.entrySet())
		{
			Matcher n = NUMBERED.matcher(e.getKey());
			if (n.matches() && n.group(1).equals("version") && !n.group(2).equals(version))
			{
				out.add(clean(e.getValue()));
				String drops = clean(params.get("dropversion" + n.group(2)));
				if (!drops.isEmpty())
				{
					out.add(drops);
				}
			}
		}
		return out;
	}

	/**
	 * Every drop version used by any infobox on the page, for pages with several.
	 */
	static List<String> pageDropVersions(String wikitext)
	{
		final List<String> out = new ArrayList<>();
		if (wikitext == null)
		{
			return out;
		}
		final Matcher m = START.matcher(wikitext);
		while (m.find())
		{
			out.addAll(new Infobox(params(templateBody(wikitext, m.end())), null).allDropVersions());
		}
		return out;
	}

	/**
	 * Every drop version any version of this infobox uses.
	 */
	List<String> allDropVersions()
	{
		final List<String> out = new ArrayList<>();
		for (Map.Entry<String, String> e : params.entrySet())
		{
			if (e.getKey().matches("dropversion\\d*"))
			{
				String v = clean(e.getValue());
				if (!v.isEmpty())
				{
					out.add(v);
				}
			}
		}
		return out;
	}

	/**
	 * The file name of this version's picture ("Barbarian (Sieglinde).png"), or null.
	 */
	String imageFile()
	{
		String raw = version != null ? params.get("image" + version) : null;
		if (raw == null || raw.trim().isEmpty())
		{
			raw = params.get("image");
		}
		if (raw == null)
		{
			return null;
		}
		Matcher f = IMAGE_FILE.matcher(raw);
		return f.find() ? f.group(1).trim() : null;
	}

	/**
	 * The text of a template from just after its name to its closing braces.
	 */
	private static String templateBody(String text, int from)
	{
		int depth = 2;
		int i = from;
		for (; i < text.length(); i++)
		{
			char c = text.charAt(i);
			if (c == '{')
			{
				depth++;
			}
			else if (c == '}')
			{
				depth--;
				if (depth == 0)
				{
					break;
				}
			}
		}
		// The two closing braces aren't part of the body
		int end = Math.max(from, Math.min(text.length(), i - 1));
		return text.substring(from, end);
	}

	/**
	 * Splits a template's parameters on | at the top level, so inner templates and links
	 * stay whole.
	 */
	static List<String> splitTop(String body)
	{
		final List<String> parts = new ArrayList<>();
		int braces = 0;
		int brackets = 0;
		StringBuilder part = new StringBuilder();
		for (int i = 0; i < body.length(); i++)
		{
			char c = body.charAt(i);
			if (c == '{')
			{
				braces++;
			}
			else if (c == '}')
			{
				braces = Math.max(0, braces - 1);
			}
			else if (c == '[')
			{
				brackets++;
			}
			else if (c == ']')
			{
				brackets = Math.max(0, brackets - 1);
			}
			if (c == '|' && braces == 0 && brackets == 0)
			{
				parts.add(part.toString());
				part.setLength(0);
			}
			else
			{
				part.append(c);
			}
		}
		parts.add(part.toString());
		return parts;
	}

	private static String chooseVersion(Map<String, String> params, int id, int combat)
	{
		final List<String> versions = new ArrayList<>();
		for (String key : params.keySet())
		{
			Matcher n = NUMBERED.matcher(key);
			if (n.matches() && n.group(1).equals("version"))
			{
				versions.add(n.group(2));
			}
		}
		if (versions.isEmpty())
		{
			return null;
		}
		// The version that lists this NPC's ID
		for (String v : versions)
		{
			if (ids(params.get("id" + v)).contains(id))
			{
				return v;
			}
		}
		// Then the one with the same combat level
		if (combat > 0)
		{
			for (String v : versions)
			{
				String level = clean(params.get("combat" + v));
				if (level.equals(Integer.toString(combat)))
				{
					return v;
				}
			}
		}
		// Then the one the wiki shows first
		String def = clean(params.get("defver"));
		if (versions.contains(def))
		{
			return def;
		}
		return versions.contains("1") ? "1" : versions.get(0);
	}

	static Set<Integer> ids(String value)
	{
		final Set<Integer> ids = new HashSet<>();
		if (value == null)
		{
			return ids;
		}
		Matcher t = ID_TOKEN.matcher(value);
		while (t.find())
		{
			try
			{
				int from = Integer.parseInt(t.group(1));
				int to = t.group(2) != null ? Integer.parseInt(t.group(2)) : from;
				for (int i = from; i <= to && i - from < 2000; i++)
				{
					ids.add(i);
				}
			}
			catch (NumberFormatException e)
			{
				// Not an ID
			}
		}
		return ids;
	}

	/**
	 * A parameter as plain text for the chosen version: its numbered form if this version
	 * has one, else the value every version shares. Empty if the wiki leaves it blank.
	 */
	String get(String name)
	{
		if (version != null)
		{
			String specific = params.get(name + version);
			if (specific != null && !clean(specific).isEmpty())
			{
				return clean(specific);
			}
		}
		return clean(params.get(name));
	}

	/**
	 * The first of several names the wiki has used for the same thing that has a value.
	 */
	String first(String... names)
	{
		for (String name : names)
		{
			String value = get(name);
			if (!value.isEmpty())
			{
				return value;
			}
		}
		return "";
	}

	/**
	 * A line of wikitext as plain text: links become their labels, simple templates their
	 * first value, and references, comments and formatting are removed.
	 */
	static String clean(String raw)
	{
		if (raw == null)
		{
			return "";
		}
		String s = COMMENT.matcher(raw).replaceAll("");
		s = REF.matcher(s).replaceAll("");
		s = BREAK.matcher(s).replaceAll(", ");
		String before;
		do
		{
			before = s;
			Matcher t = INNER_TEMPLATE.matcher(s);
			StringBuffer sb = new StringBuffer();
			while (t.find())
			{
				t.appendReplacement(sb, Matcher.quoteReplacement(templateText(t.group(1))));
			}
			t.appendTail(sb);
			s = sb.toString();
		}
		while (!s.equals(before));
		s = FILE_LINK.matcher(s).replaceAll("");
		s = PIPED_LINK.matcher(s).replaceAll("$1");
		s = LINK.matcher(s).replaceAll("$1");
		s = EXTERNAL.matcher(s).replaceAll("$1");
		s = s.replace("'''", "").replace("''", "");
		s = TAG.matcher(s).replaceAll("");
		s = decodeEntities(s);
		s = s.replaceAll("\\s+", " ").trim();
		return s.replaceAll("^[,;\\s]+|[,;\\s]+$", "").trim();
	}

	/**
	 * What a simple inline template shows: {{NA}} is N/A, others show their first value.
	 */
	private static String templateText(String inside)
	{
		List<String> parts = splitTop(inside);
		String name = parts.get(0).trim().toLowerCase(Locale.ROOT);
		if (name.equals("na") || name.equals("n/a"))
		{
			return "N/A";
		}
		for (int i = 1; i < parts.size(); i++)
		{
			String p = parts.get(i);
			if (p.indexOf('=') < 0 && !p.trim().isEmpty())
			{
				return p.trim();
			}
		}
		return "";
	}

	static String decodeEntities(String s)
	{
		Matcher m = NUMERIC_ENTITY.matcher(s);
		StringBuffer sb = new StringBuffer();
		while (m.find())
		{
			String replacement;
			try
			{
				int cp = Integer.parseInt(m.group(2), m.group(1).isEmpty() ? 10 : 16);
				replacement = new String(Character.toChars(cp));
			}
			catch (IllegalArgumentException e)
			{
				replacement = "";
			}
			m.appendReplacement(sb, Matcher.quoteReplacement(replacement));
		}
		m.appendTail(sb);
		return sb.toString()
			.replace("&nbsp;", " ")
			.replace("&quot;", "\"")
			.replace("&lt;", "<")
			.replace("&gt;", ">")
			.replace("&minus;", "-")
			.replace("&amp;", "&")
			.replace('\u2212', '-');
	}
}

package com.wikipeek;

public enum ItemDetail
{
	SHORT("Standard"),
	FULL("Full page");

	private final String label;

	ItemDetail(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.wikipeek;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * An item's tabs, built from its wiki page: Info (the infobox, the wiki's write-up and, with
 * Full detail, every other section folded away), Stats (equipment bonuses) and Sources
 * (what drops it, shops, spawns and how it's made).
 */
final class ItemInfo
{
	/**
	 * Sections that are shown elsewhere, or are just page history.
	 */
	private static final Set<String> SKIPPED = new HashSet<>(Arrays.asList(
		"contents", "combat stats", "item sources", "shop locations", "spawns", "item spawns", "creation",
		"changes", "gallery", "gallery (historical)", "references", "sound effects", "update history"));
	/**
	 * Columns that are pictures or league details, with no text worth a column.
	 */
	private static final Set<String> DROPPED_COLUMNS = new HashSet<>(Arrays.asList(
		"leagueregion", "members", "map", "restocktime", "pricebought", "pricebroughtat", "pricebought at", "changeper", "icon", "image", "highalch"));
	private static final Set<String> COMPACT = new HashSet<>(Arrays.asList(
		"level", "lvl", "qty", "quantity", "rarity", "price", "stock", "spawns", "xp", "exp", "cost", "members", "tier"));
	private static final Pattern AUTOSORT = Pattern.compile("autosort=(\\d+)");
	private static final Pattern NUMERIC = Pattern.compile("^[~<>≈]?[0-9][0-9,.]*(\\s*[-–/x×]\\s*[0-9][0-9,.]*)?( ?(gp|coins|xp|s|m|%))?$");

	private ItemInfo()
	{
	}

	/**
	 * The Info tab: Basics, Value, then the wiki's write-up. Full adds the page's other
	 * sections, each folded until opened. The GE price comes from RuneLite (0 if none).
	 */
	static MonsterInfo info(Infobox box, WikiHtml.Article article, long gePrice, boolean full, String wikitext)
	{
		final List<MonsterInfo.Section> sections = new ArrayList<>();
		final String examine = box == null ? "" : box.get("examine");
		if (box != null)
		{
			MonsterInfo.Section basics = new MonsterInfo.Section("Basics");
			basics.row("Released", box.get("release"));
			basics.row("Members", MonsterInfo.yesNo(box.get("members")));
			basics.row("Quest item", MonsterInfo.yesNo(box.get("quest")));
			basics.row("Tradeable", MonsterInfo.yesNo(box.get("tradeable")));
			basics.row("Equipable", MonsterInfo.yesNo(box.get("equipable")));
			basics.row("Stackable", MonsterInfo.yesNo(box.get("stackable")));
			basics.row("Noteable", MonsterInfo.yesNo(box.get("noteable")));
			basics.row("Options", box.get("options"));
			basics.row("Destroy", box.get("destroy"));
			final String weight = box.get("weight");
			basics.row("Weight", weight.matches("-?[0-9.]+") ? weight + " kg" : weight);
			sections.add(basics);

			MonsterInfo.Section value = new MonsterInfo.Section("Value");
			if (gePrice > 0)
			{
				value.row("Exchange price", coins(gePrice));
			}
			final String v = box.get("value").replace(",", "");
			if (v.matches("[0-9]+"))
			{
				final long c = Long.parseLong(v);
				value.row("Value", coins(c));
				// High alchemy pays 60% of value and low alchemy 40%, unless it can't be alched
				if (!box.get("alchable").equalsIgnoreCase("no"))
				{
					value.row("High alch", coins(c * 3 / 5));
					value.row("Low alch", coins(c * 2 / 5));
				}
			}
			else
			{
				value.row("Value", v);
			}
			sections.add(value);
		}

		// A clue scroll's own step: what it says and needs, first so it's easy to find
		final MonsterInfo.Section clue = clue(wikitext);
		if (clue != null)
		{
			sections.add(clue);
		}
		final MonsterInfo.Section about = about(article);
		if (about != null)
		{
			sections.add(about);
		}
		if (full)
		{
			sections.addAll(folded(article, false));
		}
		return MonsterInfo.of(examine, sections, "");
	}

	/**
	 * Infobox lines worth showing for any other kind of page, with their labels.
	 */
	private static final String[][] GENERIC_ROWS = {
		{"release", "Released"}, {"members", "Members"}, {"race", "Race"}, {"gender", "Gender"},
		{"location", "Location"}, {"owner", "Owner"}, {"type", "Type"}, {"specialty", "Specialty"},
		{"level", "Level"}, {"skill", "Skill"}, {"quest", "Quest"}, {"difficulty", "Difficulty"},
		{"length", "Length"}, {"options", "Options"}};

	/**
	 * A card for a page that's neither a monster nor an item: an NPC you can't fight, a
	 * shop, a place or an object. Its infobox basics, a shop's stock, the write-up and,
	 * with Full detail, the rest of the page folded.
	 */
	static MonsterInfo generic(Infobox box, WikiHtml.Article article, boolean full, String examined)
	{
		final List<MonsterInfo.Section> sections = new ArrayList<>();
		if (box != null)
		{
			final MonsterInfo.Section basics = new MonsterInfo.Section("Basics");
			for (String[] row : GENERIC_ROWS)
			{
				final String v = box.get(row[0]);
				basics.row(row[1], row[0].equals("members") || row[0].equals("quest") ? MonsterInfo.yesNo(v) : v);
			}
			sections.add(basics);
		}
		if (article != null)
		{
			for (WikiHtml.Table t : article.leadTables)
			{
				final String header = headerText(t);
				if (header.startsWith("item") && (header.contains("stock") || header.contains("price")))
				{
					final MonsterInfo.Section stock = new MonsterInfo.Section("Stock");
					final MonsterInfo.Table table = table(t, "stock", Kind.ITEM, true);
					if (table != null)
					{
						stock.blocks.add(table);
						sections.add(stock);
					}
					break;
				}
			}
		}
		final MonsterInfo.Section about = about(article);
		if (about != null)
		{
			sections.add(about);
		}
		if (full)
		{
			sections.addAll(folded(article, true));
		}
		String examine = box == null ? "" : box.get("examine");
		if (examine.isEmpty() && examined != null)
		{
			examine = examined;
		}
		return MonsterInfo.of(examine, sections, "");
	}

	/**
	 * A paragraph, with any formula in it split out into a box of its own.
	 */
	static List<MonsterInfo.Para> paras(char style, String text, String link)
	{
		final List<MonsterInfo.Para> out = new ArrayList<>();
		String rest = text;
		int at;
		while ((at = rest.indexOf(MathText.START)) >= 0)
		{
			final int end = rest.indexOf(MathText.END, at);
			if (end < 0)
			{
				break;
			}
			final String before = rest.substring(0, at).trim();
			if (!before.isEmpty())
			{
				out.add(new MonsterInfo.Para(style, before, link));
			}
			// The formula as text, and its MathML for drawing it properly
			final String formula = rest.substring(at + 1, end);
			final int xml = formula.indexOf(MathText.XML);
			out.add(new MonsterInfo.Para(MonsterInfo.Para.FORMULA, (xml >= 0 ? formula.substring(0, xml) : formula).trim(),
				xml >= 0 ? formula.substring(xml + 1).trim() : null));
			rest = rest.substring(end + 1);
		}
		rest = rest.replace(MathText.START, "").replace(MathText.END, "").trim();
		if (!rest.isEmpty())
		{
			out.add(new MonsterInfo.Para(style, rest, link));
		}
		return out;
	}

	/**
	 * The wiki's opening write-up, or null if the page has none.
	 */
	static MonsterInfo.Section about(WikiHtml.Article article)
	{
		if (article == null || article.lead.isEmpty())
		{
			return null;
		}
		final MonsterInfo.Section about = new MonsterInfo.Section("About");
		for (String p : article.lead)
		{
			about.blocks.addAll(paras(MonsterInfo.Para.TEXT, p, null));
		}
		return about;
	}

	/**
	 * Every other section of the page, each folded until opened. For an NPC, the drop
	 * sections are left out as they're on the Loot tab.
	 */
	static List<MonsterInfo.Section> folded(WikiHtml.Article article, boolean npc)
	{
		final List<MonsterInfo.Section> sections = new ArrayList<>();
		if (article == null)
		{
			return sections;
		}
		int n = 0;
		for (WikiHtml.Section ws : article.sections)
		{
			final String lower = ws.title == null ? null : ws.title.toLowerCase(Locale.ROOT);
			if (lower == null || SKIPPED.contains(lower) || npc && lower.contains("drop"))
			{
				continue;
			}
			MonsterInfo.Section s = new MonsterInfo.Section(ws.title);
			s.collapsible = true;
			for (int i = 0; i < ws.blocks.size(); i++)
			{
				final WikiHtml.Block b = ws.blocks.get(i);
				if ("table".equals(b.type) && isRecipe(ws.blocks, i))
				{
					// A recipe reads better as its skills, details and materials
					final WikiHtml.Table next = ws.blocks.get(i + 1).table;
					final MonsterInfo.Section r = new MonsterInfo.Section("");
					recipe(r, b.table, next);
					if (!r.rows.isEmpty())
					{
						final MonsterInfo.Table details = new MonsterInfo.Table("full" + (n++), null, false, -1, new boolean[]{false, false});
						for (MonsterInfo.Row row : r.rows)
						{
							details.rows.add(new MonsterInfo.TRow(Arrays.asList(row.label, row.value), Arrays.asList(row.label, row.value), null, null, false));
						}
						r.blocks.add(details);
					}
					s.blocks.addAll(r.blocks);
					i++;
				}
				else if ("table".equals(b.type))
				{
					final MonsterInfo.Table t = table(b.table, "full" + (n++), null, true);
					if (t != null)
					{
						s.blocks.add(t);
					}
				}
				else if (b.text != null)
				{
					char style = "li".equals(b.type) ? MonsterInfo.Para.BULLET : "h".equals(b.type) ? MonsterInfo.Para.SUB : MonsterInfo.Para.TEXT;
					s.blocks.addAll(paras(style, b.text, b.link));
				}
			}
			if (!s.blocks.isEmpty())
			{
				sections.add(s);
			}
		}
		return sections;
	}

	private static String coins(long c)
	{
		return String.format("%,d", c) + (c == 1 ? " coin" : " coins");
	}

	/**
	 * The Stats tab, or null for things that aren't worn. With worn gear to compare against,
	 * each bonus shows how much it changes (null if not comparing).
	 */
	static MonsterInfo stats(Infobox bonuses, double[] diff, String comparedWith)
	{
		if (bonuses == null)
		{
			return null;
		}
		final List<MonsterInfo.Section> sections = new ArrayList<>();
		MonsterInfo.Section attack = new MonsterInfo.Section("Attack bonuses");
		cell(attack, StatIcon.STAB, bonuses.get("astab"), diff, 0);
		cell(attack, StatIcon.SLASH, bonuses.get("aslash"), diff, 1);
		cell(attack, StatIcon.CRUSH, bonuses.get("acrush"), diff, 2);
		cell(attack, StatIcon.MAGIC, bonuses.get("amagic"), diff, 3);
		cell(attack, StatIcon.RANGED, bonuses.get("arange"), diff, 4);
		sections.add(attack);

		MonsterInfo.Section defence = new MonsterInfo.Section("Defence bonuses");
		cell(defence, StatIcon.STAB, bonuses.get("dstab"), diff, 5);
		cell(defence, StatIcon.SLASH, bonuses.get("dslash"), diff, 6);
		cell(defence, StatIcon.CRUSH, bonuses.get("dcrush"), diff, 7);
		cell(defence, StatIcon.MAGIC, bonuses.get("dmagic"), diff, 8);
		cell(defence, StatIcon.RANGED, bonuses.get("drange"), diff, 9);
		sections.add(defence);

		MonsterInfo.Section other = new MonsterInfo.Section("Other bonuses");
		cell(other, StatIcon.STRENGTH, bonuses.get("str"), diff, 10);
		cell(other, StatIcon.RANGED_STRENGTH, bonuses.get("rstr"), diff, 11);
		final String mdmg = bonuses.get("mdmg").replace("%", "").trim();
		other.cells.add(new MonsterInfo.Cell(StatIcon.MAGIC_STRENGTH, mdmg.isEmpty() ? "+0%" : MonsterInfo.signedValue(mdmg) + "%",
			difference(diff, 12, "%")));
		cell(other, StatIcon.PRAYER, bonuses.get("prayer"), diff, 13);
		sections.add(other);

		MonsterInfo.Section details = new MonsterInfo.Section("Details");
		details.row("Slot", MonsterInfo.capital(bonuses.get("slot")));
		details.row("Attack speed", MonsterInfo.ticks(bonuses.get("speed")));
		details.row("Attack range", bonuses.get("attackrange"));
		details.row("Combat style", MonsterInfo.capital(bonuses.get("combatstyle")));
		details.row("Compared with", comparedWith);
		sections.add(details);

		// Grids where the wiki gave no numbers at all say nothing
		sections.removeIf(s -> !s.cells.isEmpty() && s.cells.stream().allMatch(c -> c.value.isEmpty()));
		final MonsterInfo out = MonsterInfo.of("", sections, "");
		return out.sections.isEmpty() ? null : out;
	}

	private static void cell(MonsterInfo.Section s, StatIcon icon, String value, double[] diff, int i)
	{
		s.cells.add(new MonsterInfo.Cell(icon, value.isEmpty() ? "+0" : MonsterInfo.signedValue(value), difference(diff, i, "")));
	}

	/**
	 * "+12" or "-3" against worn gear; nothing when it's the same or not comparing.
	 */
	private static String difference(double[] diff, int i, String unit)
	{
		if (diff == null || i >= diff.length || Math.abs(diff[i]) < 0.05)
		{
			return null;
		}
		final double d = diff[i];
		final String n = d == Math.rint(d) ? String.valueOf((long) d) : String.format(Locale.ROOT, "%.1f", d);
		return (d > 0 ? "+" : "") + n + unit;
	}

	/**
	 * The Sources tab: what drops it, shops that sell it, where it spawns and the first way
	 * of making it. Null if the wiki lists none of these.
	 */
	static MonsterInfo sources(WikiHtml.Article article)
	{
		if (article == null)
		{
			return null;
		}
		final List<MonsterInfo.Section> sections = new ArrayList<>();
		final MonsterInfo.Section dropped = new MonsterInfo.Section("Dropped by");
		final MonsterInfo.Section shops = new MonsterInfo.Section("Shops");
		final MonsterInfo.Section spawns = new MonsterInfo.Section("Spawns");
		final MonsterInfo.Section creation = new MonsterInfo.Section("Creation");
		final List<MonsterInfo.Section> made = new ArrayList<>();
		// Each table with the sub-heading above it ("Adamant dagger(p)"), so tables for
		// different versions of the item can be labelled
		final List<Object[]> dropTables = new ArrayList<>();
		final List<Object[]> shopTables = new ArrayList<>();
		final List<Object[]> spawnTables = new ArrayList<>();
		for (WikiHtml.Section ws : article.sections)
		{
			final String title = ws.title == null ? "" : ws.title.toLowerCase(Locale.ROOT);
			String sub = "";
			List<Object[]> last = dropTables;
			for (int i = 0; i < ws.blocks.size(); i++)
			{
				final WikiHtml.Block b = ws.blocks.get(i);
				if ("h".equals(b.type))
				{
					sub = b.text == null ? "" : b.text.trim();
					continue;
				}
				if (!"table".equals(b.type))
				{
					// Sources the wiki describes in words, like a quest reward, or a note on
					// the table before it
					if (title.equals("item sources") && "p".equals(b.type) && b.text != null)
					{
						last.add(new Object[]{sub, new MonsterInfo.Para(MonsterInfo.Para.TEXT,
							b.text.replaceAll(MathText.XML + "[A-Za-z0-9+/=]*", "").replace(MathText.START, "")
								.replace(MathText.END, "").replace(MathText.LINE, "; "), null)});
					}
					continue;
				}
				final WikiHtml.Table t = b.table;
				final String header = headerText(t);
				final String cls = t.cls == null ? "" : t.cls;
				if (cls.contains("item-drops") && header.contains("source"))
				{
					last = dropTables;
					final MonsterInfo.Table drops = table(t, "drops" + dropTables.size(), Kind.NPC, true);
					if (drops != null)
					{
						drops.sources = true;
					}
					keep(last, sub, drops);
				}
				else if (header.startsWith("seller"))
				{
					last = shopTables;
					keep(last, sub, table(t, "shops" + shopTables.size(), Kind.PLACE, true));
				}
				else if (header.startsWith("location") && header.contains("spawns"))
				{
					last = spawnTables;
					keep(last, sub, table(t, "spawns" + spawnTables.size(), Kind.PLACE, true));
				}
				else if (isRecipe(ws.blocks, i))
				{
					// A recipe is a requirements table followed by a materials table
					final MonsterInfo.Section r = new MonsterInfo.Section("");
					recipe(r, t, ws.blocks.get(i + 1).table);
					if (!r.isEmpty())
					{
						made.add(r);
					}
					i++;
				}
			}
		}
		labelled(dropped, dropTables);
		labelled(shops, shopTables);
		labelled(spawns, spawnTables);
		// Every way of making it. With more than one, each is headed by what it's made from
		// ("Using Pure essence")
		for (MonsterInfo.Section r : made)
		{
			if (made.size() == 1)
			{
				creation.rows.addAll(r.rows);
				creation.blocks.addAll(r.blocks);
				break;
			}
			creation.blocks.add(new MonsterInfo.Para(MonsterInfo.Para.SUB, recipeName(r, made.indexOf(r) + 1), null));
			if (!r.rows.isEmpty())
			{
				final MonsterInfo.Table details = new MonsterInfo.Table("made" + made.indexOf(r), null, false, -1, new boolean[]{false, false});
				for (MonsterInfo.Row row : r.rows)
				{
					details.rows.add(new MonsterInfo.TRow(Arrays.asList(row.label, row.value), Arrays.asList(row.label, row.value), null, null, false));
				}
				creation.blocks.add(details);
			}
			creation.blocks.addAll(r.blocks);
		}
		sections.add(dropped);
		sections.add(shops);
		sections.add(spawns);
		sections.add(creation);
		final MonsterInfo out = MonsterInfo.of("", sections, "");
		return out.sections.isEmpty() ? null : out;
	}

	/**
	 * A recipe's heading: what it's made from, or its number if that can't be told.
	 */
	private static String recipeName(MonsterInfo.Section r, int number)
	{
		for (Object o : r.blocks)
		{
			if (o instanceof MonsterInfo.Table && ((MonsterInfo.Table) o).key.equals("materials")
				&& !((MonsterInfo.Table) o).rows.isEmpty())
			{
				final List<String> names = new ArrayList<>();
				for (MonsterInfo.TRow row : ((MonsterInfo.Table) o).rows)
				{
					names.add(row.cells.get(0));
				}
				return "Using " + String.join(" and ", names);
			}
		}
		return "Method " + number;
	}

	private static void keep(List<Object[]> list, String sub, MonsterInfo.Table t)
	{
		if (t != null)
		{
			list.add(new Object[]{sub, t});
		}
	}

	/**
	 * Puts the tables in a section. Where there's more than one table, each gets a small
	 * heading with the wiki's sub-heading above it, such as "Adamant dagger(p)", so it's
	 * clear what each list is for.
	 */
	private static void labelled(MonsterInfo.Section s, List<Object[]> parts)
	{
		int tables = 0;
		for (Object[] part : parts)
		{
			if (part[1] instanceof MonsterInfo.Table)
			{
				tables++;
			}
		}
		String shown = null;
		for (Object[] part : parts)
		{
			final String sub = (String) part[0];
			if (tables > 1 && part[1] instanceof MonsterInfo.Table && !sub.isEmpty() && !sub.equals(shown) && !generic(sub))
			{
				s.blocks.add(new MonsterInfo.Para(MonsterInfo.Para.SUB, sub, null));
				shown = sub;
			}
			s.blocks.add(part[1]);
		}
	}

	/**
	 * Sub-headings that only repeat the section's own name.
	 */
	private static boolean generic(String sub)
	{
		final String l = sub.toLowerCase(Locale.ROOT);
		return l.equals("shop locations") || l.equals("item spawns") || l.equals("spawns") || l.equals("item sources")
			|| l.equals("drop sources");
	}

	/**
	 * A recipe's skills, then its tools and facilities, then its materials up to the total.
	 */
	private static void recipe(MonsterInfo.Section s, WikiHtml.Table skills, WikiHtml.Table materials)
	{
		final MonsterInfo.Table needs = new MonsterInfo.Table("recipe", Arrays.asList("Skill", "Level", "XP"), false, -1,
			new boolean[]{false, true, true});
		for (List<WikiHtml.Cell> r : skills.rows)
		{
			if (r.isEmpty())
			{
				continue;
			}
			if (r.get(0).th)
			{
				// "Ticks | 5" and "Facilities | Anvil" rows, in label and value pairs
				for (int i = 0; i + 1 < r.size(); i += 2)
				{
					final String label = r.get(i).text;
					final String value = r.get(i + 1).text;
					if (!value.isEmpty() && !label.equalsIgnoreCase("members"))
					{
						s.row(label, value);
					}
				}
				continue;
			}
			final List<String> cells = texts(r);
			if (cells.size() >= 2 && cells.get(1).matches("\\d+.*"))
			{
				needs.rows.add(new MonsterInfo.TRow(cells.subList(0, Math.min(3, cells.size())), cells, linkOf(r), null, false));
			}
		}
		if (!needs.rows.isEmpty())
		{
			s.blocks.add(needs);
		}
		if (materials == null || !headerText(materials).startsWith("item"))
		{
			return;
		}
		final MonsterInfo.Table mats = new MonsterInfo.Table("materials", Arrays.asList("Material", "Qty", "Cost"), false, -1,
			new boolean[]{false, true, true});
		for (List<WikiHtml.Cell> r : materials.rows)
		{
			final List<String> cells = texts(r);
			if (cells.isEmpty() || cells.get(0).toLowerCase(Locale.ROOT).startsWith("total"))
			{
				break;
			}
			if (cells.size() >= 2)
			{
				final List<String> shown = new ArrayList<>(cells.subList(0, Math.min(3, cells.size())));
				while (shown.size() < 3)
				{
					shown.add("");
				}
				mats.rows.add(new MonsterInfo.TRow(shown, shown, linkOf(r), Kind.ITEM, true));
			}
		}
		if (!mats.rows.isEmpty())
		{
			s.blocks.add(mats);
		}
	}

	/**
	 * A recipe: a skills table ("Skill | Level | XP") straight after which comes its
	 * materials table. Other tables of skill levels (a clue scroll's requirements) aren't.
	 */
	private static boolean isRecipe(List<WikiHtml.Block> blocks, int i)
	{
		final WikiHtml.Block b = blocks.get(i);
		if (!"table".equals(b.type) || i + 1 >= blocks.size() || !"table".equals(blocks.get(i + 1).type))
		{
			return false;
		}
		final String header = headerText(b.table);
		return header.startsWith("skill") && header.contains("level") && headerText(blocks.get(i + 1).table).startsWith("item");
	}

	/**
	 * What an item holds, for reward caskets and the like: their reward tables, under
	 * each wiki heading, with the wiki's sub-headings ("Medium clue uniques") over each
	 * table. The first part is open and later ones ("Rewards on Entrana") start folded.
	 * Null if the item holds nothing.
	 */
	static MonsterInfo loot(WikiHtml.Article article)
	{
		if (article == null)
		{
			return null;
		}
		final List<MonsterInfo.Section> sections = new ArrayList<>();
		int n = 0;
		for (WikiHtml.Section ws : article.sections)
		{
			final MonsterInfo.Section s = new MonsterInfo.Section(ws.title == null ? "Loot" : ws.title);
			String sub = "";
			for (WikiHtml.Block b : ws.blocks)
			{
				if ("h".equals(b.type))
				{
					sub = b.text == null ? "" : b.text.trim();
					continue;
				}
				if (!"table".equals(b.type) || b.table.cls == null || !b.table.cls.contains("item-drops"))
				{
					continue;
				}
				final String header = headerText(b.table);
				if (header.contains("source") || !header.contains("item"))
				{
					continue;
				}
				final MonsterInfo.Table t = table(b.table, "loot" + (n++), Kind.ITEM, true);
				if (t == null)
				{
					continue;
				}
				if (!sub.isEmpty())
				{
					s.blocks.add(new MonsterInfo.Para(MonsterInfo.Para.SUB, sub, null));
					sub = "";
				}
				s.blocks.add(t);
			}
			if (!s.blocks.isEmpty())
			{
				s.collapsible = !sections.isEmpty();
				sections.add(s);
			}
		}
		final MonsterInfo out = MonsterInfo.of("", sections, "");
		return out.sections.isEmpty() ? null : out;
	}

	/**
	 * A clue scroll step's own page: the clue's text, the items it needs and its notes,
	 * from its Clue info box. Null for other pages.
	 */
	static MonsterInfo.Section clue(String wikitext)
	{
		if (wikitext == null)
		{
			return null;
		}
		final Matcher m = Pattern.compile("\\{\\{\\s*Clue info", Pattern.CASE_INSENSITIVE).matcher(wikitext);
		if (!m.find())
		{
			return null;
		}
		final MonsterInfo.Section s = new MonsterInfo.Section("Clue");
		String text = "";
		String items = "";
		String notes = "";
		for (String line : wikitext.substring(m.end()).split("\\n\\|"))
		{
			final int eq = line.indexOf('=');
			if (eq < 0)
			{
				continue;
			}
			final String key = line.substring(0, eq).trim().toLowerCase(Locale.ROOT);
			String value = line.substring(eq + 1);
			final int end = value.indexOf("\n}}");
			if (end >= 0)
			{
				value = value.substring(0, end);
			}
			value = Infobox.clean(value.replaceAll("(?i)<br\\s*/?>", " ")).trim();
			if (key.equals("text"))
			{
				text = value;
			}
			else if (key.equals("items"))
			{
				items = value;
			}
			else if (key.equals("notes"))
			{
				notes = value;
			}
			if (end >= 0)
			{
				break;
			}
		}
		if (!text.isEmpty())
		{
			s.blocks.add(new MonsterInfo.Para(MonsterInfo.Para.KEY, text, null));
		}
		s.row("Items needed", items.isEmpty() || items.equalsIgnoreCase("none") ? "" : items);
		s.row("Notes", notes.equalsIgnoreCase("none") ? "" : notes);
		return s.isEmpty() ? null : s;
	}

	/**
	 * A table's headings, lower case and joined with "|", skipping blank ones over pictures.
	 */
	private static String headerText(WikiHtml.Table t)
	{
		final List<String> h = new ArrayList<>();
		for (String s : t.headers)
		{
			if (s != null && !s.trim().isEmpty())
			{
				h.add(s.trim());
			}
		}
		return String.join("|", h).toLowerCase(Locale.ROOT);
	}

	/**
	 * A row's cell texts, leaving out the picture cells that have no text.
	 */
	private static List<String> texts(List<WikiHtml.Cell> row)
	{
		final List<String> out = new ArrayList<>();
		for (WikiHtml.Cell c : row)
		{
			if (c.text != null && !c.text.isEmpty())
			{
				out.add(c.text);
			}
		}
		return out;
	}

	private static String linkOf(List<WikiHtml.Cell> row)
	{
		for (WikiHtml.Cell c : row)
		{
			if (c.link != null)
			{
				return c.link;
			}
		}
		return null;
	}

	/**
	 * A wiki table cut down to the columns with text in them, sortable like the wiki's.
	 * {@code card} says whether rows can open as a card, with {@code kind} as the likely
	 * kind of page (null to try both).
	 */
	static MonsterInfo.Table table(WikiHtml.Table t, String key, Kind kind, boolean card)
	{
		if (t == null || t.rows.isEmpty())
		{
			return null;
		}
		int cols = t.headers.size();
		for (List<WikiHtml.Cell> r : t.rows)
		{
			cols = Math.max(cols, r.size());
		}
		final List<Integer> keep = new ArrayList<>();
		final Set<Integer> iconColumns = new HashSet<>();
		for (int c = 0; c < cols; c++)
		{
			final String h = c < t.headers.size() ? t.headers.get(c).trim() : "";
			final String squashed = h.toLowerCase(Locale.ROOT).replaceAll("\\s+", "");
			// A shop's own exchange rates for its currency (Tokkul and the like) are left out,
			// so every shop's stock reads the same as a general store's
			if (DROPPED_COLUMNS.contains(squashed) || squashed.startsWith("pricebought")
				|| squashed.contains("obtainedfrom") || squashed.contains("spentfor"))
			{
				continue;
			}
			int text = 0;
			int pictures = 0;
			for (List<WikiHtml.Cell> r : t.rows)
			{
				if (c < r.size() && r.get(c).text != null && !r.get(c).text.isEmpty())
				{
					text++;
				}
				if (c < r.size() && r.get(c).icons != null)
				{
					pictures++;
				}
			}
			// A column of pictures (a spell's runes) is kept as pictures
			if (pictures > text)
			{
				iconColumns.add(c);
			}
			if (text > 0 || pictures > text)
			{
				keep.add(c);
			}
		}
		// A picture column that only pictures the next column's page (a spell's icon beside
		// its name, a spellbook's beside "Standard") is folded into that column, the picture
		// in front of the text, rather than taking a column of its own
		final java.util.Map<Integer, Integer> leads = new java.util.HashMap<>();
		for (int k = 0; k + 1 < keep.size(); k++)
		{
			final int c = keep.get(k);
			final int next = keep.get(k + 1);
			if (!iconColumns.contains(c) || iconColumns.contains(next))
			{
				continue;
			}
			int same = 0;
			int with = 0;
			for (List<WikiHtml.Cell> r : t.rows)
			{
				if (c < r.size() && r.get(c).icons != null)
				{
					with++;
					final String title = r.get(c).icons.get(0).split("\\|")[0];
					if (next < r.size() && title.equals(r.get(next).link))
					{
						same++;
					}
				}
			}
			if (with > 0 && same * 10 >= with * 6)
			{
				leads.put(next, c);
				keep.remove(k);
				k--;
			}
		}
		// A column of single pictures that only name a file (the skill icons down the side of
		// a level table) says nothing on its own: each picture is shown with its name
		final Set<Integer> named = new HashSet<>();
		for (int c : keep)
		{
			if (!iconColumns.contains(c) || leads.containsValue(c))
			{
				continue;
			}
			boolean all = true;
			int with = 0;
			for (List<WikiHtml.Cell> r : t.rows)
			{
				final WikiHtml.Cell cell = c < r.size() ? r.get(c) : null;
				if (cell == null || cell.icons == null)
				{
					continue;
				}
				with++;
				final String[] part = cell.icons.get(0).split("\\|");
				all &= cell.icons.size() == 1 && (cell.text == null || cell.text.isEmpty())
					&& part.length > 3 && "f".equals(part[3]) && "0".equals(part[1]);
			}
			if (with > 0 && all)
			{
				named.add(c);
			}
		}
		iconColumns.removeAll(named);
		if (keep.isEmpty())
		{
			return null;
		}
		final List<String> headers = new ArrayList<>();
		boolean anyHeader = false;
		for (int c : keep)
		{
			final String h = c < t.headers.size() ? tidyHeader(t.headers.get(c)) : "";
			anyHeader |= !h.isEmpty();
			headers.add(h);
		}
		int sortCol = -1;
		// Drop sources start commonest first, whatever the wiki's own order
		final int rarity = headers.indexOf("Rarity");
		if (t.cls != null && t.cls.contains("item-drops") && rarity >= 0)
		{
			sortCol = rarity;
		}
		final Matcher auto = AUTOSORT.matcher(t.cls == null ? "" : t.cls);
		if (sortCol < 0 && auto.find())
		{
			sortCol = keep.indexOf(Integer.parseInt(auto.group(1)) - 1);
		}
		final boolean[] right = new boolean[keep.size()];
		final int[] numeric = new int[keep.size()];
		final int[] filled = new int[keep.size()];
		final List<MonsterInfo.TRow> rows = new ArrayList<>();
		for (List<WikiHtml.Cell> r : t.rows)
		{
			final List<String> cells = new ArrayList<>();
			final List<String> sort = new ArrayList<>();
			List<String> notes = null;
			List<List<String>> icons = null;
			List<String> lead = null;
			boolean any = false;
			for (int k = 0; k < keep.size(); k++)
			{
				final int c = keep.get(k);
				final WikiHtml.Cell cell = c < r.size() ? r.get(c) : null;
				String text = cell == null || cell.text == null ? "" : cell.text;
				if (named.contains(c) && cell != null && cell.icons != null)
				{
					// The picture's name, with the picture in front of it
					final String icon = cell.icons.get(0);
					text = icon.split("\\|")[0];
					if (k == 0)
					{
						if (lead == null)
						{
							lead = new ArrayList<>();
						}
						lead.add(icon);
					}
					else
					{
						if (icons == null)
						{
							icons = new ArrayList<>();
						}
						while (icons.size() < k)
						{
							icons.add(null);
						}
						icons.add(cell.icons);
						cells.add(Rich.mark(0) + " " + text);
						sort.add(text);
						any = true;
						filled[k]++;
						continue;
					}
				}
				// The first column's link names the row; anything after it is a note under it
				// ("Cave bug" and "Level 96"). The wiki often puts the note inside the link, so
				// the linked page's title is tried too.
				final String name = k != 0 || cell == null ? null
					: startsName(text, cell.linkText) ? cell.linkText : startsName(text, cell.link) ? cell.link : null;
				if (name != null)
				{
					notes = new ArrayList<>();
					notes.add(text.substring(name.length()).trim());
					text = name;
				}
				// Text with pictures in it is shown with each picture in its place (the skill
				// icon by each unlock level), when it isn't a column of pictures
				final boolean rich = name == null && cell != null && cell.rich != null && !iconColumns.contains(c) && k > 0;
				cells.add(rich ? cell.rich : text);
				final Integer from = leads.get(c);
				if (from != null && from < r.size() && r.get(from).icons != null)
				{
					if (lead == null)
					{
						lead = new ArrayList<>();
					}
					while (lead.size() < k)
					{
						lead.add(null);
					}
					lead.add(r.get(from).icons.get(0));
				}
				// Pictures are kept for a column of pictures, and for a short value with a
				// small picture or two by it (a skill icon by an unlock level)
				if (cell != null && cell.icons != null && (iconColumns.contains(c) || rich))
				{
					if (icons == null)
					{
						icons = new ArrayList<>();
					}
					while (icons.size() < k)
					{
						icons.add(null);
					}
					icons.add(cell.icons);
					any = true;
				}
				sort.add(cell != null && cell.sort != null ? cell.sort : text);
				if (!text.isEmpty())
				{
					any = true;
					filled[k]++;
					if (NUMERIC.matcher(text.toLowerCase(Locale.ROOT)).matches() || text.equalsIgnoreCase("always") || text.equalsIgnoreCase("n/a"))
					{
						numeric[k]++;
					}
				}
			}
			if (any)
			{
				final String link = linkOf(r);
				final MonsterInfo.TRow row = new MonsterInfo.TRow(cells, sort, link, kind, card && link != null);
				row.notes = notes;
				row.icons = icons;
				row.lead = lead;
				rows.add(row);
			}
		}
		for (int k = 0; k < keep.size(); k++)
		{
			// Short number-like columns are kept narrow and centred, like the wiki's
			right[k] = k > 0 && (COMPACT.contains(headers.get(k).toLowerCase(Locale.ROOT))
				|| filled[k] > 0 && numeric[k] * 10 >= filled[k] * 7)
				// A column of only pictures is kept narrow too
				|| iconColumns.contains(keep.get(k)) && filled[k] == 0;
		}
		final boolean sortable = anyHeader && t.cls != null && t.cls.contains("sortable");
		final MonsterInfo.Table out = new MonsterInfo.Table(key, anyHeader ? headers : null, sortable, sortCol, right);
		// Drop and reward lists read best with every row the same height
		out.uniform = t.cls != null && t.cls.contains("item-drops");
		out.rows.addAll(rows);
		return out;
	}

	private static boolean startsName(String text, String name)
	{
		return name != null && !name.isEmpty() && text.length() > name.length() + 1 && text.startsWith(name)
			&& text.charAt(name.length()) == ' ';
	}

	/**
	 * "Numberin stock" (two lines run together) as "Stock", and the like.
	 */
	private static String tidyHeader(String h)
	{
		final String l = h.toLowerCase(Locale.ROOT).replaceAll("\\s+", "");
		if (l.contains("instock"))
		{
			return "Stock";
		}
		if (l.contains("pricesold") || l.startsWith("price"))
		{
			return "Price";
		}
		if (l.equals("quantity"))
		{
			return "Qty";
		}
		return h.trim();
	}
}

package com.wikipeek;

/**
 * What a lookup is of: an NPC (a monster page) or an item.
 */
enum Kind
{
	NPC("NPC", "Template:Infobox Monster", "npcs1.json"),
	ITEM("Item", "Template:Infobox Item", "items1.json"),
	/**
	 * NPCs you can't fight (slayer masters, shopkeepers), for the search box only.
	 */
	PERSON("NPC", "Template:Infobox NPC", "people1.json"),
	/**
	 * Places, shops and objects, for the search box only.
	 */
	PLACE("Place", "Template:Infobox Location", "places1.json"),
	SHOP("Shop", "Template:Infobox Shop", "shops1.json"),
	OBJECT("Object", "Template:Infobox Scenery", "objects1.json"),
	/**
	 * Any other wiki page found by the wiki's own search as you type (a strategy guide, a
	 * quest), for the search box only. Has no list of its own.
	 */
	PAGE("Page", null, null);

	/**
	 * Only shown as a card for any wiki page, not a monster or item card.
	 */
	boolean isPage()
	{
		return this != NPC && this != ITEM;
	}

	final String label;
	final String template;
	final String titlesFile;

	Kind(String label, String template, String titlesFile)
	{
		this.label = label;
		this.template = template;
		this.titlesFile = titlesFile;
	}
}

