{
	TABS("Tabs"),
	SINGLE_PAGE("Single page");

	private final String label;

	Layout(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.wikipeek;

import java.awt.image.BufferedImage;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * The NPC the pop-out is showing, and what has arrived for it so far. Filled in from other
 * threads; every change bumps the version so the overlay knows to redraw.
 */
final class Lookup
{
	enum State
	{
		LOADING,
		READY,
		NOT_FOUND,
		ERROR
	}

	final Kind kind;
	/**
	 * The NPC's or item's ID, or -1 for a search.
	 */
	final int npcId;
	final int combat;
	/**
	 * The tabs along the bottom, in order.
	 */
	private volatile java.util.List<Tab> tabs;
	/**
	 * For an item: its equipment stats (null if not worn) and where it comes from.
	 */
	private volatile MonsterInfo stats;
	private volatile MonsterInfo sources;
	/**
	 * The NPC's name, or for a search, what was typed until the page's title is known.
	 */
	private volatile String name;
	/**
	 * Whether the portrait has been clicked to show it full size.
	 */
	private volatile boolean expanded;

	private volatile State state = State.LOADING;
	private volatile MonsterInfo info;
	private volatile String url;
	/**
	 * The drop table once its prices and pictures are in, or null until then.
	 */
	private volatile List<Drops.Group> drops;
	private volatile BufferedImage image;
	private volatile Tab tab;
	/**
	 * Scroll offset for the Info tab, the Loot tab and the single page.
	 */
	private final int[] scroll = new int[Tab.values().length + 1];
	private final AtomicInteger version = new AtomicInteger();
	/**
	 * How each table is sorted: column * 2, plus 1 if reversed. Tables not here are in the
	 * wiki's own order.
	 */
	private final java.util.Map<String, Integer> sorts = new java.util.concurrent.ConcurrentHashMap<>();
	/**
	 * Folded sections that have been opened, by title.
	 */
	private final java.util.Set<String> opened = java.util.concurrent.ConcurrentHashMap.newKeySet();

	/**
	 * For an NPC page covering several monsters: their names, and which is shown.
	 */
	private volatile List<String> versions = java.util.Collections.emptyList();
	private volatile int shownVersion = -1;
	/**
	 * The page, kept so another version can be shown without fetching it again.
	 */
	private volatile WikiClient.Page page;
	/**
	 * For an item that holds loot of its own (a reward casket): what it gives.
	 */
	private volatile MonsterInfo loot;

	/**
	 * The versions dropdown is open.
	 */
	private volatile boolean listOpen;

	boolean isListOpen()
	{
		return listOpen;
	}

	void setListOpen(boolean open)
	{
		if (listOpen != open)
		{
			listOpen = open;
			changed();
		}
	}

	List<String> getVersions()
	{
		return versions;
	}

	int getShownVersion()
	{
		return shownVersion;
	}

	void setVersions(List<String> versions, int shown)
	{
		this.versions = versions;
		this.shownVersion = shown;
		changed();
	}

	WikiClient.Page getPage()
	{
		return page;
	}

	void setPage(WikiClient.Page page)
	{
		this.page = page;
	}

	MonsterInfo getLoot()
	{
		return loot;
	}

	/**
	 * Back to the top of every tab, for when the card shows something new.
	 */
	void resetScroll()
	{
		java.util.Arrays.fill(scroll, 0);
		changed();
	}

	/**
	 * The cards before and after this one on the same card, for back and forward.
	 */
	private volatile Lookup back;
	private volatile Lookup forward;

	Lookup getBack()
	{
		return back;
	}

	Lookup getForward()
	{
		return forward;
	}

	/**
	 * Opened from a link on {@code from}: back leads there, and its forward leads here.
	 */
	void openedFrom(Lookup from)
	{
		back = from;
		if (from != null)
		{
			from.forward = this;
		}
	}

	/**
	 * Shown as a card for any wiki page (not a monster or item), so versions come from its
	 * own infobox.
	 */
	volatile boolean generic;
	/**
	 * For an object's card, its ID, so its examine text can be added once it's examined.
	 */
	volatile int objectId = -1;

	Integer getSort(String table)
	{
		return sorts.get(table);
	}

	/**
	 * Sorts a table by a column, or reverses it if it's already sorted by that column.
	 */
	void sortBy(String table, int column, int current)
	{
		sorts.put(table, current == column * 2 ? column * 2 + 1 : column * 2);
		changed();
	}

	boolean isOpened(String section)
	{
		return opened.contains(section);
	}

	void toggle(String section)
	{
		if (!opened.remove(section))
		{
			opened.add(section);
		}
		changed();
	}

	Lookup(Kind kind, int npcId, String name, int combat, java.util.List<Tab> tabs)
	{
		this.kind = kind;
		this.tabs = tabs;
		this.tab = tabs.get(0);
		this.npcId = npcId;
		this.name = name;
		this.combat = combat;
	}

	java.util.List<Tab> getTabs()
	{
		return tabs;
	}

	/**
	 * Takes a tab off (Loot for an NPC with no drops), moving to Info if it was open.
	 */
	void removeTab(Tab gone)
	{
		final java.util.List<Tab> t = new java.util.ArrayList<>(tabs);
		if (t.size() > 1 && t.remove(gone))
		{
			tabs = t;
			if (tab == gone)
			{
				tab = t.get(0);
			}
			changed();
		}
	}

	MonsterInfo getStats()
	{
		return stats;
	}

	MonsterInfo getSources()
	{
		return sources;
	}

	/**
	 * An item's tabs and what's on them, all at once.
	 */
	void readyItem(MonsterInfo info, MonsterInfo stats, MonsterInfo loot, MonsterInfo sources, String url)
	{
		this.stats = stats;
		this.sources = sources;
		this.loot = loot;
		// Tabs with nothing on them are left off
		java.util.List<Tab> t = new java.util.ArrayList<>(tabs);
		if (loot == null)
		{
			t.remove(Tab.LOOT);
		}
		if (stats == null)
		{
			t.remove(Tab.STATS);
		}
		if (sources == null)
		{
			t.remove(Tab.SOURCES);
		}
		this.tabs = t;
		if (!t.contains(tab))
		{
			tab = Tab.INFO;
		}
		ready(info, url);
	}

	String getName()
	{
		return name;
	}

	void setName(String name)
	{
		this.name = name;
		changed();
	}

	boolean isExpanded()
	{
		return expanded;
	}

	void setExpanded(boolean expanded)
	{
		this.expanded = expanded;
		changed();
	}

	// Finding words on the card (Ctrl+F over it): the words, or null when the find bar is shut

	private volatile String find;
	private volatile int findAt;
	private volatile boolean findJump;

	boolean isFinding()
	{
		return find != null;
	}

	String getFind()
	{
		return find;
	}

	void openFind()
	{
		if (find == null)
		{
			find = "";
			findAt = 0;
			changed();
		}
	}

	void closeFind()
	{
		if (find != null)
		{
			find = null;
			changed();
		}
	}

	/**
	 * New words to find: the first match comes into view.
	 */
	void setFind(String text)
	{
		if (find != null)
		{
			find = text.length() > 60 ? text.substring(0, 60) : text;
			findAt = 0;
			findJump = true;
			changed();
		}
	}

	/**
	 * Moves to the next match, or back a match.
	 */
	void stepFind(int delta)
	{
		if (find != null)
		{
			findAt += delta;
			findJump = true;
			changed();
		}
	}

	int getFindAt()
	{
		return findAt;
	}

	/**
	 * The match number put back in range once the card knows how many there are.
	 */
	void keepFindAt(int at)
	{
		findAt = at;
	}

	/**
	 * Whether the card should scroll to the current match, asked once per move.
	 */
	boolean takeFindJump()
	{
		final boolean jump = findJump;
		findJump = false;
		return jump;
	}

	int version()
	{
		return version.get();
	}

	void changed()
	{
		version.incrementAndGet();
	}

	State getState()
	{
		return state;
	}

	MonsterInfo getInfo()
	{
		return info;
	}

	String getUrl()
	{
		return url;
	}

	List<Drops.Group> getDrops()
	{
		return drops;
	}

	BufferedImage getImage()
	{
		return image;
	}

	Tab getTab()
	{
		return tab;
	}

	void ready(MonsterInfo info, String url)
	{
		this.info = info;
		this.url = url;
		this.state = State.READY;
		changed();
	}

	void failed(State state, String url)
	{
		this.url = url;
		this.state = state;
		changed();
	}

	void setDrops(List<Drops.Group> drops)
	{
		this.drops = drops;
		changed();
	}

	void setImage(BufferedImage image)
	{
		this.image = image;
		changed();
	}

	void setTab(Tab tab)
	{
		this.tab = tab;
		changed();
	}

	int getScroll(int slot)
	{
		return scroll[slot];
	}

	void setScroll(int slot, int value)
	{
		if (scroll[slot] != value)
		{
			scroll[slot] = value;
			changed();
		}
	}
}

package com.wikipeek;

import java.awt.Color;
import java.awt.Graphics2D;
import java.util.Locale;

/**
 * A font that marks the words being found on a card as it draws them: a band behind each
 * match, brighter on the match being looked at.
 */
final class Marker implements CardFont
{
	private static final Color BAND = new Color(255, 225, 40, 150);
	private static final Color CURRENT = new Color(255, 140, 0, 220);

	private final CardFont font;
	private final String words;
	private final boolean current;

	Marker(CardFont font, String words, boolean current)
	{
		this.font = font;
		this.words = words;
		this.current = current;
	}

	/**
	 * The font underneath, if this is a marker.
	 */
	static CardFont plain(CardFont f)
	{
		return f instanceof Marker ? ((Marker) f).font : f;
	}

	@Override
	public int width(String s)
	{
		return font.width(s);
	}

	@Override
	public int ascent()
	{
		return font.ascent();
	}

	@Override
	public int lineHeight()
	{
		return font.lineHeight();
	}

	@Override
	public int digitMiddle()
	{
		return font.digitMiddle();
	}

	@Override
	public void draw(Graphics2D g, String s, int x, int y, Color colour)
	{
		band(g, s, x, y);
		font.draw(g, s, x, y, colour);
	}

	/**
	 * The bands behind the found words in this text, drawn before the text itself.
	 */
	void band(Graphics2D g, String s, int x, int y)
	{
		if (s == null || words.isEmpty())
		{
			return;
		}
		final String lower = s.toLowerCase(Locale.ROOT);
		int at = lower.indexOf(words);
		while (at >= 0)
		{
			final int x0 = x + font.width(s.substring(0, at));
			final int w = font.width(s.substring(at, at + words.length()));
			g.setColor(current ? CURRENT : BAND);
			g.fillRect(x0 - 1, y - font.ascent(), w + 2, font.lineHeight());
			at = lower.indexOf(words, at + words.length());
		}
	}
}

package com.wikipeek;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * Slayer masters as the wiki's infobox names them, with their display names and the wiki
 * file of their chathead.
 */
final class Masters
{
	private static final Map<String, String> NAMES = new HashMap<>();
	private static final Map<String, String> FILES = new HashMap<>();

	static
	{
		NAMES.put("konar", "Konar");
		FILES.put("konar", "Konar quo Maten chathead.png");
	}

	private Masters()
	{
	}

	static String name(String code)
	{
		String known = NAMES.get(code);
		if (known != null)
		{
			return known;
		}
		return code.isEmpty() ? code : Character.toUpperCase(code.charAt(0)) + code.substring(1).toLowerCase(Locale.ROOT);
	}

	static String file(String code)
	{
		String known = FILES.get(code);
		return known != null ? known : name(code) + " chathead.png";
	}
}

package com.wikipeek;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.font.FontRenderContext;
import java.awt.geom.Rectangle2D;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Lays a formula out the way the wiki shows it, by the rules MathML and TeX share: a
 * fraction's top and bottom a size smaller than the line it sits in (and smaller again
 * inside another fraction), powers raised and smaller, spaces round + and =, a table's
 * columns lined up as the wiki aligns them, brackets as tall as what they hold. Drawn in a
 * smoothed serif font like the wiki's.
 */
abstract class MathBox
{
	int w;
	int asc;
	int desc;

	abstract void draw(Graphics2D g, int x, int baseline, Color ink);

	int height()
	{
		return asc + desc;
	}

	/**
	 * A formula's layout with its main text at this size in pixels, or null if it can't
	 * be laid out.
	 */
	static MathBox of(String xml, int size)
	{
		try
		{
			final MathText.Node root = MathText.parse(xml);
			MathText.Node math = root;
			for (MathText.Node k : root.kids)
			{
				if (k.tag.equals("math"))
				{
					math = k;
				}
			}
			final boolean display = "block".equals(math.attr("display"));
			return new Layout(size).box(math, 0, display);
		}
		catch (RuntimeException e)
		{
			return null;
		}
	}

	// Fonts

	/**
	 * The serif font at one size: Times New Roman where it's installed (as the wiki is
	 * usually drawn on Windows), or one of the same measurements, else Java's own serif.
	 */
	static final class MathFont
	{
		private static final FontRenderContext FRC = new FontRenderContext(null, true, true);
		private static final Map<String, MathFont> MADE = new HashMap<>();
		private static String family;

		final Font font;
		final int size;

		private MathFont(Font font, int size)
		{
			this.font = font;
			this.size = size;
		}

		/**
		 * Java's own serif, which looks through the computer's other fonts for symbols the
		 * main one lacks (the "is in" sign).
		 */
		static synchronized MathFont any(int size, boolean italic)
		{
			return MADE.computeIfAbsent(size + (italic ? "i" : "") + "*", k -> new MathFont(new Font(Font.SERIF, italic ? Font.ITALIC : Font.PLAIN, size), size));
		}

		static synchronized MathFont get(int size, boolean italic)
		{
			if (family == null)
			{
				// Times New Roman, or a font made to the same measurements, else any serif
				family = Font.SERIF;
				for (String f : new String[]{"Times New Roman", "Liberation Serif", "Tinos", "Nimbus Roman", "Times"})
				{
					if (new Font(f, Font.PLAIN, 12).getFamily(Locale.ROOT).equalsIgnoreCase(f))
					{
						family = f;
						break;
					}
				}
			}
			final String key = size + (italic ? "i" : "");
			return MADE.computeIfAbsent(key, k -> new MathFont(new Font(family, italic ? Font.ITALIC : Font.PLAIN, size), size));
		}

		int width(String s)
		{
			return (int) Math.ceil(font.getStringBounds(s, FRC).getWidth());
		}

		/**
		 * How far the ink of this text reaches above and below the baseline.
		 */
		int[] ink(String s)
		{
			final Rectangle2D b = font.createGlyphVector(FRC, s).getVisualBounds();
			final int up = (int) Math.ceil(-b.getY());
			final int down = (int) Math.ceil(b.getY() + b.getHeight());
			return new int[]{Math.max(up, size * 2 / 3), Math.max(down, 1)};
		}

		/**
		 * The height of the maths axis, where fraction bars and the middle of a minus sit.
		 */
		int axis()
		{
			return Math.max(2, Math.round(size * 0.27f));
		}

		boolean shows(String s)
		{
			return font.canDisplayUpTo(s) < 0;
		}
	}

	// Boxes

	private static final class Text extends MathBox
	{
		final String s;
		final MathFont f;

		Text(String s, MathFont f)
		{
			this.s = s;
			this.f = f;
			w = f.width(s);
			final int[] ink = f.ink(s);
			asc = ink[0];
			desc = ink[1];
		}

		@Override
		void draw(Graphics2D g, int x, int baseline, Color ink)
		{
			smooth(g);
			g.setFont(f.font);
			g.setColor(ink);
			g.drawString(s, x, baseline);
		}
	}

	/**
	 * Empty space: round an operator, between table columns.
	 */
	private static final class Gap extends MathBox
	{
		Gap(int width)
		{
			w = width;
		}

		@Override
		void draw(Graphics2D g, int x, int baseline, Color ink)
		{
		}
	}

	private static final class Row extends MathBox
	{
		final List<MathBox> parts = new ArrayList<>();

		void add(MathBox b)
		{
			if (b == null)
			{
				return;
			}
			parts.add(b);
			w += b.w;
			asc = Math.max(asc, b.asc);
			desc = Math.max(desc, b.desc);
		}

		@Override
		void draw(Graphics2D g, int x, int baseline, Color ink)
		{
			for (MathBox b : parts)
			{
				b.draw(g, x, baseline, ink);
				x += b.w;
			}
		}
	}

	private static final class Fraction extends MathBox
	{
		final MathBox top;
		final MathBox bottom;
		final int axis;
		final int gap;

		Fraction(MathBox top, MathBox bottom, int axis, int gap)
		{
			this.top = top;
			this.bottom = bottom;
			this.axis = axis;
			this.gap = gap;
			w = Math.max(top.w, bottom.w) + 4;
			asc = axis + gap + top.height();
			desc = bottom.height() + gap - axis + 1;
		}

		@Override
		void draw(Graphics2D g, int x, int baseline, Color ink)
		{
			final int bar = baseline - axis;
			top.draw(g, x + (w - top.w) / 2, bar - gap - top.desc, ink);
			g.setColor(ink);
			g.fillRect(x + 1, bar, w - 2, 1);
			bottom.draw(g, x + (w - bottom.w) / 2, bar + 1 + gap + bottom.asc, ink);
		}
	}

	private static final class Script extends MathBox
	{
		final MathBox base;
		final MathBox script;
		final int shift;

		Script(MathBox base, MathBox script, int shift)
		{
			this.base = base;
			this.script = script;
			this.shift = shift;
			w = base.w + script.w + 1;
			asc = Math.max(base.asc, script.asc - shift);
			desc = Math.max(base.desc, script.desc + shift);
		}

		@Override
		void draw(Graphics2D g, int x, int baseline, Color ink)
		{
			base.draw(g, x, baseline, ink);
			script.draw(g, x + base.w + 1, baseline + shift, ink);
		}
	}

	/**
	 * A base with both a lower and an upper script (x with subscript i and power 2).
	 */
	private static final class Scripts extends MathBox
	{
		final MathBox base;
		final MathBox low;
		final MathBox high;
		final int down;
		final int up;

		Scripts(MathBox base, MathBox low, MathBox high, int down, int up)
		{
			this.base = base;
			this.low = low;
			this.high = high;
			this.down = down;
			this.up = up;
			w = base.w + Math.max(low.w, high.w) + 1;
			asc = Math.max(base.asc, high.asc + up);
			desc = Math.max(base.desc, low.desc + down);
		}

		@Override
		void draw(Graphics2D g, int x, int baseline, Color ink)
		{
			base.draw(g, x, baseline, ink);
			high.draw(g, x + base.w + 1, baseline - up, ink);
			low.draw(g, x + base.w + 1, baseline + down, ink);
		}
	}

	/**
	 * Something with a smaller line above or below it (a sum's limits, an accent).
	 */
	private static final class Stack extends MathBox
	{
		final MathBox base;
		final MathBox over;
		final MathBox under;

		Stack(MathBox base, MathBox over, MathBox under)
		{
			this.base = base;
			this.over = over;
			this.under = under;
			w = Math.max(base.w, Math.max(over == null ? 0 : over.w, under == null ? 0 : under.w));
			asc = base.asc + (over == null ? 0 : over.height() + 2);
			desc = base.desc + (under == null ? 0 : under.height() + 2);
		}

		@Override
		void draw(Graphics2D g, int x, int baseline, Color ink)
		{
			base.draw(g, x + (w - base.w) / 2, baseline, ink);
			if (over != null)
			{
				over.draw(g, x + (w - over.w) / 2, baseline - base.asc - 2 - over.desc, ink);
			}
			if (under != null)
			{
				under.draw(g, x + (w - under.w) / 2, baseline + base.desc + 2 + under.asc, ink);
			}
		}
	}

	private static final class Root extends MathBox
	{
		final MathBox inside;

		Root(MathBox inside)
		{
			this.inside = inside;
			w = inside.w + 10;
			asc = inside.asc + 3;
			desc = inside.desc + 1;
		}

		@Override
		void draw(Graphics2D g, int x, int baseline, Color ink)
		{
			smooth(g);
			g.setColor(ink);
			final int top = baseline - asc;
			final int bottom = baseline + desc;
			g.drawLine(x, bottom - 5, x + 2, bottom - 6);
			g.drawLine(x + 2, bottom - 6, x + 4, bottom);
			g.drawLine(x + 4, bottom, x + 8, top);
			g.drawLine(x + 8, top, x + w, top);
			inside.draw(g, x + 9, baseline, ink);
		}
	}

	/**
	 * Brackets as tall as what they hold.
	 */
	private static final class Fence extends MathBox
	{
		final MathBox inside;
		final String open;
		final String close;
		final int pw;
		final int size;

		Fence(MathBox inside, String open, String close, int size)
		{
			this.inside = inside;
			this.open = open;
			this.close = close;
			this.size = size;
			pw = Math.max(4, size / 3);
			w = inside.w + (open.isEmpty() ? 0 : pw + 1) + (close.isEmpty() ? 0 : pw + 1);
			asc = inside.asc + 1;
			desc = inside.desc + 1;
		}

		@Override
		void draw(Graphics2D g, int x, int baseline, Color ink)
		{
			smooth(g);
			g.setColor(ink);
			final java.awt.Stroke was = g.getStroke();
			g.setStroke(new BasicStroke(1.2f));
			final int top = baseline - asc;
			final int h = asc + desc;
			if (!open.isEmpty())
			{
				bracket(g, open, x, top, h, true);
			}
			if (!close.isEmpty())
			{
				bracket(g, close, x + w - pw, top, h, false);
			}
			g.setStroke(was);
			inside.draw(g, x + (open.isEmpty() ? 0 : pw + 1), baseline, ink);
		}

		private void bracket(Graphics2D g, String b, int x, int top, int h, boolean left)
		{
			switch (b)
			{
				case "[":
				case "]":
				{
					final int stem = left ? x + 1 : x + pw - 2;
					final int arm = left ? x + pw - 1 : x;
					g.drawLine(stem, top, stem, top + h - 1);
					g.drawLine(stem, top, arm, top);
					g.drawLine(stem, top + h - 1, arm, top + h - 1);
					break;
				}
				case "|":
					g.drawLine(x + pw / 2, top, x + pw / 2, top + h - 1);
					break;
				case "\u230a":
				case "\u230b":
				case "\u2308":
				case "\u2309":
				{
					// Floor brackets have their arms at the bottom, ceiling brackets at the top
					final boolean floor = b.equals("\u230a") || b.equals("\u230b");
					final int stem = left ? x + 1 : x + pw - 2;
					final int arm = left ? x + pw - 1 : x;
					final int y = floor ? top + h - 1 : top;
					g.drawLine(stem, top, stem, top + h - 1);
					g.drawLine(stem, y, arm, y);
					break;
				}
				case "{":
				case "}":
					brace(g, x, top, h, pw, left);
					break;
				default:
					// Round brackets: the left or right part of a tall ellipse
					g.drawArc(left ? x + 1 : x - pw + 2, top, 2 * pw - 2, h - 1, left ? 105 : 285, 150);
					break;
			}
		}
	}

	private static void brace(Graphics2D g, int x, int top, int h, int pw, boolean left)
	{
		final int mid = top + h / 2;
		final int bottom = top + h - 1;
		final int c = x + pw / 2;
		final int out = left ? x + pw - 1 : x;
		final int in = left ? x : x + pw - 1;
		g.drawLine(out, top, c, top + 2);
		g.drawLine(c, top + 2, c, mid - 2);
		g.drawLine(c, mid - 2, in, mid);
		g.drawLine(in, mid, c, mid + 2);
		g.drawLine(c, mid + 2, c, bottom - 2);
		g.drawLine(c, bottom - 2, out, bottom);
	}

	/**
	 * Rows of cells, each column lined up as the wiki aligns it, centred on the axis.
	 */
	private static final class Table extends MathBox
	{
		final List<List<MathBox>> rows;
		final int[] colW;
		final int[] rowAsc;
		final int[] rowDesc;
		final String[] align;
		final int[] spacing;
		final int rowGap;

		Table(List<List<MathBox>> rows, String[] align, int[] spacing, int rowGap, int axis)
		{
			this.rows = rows;
			this.align = align;
			this.spacing = spacing;
			this.rowGap = rowGap;
			int cols = 0;
			for (List<MathBox> r : rows)
			{
				cols = Math.max(cols, r.size());
			}
			colW = new int[cols];
			rowAsc = new int[rows.size()];
			rowDesc = new int[rows.size()];
			int total = 0;
			for (int i = 0; i < rows.size(); i++)
			{
				for (int c = 0; c < rows.get(i).size(); c++)
				{
					final MathBox b = rows.get(i).get(c);
					colW[c] = Math.max(colW[c], b.w);
					rowAsc[i] = Math.max(rowAsc[i], b.asc);
					rowDesc[i] = Math.max(rowDesc[i], b.desc);
				}
				total += rowAsc[i] + rowDesc[i] + (i > 0 ? rowGap : 0);
			}
			for (int c = 0; c < cols; c++)
			{
				w += colW[c] + (c > 0 ? spacing[Math.min(c - 1, spacing.length - 1)] : 0);
			}
			asc = total / 2 + axis;
			desc = total - asc;
		}

		@Override
		void draw(Graphics2D g, int x, int baseline, Color ink)
		{
			int y = baseline - asc;
			for (int i = 0; i < rows.size(); i++)
			{
				final int rowBase = y + rowAsc[i];
				int cx = x;
				for (int c = 0; c < rows.get(i).size(); c++)
				{
					final MathBox b = rows.get(i).get(c);
					final String a = align[Math.min(c, align.length - 1)];
					final int dx = a.equals("left") ? 0 : a.equals("right") ? colW[c] - b.w : (colW[c] - b.w) / 2;
					b.draw(g, cx + dx, rowBase, ink);
					cx += colW[c] + (c + 1 < colW.length ? spacing[Math.min(c, spacing.length - 1)] : 0);
				}
				y += rowAsc[i] + rowDesc[i] + rowGap;
			}
		}
	}

	/**
	 * A tall brace in front of a table of cases.
	 */
	private static final class Cases extends MathBox
	{
		final MathBox table;
		final int pw;

		Cases(MathBox table, int size)
		{
			this.table = table;
			pw = Math.max(5, size / 2);
			w = table.w + pw + 4;
			asc = table.asc;
			desc = table.desc;
		}

		@Override
		void draw(Graphics2D g, int x, int baseline, Color ink)
		{
			smooth(g);
			g.setColor(ink);
			brace(g, x + 1, baseline - asc, asc + desc, pw, true);
			table.draw(g, x + pw + 4, baseline, ink);
		}
	}

	private static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_ON);
	}

	// Laying out

	private static final class Layout
	{
		final int size;

		Layout(int size)
		{
			this.size = size;
		}

		/**
		 * The text size at a script level: the line, then each level about 0.71 of the one
		 * above, as MathML and TeX shrink them, never too small to read.
		 */
		int size(int level)
		{
			final double s = size * Math.pow(0.71, Math.min(level, 2));
			return Math.max(8, (int) Math.round(s));
		}

		MathFont font(int level)
		{
			return MathFont.get(size(level), false);
		}

		MathBox text(String s, int level, boolean italic)
		{
			if (s == null || s.isEmpty())
			{
				return null;
			}
			final MathFont f = MathFont.get(size(level), italic);
			if (f.shows(s))
			{
				return new Text(s, f);
			}
			final MathFont other = MathFont.any(size(level), italic);
			return other.shows(s) ? new Text(s, other) : new Text(MathText.plain(s), f);
		}

		int em(int level, double times)
		{
			return (int) Math.round(size(level) * times);
		}

		MathBox box(MathText.Node n, int level, boolean display)
		{
			switch (n.tag)
			{
				case "#":
				{
					final String s = n.text.trim();
					return s.isEmpty() ? null : text(s, level, false);
				}
				case "mi":
				{
					final String s = MathText.plainText(n).trim();
					// One letter is a variable, in italic; a name ("Magic") stays upright
					final boolean italic = s.codePointCount(0, s.length()) == 1 && Character.isLetter(s.codePointAt(0))
						&& !"normal".equals(n.attr("mathvariant"));
					return text(s, level, italic);
				}
				case "mn":
					return text(MathText.plainText(n).trim(), level, false);
				case "mtext":
					return text(MathText.plainText(n).replace(' ', ' '), level, false);
				case "ms":
					return text("\"" + MathText.plainText(n) + "\"", level, false);
				case "mo":
					return operator(n, level);
				case "mspace":
				{
					final int width = length(n.attr("width"), level, em(level, 0.28));
					return new Gap(width);
				}
				case "mfrac":
				{
					if (n.kids.size() != 2)
					{
						return row(n, level, display);
					}
					// In a displayed formula a fraction keeps its size; otherwise its top and
					// bottom are a size smaller
					final int inner = display ? level : level + 1;
					final MathBox top = box(n.kids.get(0), inner, false);
					final MathBox bottom = box(n.kids.get(1), inner, false);
					if (top == null || bottom == null)
					{
						return row(n, level, display);
					}
					if ("0".equals(n.attr("linethickness")) || "0px".equals(n.attr("linethickness")))
					{
						return new Stack(top, null, bottom);
					}
					return new Fraction(top, bottom, font(level).axis(), Math.max(1, em(level, display ? 0.15 : 0.1)));
				}
				case "msup":
				case "msub":
				{
					if (n.kids.size() != 2)
					{
						return row(n, level, display);
					}
					final MathBox base = box(n.kids.get(0), level, display);
					final MathBox script = box(n.kids.get(1), level + 1, false);
					if (base == null || script == null)
					{
						return base != null ? base : script;
					}
					final int shift = n.tag.equals("msup")
						? -Math.max(em(level, 0.36), base.asc - script.asc / 2 - 1)
						: Math.max(em(level, 0.15), base.desc + script.asc / 3);
					return new Script(base, script, shift);
				}
				case "msubsup":
				{
					if (n.kids.size() != 3)
					{
						return row(n, level, display);
					}
					final MathBox base = box(n.kids.get(0), level, display);
					final MathBox low = box(n.kids.get(1), level + 1, false);
					final MathBox high = box(n.kids.get(2), level + 1, false);
					if (base == null || low == null || high == null)
					{
						return row(n, level, display);
					}
					return new Scripts(base, low, high, Math.max(em(level, 0.2), base.desc + low.asc / 3),
						Math.max(em(level, 0.38), base.asc - high.asc / 2));
				}
				case "munder":
				case "mover":
				case "munderover":
				{
					final MathBox base = n.kids.isEmpty() ? null : box(n.kids.get(0), level, display);
					if (base == null)
					{
						return row(n, level, display);
					}
					final MathBox a = n.kids.size() > 1 ? box(n.kids.get(1), level + 1, false) : null;
					final MathBox b = n.kids.size() > 2 ? box(n.kids.get(2), level + 1, false) : null;
					if (n.tag.equals("mover"))
					{
						return new Stack(base, a, null);
					}
					return new Stack(base, b, a);
				}
				case "msqrt":
				{
					final MathBox inside = row(n, level, display);
					return inside == null ? null : new Root(inside);
				}
				case "mroot":
				{
					final MathBox inside = n.kids.isEmpty() ? null : box(n.kids.get(0), level, display);
					return inside == null ? null : new Root(inside);
				}
				case "mstyle":
				{
					final String d = n.attr("displaystyle");
					return row(n, level, d == null ? display : d.equals("true"));
				}
				case "mtable":
					return table(n, level);
				case "mphantom":
				{
					final MathBox inside = row(n, level, display);
					if (inside == null)
					{
						return null;
					}
					final Gap gap = new Gap(inside.w);
					gap.asc = inside.asc;
					gap.desc = inside.desc;
					return gap;
				}
				case "annotation":
				case "annotation-xml":
				case "none":
				case "mprescripts":
					return null;
				default:
					return row(n, level, display);
			}
		}

		/**
		 * An operator with the spacing MathML gives it: a little either side of + and -,
		 * a little more round = and the like, a space after a comma, none round brackets.
		 */
		MathBox operator(MathText.Node n, int level)
		{
			String op = MathText.plainText(n).trim();
			if (op.isEmpty())
			{
				return null;
			}
			if (op.equals("-"))
			{
				op = "−";
			}
			if (op.equals("*") || op.equals("⋅"))
			{
				op = op.equals("*") ? "×" : op;
			}
			final MathBox t = text(op, level, false);
			// Scripts are set tighter, as TeX does
			final double scale = level > 0 ? 0.5 : 1;
			final int gap;
			switch (op)
			{
				case "=":
				case "<":
				case ">":
				case "≤":
				case "≥":
				case "≠":
				case "≈":
				case "∈":
				case "∉":
				case "≡":
				case "→":
				case "⇒":
					gap = em(level, 0.28 * scale);
					break;
				case "+":
				case "−":
				case "×":
				case "·":
				case "⋅":
				case "÷":
				case "±":
				case "/":
					gap = op.equals("/") ? 0 : em(level, 0.22 * scale);
					break;
				case ",":
				case ";":
				{
					final Row r = new Row();
					r.add(t);
					r.add(new Gap(em(level, 0.17)));
					return r.parts.size() == 1 ? t : r;
				}
				default:
					gap = 0;
					break;
			}
			if (gap == 0)
			{
				return t;
			}
			final Row r = new Row();
			r.add(new Gap(gap));
			r.add(t);
			r.add(new Gap(gap));
			return r;
		}

		MathBox table(MathText.Node n, int level)
		{
			final List<List<MathBox>> rows = new ArrayList<>();
			for (MathText.Node tr : n.kids)
			{
				if (!tr.tag.equals("mtr") && !tr.tag.equals("mlabeledtr"))
				{
					continue;
				}
				final List<MathBox> cells = new ArrayList<>();
				for (MathText.Node td : tr.kids)
				{
					// A table's cells are never displayed size, as MathML lays them out
					final MathBox cell = row(td, level, false);
					cells.add(cell == null ? new Gap(0) : cell);
				}
				if (!cells.isEmpty())
				{
					rows.add(cells);
				}
			}
			if (rows.isEmpty())
			{
				return null;
			}
			final String alignAttr = n.attr("columnalign");
			final String[] align = alignAttr == null || alignAttr.trim().isEmpty() ? new String[]{"center"} : alignAttr.trim().split("\\s+");
			final String spaceAttr = n.attr("columnspacing");
			final String[] spaces = spaceAttr == null || spaceAttr.trim().isEmpty() ? new String[]{"0.8em"} : spaceAttr.trim().split("\\s+");
			final int[] spacing = new int[spaces.length];
			for (int i = 0; i < spaces.length; i++)
			{
				spacing[i] = length(spaces[i], level, em(level, 0.8));
			}
			final String rowAttr = n.attr("rowspacing");
			final int rowGap = length(rowAttr == null ? null : rowAttr.trim().split("\\s+")[0], level, em(level, 0.5));
			return new Table(rows, align, spacing, Math.max(2, rowGap), font(level).axis());
		}

		/**
		 * A MathML length ("0.8em", "3pt", "2px") in pixels.
		 */
		int length(String v, int level, int fallback)
		{
			if (v == null)
			{
				return fallback;
			}
			final java.util.regex.Matcher m = LENGTH.matcher(v.trim());
			if (!m.matches())
			{
				return fallback;
			}
			final double num = Double.parseDouble(m.group(1));
			final String unit = m.group(2);
			switch (unit)
			{
				case "em":
					return (int) Math.round(num * size(level));
				case "ex":
					return (int) Math.round(num * size(level) * 0.45);
				case "pt":
					return (int) Math.round(num * 1.33);
				case "px":
				case "":
					return (int) Math.round(num);
				default:
					return fallback;
			}
		}

		MathBox row(MathText.Node n, int level, boolean display)
		{
			final Row row = new Row();
			for (int i = 0; i < n.kids.size(); i++)
			{
				final MathText.Node k = n.kids.get(i);
				final String op = k.tag.equals("mo") ? MathText.plainText(k).trim() : "";
				// A brace opening a table of cases is drawn tall beside the table
				if (op.equals("{") && i + 1 < n.kids.size() && MathText.has(n.kids.get(i + 1), "mtable"))
				{
					final MathBox next = box(n.kids.get(i + 1), level, display);
					if (next != null)
					{
						row.add(new Cases(next, size(level)));
						i++;
						continue;
					}
				}
				// Brackets round something taller than a line (a fraction) grow to fit it
				final String closer = CLOSERS.get(op);
				if (closer != null)
				{
					int depth = 0;
					int match = -1;
					for (int j = i; j < n.kids.size(); j++)
					{
						final MathText.Node kj = n.kids.get(j);
						final String t = kj.tag.equals("mo") ? MathText.plainText(kj).trim() : "";
						depth += t.equals(op) && !op.equals(closer) ? 1 : t.equals(closer) ? -1 : 0;
						if (op.equals(closer) && j > i && t.equals(closer))
						{
							depth = 0;
						}
						else if (op.equals(closer) && j == i)
						{
							depth = 1;
						}
						if (depth == 0)
						{
							match = j;
							break;
						}
					}
					if (match > i + 1)
					{
						final Row inner = new Row();
						for (int j = i + 1; j < match; j++)
						{
							inner.add(box(n.kids.get(j), level, display));
						}
						final MathFont f = font(level);
						if (!inner.parts.isEmpty() && inner.height() > f.size + 3)
						{
							row.add(new Fence(inner, op, closer, size(level)));
							i = match;
							continue;
						}
					}
				}
				row.add(box(k, level, display));
			}
			if (row.parts.isEmpty())
			{
				return null;
			}
			return row.parts.size() == 1 ? row.parts.get(0) : row;
		}
	}

	private static final java.util.regex.Pattern LENGTH = java.util.regex.Pattern.compile("(-?[0-9]*\\.?[0-9]+)\\s*([a-z]*)");
	private static final Map<String, String> CLOSERS = new HashMap<>();

	static
	{
		CLOSERS.put("(", ")");
		CLOSERS.put("[", "]");
		CLOSERS.put("{", "}");
		CLOSERS.put("|", "|");
		CLOSERS.put("⌊", "⌋");
		CLOSERS.put("⌈", "⌉");
	}

	// Fitting a narrow card

	/**
	 * The formula broken onto as many lines as it needs to fit the room, at its plus,
	 * minus, times and equals signs and its commas, each later line indented. A table of
	 * formulas whose columns don't fit is restacked a row at a time, each expression
	 * wrapped on its own and the rest of the row under it. A part that can't be broken (one
	 * fraction) stays whole.
	 */
	static MathBox wrapped(MathBox box, int room)
	{
		if (box == null || box.w <= room)
		{
			return box;
		}
		MathBox core = box;
		while (core instanceof Row && ((Row) core).parts.size() == 1)
		{
			core = ((Row) core).parts.get(0);
		}
		if (core instanceof Table)
		{
			return restack((Table) core, room);
		}
		final List<MathBox> atoms = new ArrayList<>();
		flatten(box, atoms, room);
		// Breaks outside brackets read best; inside them only if nothing else fits
		final MathBox outside = breakLines(box, atoms, room, true);
		return outside.w <= room ? outside : breakLines(box, atoms, room, false);
	}

	private static MathBox breakLines(MathBox box, List<MathBox> atoms, int room, boolean outsideOnly)
	{
		final boolean[] open = new boolean[atoms.size()];
		int depth = 0;
		for (int i = 0; i < atoms.size(); i++)
		{
			final String s = atoms.get(i) instanceof Text ? ((Text) atoms.get(i)).s.trim() : "";
			if (s.equals(")") || s.equals("]") || s.equals("}") || s.equals("\u230b") || s.equals("\u2309"))
			{
				depth = Math.max(0, depth - 1);
			}
			open[i] = depth > 0;
			if (s.equals("(") || s.equals("[") || s.equals("{") || s.equals("\u230a") || s.equals("\u2308"))
			{
				depth++;
			}
		}
		final List<MathBox> lines = new ArrayList<>();
		final List<Integer> indents = new ArrayList<>();
		Row line = new Row();
		for (int i = 0; i < atoms.size(); i++)
		{
			final MathBox a = atoms.get(i);
			final int limit = lines.isEmpty() ? room : room - INDENT;
			if (breaks(a) && (!outsideOnly || !open[i]) && hasInk(line) && line.w + width(atoms, i, open, outsideOnly) > limit)
			{
				indents.add(lines.isEmpty() ? 0 : INDENT);
				lines.add(line);
				line = new Row();
			}
			if (!(a instanceof Gap && line.parts.isEmpty() && !lines.isEmpty()))
			{
				line.add(a);
			}
		}
		if (!line.parts.isEmpty())
		{
			indents.add(lines.isEmpty() ? 0 : INDENT);
			lines.add(line);
		}
		return lines.size() < 2 ? box : new Lines(lines, indents, Lines.GAP);
	}

	private static boolean hasInk(Row line)
	{
		for (MathBox b : line.parts)
		{
			if (!(b instanceof Gap))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * A table of formulas a row at a time: its first two cells ("Accuracy" and "= 140 +
	 * ...") together and wrapped, any further cells (the range) each on an indented line.
	 * A table that's already one column per line just has each cell wrapped.
	 */
	private static MathBox restack(Table t, int room)
	{
		final List<MathBox> lines = new ArrayList<>();
		final List<Integer> indents = new ArrayList<>();
		for (List<MathBox> cells : t.rows)
		{
			if (cells.isEmpty())
			{
				continue;
			}
			final Row head = new Row();
			head.add(cells.get(0));
			if (cells.size() > 1)
			{
				head.add(cells.get(1));
			}
			add(lines, indents, wrapped(head, room), 0);
			for (int c = 2; c < cells.size(); c++)
			{
				add(lines, indents, wrapped(cells.get(c), room - INDENT), INDENT);
			}
		}
		return lines.isEmpty() ? t : new Lines(lines, indents, Math.max(Lines.GAP, t.rowGap));
	}

	private static void add(List<MathBox> lines, List<Integer> indents, MathBox b, int indent)
	{
		if (b instanceof Lines)
		{
			final Lines l = (Lines) b;
			for (int i = 0; i < l.lines.size(); i++)
			{
				lines.add(l.lines.get(i));
				indents.add(indent + l.indents.get(i));
			}
		}
		else if (b != null)
		{
			lines.add(b);
			indents.add(indent);
		}
	}

	private static final int INDENT = 18;

	/**
	 * How many lines a laid-out formula takes.
	 */
	static int lineCount(MathBox b)
	{
		return b instanceof Lines ? ((Lines) b).lines.size() : 1;
	}

	/**
	 * The width from this break point to the next one, the piece that has to fit.
	 */
	private static int width(List<MathBox> atoms, int from, boolean[] open, boolean outsideOnly)
	{
		int w = 0;
		for (int i = from; i < atoms.size(); i++)
		{
			if (i > from && breaks(atoms.get(i)) && (!outsideOnly || !open[i]))
			{
				break;
			}
			w += atoms.get(i).w;
		}
		return w;
	}

	private static boolean breaks(MathBox b)
	{
		if (!(b instanceof Text))
		{
			return false;
		}
		switch (((Text) b).s.trim())
		{
			case "+":
			case "-":
			case "−":
			case "×":
			case "=":
			case "<":
			case ">":
			case "≤":
			case "≥":
			case ",":
			case "∈":
				return true;
			default:
				return false;
		}
	}

	private static void flatten(MathBox b, List<MathBox> out, int room)
	{
		if (b instanceof Row)
		{
			for (MathBox part : ((Row) b).parts)
			{
				flatten(part, out, room);
			}
		}
		else if (b instanceof Fence && b.w > room)
		{
			// Brackets round more than fits on a line are opened up, drawn at text height,
			// so what's inside can break across lines
			final Fence f = (Fence) b;
			final MathFont font = MathFont.get(f.size, false);
			if (!f.open.isEmpty())
			{
				out.add(new Text(f.open, font));
			}
			flatten(f.inside, out, room);
			if (!f.close.isEmpty())
			{
				out.add(new Text(f.close, font));
			}
		}
		else
		{
			out.add(b);
		}
	}

	/**
	 * A table of formulas with any columns after the second (a range, a condition) moved
	 * onto their own indented lines under each row, nothing else broken. Anything else is
	 * returned as it is.
	 */
	static MathBox stacked(MathBox box)
	{
		MathBox core = box;
		while (core instanceof Row && ((Row) core).parts.size() == 1)
		{
			core = ((Row) core).parts.get(0);
		}
		if (!(core instanceof Table) || ((Table) core).colW.length < 3)
		{
			return box;
		}
		return restack((Table) core, Integer.MAX_VALUE);
	}

	/**
	 * A formula on several lines, each with its own indent.
	 */
	private static final class Lines extends MathBox
	{
		final List<MathBox> lines;
		final List<Integer> indents;
		final int gap;
		static final int GAP = 6;

		Lines(List<MathBox> lines, List<Integer> indents, int gap)
		{
			this.lines = lines;
			this.indents = indents;
			this.gap = gap;
			asc = lines.get(0).asc;
			desc = lines.get(0).desc;
			for (int i = 0; i < lines.size(); i++)
			{
				w = Math.max(w, lines.get(i).w + indents.get(i));
				if (i > 0)
				{
					desc += gap + lines.get(i).asc + lines.get(i).desc;
				}
			}
		}

		@Override
		void draw(Graphics2D g, int x, int baseline, Color ink)
		{
			int base = baseline;
			for (int i = 0; i < lines.size(); i++)
			{
				if (i > 0)
				{
					base += lines.get(i - 1).desc + gap + lines.get(i).asc;
				}
				lines.get(i).draw(g, x + indents.get(i), base, ink);
			}
		}
	}
}

package com.wikipeek;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Turns the wiki's formulas (written in LaTeX, as on Larran's key) into plain text the
 * game's font can show, and swaps characters the font doesn't have for ones it does.
 */
final class MathText
{
	private static final Pattern MATH = Pattern.compile("<math[\\s>].*?</math>", Pattern.DOTALL);
	private static final Pattern TAG = Pattern.compile("<(/?)([a-zA-Z]+)([^>]*?)(/?)>|([^<]+)");
	private static final Pattern ATTR = Pattern.compile("([a-zA-Z-]+)=\"([^\"]*)\"");
	/**
	 * Marks around a formula, and between the lines of one with several cases.
	 */
	static final String START = "\uE000";
	static final String END = "\uE001";
	static final String LINE = "\uE002";
	static final String XML = "\uE003";

	private static final Pattern FRAC = Pattern.compile("\\\\[dt]?frac\\s*\\{([^{}]*)\\}\\s*\\{([^{}]*)\\}");
	private static final Pattern SQRT = Pattern.compile("\\\\sqrt\\s*\\{([^{}]*)\\}");
	private static final Pattern POWER = Pattern.compile("\\^\\s*\\{([^{}]*)\\}");
	private static final Pattern TEXT = Pattern.compile("\\\\(?:text|mathrm|textrm|operatorname|mbox|textit|mathit|textbf)\\s*\\{([^{}]*)\\}");

	private MathText()
	{
	}

	/**
	 * Replaces each formula in the page's HTML with readable text.
	 */
	static String formulas(String html)
	{
		if (html == null || !html.contains("<math"))
		{
			return html;
		}
		final Matcher m = MATH.matcher(html);
		final StringBuffer out = new StringBuffer();
		while (m.find())
		{
			String text;
			try
			{
				text = mathml(m.group());
			}
			catch (RuntimeException e)
			{
				text = "";
			}
			// A whole formula gets a box of its own (marked here, split out later); a single
			// letter or number stays in the sentence
			if (text.contains("=") || text.length() > 15)
			{
				// The MathML goes along too (encoded so it passes through as text), to be
				// drawn the way the wiki shows it
				final String xml = java.util.Base64.getEncoder().encodeToString(m.group().getBytes(java.nio.charset.StandardCharsets.UTF_8));
				text = START + text + XML + xml + END;
			}
			else
			{
				text = text.replace(LINE, "; ");
			}
			// Escaped, as it goes back into HTML
			m.appendReplacement(out, Matcher.quoteReplacement(" " + text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;") + " "));
		}
		m.appendTail(out);
		return out.toString();
	}

	/**
	 * One element of a formula: its tag and what's inside it.
	 */
	static final class Node
	{
		final String tag;
		final java.util.List<Node> kids = new java.util.ArrayList<>();
		String text;
		/**
		 * The attributes the layout uses (displaystyle, columnalign, mathvariant...).
		 */
		final java.util.Map<String, String> attrs = new java.util.HashMap<>();

		String attr(String name)
		{
			return attrs.get(name);
		}

		Node(String tag)
		{
			this.tag = tag;
		}
	}

	/**
	 * MathML as plain text: fractions as a/b, powers as ^2, the lines of a "cases" table
	 * split by semicolons.
	 */
	static String mathml(String xml)
	{
		return plain(render(parse(xml))).replaceAll("[ \\t\\n\\r]+", " ").replaceAll("\\(\\s+", "(")
			.replaceAll("\\s+\\)", ")").replaceAll("\\s*" + LINE + "\\s*", LINE)
			// A minus sign that starts a bracket is a negative number: (-527, not (- 527
			.replaceAll("\\(\\s*-\\s+", "(-").trim();
	}

	/**
	 * MathML read into a tree of its elements.
	 */
	static Node parse(String xml)
	{
		final Node root = new Node("root");
		final java.util.Deque<Node> open = new java.util.ArrayDeque<>();
		open.push(root);
		final Matcher t = TAG.matcher(xml);
		while (t.find())
		{
			if (t.group(5) != null)
			{
				final Node leaf = new Node("#");
				leaf.text = Infobox.decodeEntities(t.group(5));
				open.peek().kids.add(leaf);
			}
			else if (t.group(1).isEmpty())
			{
				final Node n = new Node(t.group(2).toLowerCase(java.util.Locale.ROOT));
				final Matcher a = ATTR.matcher(t.group(3));
				while (a.find())
				{
					n.attrs.put(a.group(1).toLowerCase(java.util.Locale.ROOT), a.group(2));
				}
				open.peek().kids.add(n);
				if (t.group(4).isEmpty())
				{
					open.push(n);
				}
			}
			else if (open.size() > 1)
			{
				open.pop();
			}
		}
		return root;
	}

	private static String render(Node n)
	{
		switch (n.tag)
		{
			case "#":
				return n.text.trim();
			case "mo":
			{
				final String op = joined(n).trim();
				switch (op)
				{
					case "\u00D7":
					case "\u22C5":
						return " x ";
					case "=":
					case "+":
					case "\u2212":
					case "-":
					case "<":
					case ">":
					case "\u2264":
					case "\u2265":
					case "\u2208":
						return " " + op + " ";
					case ",":
						return ", ";
					default:
						return op;
				}
			}
			case "mtext":
				return " " + joined(n).trim() + " ";
			case "mspace":
				return " ";
			case "mfrac":
				return n.kids.size() == 2 ? group(n.kids.get(0)) + "/" + group(n.kids.get(1)) : joined(n);
			case "msup":
				return n.kids.size() == 2 ? render(n.kids.get(0)) + "^" + group(n.kids.get(1)) : joined(n);
			case "msub":
				return n.kids.size() == 2 ? render(n.kids.get(0)) + render(n.kids.get(1)) : joined(n);
			case "msubsup":
				return n.kids.size() == 3 ? render(n.kids.get(0)) + render(n.kids.get(1)) + "^" + group(n.kids.get(2)) : joined(n);
			case "msqrt":
				return "sqrt(" + joined(n).trim() + ")";
			case "mroot":
				return n.kids.size() == 2 ? "root" + group(n.kids.get(1)) + "(" + render(n.kids.get(0)).trim() + ")" : joined(n);
			case "mtable":
			{
				// A cases table: each line on its own, split by semicolons
				final java.util.List<String> rows = new java.util.ArrayList<>();
				for (Node row : n.kids)
				{
					rows.add(joined(row).trim());
				}
				return " " + String.join(LINE, rows) + " ";
			}
			case "mtd":
				return joined(n) + " ";
			case "annotation":
			case "annotation-xml":
				return "";
			default:
			{
				// A brace that opens a cases table isn't needed in text; instead each case is a
				// line of its own with what comes before it ("P = ... if ...")
				StringBuilder b = new StringBuilder();
				for (int i = 0; i < n.kids.size(); i++)
				{
					final Node k = n.kids.get(i);
					if (k.tag.equals("mo") && joined(k).trim().equals("{") && i + 1 < n.kids.size() && contains(n.kids.get(i + 1), "mtable"))
					{
						final String before = b.toString();
						final String[] cases = render(n.kids.get(i + 1)).trim().split(LINE);
						b = new StringBuilder();
						for (int j = 0; j < cases.length; j++)
						{
							b.append(j > 0 ? LINE : "").append(before).append(cases[j].trim());
						}
						i++;
						continue;
					}
					final String part = render(k);
					if (part.contains(LINE) && b.length() > 0 && !b.toString().contains(LINE))
					{
						// Cases nested a level down still each start with what came before
						final String before = b.toString();
						final String[] cases = part.trim().split(LINE);
						b = new StringBuilder();
						for (int j = 0; j < cases.length; j++)
						{
							b.append(j > 0 ? LINE : "").append(before).append(cases[j].trim());
						}
						continue;
					}
					b.append(part);
				}
				return b.toString();
			}
		}
	}

	static boolean has(Node n, String tag)
	{
		return contains(n, tag);
	}

	/**
	 * All the text inside an element, decoded.
	 */
	static String plainText(Node n)
	{
		if (n.tag.equals("#"))
		{
			return n.text;
		}
		final StringBuilder b = new StringBuilder();
		for (Node k : n.kids)
		{
			b.append(plainText(k));
		}
		return b.toString();
	}

	private static boolean contains(Node n, String tag)
	{
		if (n.tag.equals(tag))
		{
			return true;
		}
		for (Node k : n.kids)
		{
			if (contains(k, tag))
			{
				return true;
			}
		}
		return false;
	}

	private static String joined(Node n)
	{
		final StringBuilder b = new StringBuilder();
		for (Node k : n.kids)
		{
			b.append(render(k));
		}
		return b.toString();
	}

	/**
	 * A part in brackets unless it's a single number or letter.
	 */
	private static String group(Node n)
	{
		final String s = render(n).trim();
		return s.matches("[0-9A-Za-z.]+") ? s : "(" + s + ")";
	}

	/**
	 * A LaTeX formula as plain text: fractions as a/b, powers as ^2, cases split by
	 * semicolons, and symbols spelt out.
	 */
	static String latex(String tex)
	{
		String s = tex.replace("{\\displaystyle", "{").replace("\\displaystyle", "");
		s = s.replace("\\left", "").replace("\\right", "").replace("\\bigl", "").replace("\\bigr", "");
		s = s.replace("\\begin{cases}", "").replace("\\end{cases}", "");
		s = s.replace("\\\\", "; ").replace("&", " ");
		for (int i = 0; i < 6; i++)
		{
			String before = s;
			s = TEXT.matcher(s).replaceAll("$1");
			s = FRAC.matcher(s).replaceAll("($1)/($2)");
			s = SQRT.matcher(s).replaceAll("sqrt($1)");
			s = POWER.matcher(s).replaceAll("^($1)");
			if (s.equals(before))
			{
				break;
			}
		}
		s = s.replace("\\times", " x ").replace("\\cdot", " x ").replace("\\div", " / ")
			.replace("\\leq", " <= ").replace("\\le", " <= ").replace("\\geq", " >= ").replace("\\ge", " >= ")
			.replace("\\neq", " != ").replace("\\in", " in ").replace("\\approx", " ~ ").replace("\\pm", " +/- ")
			.replace("\\lfloor", "floor(").replace("\\rfloor", ")").replace("\\lceil", "ceil(").replace("\\rceil", ")")
			.replace("\\min", "min").replace("\\max", "max").replace("\\log", "log").replace("\\%", "%")
			.replace("\\,", " ").replace("\\;", " ").replace("\\:", " ").replace("\\ ", " ").replace("\\quad", " ")
			.replace("\\qquad", " ").replace("\\infty", "infinity");
		// Powers of a single number or letter read better without brackets: (80-L)^(2) as ^2
		s = s.replaceAll("\\^\\(([0-9A-Za-z.]+)\\)", "^$1");
		// Any other command name is dropped, then the braces that grouped things
		s = s.replaceAll("\\\\[A-Za-z]+", "").replace("{", "").replace("}", "");
		return plain(s).replaceAll("\\s+", " ").replaceAll("\\s*;\\s*", "; ").trim();
	}

	/**
	 * Characters the game's font lacks, swapped for ones it has.
	 */
	static String plain(String s)
	{
		if (s == null)
		{
			return null;
		}
		return s.replace('−', '-').replace('–', '-').replace('—', '-').replace('‐', '-')
			.replace('‘', '\'').replace('’', '\'').replace('“', '"').replace('”', '"')
			.replace("≤", "<=").replace("≥", ">=").replace("∈", " in ").replace("≈", "~")
			.replace("…", "...").replace("→", "->").replace("←", "<-").replace("≠", "!=")
			.replace("∞", "infinity").replace("′", "'").replace(" ", " ").replace("​", "")
			.replace(" ", " ").replace(" ", " ").replace("⁡", "").replace("⁢", "")
			// Symbols the game font lacks, as the nearest it has
			.replace('\u2022', '\u00b7').replace('\u25aa', '\u00b7').replace('\u25cf', '\u00b7').replace('\u2011', '-')
			.replace("\u2020", "+").replace("\u2021", "++").replace("\u2191", "^").replace("\u2193", "v")
			.replace("\u2116", "No.").replace("\u2605", "*").replace("\u2606", "*").replace("\u2153", "1/3")
			.replace("\u2154", "2/3").replace("\u215b", "1/8").replace("\u2060", "").replace("\ufe0f", "")
			.replace("\u21d2", "=>").replace("\u2194", "<->");
	}
}

