package com.wikipeek;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/**
 * Everything the Info tab shows, grouped under the wiki infobox's own headings. Rows and
 * sections the wiki leaves blank are left out.
 */
final class MonsterInfo
{
	static final class Row
	{
		final String label;
		final String value;
		/**
		 * A wiki page the row opens when clicked, or null.
		 */
		final String url;

		Row(String label, String value, String url)
		{
			this.label = label;
			this.value = value;
			this.url = url;
		}
	}

	/**
	 * One column of an icon grid: the icon on top, the value under it.
	 */
	static final class Cell
	{
		final StatIcon icon;
		final String value;
		/**
		 * The difference from worn gear, as "+12" or "-3", or null.
		 */
		final String diff;

		Cell(StatIcon icon, String value)
		{
			this(icon, value, null);
		}

		Cell(StatIcon icon, String value, String diff)
		{
			this.icon = icon;
			this.value = value;
			this.diff = diff;
		}
	}

	/**
	 * A paragraph, list item or sub-heading inside a section. A list item may link to a page.
	 */
	static final class Para
	{
		static final char TEXT = 'p';
		static final char BULLET = 'l';
		static final char SUB = 'h';
		/**
		 * Text that should stand out, like a clue scroll's clue.
		 */
		static final char KEY = 'k';
		/**
		 * A formula, in a box of its own with each case on its own line.
		 */
		static final char FORMULA = 'f';

		final char style;
		final String text;
		final String link;

		Para(char style, String text, String link)
		{
			this.style = style;
			this.text = text;
			this.link = link;
		}
	}

	/**
	 * A table as the wiki shows it, cut down to the columns worth reading. Rows can link to a
	 * page, which they open on the wiki or as a card.
	 */
	static final class Table
	{
		final String key;
		final List<String> headers;
		final List<TRow> rows = new ArrayList<>();
		final boolean sortable;
		/**
		 * The column the wiki sorts it by to start with, or -1 for the wiki's order.
		 */
		final int defaultSort;
		final boolean[] right;
		/**
		 * Every row as tall as the tallest, so a list reads evenly.
		 */
		boolean uniform;
		/**
		 * An item's drop sources, where sources that are items can show their picture.
		 */
		boolean sources;

		Table(String key, List<String> headers, boolean sortable, int defaultSort, boolean[] right)
		{
			this.key = key;
			this.headers = headers;
			this.sortable = sortable;
			this.defaultSort = defaultSort;
			this.right = right;
		}
	}

	static final class TRow
	{
		final List<String> cells;
		final List<String> sort;
		final String link;
		/**
		 * What the linked page is likely to be, for opening it as a card: NPC, item, or null
		 * to try both. Not used when {@link #card} is false.
		 */
		final Kind kind;
		final boolean card;
		/**
		 * Smaller text under a cell's main text ("Level 96" under "Cave bug"), by column,
		 * or null.
		 */
		List<String> notes;
		/**
		 * Pictures in a cell, by column, as "Title|count", or null.
		 */
		List<List<String>> icons;
		/**
		 * A picture in front of a cell's text (a spell's icon), by column, or null.
		 */
		List<String> lead;

		TRow(List<String> cells, List<String> sort, String link, Kind kind, boolean card)
		{
			this.cells = cells;
			this.sort = sort;
			this.link = link;
			this.kind = kind;
			this.card = card;
		}
	}

	static final class Section
	{
		final String title;
		final List<Row> rows = new ArrayList<>();
		final List<Cell> cells = new ArrayList<>();
		/**
		 * Slayer masters who assign this monster, as the wiki's codes (turael, konar...).
		 */
		final List<String> masters = new ArrayList<>();
		/**
		 * Paragraphs and tables, in the wiki's order, after the rows above.
		 */
		final List<Object> blocks = new ArrayList<>();
		/**
		 * Starts folded away; its heading opens it.
		 */
		boolean collapsible;

		Section(String title)
		{
			this.title = title;
		}

		boolean isEmpty()
		{
			return rows.isEmpty() && cells.isEmpty() && masters.isEmpty() && blocks.isEmpty();
		}

		void row(String label, String value)
		{
			if (value != null && !value.isEmpty())
			{
				rows.add(new Row(label, value, null));
			}
		}
	}

	final String examine;
	final List<Section> sections;
	/**
	 * A paragraph shown above the sections (an item's wiki introduction), or empty.
	 */
	final String intro;

	private MonsterInfo(String examine, List<Section> sections)
	{
		this(examine, sections, "");
	}

	private MonsterInfo(String examine, List<Section> sections, String intro)
	{
		this.examine = examine;
		this.sections = sections;
		this.intro = intro == null ? "" : intro;
	}

	/**
	 * Sections built elsewhere (an item's), leaving out empty ones.
	 */
	static MonsterInfo of(String examine, List<Section> sections, String intro)
	{
		final List<Section> kept = new ArrayList<>(sections);
		kept.removeIf(Section::isEmpty);
		return new MonsterInfo(examine, kept, intro);
	}

	static MonsterInfo of(Infobox box)
	{
		return of(box, null, null);
	}

	/**
	 * The infobox as sections, with links to the wiki's slayer task guide and strategy
	 * guide where they exist (null where they don't).
	 */
	static MonsterInfo of(Infobox box, String slayerGuide, String strategyGuide)
	{
		if (box == null)
		{
			return new MonsterInfo("", Collections.<Section>emptyList());
		}
		final List<Section> sections = new ArrayList<>();
		final String examine = box.get("examine");

		Section basics = new Section("Basics");
		basics.row("Released", box.get("release"));
		basics.row("Members", yesNo(box.get("members")));
		basics.row("Combat level", box.get("combat"));
		basics.row("Size", size(box.get("size")));
		sections.add(basics);

		Section combat = new Section("Combat info");
		combat.row("XP bonus", percent(box.get("xpbonus")));
		combat.row("Flat armour", box.get("flatarmour"));
		combat.row("Max hit", box.get("max hit"));
		combat.row("Aggressive", yesNo(box.get("aggressive")));
		combat.row("Poisonous", poisonous(box.get("poisonous")));
		combat.row("Attack style", box.get("attack style"));
		combat.row("Attributes", attributes(box.get("attributes")));
		combat.row("Attack speed", ticks(box.get("attack speed")));
		combat.row("Respawn time", ticks(box.get("respawn")));
		if (strategyGuide != null)
		{
			combat.rows.add(new Row("Strategy guide", "Open on the wiki", strategyGuide));
		}
		sections.add(combat);

		final String slayXp = box.get("slayxp");
		final String category = box.get("cat");
		final List<String> masters = masters(box.get("assignedby"));
		final boolean slayer = isSet(slayXp) || isSet(category) || !masters.isEmpty();
		if (slayer)
		{
			Section s = new Section("Slayer info");
			String level = box.get("slaylvl");
			s.row("Slayer level", isSet(level) && !level.equals("1") ? level : "None");
			s.row("Slayer XP", isSet(slayXp) ? slayXp : "");
			s.row("Category", isSet(category) ? category : "");
			s.masters.addAll(masters);
			if (slayerGuide != null)
			{
				s.rows.add(new Row("Task guide", "Open on the wiki", slayerGuide));
			}
			sections.add(s);
		}

		Section stats = new Section("Combat stats");
		grid(stats, StatIcon.HITPOINTS, box.get("hitpoints"), false);
		grid(stats, StatIcon.ATTACK, box.get("att"), false);
		grid(stats, StatIcon.STRENGTH, box.get("str"), false);
		grid(stats, StatIcon.DEFENCE, box.get("def"), false);
		grid(stats, StatIcon.MAGIC, box.get("mage"), false);
		grid(stats, StatIcon.RANGED, box.get("range"), false);
		sections.add(stats);

		Section aggressive = new Section("Aggressive stats");
		grid(aggressive, StatIcon.ATTACK, box.get("attbns"), true);
		grid(aggressive, StatIcon.STRENGTH, box.get("strbns"), true);
		grid(aggressive, StatIcon.MAGIC, box.get("amagic"), true);
		grid(aggressive, StatIcon.MAGIC_STRENGTH, box.get("mbns"), true);
		grid(aggressive, StatIcon.RANGED, box.get("arange"), true);
		grid(aggressive, StatIcon.RANGED_STRENGTH, box.get("rngbns"), true);
		sections.add(aggressive);

		Section melee = new Section("Melee defence");
		grid(melee, StatIcon.STAB, box.get("dstab"), true);
		grid(melee, StatIcon.SLASH, box.get("dslash"), true);
		grid(melee, StatIcon.CRUSH, box.get("dcrush"), true);
		sections.add(melee);

		Section magic = new Section("Magic defence");
		grid(magic, StatIcon.MAGIC_DEFENCE, box.get("dmagic"), true);
		if (!box.get("dmagic").isEmpty() || !box.get("elementalweaknesstype").isEmpty())
		{
			weakness(magic, box.get("elementalweaknesstype"), box.get("elementalweaknesspercent"));
		}
		sections.add(magic);

		// Older pages give one ranged defence for all three types
		final String ranged = box.get("drange");
		Section range = new Section("Ranged defence");
		grid(range, StatIcon.LIGHT, or(box.get("dlight"), ranged), true);
		grid(range, StatIcon.STANDARD, or(box.get("dstandard"), ranged), true);
		grid(range, StatIcon.HEAVY, or(box.get("dheavy"), ranged), true);
		sections.add(range);

		Section immune = new Section("Immunities");
		immune.row("Poison", resistance(box.get("poisonresistance"), box.get("immunepoison")));
		immune.row("Venom", resistance(box.get("venomresistance"), box.get("immunevenom")));
		immune.row("Cannons", immunity(box.get("immunecannon")));
		immune.row("Thralls", immunity(box.get("immunethrall")));
		sections.add(immune);

		sections.removeIf(Section::isEmpty);
		// A grid where the wiki gave no numbers at all says nothing
		sections.removeIf(s -> !s.cells.isEmpty() && s.rows.isEmpty() && s.masters.isEmpty() && allBlank(s.cells));
		return new MonsterInfo(examine, sections);
	}

	private static boolean allBlank(List<Cell> cells)
	{
		for (Cell c : cells)
		{
			if (!c.value.isEmpty() && c.icon != StatIcon.NO_WEAKNESS)
			{
				return false;
			}
		}
		return true;
	}

	private static void grid(Section s, StatIcon icon, String value, boolean signed)
	{
		s.cells.add(new Cell(icon, signed ? signed(value) : value));
	}

	private static void weakness(Section s, String type, String percent)
	{
		final String t = type.toLowerCase(Locale.ROOT);
		StatIcon icon;
		switch (t)
		{
			case "air":
				icon = StatIcon.AIR;
				break;
			case "water":
				icon = StatIcon.WATER;
				break;
			case "earth":
				icon = StatIcon.EARTH;
				break;
			case "fire":
				icon = StatIcon.FIRE;
				break;
			default:
				icon = null;
				break;
		}
		if (icon == null)
		{
			s.cells.add(new Cell(StatIcon.NO_WEAKNESS, "No elemental weakness"));
			return;
		}
		String pct = percent.replace("%", "").trim();
		String name = Character.toUpperCase(t.charAt(0)) + t.substring(1);
		s.cells.add(new Cell(icon, pct.isEmpty() ? "Weak to " + t : name + " weakness " + pct + "%"));
	}

	private static String or(String a, String b)
	{
		return a.isEmpty() ? b : a;
	}

	private static boolean isSet(String v)
	{
		return v != null && !v.isEmpty() && !v.equalsIgnoreCase("no") && !v.equalsIgnoreCase("none") && !v.equals("0");
	}

	static String signedValue(String v)
	{
		return signed(v);
	}

	static String yesNo(String v)
	{
		if (v.equalsIgnoreCase("yes"))
		{
			return "Yes";
		}
		if (v.equalsIgnoreCase("no"))
		{
			return "No";
		}
		return capital(v);
	}

	static String capital(String v)
	{
		return v.isEmpty() ? v : Character.toUpperCase(v.charAt(0)) + v.substring(1);
	}

	/**
	 * "demon, fiery" as "Demon, Fiery".
	 */
	private static String attributes(String v)
	{
		final List<String> out = new ArrayList<>();
		for (String part : v.split(","))
		{
			String a = part.trim();
			if (!a.isEmpty())
			{
				out.add(capital(a));
			}
		}
		return String.join(", ", out);
	}

	private static String size(String v)
	{
		return v.matches("\\d+") ? v + "x" + v : v;
	}

	private static String percent(String v)
	{
		String n = v.replace("%", "").replace("+", "").trim();
		if (n.matches("-?\\d+(\\.\\d+)?"))
		{
			return (n.startsWith("-") ? "" : "+") + n + "%";
		}
		return v;
	}

	private static String poisonous(String v)
	{
		if (v.matches("\\d+"))
		{
			return "Yes (" + v + ")";
		}
		return yesNo(v);
	}

	/**
	 * Game ticks with the seconds they work out to, as Lore Cards shows attack speed.
	 */
	static String ticks(String v)
	{
		if (v.matches("\\d+"))
		{
			int t = Integer.parseInt(v);
			return t + (t == 1 ? " tick (" : " ticks (") + String.format(Locale.ROOT, "%.1f", t * 0.6) + "s)";
		}
		return capital(v);
	}

	private static String signed(String v)
	{
		String n = v.trim();
		if (n.matches("[+-]?\\d+"))
		{
			int i = Integer.parseInt(n.startsWith("+") ? n.substring(1) : n);
			return (i >= 0 ? "+" : "") + i;
		}
		return n;
	}

	private static String resistance(String percent, String legacy)
	{
		String p = percent.replace("%", "").trim();
		if (p.equalsIgnoreCase("poison"))
		{
			return "Poisoned instead";
		}
		if (p.matches("\\d+"))
		{
			int n = Integer.parseInt(p);
			return n >= 100 ? "Immune" : n == 0 ? "Not immune" : n + "% resistance";
		}
		if (!p.isEmpty())
		{
			return capital(p);
		}
		return immunity(legacy);
	}

	private static String immunity(String v)
	{
		if (v.equalsIgnoreCase("yes"))
		{
			return "Immune";
		}
		if (v.equalsIgnoreCase("no"))
		{
			return "Not immune";
		}
		return capital(v);
	}

	private static List<String> masters(String v)
	{
		final List<String> out = new ArrayList<>();
		for (String part : v.split("[,;]"))
		{
			String code = part.trim().toLowerCase(Locale.ROOT);
			if (!code.isEmpty() && !code.equals("no") && !code.equals("none") && !out.contains(code))
			{
				out.add(code);
			}
		}
		return out;
	}
}

package com.wikipeek;

import java.awt.Point;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import net.runelite.client.ui.overlay.Overlay;

/**
 * Moving a panel by dragging its name bar. RuneLite stores an overlay's spot relative to
 * whichever screen edge it's nearest, so the panel is moved by how far the mouse has moved
 * rather than to an absolute point; that keeps it under the mouse whatever edge it uses.
 */
final class NameBarDrag
{
	private boolean active;
	private int pressX;
	private int pressY;
	private Point startLocation;
	private Rectangle startBounds;

	void start(Overlay overlay, MouseEvent e)
	{
		final Rectangle bounds = overlay.getBounds();
		if (bounds == null)
		{
			return;
		}
		startBounds = new Rectangle(bounds);
		final Point preferred = overlay.getPreferredLocation();
		// Not moved before, so it's still placed from the top-left
		startLocation = preferred != null ? new Point(preferred) : new Point(bounds.x, bounds.y);
		pressX = e.getX();
		pressY = e.getY();
		active = true;
	}

	boolean isActive()
	{
		return active;
	}

	/**
	 * Follows the mouse, keeping the whole panel on the game screen.
	 */
	void drag(Overlay overlay, MouseEvent e, int canvasWidth, int canvasHeight)
	{
		if (!active)
		{
			return;
		}
		final int x = Math.max(0, Math.min(canvasWidth - startBounds.width, startBounds.x + e.getX() - pressX));
		final int y = Math.max(0, Math.min(canvasHeight - startBounds.height, startBounds.y + e.getY() - pressY));
		overlay.setPreferredPosition(null);
		overlay.setPreferredLocation(new Point(startLocation.x + x - startBounds.x, startLocation.y + y - startBounds.y));
	}

	/**
	 * Ends a drag. True if one was happening.
	 */
	boolean finish()
	{
		final boolean was = active;
		active = false;
		return was;
	}
}

