/**
 * Shows the pop-out and handles its clicks and scrolling. It sits in a fixed spot that can be
 * moved by holding Alt and dragging, and resized by Alt-dragging an edge, like any other
 * RuneLite overlay. The panel is only redrawn when something on it changes, so each frame
 * just draws a saved image.
 */
class PanelOverlay extends Overlay implements MouseListener, MouseWheelListener
{
	/**
	 * Pixels moved per arrow click, and per wheel notch.
	 */
	private static final int SCROLL_STEP = 24;
	private static final int WHEEL_STEP = 48;

	private final Client client;
	private final WikiPeekPlugin plugin;
	private final WikiPeekConfig config;
	private final SpriteManager spriteManager;
	private final OverlayManager overlayManager;

	private final PanelRenderer renderer = new PanelRenderer();
	private final PanelRenderer.Assets assets = new PanelRenderer.Assets();

	private volatile PanelRenderer.Hits hits = PanelRenderer.Hits.NONE;
	private PanelRenderer.Result result;

	// What the saved image was drawn for
	private Lookup drawnLookup;
	private int drawnVersion = -1;
	private int drawnIcons = -1;
	private int drawnSettings = -1;
	private PanelRenderer.Hover drawnHover;
	private int drawnLit = -1;
	private int drawnWidth;
	private int drawnHeight;
	private boolean drawnSprites;

	/**
	 * Mouse buttons pressed on the panel. Only their releases are kept from the game, so a
	 * camera drag that ends over the panel still ends.
	 */
	private final boolean[] pressedOnPanel = new boolean[8];

	private boolean draggingThumb;
	private volatile java.awt.Point lastMouse;
	private final NameBarDrag nameBarDrag = new NameBarDrag();
	private int dragStartY;
	private int dragStartScroll;

	private final net.runelite.client.ui.overlay.tooltip.TooltipManager tooltipManager;

	@Inject
	PanelOverlay(Client client, WikiPeekPlugin plugin, WikiPeekConfig config, SpriteManager spriteManager,
		OverlayManager overlayManager, net.runelite.client.ui.overlay.tooltip.TooltipManager tooltipManager)
	{
		this.tooltipManager = tooltipManager;
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.spriteManager = spriteManager;
		this.overlayManager = overlayManager;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
		setResizable(true);
		setMinimumSize(PanelRenderer.MIN_WIDTH);
	}

	/**
	 * For an extra card opened alongside the first: its own lookup. Null for the first card,
	 * which shows the plugin's.
	 */
	private volatile Lookup own;
	private boolean extra;
	private String extraName;

	/**
	 * Makes this an extra card, showing its own lookups and not saving its position.
	 */
	void makeExtra(String name)
	{
		extra = true;
		extraName = name;
	}

	boolean isExtra()
	{
		return extra;
	}

	@Override
	public String getName()
	{
		return extra ? extraName : super.getName();
	}

	Lookup current()
	{
		return extra ? own : plugin.getLookup();
	}

	/**
	 * Puts a lookup on this card.
	 */
	void show(Lookup lookup)
	{
		if (extra)
		{
			own = lookup;
		}
		else
		{
			plugin.setLookup(lookup);
		}
	}

	private void closeCard()
	{
		if (extra)
		{
			plugin.closeExtra(this);
		}
		else
		{
			plugin.close();
		}
	}

	void reset()
	{
		result = null;
		drawnLookup = null;
		hits = PanelRenderer.Hits.NONE;
		draggingThumb = false;
		nameBarDrag.finish();
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		final Lookup lookup = current();
		if (lookup == null)
		{
			if (drawnLookup != null)
			{
				reset();
			}
			return null;
		}
		if (!loadAssets())
		{
			return null;
		}

		final Dimension size = panelSize();
		final Rectangle bounds = getBounds();
		// The mouse as this card's own events last saw it, so hovering still works while
		// the game is kept from seeing the mouse over the card
		final java.awt.Point mouse = lastMouse;
		final java.awt.Point local = bounds != null && mouse != null && bounds.contains(mouse)
			? new java.awt.Point(mouse.x - bounds.x, mouse.y - bounds.y)
			: null;
		final PanelRenderer.Hover hover = hits.hoverAt(local);
		final int lit = litAt(hits, local);
		final boolean sprites = assets.close != null && assets.parchment != null;
		final int settings = plugin.getSettingsVersion();
		final int icons = plugin.getIconsVersion();

		// Only draw again when something changed; otherwise reuse the saved image
		if (result == null || lookup != drawnLookup || lookup.version() != drawnVersion || icons != drawnIcons
			|| settings != drawnSettings || hover != drawnHover || size.width != drawnWidth || size.height != drawnHeight
			|| sprites != drawnSprites || lit != drawnLit)
		{
			drawnLookup = lookup;
			drawnVersion = lookup.version();
			drawnIcons = icons;
			drawnSettings = settings;
			drawnHover = hover;
			drawnLit = lit;
			drawnWidth = size.width;
			drawnHeight = size.height;
			drawnSprites = sprites;
			final boolean single = config.layout() == Layout.SINGLE_PAGE;
			assets.body = bodyFont();
			renderer.copyButton = config.copyButton();
			renderer.tableIcons = config.tableIcons();
			renderer.sourceIcons = config.tableIcons();
			renderer.fitHeight = config.fitHeight();
			// Never taller or wider than the game window has room for below and beside the
			// card, so a small client still shows all of it, scrolled
			final Rectangle at = getBounds();
			final int roomH = client.getCanvasHeight() - (at != null && at.height > 0 ? Math.max(0, at.y) : 0) - 2;
			final int roomW = client.getCanvasWidth() - (at != null && at.width > 0 ? Math.max(0, at.x) : 0) - 2;
			renderer.limitHeight = roomH > 100 ? roomH : 0;
			renderer.limitWidth = roomW > 100 ? roomW : 0;
			renderer.namesReady = plugin.isItem("Coins");
			renderer.versionStyle = config.versionStyle();
			result = renderer.render(lookup, assets, plugin, hover, size.width, size.height,
				single, config.defaultTab().tab(), config.showPrices(), config.portraitSize(), local);
			hits = result.hits;
		}
		// See-through as set in the settings
		final int opacity = Math.max(20, Math.min(100, config.opacity()));
		final java.awt.Composite was = g.getComposite();
		if (opacity < 100)
		{
			g.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, opacity / 100f));
		}
		g.drawImage(result.image, 0, 0, null);
		g.setComposite(was);
		if (local != null && hits.camera != null && hits.camera.contains(local))
		{
			tooltipManager.add(new net.runelite.client.ui.overlay.tooltip.Tooltip("Copy a picture of this card, to paste into Discord or anywhere else"));
		}
		return new Dimension(result.image.getWidth(), result.image.getHeight());
	}

	/**
	 * The size the panel has been resized to, or the default.
	 */
	private Dimension panelSize()
	{
		final Dimension preferred = getPreferredSize();
		if (preferred == null)
		{
			return new Dimension(PanelRenderer.DEFAULT_WIDTH, PanelRenderer.DEFAULT_HEIGHT);
		}
		return new Dimension(
			Math.max(PanelRenderer.MIN_WIDTH, Math.min(PanelRenderer.MAX_WIDTH, preferred.width)),
			Math.max(PanelRenderer.MIN_HEIGHT, Math.min(PanelRenderer.MAX_HEIGHT, preferred.height)));
	}

	/**
	 * Fetches sprites and fonts. Sprites come from the game cache, so they are asked for again
	 * until available. Returns false if the fonts couldn't be loaded.
	 */
	private boolean loadAssets()
	{
		if (assets.close == null)
		{
			assets.close = spriteManager.getSprite(SpriteID.CloseButtonsV2.BUTTON, 0);
		}
		if (assets.closeHovered == null)
		{
			assets.closeHovered = spriteManager.getSprite(SpriteID.CloseButtonsV2.HOVERED, 0);
		}
		if (assets.parchment == null)
		{
			assets.parchment = spriteManager.getSprite(SpriteID.CHAT_BACKGROUND, 0);
		}
		if (assets.quill == null)
		{
			assets.quill = font(plugin.getQuill(), FontManager.getRunescapeFont());
			assets.bold = font(plugin.getBold(), FontManager.getRunescapeBoldFont());
			assets.plain = font(plugin.getPlain(), FontManager.getRunescapeFont());
			assets.small = font(plugin.getSmall(), FontManager.getRunescapeSmallFont());
		}
		return assets.quill != null;
	}

	private CardFont large;

	/**
	 * The reading text at the size chosen in the settings. Large is the game's font drawn
	 * a size up, as there's no bigger bitmap font.
	 */
	private CardFont bodyFont()
	{
		switch (config.textSize())
		{
			case SMALL:
				return assets.small;
			case LARGE:
				if (large == null)
				{
					large = CardFont.of(FontManager.getRunescapeFont().deriveFont(20f));
				}
				return large;
			default:
				return assets.plain;
		}
	}

	private static CardFont font(CardFont bitmap, java.awt.Font fallback)
	{
		return bitmap != null ? bitmap : CardFont.of(fallback);
	}

	private void scrollBy(Lookup lookup, int delta)
	{
		final int slot = PanelRenderer.scrollSlot(lookup, config.layout() == Layout.SINGLE_PAGE);
		final int max = hits.maxScroll;
		lookup.setScroll(slot, Math.max(0, Math.min(max, lookup.getScroll(slot) + delta)));
	}

	// Mouse handling

	private java.awt.Point localPoint(MouseEvent e)
	{
		if (current() == null || e.isAltDown())
		{
			// Alt is left alone so the panel can still be moved and resized
			return null;
		}
		final Rectangle bounds = getBounds();
		if (bounds == null || !bounds.contains(e.getPoint()))
		{
			return null;
		}
		return new java.awt.Point(e.getX() - bounds.x, e.getY() - bounds.y);
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		if (e.isConsumed())
		{
			// A card on top of this one has taken it
			return e;
		}
		lastMouse = e.getPoint();
		final java.awt.Point p = localPoint(e);
		if (p == null)
		{
			// A left click anywhere else in the game puts the panel away, if that's turned on.
			// The click still goes through to the game.
			if (current() != null && config.closeOnClickAway() && e.getButton() == MouseEvent.BUTTON1 && !e.isAltDown())
			{
				closeCard();
			}
			return e;
		}
		// The mouse's own back and forward buttons step through cards, like a web browser
		if (e.getButton() == 4 || e.getButton() == 5)
		{
			final Lookup now = current();
			final Lookup to = now == null ? null : e.getButton() == 4 ? now.getBack() : now.getForward();
			if (to != null)
			{
				show(to);
			}
			e.consume();
			return e;
		}
		if (e.getButton() == MouseEvent.BUTTON3 || client.isMenuOpen())
		{
			// Right-clicks open the game's menu as usual, with Wiki and WikiPeek options over a
			// row. A click while a menu is open is choosing from that menu, even where it's
			// drawn over the panel, so it's left for the game.
			return e;
		}
		e.consume();
		plugin.toFront(this);
		if (e.getButton() >= 0 && e.getButton() < pressedOnPanel.length)
		{
			pressedOnPanel[e.getButton()] = true;
		}
		if (e.getButton() != MouseEvent.BUTTON1)
		{
			return e;
		}

		final Lookup lookup = current();
		final PanelRenderer.Hits h = hits;
		// The find bar's buttons sit over the bottom of the text
		final int findAt = lookup.isFinding() ? findButton(h, p) : 0;
		if (findAt != 0)
		{
			if (findAt == 2)
			{
				lookup.closeFind();
			}
			else
			{
				lookup.stepFind(findAt);
			}
			return e;
		}
		// The open versions list is on top of everything, so it's checked first; a click
		// anywhere else shuts it
		if (lookup.isListOpen() && versionAt(h, p) < 0 && (h.versionBox == null || !h.versionBox.contains(p)))
		{
			lookup.setListOpen(false);
			return e;
		}
		// Sort buttons on a pinned heading sit over the bar that keeps rows from showing through
		final PanelRenderer.Head sortHead = headAt(h, p);
		final PanelRenderer.Bar bar = sortHead != null ? null : barAt(h, p);
		// The game's own key state too, in case the event's flags don't say
		final boolean shift = e.isShiftDown() || client.isKeyPressed(KeyCode.KC_SHIFT);
		final boolean ctrl = e.isControlDown() || client.isKeyPressed(KeyCode.KC_CONTROL);
		final PanelRenderer.Target target = bar == null ? targetAt(h, p) : null;
		if (h.close != null && h.close.contains(p))
		{
			closeCard();
		}
		else if (h.link != null && h.link.contains(p) && h.url != null)
		{
			LinkBrowser.browse(h.url);
		}
		else if (h.camera != null && h.camera.contains(p))
		{
			copyPicture(lookup);
		}
		else if (h.back != null && h.back.contains(p))
		{
			show(lookup.getBack());
		}
		else if (h.forward != null && h.forward.contains(p))
		{
			show(lookup.getForward());
		}
		else if (versionAt(h, p) >= 0)
		{
			lookup.setListOpen(false);
			plugin.showVersion(lookup, versionAt(h, p));
		}
		else if (h.versionBox != null && h.versionBox.contains(p))
		{
			lookup.setListOpen(!lookup.isListOpen());
		}
		else if (h.titleBar != null && h.titleBar.contains(p))
		{
			// Drag the name bar to move the panel
			nameBarDrag.start(this, e);
		}
		else if (h.portrait != null && h.portrait.contains(p))
		{
			if (config.wikiClick().matches(shift, ctrl) && lookup.getUrl() != null)
			{
				LinkBrowser.browse(lookup.getUrl());
			}
			// Compact pictures open up to full size when clicked, and close again
			else if (config.portraitSize() == PortraitSize.COMPACT && lookup.getImage() != null && !shift && !ctrl)
			{
				lookup.setExpanded(!lookup.isExpanded());
			}
		}
		else if (bar != null)
		{
			if (bar.key != null)
			{
				final int slot = PanelRenderer.scrollSlot(lookup, config.layout() == Layout.SINGLE_PAGE);
				lookup.toggle(bar.key);
				// Folding a section from its pinned heading puts that heading back in view
				if (bar.pinned)
				{
					lookup.setScroll(slot, bar.offset);
				}
			}
		}
		else if (sortHead != null)
		{
			lookup.sortBy(sortHead.table, sortHead.column, sortHead.current);
		}
		else if (target != null && config.cardClick().matches(shift, ctrl))
		{
			// Rows with no card of their own (shops, places) open on the wiki instead
			if (target.card)
			{
				plugin.openTarget(target, this);
			}
			else
			{
				LinkBrowser.browse(WikiClient.pageUrl(target.title));
			}
		}
		else if (target != null && config.wikiClick().matches(shift, ctrl))
		{
			LinkBrowser.browse(WikiClient.pageUrl(target.title));
		}
		else if (linkAt(h, p) != null)
		{
			LinkBrowser.browse(linkAt(h, p));
		}
		else if (tabAt(h, p) != null)
		{
			lookup.setTab(tabAt(h, p));
		}
		else if (h.scrollUp != null && h.scrollUp.contains(p))
		{
			scrollBy(lookup, -SCROLL_STEP);
		}
		else if (h.scrollDown != null && h.scrollDown.contains(p))
		{
			scrollBy(lookup, SCROLL_STEP);
		}
		else if (h.scrollThumb != null && h.scrollThumb.contains(p))
		{
			draggingThumb = true;
			dragStartY = e.getY();
			dragStartScroll = lookup.getScroll(PanelRenderer.scrollSlot(lookup, config.layout() == Layout.SINGLE_PAGE));
		}
		else if (h.scrollTrack != null && h.scrollTrack.contains(p))
		{
			// Clicking the track moves a page towards the click
			final int page = Math.max(SCROLL_STEP, h.panel.height - 2 * SCROLL_STEP);
			scrollBy(lookup, p.y < h.scrollThumb.y ? -page : page);
		}
		return e;
	}

	/**
	 * Which row, heading or column heading the mouse is over, as a number that changes when
	 * it moves to another, so the panel is only redrawn then. -1 for none.
	 */
	/**
	 * Which find bar button is at the point: -1 up, 1 down, 2 close, or 0 for none.
	 */
	private static int findButton(PanelRenderer.Hits h, java.awt.Point p)
	{
		if (h.findUp != null && h.findUp.contains(p))
		{
			return -1;
		}
		if (h.findDown != null && h.findDown.contains(p))
		{
			return 1;
		}
		return h.findClose != null && h.findClose.contains(p) ? 2 : 0;
	}

	private static int litAt(PanelRenderer.Hits h, java.awt.Point p)
	{
		if (p == null)
		{
			return -1;
		}
		final int find = findButton(h, p);
		if (find != 0)
		{
			return 400000 + find;
		}
		if (versionAt(h, p) >= 0)
		{
			return 300000 + versionAt(h, p);
		}
		if (h.versionBox != null && h.versionBox.contains(p))
		{
			return 400000;
		}
		if (h.camera != null && h.camera.contains(p))
		{
			return 500000;
		}
		final PanelRenderer.Head head = headAt(h, p);
		if (head != null)
		{
			return 200000 + h.heads.indexOf(head);
		}
		for (int i = 0; i < h.bars.size(); i++)
		{
			if (h.bars.get(i).area.contains(p))
			{
				return h.bars.get(i).key == null ? -1 : 100000 + i;
			}
		}
		for (int i = 0; i < h.rows.size(); i++)
		{
			if (h.rows.get(i).contains(p))
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * The tallest picture to share; Coins' full source list would otherwise be enormous.
	 */
	private static final int SHARE_MAX_HEIGHT = 4000;

	/**
	 * Draws the whole card, tall enough to show everything on the open tab without
	 * scrolling, and copies it to the clipboard. Nothing is saved to disk.
	 */
	private void copyPicture(Lookup lookup)
	{
		final PanelRenderer.Result shown = result;
		if (lookup == null || shown == null)
		{
			return;
		}
		final Dimension size = panelSize();
		final PanelRenderer share = new PanelRenderer();
		share.sharing = true;
		share.baseHeight = size.height;
		final boolean single = config.layout() == Layout.SINGLE_PAGE;
		final int tall = Math.min(SHARE_MAX_HEIGHT, size.height + hits.maxScroll);
		final int slot = PanelRenderer.scrollSlot(lookup, single);
		final int was = lookup.getScroll(slot);
		lookup.setScroll(slot, 0);
		final PanelRenderer.Result r = share.render(lookup, assets, plugin, PanelRenderer.Hover.NONE, size.width, tall,
			single, config.defaultTab().tab(), config.showPrices(), config.portraitSize(), null);
		lookup.setScroll(slot, was);
		plugin.copyImage(r.image, lookup.getName());
	}

	private static int versionAt(PanelRenderer.Hits h, java.awt.Point p)
	{
		for (int i = 0; i < h.versions.size(); i++)
		{
			if (h.versions.get(i).contains(p))
			{
				return i;
			}
		}
		return -1;
	}

	private static PanelRenderer.Bar barAt(PanelRenderer.Hits h, java.awt.Point p)
	{
		for (PanelRenderer.Bar b : h.bars)
		{
			if (b.area.contains(p))
			{
				return b;
			}
		}
		return null;
	}

	private static PanelRenderer.Head headAt(PanelRenderer.Hits h, java.awt.Point p)
	{
		for (PanelRenderer.Head head : h.heads)
		{
			if (head.area.contains(p))
			{
				if (!head.pinned)
				{
					// A heading scrolled under a pinned bar is hidden, so it can't be clicked
					for (PanelRenderer.Bar b : h.bars)
					{
						if (b.pinned && b.area.contains(p))
						{
							return null;
						}
					}
				}
				return head;
			}
		}
		return null;
	}

	private static PanelRenderer.Target targetAt(PanelRenderer.Hits h, java.awt.Point p)
	{
		for (int i = 0; i < h.rows.size(); i++)
		{
			if (h.rows.get(i).contains(p))
			{
				return h.targets.get(i);
			}
		}
		return null;
	}

	/**
	 * The row or drop under the mouse, for the right-click menu, or null.
	 */
	PanelRenderer.Target targetUnderMouse()
	{
		// Where the mouse last was by its own events, the same measure the clicks use
		final java.awt.Point at = lastMouse;
		final Rectangle area = getBounds();
		if (at != null && area != null && current() != null && area.contains(at))
		{
			final java.awt.Point local = new java.awt.Point(at.x - area.x, at.y - area.y);
			return barAt(hits, local) != null || headAt(hits, local) != null ? null : targetAt(hits, local);
		}
		final Point mouse = client.getMouseCanvasPosition();
		final Rectangle bounds = getBounds();
		if (current() == null || mouse == null || bounds == null || !bounds.contains(mouse.getX(), mouse.getY()))
		{
			return null;
		}
		final java.awt.Point p = new java.awt.Point(mouse.getX() - bounds.x, mouse.getY() - bounds.y);
		return barAt(hits, p) != null || headAt(hits, p) != null ? null : targetAt(hits, p);
	}

	private static String linkAt(PanelRenderer.Hits h, java.awt.Point p)
	{
		for (int i = 0; i < h.links.size(); i++)
		{
			if (h.links.get(i).contains(p))
			{
				return h.linkUrls.get(i);
			}
		}
		return null;
	}

	private static Tab tabAt(PanelRenderer.Hits h, java.awt.Point p)
	{
		for (int i = 0; i < h.tabs.size(); i++)
		{
			if (h.tabs.get(i).contains(p))
			{
				return h.tabViews.get(i);
			}
		}
		return null;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent e)
	{
		if (nameBarDrag.isActive())
		{
			nameBarDrag.drag(this, e, client.getCanvasWidth(), client.getCanvasHeight());
			e.consume();
			return e;
		}
		if (!draggingThumb)
		{
			return e;
		}
		final Lookup lookup = current();
		final PanelRenderer.Hits h = hits;
		if (lookup == null || h.scrollTrack == null || h.scrollThumb == null)
		{
			draggingThumb = false;
			return e;
		}
		final int travel = Math.max(1, h.scrollTrack.height - h.scrollThumb.height);
		final int scroll = dragStartScroll + (e.getY() - dragStartY) * h.maxScroll / travel;
		lookup.setScroll(PanelRenderer.scrollSlot(lookup, config.layout() == Layout.SINGLE_PAGE), Math.max(0, Math.min(h.maxScroll, scroll)));
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		final boolean ours = e.getButton() >= 0 && e.getButton() < pressedOnPanel.length && pressedOnPanel[e.getButton()];
		if (e.getButton() >= 0 && e.getButton() < pressedOnPanel.length)
		{
			pressedOnPanel[e.getButton()] = false;
		}
		draggingThumb = false;
		if (nameBarDrag.finish() && !extra)
		{
			// Remember where it was put, as an Alt-drag would
			overlayManager.saveOverlay(this);
		}
		// A release only stays with the panel if the press was on it. Otherwise the game must
		// see it, or a camera drag that ends over the panel never stops.
		if (ours)
		{
			e.consume();
		}
		return e;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent e)
	{
		if (localPoint(e) != null && e.getButton() == MouseEvent.BUTTON1 && !client.isMenuOpen())
		{
			e.consume();
		}
		return e;
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e)
	{
		if (e.isConsumed())
		{
			return e;
		}
		final java.awt.Point p = localPoint(e);
		if (p == null)
		{
			return e;
		}
		if (hits.maxScroll > 0)
		{
			scrollBy(current(), e.getWheelRotation() * WHEEL_STEP);
		}
		// Don't zoom the game camera while reading
		e.consume();
		return e;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent e)
	{
		lastMouse = e.getPoint();
		// The game still sees the mouse move, so its menus open and stay open in the right
		// place; clicks over the card are what's held back
		return e;
	}

	/**
	 * Whether the mouse is over this card.
	 */
	boolean isUnderMouse()
	{
		final java.awt.Point at = lastMouse;
		final Rectangle area = getBounds();
		return current() != null && at != null && area != null && area.contains(at);
	}
}

