		Hover hoverAt(Point p)
		{
			if (p == null)
			{
				return Hover.NONE;
			}
			if (close != null && close.contains(p))
			{
				return Hover.CLOSE;
			}
			for (int i = 0; i < tabs.size() && i < 3; i++)
			{
				if (tabs.get(i).contains(p))
				{
					return Hover.tab(i);
				}
			}
			if (link != null && link.contains(p))
			{
				return Hover.LINK;
			}
			return Hover.NONE;
		}
	}

