	private final Map<String, List<String>> wrapCache = new HashMap<>();
	private final Map<BufferedImage, BufferedImage> scaled = new IdentityHashMap<>();
	private BufferedImage pictureSource;
	private CardPicture.Fitted picture;
	private int pictureW;
	private boolean pictureFigure;
	private BufferedImage trimmedSource;
	private int trimmedW;
	private int trimmedH;
	private int pictureH;
	private int width;
	private int height;

	/**
	 * Where the mouse is over the panel, for lighting up the row or heading under it; null
	 * if it's elsewhere.
	 */
	private Point mouse;
	/**
	 * Show the copy picture button on the name bar.
	 */
	boolean copyButton;
	/**
	 * Drawing a picture to share: as tall as it needs to be, with no button lit.
	 */
	boolean sharing;
	/**
	 * Cards are only as tall as what's on them, up to the size they've been given.
	 */
	boolean fitHeight;
	/**
	 * The most room the game window has for the card, or 0 for no limit.
	 */
	int limitHeight;
	int limitWidth;
	private boolean fitting;
	private static final int FIT_MIN_HEIGHT = 150;
	/**
	 * Show items' pictures beside their names in tables.
	 */
	boolean tableIcons;
	/**
	 * Show pictures beside drop sources that are items.
	 */
	boolean sourceIcons;
	/**
	 * How the versions of an NPC are offered.
	 */
	VersionStyle versionStyle = VersionStyle.HEADERS;
	/**
	 * The card's height on screen, when drawing a taller one to share.
	 */
	int baseHeight;

	Result render(Lookup lookup, Assets a, Icons icons, Hover hover, int panelWidth, int panelHeight,
		boolean singlePage, Tab first, boolean prices, PortraitSize portrait, Point mouse)
	{
		this.mouse = mouse;
		this.pictures = icons;
		// Words being found on the card, in lower case, or null
		final boolean finding = !sharing && lookup.isFinding();
		final String findText = finding ? lookup.getFind() : null;
		find = findText != null && !findText.trim().isEmpty() ? findText.trim().toLowerCase(Locale.ROOT) : null;
		width = Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, panelWidth));
		height = Math.max(fitting ? FIT_MIN_HEIGHT : MIN_HEIGHT, sharing ? panelHeight : Math.min(MAX_HEIGHT, panelHeight));
		if (!sharing && limitHeight > 0)
		{
			height = Math.min(height, Math.max(FIT_MIN_HEIGHT, limitHeight));
		}
		if (limitWidth > 0)
		{
			width = Math.min(width, Math.max(MIN_WIDTH * 3 / 4, limitWidth));
		}
		if (a.body == null)
		{
			a.body = a.plain;
		}
		final boolean expanded = lookup.isExpanded() && portrait == PortraitSize.COMPACT;
		final int artH = artHeight(portrait, expanded, lookup.getImage(), lookup.kind == Kind.ITEM);
		// Compact and Large crop tall figures to keep faces in view; the others show it whole
		final boolean figure = !expanded && portrait == PortraitSize.COMPACT;
		final Lookup.State state = lookup.getState();
		final MonsterInfo info = lookup.getInfo();
		final Hits hits = new Hits();

		final BufferedImage img = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);

		raised(g, 0, 0, width, height);

		// Name plate with the close button
		int y = M;
		sunken(g, M, y, width - 2 * M, PLATE_H, Stone.PANEL);
		final Rectangle close = closeBounds(a, y);
		final int titleRoom = width - 2 * (width - close.x) - 8;
		final String fitted = fit(lookup.getName(), a.bold, titleRoom);
		shadow(g, a.bold, fitted, width / 2 - a.bold.width(fitted) / 2, y + 15, ORANGE);
		drawClose(g, a, close, hover == Hover.CLOSE);
		hits.close = close;
		int barLeft = M;
		if (copyButton && !sharing)
		{
			final Rectangle cam = new Rectangle(M + 2, y + 1, 20, PLATE_H - 2);
			final boolean lit = mouse != null && cam.contains(mouse);
			final BufferedImage orb = icons == null ? null : icons.wiki("/images/Oculus_orb.png");
			if (orb != null)
			{
				final BufferedImage small = fitIcon(orb, cam.width, cam.height);
				g.drawImage(small, cam.x + (cam.width - small.getWidth()) / 2, cam.y + (cam.height - small.getHeight()) / 2, null);
				if (lit)
				{
					g.setColor(new Color(255, 255, 255, 50));
					g.fillRect(cam.x, cam.y, cam.width, cam.height);
				}
			}
			else
			{
				drawCamera(g, cam, lit);
			}
			hits.camera = cam;
			barLeft = cam.x + cam.width + 2;
		}
		// Back and forward, for cards opened from links on this one
		if (!sharing && (lookup.getBack() != null || lookup.getForward() != null))
		{
			final Rectangle back = new Rectangle(barLeft, y + 2, 16, PLATE_H - 4);
			final Rectangle forward = new Rectangle(barLeft + 18, y + 2, 16, PLATE_H - 4);
			historyArrow(g, back, true, lookup.getBack() != null, mouse != null && back.contains(mouse));
			historyArrow(g, forward, false, lookup.getForward() != null, mouse != null && forward.contains(mouse));
			hits.back = lookup.getBack() != null ? back : null;
			hits.forward = lookup.getForward() != null ? forward : null;
			barLeft = forward.x + forward.width + 2;
		}
		hits.titleBar = new Rectangle(barLeft, y, close.x - barLeft - 2, PLATE_H);
		y += PLATE_H + GAP;

		// The wiki picture, unless pictures are turned off
		if (artH > 0)
		{
			sunken(g, M, y, width - 2 * M, artH, Stone.PANEL);
			if (lookup.getImage() != null)
			{
				drawPicture(g, lookup.getImage(), M, y, width - 2 * M, artH, figure, lookup.kind == Kind.ITEM);
			}
			if (lookup.combat > 0 && lookup.getVersions().size() < 2)
			{
				shadow(g, a.small, "Level " + lookup.combat, M + 5, y + 13, GREY);
			}
			hits.portrait = new Rectangle(M, y, width - 2 * M, artH);
			y += artH + GAP;
		}

		// Examine strip, up to two lines
		final String examine = info != null ? info.examine : "";
		if (!examine.isEmpty())
		{
			List<String> ex = wrapExamine(examine, a, width - 2 * M - 10);
			CardFont ef = ex.size() > 1 || a.plain.width(examine) > width - 2 * M - 10 ? a.small : a.plain;
			int stripH = ex.size() > 1 ? 30 : ROW_H;
			sunken(g, M, y, width - 2 * M, stripH, Stone.PANEL_ALT);
			int ly = y + (ex.size() > 1 ? 12 : 13);
			for (String line : ex)
			{
				shadow(g, ef, line, width / 2 - ef.width(line) / 2, ly, YELLOW);
				ly += 13;
			}
			y += stripH + GAP;
		}

		// A page covering several versions: pick between them, like the wiki's tabs
		final List<String> versions = lookup.getVersions();
		Rectangle listBox = null;
		if (versions.size() > 1 && lookup.getShownVersion() >= 0)
		{
			final int shown = Math.min(lookup.getShownVersion(), versions.size() - 1);
			final String title = "Variation:";
			if (versionStyle == VersionStyle.DROPDOWN)
			{
				listBox = new Rectangle(M, y, width - 2 * M, ROW_H + 2);
				final boolean lit = mouse != null && listBox.contains(mouse) && !sharing;
				sunken(g, listBox.x, listBox.y, listBox.width, listBox.height, lit ? Stone.PANEL_ALT : Stone.PANEL);
				shadow(g, a.small, title, M + 6, y + 14, GREY);
				final int lx = M + 10 + a.small.width(title);
				final String count = (shown + 1) + " of " + versions.size();
				final String label = fit(versions.get(shown), a.plain, listBox.x + listBox.width - 30 - a.small.width(count) - lx);
				shadow(g, a.plain, label, lx, y + 14, ORANGE);
				shadow(g, a.small, count, listBox.x + listBox.width - 22 - a.small.width(count), y + 14, GREY);
				downArrow(g, listBox.x + listBox.width - 12, y + (ROW_H + 2) / 2, lookup.isListOpen(), lit);
				hits.versionBox = listBox;
				y += ROW_H + 2 + GAP;
			}
			else
			{
				// A neat grid of equal buttons under a "Variation:" title, in a sunken panel
				final int bh = 18;
				final int gapX = 3;
				final int room = width - 2 * M - 8;
				int widest = 0;
				for (String v : versions)
				{
					widest = Math.max(widest, a.small.width(v) + 14);
				}
				final int cols = Math.max(1, Math.min(versions.size(), Math.min(4, (room + gapX) / Math.max(60, widest + gapX))));
				final int bw = (room - (cols - 1) * gapX) / cols;
				final int rowsNeeded = (versions.size() + cols - 1) / cols;
				final int boxH = 18 + rowsNeeded * (bh + 3) + 3;
				sunken(g, M, y, width - 2 * M, boxH, Stone.PANEL);
				shadow(g, a.small, title, M + 6, y + 13, GREY);
				for (int i = 0; i < versions.size(); i++)
				{
					final int bx = M + 4 + (i % cols) * (bw + gapX);
					final int by = y + 18 + (i / cols) * (bh + 3);
					final Rectangle r = new Rectangle(bx, by, bw, bh);
					final boolean open = i == shown;
					final boolean lit = mouse != null && r.contains(mouse) && !sharing;
					stoneButton(g, r, open, lit);
					final String text = fit(versions.get(i), a.small, bw - 8);
					shadow(g, a.small, text, bx + (bw - a.small.width(text)) / 2, by + bh - 5, open || lit ? WHITE : ORANGE);
					hits.versions.add(r);
				}
				y += boxH + GAP;
			}
		}

		// The text panel
		final int textW = width - 2 * M - SCROLLBAR_W - 12;
		final List<Line> lines = new ArrayList<>();
		if (state != Lookup.State.READY)
		{
			message(lines, lookup, a, textW);
		}
		else if (singlePage)
		{
			for (Tab t : pageOrder(lookup, first))
			{
				tabLines(t, lines, lookup, a, icons, textW, prices, true);
			}
		}
		else
		{
			tabLines(lookup.getTab(), lines, lookup, a, icons, textW, prices, false);
		}

		// The lines holding the words being found, and the one being looked at
		final java.util.Set<Line> found = java.util.Collections.newSetFromMap(new IdentityHashMap<>());
		Line foundAt = null;
		int foundOffset = 0;
		int foundCount = 0;
		int foundIndex = 0;
		if (find != null)
		{
			final List<Integer> offsets = new ArrayList<>();
			final List<Line> hitLines = new ArrayList<>();
			int off = 0;
			for (Line line : lines)
			{
				if (matches(line, find))
				{
					found.add(line);
					hitLines.add(line);
					offsets.add(off);
				}
				off += line.height;
			}
			foundCount = hitLines.size();
			if (foundCount > 0)
			{
				foundIndex = Math.floorMod(lookup.getFindAt(), foundCount);
				lookup.keepFindAt(foundIndex);
				foundAt = hitLines.get(foundIndex);
				foundOffset = offsets.get(foundIndex);
			}
		}

		// Stone rows first: the panel joins straight onto the strip above, like Lore Cards' facts
		final boolean stoneTop = !lines.isEmpty() && lines.get(0).stone();
		if (stoneTop)
		{
			y -= GAP;
		}
		final int panelH = height - y - M - FOOTER_H;
		final Rectangle panel = new Rectangle(M, y, width - 2 * M, panelH);
		if (a.parchment != null)
		{
			// Only the plain middle of the chatbox parchment, so its darker edges don't stretch
			int pw = a.parchment.getWidth();
			int ph = a.parchment.getHeight();
			int insetX = pw / 20;
			int insetY = ph / 6;
			g.drawImage(a.parchment, panel.x, panel.y, panel.x + panel.width, panel.y + panel.height,
				insetX, insetY, pw - insetX, ph - insetY, null);
		}
		else
		{
			g.setColor(new Color(201, 184, 150));
			g.fill(panel);
		}
		sunken(g, panel.x, panel.y, panel.width, panel.height, null);

		// No parchment margin above a first stone row or below a last one, so stone rows
		// meet the panel's edges cleanly when scrolled to either end
		final boolean stoneBottom = !lines.isEmpty() && lines.get(lines.size() - 1).stone();
		int contentH = (stoneTop ? 0 : 6) + (stoneBottom ? 0 : 6);
		for (Line line : lines)
		{
			contentH += line.height;
		}
		if (finding)
		{
			// Room to scroll the last lines up out from under the find bar
			contentH += FIND_H;
		}
		final int visible = stoneTop || stoneBottom ? panel.height : panel.height - 4;
		// Shrink to fit: a card with little on it is drawn again only as tall as it needs,
		// keeping the picture the size it is at the full height
		if (fitHeight && !fitting && !sharing && contentH < visible - 2)
		{
			g.dispose();
			fitting = true;
			final int full = baseHeight;
			baseHeight = height;
			try
			{
				return render(lookup, a, icons, hover, panelWidth, height - (visible - contentH), singlePage, first, prices, portrait, mouse);
			}
			finally
			{
				fitting = false;
				baseHeight = full;
			}
		}
		final int maxScroll = Math.max(0, contentH - visible);
		final int slot = scrollSlot(lookup, singlePage);
		if (finding && lookup.takeFindJump() && foundAt != null)
		{
			// Bring the match into view, a third of the way down
			final int startOff = stoneTop ? 0 : 6;
			lookup.setScroll(slot, Math.max(0, Math.min(maxScroll, startOff + foundOffset - visible / 3)));
		}
		final int scroll = Math.max(0, Math.min(lookup.getScroll(slot), maxScroll));
		final int textArea = panel.width - (maxScroll > 0 ? SCROLLBAR_W : 0);

		final Shape clip = g.getClip();
		final Rectangle inner = new Rectangle(panel.x + 2, panel.y + 2, textArea - 4, panel.height - 4);
		// Stone rows run the panel's full width, over its border, so they join the strip above
		final Rectangle full = new Rectangle(panel.x, panel.y, textArea, panel.height);
		g.setClip(inner);
		final int start = stoneTop ? 0 : 6;
		int top = panel.y + start - scroll;
		int stripe = 0;
		// Where each bar's section starts and ends, so the one being read stays pinned on top
		Line pinned = null;
		int pinnedStart = 0;
		int pinnedEnd = 0;
		{
			int off = start;
			Line current = null;
			int currentStart = 0;
			for (Line line : lines)
			{
				if (line.kind == Line.Kind.BAR)
				{
					if (current != null && currentStart < scroll && off > scroll)
					{
						pinned = current;
						pinnedStart = currentStart;
						pinnedEnd = off;
					}
					current = line;
					currentStart = off;
				}
				off += line.height;
			}
			if (current != null && currentStart < scroll && off > scroll)
			{
				pinned = current;
				pinnedStart = currentStart;
				pinnedEnd = off;
			}
		}
		// Likewise a table's column headings, under the pinned bar, while its rows scroll past
		final int cover = pinned == null ? 0 : Math.max(0, Math.min(pinned.height, pinnedEnd - scroll));
		Line pinnedHead = null;
		int headEnd = 0;
		{
			int off = start;
			for (int i = 0; i < lines.size(); i++)
			{
				final Line line = lines.get(i);
				if (line.kind == Line.Kind.THEAD)
				{
					int end = off + line.height;
					for (int j = i + 1; j < lines.size() && lines.get(j).kind == Line.Kind.TROW; j++)
					{
						end += lines.get(j).height;
					}
					if (off < scroll + cover && end > scroll + cover + line.height)
					{
						pinnedHead = line;
						headEnd = end;
					}
				}
				off += line.height;
			}
		}
		// While finding, a matching line is drawn with fonts that mark the words
		final CardFont[] plainFonts = {Marker.plain(a.quill), Marker.plain(a.bold), Marker.plain(a.plain), Marker.plain(a.small), Marker.plain(a.body)};
		setFonts(a, plainFonts);
		for (Line line : lines)
		{
			setFonts(a, plainFonts);
			if (found.contains(line))
			{
				final boolean current = line == foundAt;
				setFonts(a, new CardFont[]{
					new Marker(plainFonts[0], find, current), new Marker(plainFonts[1], find, current),
					new Marker(plainFonts[2], find, current), new Marker(plainFonts[3], find, current),
					new Marker(plainFonts[4], find, current)});
			}
			final int lh = line.height;
			if (top + lh < panel.y || top > panel.y + panel.height)
			{
				// Off screen: nothing to draw, but keep the stripes in step
				if (line.kind == Line.Kind.BAR || line.kind == Line.Kind.HEADING || line.kind == Line.Kind.THEAD)
				{
					stripe = 0;
				}
				else if (line.kind == Line.Kind.DROP || line.kind == Line.Kind.FACT || line.kind == Line.Kind.TROW)
				{
					stripe++;
				}
				top += lh;
				continue;
			}
			final int left = panel.x + 6;
			final int rightEdge = panel.x + textArea - 7;
			switch (line.kind)
			{
				case QUILL:
					a.quill.draw(g, line.text, panel.x + textArea / 2 - a.quill.width(line.text) / 2, top + a.quill.ascent(), line.colour);
					break;
				case HEADING:
					stripe = 0;
					a.bold.draw(g, line.text, left + 2, top + 3 + a.bold.ascent(), line.colour);
					break;
				case DROP:
					drawDrop(g, a, line, hits, inner, top, lh, left, rightEdge, panel.x, textArea, stripe++);
					break;
				case FACT:
				{
					g.setClip(full);
					g.setColor(stripe++ % 2 == 0 ? Stone.PANEL : Stone.PANEL_ALT);
					g.fillRect(panel.x, top, textArea, lh);
					g.setColor(Stone.DARK);
					g.fillRect(panel.x, top + lh - 1, textArea, 1);
					g.setClip(inner);
					int base = top + FACT_PAD / 2 + a.body.ascent();
					shadow(g, a.body, line.text, left + 2, base, ORANGE);
					// A row with a link (a guide on the wiki) shows its value in yellow and opens it
					final Color valueColour = line.right != null ? YELLOW : WHITE;
					for (String value : line.values)
					{
						shadow(g, a.body, value, rightEdge - 2 - a.body.width(value), base, valueColour);
						base += factLine(a);
					}
					if (line.right != null)
					{
						Rectangle row = new Rectangle(panel.x, top, textArea, lh).intersection(inner);
						if (!row.isEmpty())
						{
							hits.links.add(row);
							hits.linkUrls.add(line.right);
						}
					}
					break;
				}
				case BAR:
				{
					stripe = 0;
					g.setClip(full);
					drawBar(g, a, line, hits, panel.x, top, textArea, top - panel.y + scroll, false);
					g.setClip(inner);
					break;
				}
				case TEXT:
					drawText(g, a.body, line, left + TEXT_MARGIN, top + 1 + a.body.ascent(), textArea - 13 - 2 * TEXT_MARGIN);
					break;
				case SUB:
					a.bold.draw(g, line.text, left + 2, top + 2 + a.bold.ascent(), line.colour);
					break;
				case FTOGGLE:
				{
					final int bx = left + TEXT_MARGIN;
					final int bw = textArea - 13 - 2 * TEXT_MARGIN;
					final Rectangle area = new Rectangle(bx, top + 2, bw, lh - 4);
					final boolean lit = mouse != null && area.contains(mouse);
					g.setColor(lit ? new Color(255, 255, 255, 70) : GRID_BAND);
					g.fillRect(area.x, area.y, area.width, area.height);
					g.setColor(KEY_EDGE);
					g.drawRect(area.x, area.y, area.width - 1, area.height - 1);
					final boolean open = Boolean.TRUE.equals(line.data);
					final int cx = area.x + 8;
					final int cy = area.y + area.height / 2;
					g.setColor(HEADING_RED);
					g.fillRect(cx - 3, cy, 7, 1);
					if (!open)
					{
						g.fillRect(cx, cy - 3, 1, 7);
					}
					a.small.draw(g, line.text, cx + 8, area.y + (area.height + a.small.ascent()) / 2 - 1, HEADING_RED);
					final Rectangle hit = area.intersection(inner);
					if (!hit.isEmpty())
					{
						hits.bars.add(new Bar(hit, line.key, 0, false));
					}
					break;
				}
				case MATH:
				{
					final MathBox math = (MathBox) line.data;
					final int bx = left + TEXT_MARGIN;
					final int bw = textArea - 13 - 2 * TEXT_MARGIN;
					g.setColor(FORMULA_BAND);
					g.fillRect(bx, top, bw, lh);
					g.setColor(KEY_EDGE);
					g.drawRect(bx, top, bw - 1, lh - 1);
					math.draw(g, bx + (bw - math.w) / 2, top + 8 + math.asc, INK);
					break;
				}
				case KEY:
				{
					final boolean[] ends = (boolean[]) line.data;
					final int bx = left + TEXT_MARGIN;
					final int bw = textArea - 13 - 2 * TEXT_MARGIN;
					g.setColor(KEY_BAND);
					g.fillRect(bx, top, bw, lh);
					if (line.key != null)
					{
						g.setColor(FORMULA_BAND);
						g.fillRect(bx, top, bw, lh);
					}
					// The same one-pixel edge all round
					g.setColor(KEY_EDGE);
					g.fillRect(bx, top, 1, lh);
					g.fillRect(bx + bw - 1, top, 1, lh);
					if (ends[0])
					{
						g.fillRect(bx + 1, top, bw - 2, 1);
					}
					if (ends[1])
					{
						g.fillRect(bx + 1, top + lh - 1, bw - 2, 1);
					}
					// A clue in bold; a formula in the reading font, in a cooler box
					final CardFont kf = "formula".equals(line.key) ? a.body : "formula-small".equals(line.key) ? a.small : a.bold;
					final int ty = top + (ends[0] ? 6 : 0) + 1 + kf.ascent();
					kf.draw(g, line.text, bx + bw / 2 - kf.width(line.text) / 2, ty, line.colour);
					break;
				}
				case BULLET:
				{
					if (line.right != null)
					{
						g.setColor(INK);
						g.fillRect(left + 4, top + a.body.ascent() / 2 + 1, 3, 3);
					}
					a.body.draw(g, line.text, left + 14, top + a.body.ascent(), line.colour);
					if (line.key != null)
					{
						Rectangle row = new Rectangle(inner.x, top, inner.width, lh).intersection(inner);
						if (!row.isEmpty())
						{
							hits.rows.add(row);
							hits.targets.add(new Target(line.key, null, true));
						}
					}
					break;
				}
				case THEAD:
				{
					stripe = 0;
					drawHead(g, a, line, hits, inner, top, lh, left, false);
					break;
				}
				case TROW:
					drawRow(g, a, line, hits, inner, top, lh, left, stripe++);
					break;
				case GRID:
					drawGrid(g, a, icons, line, inner.x, top, inner.width);
					break;
				case MASTERS:
					g.setClip(full);
					drawMasters(g, a, icons, line, panel.x, top, textArea, stripe++, hits);
					g.setClip(inner);
					break;
				default:
					break;
			}
			if (found.contains(line))
			{
				// A tick at the edge too, for matches that run across cells or are cut short
				final Rectangle tick = new Rectangle(inner.x, top, line == foundAt ? 3 : 2, lh).intersection(inner);
				g.setColor(line == foundAt ? FOUND_CURRENT : FOUND_BAND);
				g.fillRect(tick.x, tick.y, tick.width, tick.height);
			}
			top += lh;
		}
		setFonts(a, plainFonts);
		// Below a card that ends on stone (a folded heading, say) the rest stays dark stone
		// rather than showing bare papyrus
		if (stoneBottom && top < panel.y + panel.height)
		{
			g.setClip(full);
			g.setColor(Stone.FILL);
			g.fillRect(panel.x, top, textArea, panel.y + panel.height - top);
			g.setClip(inner);
		}
		// The section being read keeps its heading on top, so it can be folded from anywhere.
		// It's pushed up as the next heading arrives.
		if (pinnedHead != null)
		{
			g.setClip(inner);
			final int headY = Math.min(panel.y + cover, panel.y + headEnd - scroll - pinnedHead.height);
			drawHead(g, a, pinnedHead, hits, inner, headY, pinnedHead.height, panel.x + 6, true);
		}
		if (pinned != null)
		{
			g.setClip(full);
			final int pinY = panel.y + Math.min(0, pinnedEnd - scroll - pinned.height);
			drawBar(g, a, pinned, hits, panel.x, pinY, textArea, pinnedStart, true);
		}
		if (finding)
		{
			g.setClip(full);
			drawFindBar(g, a, hits, findText, foundCount, foundIndex, panel.x, panel.y + panel.height - FIND_H, textArea);
		}
		g.setClip(clip);

		hits.panel = panel;
		hits.maxScroll = maxScroll;
		if (maxScroll > 0)
		{
			scrollbar(g, hits, panel.x + panel.width - SCROLLBAR_W, panel.y, SCROLLBAR_W, panel.height, scroll, maxScroll, visible);
		}

		// Footer: stone tabs on the left, the wiki link on the right
		final int fy = height - M - 6;
		if (!singlePage && (state == Lookup.State.READY || state == Lookup.State.LOADING))
		{
			tabs(g, a, lookup, hover, hits, height - M - FOOTER_H + 2);
		}
		if (lookup.getUrl() != null && state != Lookup.State.LOADING)
		{
			String link = lookup.getUrl().contains("Special:Search") ? "Search wiki" : "Wiki";
			int w = a.small.width(link);
			int rx = width - M - 6 - w;
			hits.link = new Rectangle(rx - 2, fy - 11, w + 4, 15);
			hits.url = lookup.getUrl();
			shadow(g, a.small, link, rx, fy, hover == Hover.LINK ? WHITE : ORANGE);
		}

		// The open versions list sits over everything else
		if (listBox != null && lookup.isListOpen() && !sharing)
		{
			final int shown = Math.min(lookup.getShownVersion(), versions.size() - 1);
			final int fits = Math.max(1, (height - M - listBox.y - listBox.height - 4) / ROW_H);
			final int count = Math.min(versions.size(), fits);
			final int ly = listBox.y + listBox.height + 1;
			g.setColor(Stone.EDGE);
			g.fillRect(listBox.x - 1, ly - 1, listBox.width + 2, count * ROW_H + 2);
			hits.versions.clear();
			for (int i = 0; i < count; i++)
			{
				final Rectangle r = new Rectangle(listBox.x, ly + i * ROW_H, listBox.width, ROW_H);
				final boolean lit = mouse != null && r.contains(mouse);
				g.setColor(i == shown ? new Color(110, 32, 22) : lit ? Stone.PANEL_ALT : Stone.PANEL);
				g.fillRect(r.x, r.y, r.width, r.height);
				g.setColor(Stone.DARK);
				g.fillRect(r.x, r.y + r.height - 1, r.width, 1);
				final String text = fit(versions.get(i), a.plain, r.width - 12);
				shadow(g, a.plain, text, r.x + 6, r.y + 13, i == shown || lit ? WHITE : ORANGE);
				hits.versions.add(r);
			}
		}

		g.dispose();
		return new Result(img, hits);
	}

	/**
	 * The strip along the bottom of the text while finding: the words typed, and which
	 * match is showing.
	 */
	private void drawFindBar(Graphics2D g, Assets a, Hits hits, String text, int count, int index, int x, int y, int w)
	{
		g.setColor(Stone.DARK);
		g.fillRect(x, y, w, 1);
		g.setColor(Stone.PANEL);
		g.fillRect(x, y + 1, w, FIND_H - 1);
		final String label = "Find:";
		shadow(g, a.plain, label, x + 6, y + 14, ORANGE);
		final int tx = x + 10 + a.plain.width(label);
		// Previous, next and close buttons at the right-hand end
		final int bs = FIND_H - 6;
		int bx = x + w - 6 - bs;
		hits.findClose = new Rectangle(bx, y + 3, bs, bs);
		findButton(g, hits.findClose, 0);
		bx -= bs + 3;
		hits.findDown = new Rectangle(bx, y + 3, bs, bs);
		findButton(g, hits.findDown, 1);
		bx -= bs + 3;
		hits.findUp = new Rectangle(bx, y + 3, bs, bs);
		findButton(g, hits.findUp, -1);
		final boolean typed = text != null && !text.trim().isEmpty();
		final String status = !typed ? "Enter: next, Esc: close" : count == 0 ? "Not on this card" : (index + 1) + " of " + count;
		final int sw = a.small.width(status);
		shadow(g, a.small, status, bx - 6 - sw, y + 14, typed && count == 0 ? WORSE : GREY);
		final int room = bx - 14 - sw - tx;
		String shown = text == null ? "" : text;
		while (!shown.isEmpty() && a.plain.width(shown + "|") > room)
		{
			// Long words keep their end in view, where the typing is
			shown = shown.substring(1);
		}
		shadow(g, a.plain, shown, tx, y + 14, WHITE);
		// Where the typing goes
		g.setColor(WHITE);
		g.fillRect(tx + a.plain.width(shown) + 1, y + 4, 1, 12);
	}

	/**
	 * A small stone button on the find bar: up (-1), down (1) or close (0), lit under the
	 * mouse.
	 */
	private void findButton(Graphics2D g, Rectangle r, int which)
	{
		final boolean lit = mouse != null && r.contains(mouse);
		g.setColor(lit ? Stone.LIGHT : Stone.DARK);
		g.fillRect(r.x, r.y, r.width, r.height);
		g.setColor(lit ? WHITE : ORANGE);
		final int cx = r.x + r.width / 2;
		final int cy = r.y + r.height / 2;
		if (which == 0)
		{
			for (int i = -3; i <= 3; i++)
			{
				g.fillRect(cx + i, cy + i, 1, 1);
				g.fillRect(cx + i, cy - i, 1, 1);
			}
			return;
		}
		for (int i = 0; i < 4; i++)
		{
			// A small triangle pointing up or down
			final int row = which < 0 ? cy - 2 + i : cy + 1 - i;
			g.fillRect(cx - i, row, i * 2 + 1, 1);
		}
	}

	private static void setFonts(Assets a, CardFont[] fonts)
	{
		a.quill = fonts[0];
		a.bold = fonts[1];
		a.plain = fonts[2];
		a.small = fonts[3];
		a.body = fonts[4];
	}

	/**
	 * Whether a line holds the words, ignoring case.
	 */
	private static boolean matches(Line line, String words)
	{
		if (line.search == null)
		{
			line.search = searchText(line);
		}
		return !line.search.isEmpty() && line.search.contains(words);
	}

	private static String searchText(Line line)
	{
		final StringBuilder b = new StringBuilder();
		switch (line.kind)
		{
			case GAP:
			case GRID:
			case MATH:
			case FTOGGLE:
			case THEAD:
				return "";
			default:
				break;
		}
		if (line.text != null)
		{
			b.append(line.text).append(' ');
		}
		if (line.values != null)
		{
			for (String v : line.values)
			{
				b.append(v).append(' ');
			}
		}
		if (line.item != null && line.item.name != null)
		{
			b.append(line.item.name).append(' ');
		}
		if (line.data instanceof RowCells)
		{
			final MonsterInfo.TRow row = ((RowCells) line.data).row;
			for (String c : row.cells)
			{
				b.append(c).append(' ');
			}
			if (row.notes != null)
			{
				for (String n : row.notes)
				{
					if (n != null)
					{
						b.append(n).append(' ');
					}
				}
			}
		}
		// Inline picture marks and formula markers aren't words
		final StringBuilder out = new StringBuilder(b.length());
		for (int i = 0; i < b.length(); i++)
		{
			final char c = b.charAt(i);
			if (c < '\uE000' || c > '\uF8FF')
			{
				out.append(c);
			}
		}
		return out.toString().toLowerCase(Locale.ROOT);
	}

	static int scrollSlot(Lookup lookup, boolean singlePage)
	{
		return singlePage ? Tab.values().length : lookup.getTab().ordinal();
	}

	/**
	 * The one line shown while fetching, or when there's nothing to show.
	 */
	private void message(List<Line> lines, Lookup lookup, Assets a, int textW)
	{
		switch (lookup.getState())
		{
			case LOADING:
				paragraph(lines, "Fetching from the wiki...", INK_MUTED, a, textW);
				break;
			case NOT_FOUND:
				paragraph(lines, "No wiki data found.", INK_MUTED, a, textW);
				break;
			default:
				paragraph(lines, "Couldn't reach the wiki. Close this and try again in a moment.", INK_MUTED, a, textW);
				break;
		}
	}

	/**
	 * The single page shows every tab in turn: for an NPC, Info and Loot in the chosen
	 * order; for an item, its tabs in order.
	 */
	private static List<Tab> pageOrder(Lookup lookup, Tab first)
	{
		if (lookup.kind == Kind.NPC)
		{
			List<Tab> order = new ArrayList<>();
			order.add(first);
			order.add(first == Tab.LOOT ? Tab.INFO : Tab.LOOT);
			return order;
		}
		return lookup.getTabs();
	}

	private void tabLines(Tab tab, List<Line> lines, Lookup lookup, Assets a, Icons icons, int textW, boolean prices, boolean single)
	{
		keyPrefix = tab.name() + ":";
		formulas = 0;
		switch (tab)
		{
			case LOOT:
				if (lookup.kind == Kind.ITEM)
				{
					// What an item holds, like a reward casket's rewards
					sectionLines(lines, lookup, lookup.getLoot(), "Nothing comes out of this.", a, icons, textW);
					break;
				}
				if (single)
				{
					lines.add(bar("Loot", a));
				}
				lootLines(lines, lookup, a, textW, prices);
				break;
			case STATS:
				sectionLines(lines, lookup, lookup.getStats(), "This isn't worn, so it has no stats.", a, icons, textW);
				break;
			case SOURCES:
				sectionLines(lines, lookup, lookup.getSources(), "The wiki lists no drop sources, shops or recipe for this.", a, icons, textW);
				break;
			case INFO:
			default:
				sectionLines(lines, lookup, lookup.getInfo(), "The wiki has no infobox for this one.", a, icons, textW);
				break;
		}
	}

	private String keyPrefix = "";
	/**
	 * The words being found on the card, in lower case, or null.
	 */
	private String find;
	private int formulas;

	private void sectionLines(List<Line> lines, Lookup lookup, MonsterInfo info, String empty, Assets a, Icons icons, int textW)
	{
		if (info != null && !info.intro.isEmpty())
		{
			paragraph(lines, info.intro, INK, a, textW);
			lines.add(gap(a));
		}
		if (info == null || info.sections.isEmpty())
		{
			if (info == null || info.intro.isEmpty())
			{
				paragraph(lines, empty, INK_MUTED, a, textW);
			}
			return;
		}
		for (MonsterInfo.Section section : info.sections)
		{
			final Line bar = bar(section.title, a);
			// Each tab folds its own headings, so Loot's "Rewards" isn't tied to Info's
			bar.key = keyPrefix + section.title;
			// Every heading folds; full page sections start folded
			final boolean open = section.collapsible == lookup.isOpened(bar.key);
			bar.data = open ? Boolean.TRUE : Boolean.FALSE;
			lines.add(bar);
			if (!open)
			{
				// While finding, a folded section opens if the words are in it
				if (find != null)
				{
					final List<Line> body = new ArrayList<>();
					final int counted = formulas;
					sectionBody(body, lookup, section, a, icons, textW);
					boolean found = false;
					for (Line l : body)
					{
						if (matches(l, find))
						{
							found = true;
							break;
						}
					}
					if (found)
					{
						bar.data = Boolean.TRUE;
						lines.addAll(body);
					}
					else
					{
						// Formulas are numbered as they're laid out, so the hidden ones don't count
						formulas = counted;
					}
				}
				continue;
			}
			sectionBody(lines, lookup, section, a, icons, textW);
		}
	}

	private void sectionBody(List<Line> lines, Lookup lookup, MonsterInfo.Section section, Assets a, Icons icons, int textW)
	{
		for (MonsterInfo.Row row : section.rows)
		{
			factRow(lines, row.label, row.value, row.url, a, textW);
		}
		if (!section.cells.isEmpty())
		{
			final boolean diffs = section.cells.stream().anyMatch(c -> c.diff != null);
			lines.add(new Line(Line.Kind.GRID, null, null, null, null, null, section.cells,
				GRID_ICON_H + GRID_VALUE_H + (diffs ? GRID_DIFF_H : 0)));
		}
		if (!section.masters.isEmpty())
		{
			int cols = Math.max(1, (textW + 12) / MASTER_W);
			int rows = (section.masters.size() + cols - 1) / cols;
			lines.add(new Line(Line.Kind.MASTERS, "Assigned by", ORANGE, null, null, section.masters, null,
				FACT_PAD + FACT_LINE + rows * MASTER_H + 4));
		}
		blockLines(lines, lookup, section.blocks, a, textW);
	}

	/**
	 * A section's writing and tables, on the parchment.
	 */
	private void blockLines(List<Line> lines, Lookup lookup, List<Object> blocks, Assets a, int textW)
	{
		if (blocks.isEmpty())
		{
			return;
		}
		final CardFont f = a.body;
		final int lh = f.lineHeight();
		lines.add(new Line(Line.Kind.GAP, "", INK, null, null, null, null, 7));
		Object previous = null;
		for (Object block : blocks)
		{
			if (block instanceof MonsterInfo.Para)
			{
				final MonsterInfo.Para p = (MonsterInfo.Para) block;
				boolean shown = true;
				if (p.style == MonsterInfo.Para.FORMULA)
				{
					// Formulas fold away behind a small "Formula" line, folded to start with
					final String key = keyPrefix + "formula:" + (formulas++);
					shown = lookup.isOpened(key);
					Line toggle = new Line(Line.Kind.FTOGGLE, shown ? "Formula" : "Formula (click to show)", HEADING_RED, null, null, null, null, a.small.lineHeight() + 8);
					toggle.key = key;
					toggle.data = shown;
					lines.add(toggle);
				}
				final MathBox math = shown && p.style == MonsterInfo.Para.FORMULA ? mathBox(p, a, textW - 4 * TEXT_MARGIN - 12) : null;
				if (!shown)
				{
					lines.add(new Line(Line.Kind.GAP, "", INK, null, null, null, null, 4));
				}
				else if (math != null)
				{
					// Drawn the way the wiki shows it, in a box of its own
					Line l = new Line(Line.Kind.MATH, null, INK, null, null, null, null, math.height() + 16);
					l.data = math;
					lines.add(l);
					lines.add(new Line(Line.Kind.GAP, "", INK, null, null, null, null, 6));
				}
				else if (p.style == MonsterInfo.Para.FORMULA)
				{
					// Each case on one unbroken line, in a box, smaller text if it's long
					final String[] cases = p.text.split(MathText.LINE);
					int widest = 0;
					for (String one : cases)
					{
						widest = Math.max(widest, f.width(one.trim()));
					}
					final boolean shrink = widest > textW - 4 * TEXT_MARGIN;
					final CardFont ff = shrink ? a.small : f;
					// A case too long for one line carries on below it rather than being cut off
					final List<String> parts = new ArrayList<>();
					for (String one : cases)
					{
						parts.addAll(wrap(one.trim(), ff, textW - 4 * TEXT_MARGIN));
					}
					for (int i = 0; i < parts.size(); i++)
					{
						Line l = new Line(Line.Kind.KEY, parts.get(i), INK, null, null, null, null,
							ff.lineHeight() + 2 + (i == 0 ? 6 : 0) + (i == parts.size() - 1 ? 6 : 0));
						l.data = new boolean[]{i == 0, i == parts.size() - 1};
						l.key = shrink ? "formula-small" : "formula";
						lines.add(l);
					}
					lines.add(new Line(Line.Kind.GAP, "", INK, null, null, null, null, 6));
				}
				else if (p.style == MonsterInfo.Para.KEY)
				{
					final List<String> parts = wrap(p.text, a.bold, textW - 4 * TEXT_MARGIN);
					for (int i = 0; i < parts.size(); i++)
					{
						Line l = new Line(Line.Kind.KEY, parts.get(i), HEADING_RED, null, null, null, null,
							a.bold.lineHeight() + 3 + (i == 0 ? 6 : 0) + (i == parts.size() - 1 ? 6 : 0));
						l.data = new boolean[]{i == 0, i == parts.size() - 1};
						lines.add(l);
					}
					lines.add(new Line(Line.Kind.GAP, "", INK, null, null, null, null, 6));
				}
				else if (p.style == MonsterInfo.Para.SUB)
				{
					if (previous != null)
					{
						lines.add(new Line(Line.Kind.GAP, "", INK, null, null, null, null, 6));
					}
					for (String part : wrap(p.text, a.bold, textW))
					{
						lines.add(new Line(Line.Kind.SUB, part, HEADING_RED, null, null, null, null, a.bold.lineHeight() + 4));
					}
				}
				else if (p.style == MonsterInfo.Para.BULLET)
				{
					boolean first = true;
					for (String part : wrap(p.text, f, textW - 14))
					{
						Line l = new Line(Line.Kind.BULLET, part, p.link != null ? INK_LINK : INK, first ? "*" : null, null, null, null, lh);
						l.key = p.link;
						lines.add(l);
						first = false;
					}
					lines.add(new Line(Line.Kind.GAP, "", INK, null, null, null, null, 2));
				}
				else
				{
					if (previous instanceof MonsterInfo.Para && ((MonsterInfo.Para) previous).style == MonsterInfo.Para.TEXT)
					{
						lines.add(new Line(Line.Kind.GAP, "", INK, null, null, null, null, lh * 2 / 3));
					}
					final List<String> parts = wrap(p.text, f, textW - 2 * TEXT_MARGIN);
					for (int i = 0; i < parts.size(); i++)
					{
						// Lines are spread to both edges like a book, apart from a paragraph's last
						Line l = new Line(Line.Kind.TEXT, parts.get(i), INK, i < parts.size() - 1 ? "justify" : null, null, null, null, lh + 2);
						lines.add(l);
					}
				}
			}
			else if (block instanceof MonsterInfo.Table)
			{
				if (previous != null)
				{
					lines.add(new Line(Line.Kind.GAP, "", INK, null, null, null, null, 6));
				}
				tableLines(lines, lookup, (MonsterInfo.Table) block, a, textW);
			}
			previous = block;
		}
		lines.add(new Line(Line.Kind.GAP, "", INK, null, null, null, null, 6));
	}

	/**
	 * A formula's two-dimensional layout, in the reading font or the small one if that's
	 * too wide; null if it can't be drawn that way in the room there is.
	 */
	/**
	 * Formulas already laid out, by formula and room, so redrawing a card (the mouse moving
	 * over it) doesn't lay them out again.
	 */
	private static final Map<String, Optional<MathBox>> MATH_LAID = new java.util.LinkedHashMap<String, Optional<MathBox>>(16, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, Optional<MathBox>> eldest)
		{
			return size() > 64;
		}
	};

	private static MathBox mathBox(MonsterInfo.Para p, Assets a, int room)
	{
		if (p.link == null)
		{
			return null;
		}
		final String key = room + ":" + p.link;
		synchronized (MATH_LAID)
		{
			final Optional<MathBox> known = MATH_LAID.get(key);
			if (known != null)
			{
				return known.orElse(null);
			}
		}
		final MathBox laid = layMath(p, room);
		synchronized (MATH_LAID)
		{
			MATH_LAID.put(key, Optional.ofNullable(laid));
		}
		return laid;
	}

	private static MathBox layMath(MonsterInfo.Para p, int room)
	{
		final String xml;
		try
		{
			xml = new String(java.util.Base64.getDecoder().decode(p.link), java.nio.charset.StandardCharsets.UTF_8);
		}
		catch (IllegalArgumentException e)
		{
			return null;
		}
		// As large as fits on its own lines, from the card's text size down a little;
		// only if even the smallest doesn't fit is it restacked or broken onto more lines
		for (int size = MATH_SIZE; size >= MATH_MIN; size--)
		{
			final MathBox box = MathBox.of(xml, size);
			if (box == null || box.w <= room)
			{
				return box;
			}
		}
		// Then a table's extra columns (a range) moved under each row, still as large as fits
		for (int size = MATH_SIZE; size >= MATH_MIN; size--)
		{
			final MathBox box = MathBox.stacked(MathBox.of(xml, size));
			if (box == null || box.w <= room)
			{
				return box;
			}
		}
		return MathBox.wrapped(MathBox.of(xml, MATH_WRAP), room);
	}

	/**
	 * Where a table's columns sit, and its rows in the order they're shown.
	 */
	private static final class TableLayout
	{
		final MonsterInfo.Table table;
		/**
		 * For each column shown, its column in the table (picture columns can be hidden).
		 */
		final int[] col;
		final int[] x;
		final int[] w;
		final boolean[] right;
		/**
		 * Columns of pictures with counts (a spell's runes), where a picture without a
		 * count is shown as 1.
		 */
		final boolean[] counts;
		final int sort;
		/**
		 * Too many columns to fit side by side: each row is shown as its name, then each
		 * other column as a "Heading: value" line under it.
		 */
		boolean stacked;
		int labelW;
		int valueW;
		/**
		 * In a stacked table, where each column's sort button sits in the heading strip.
		 */
		Rectangle[] chips;

		TableLayout(MonsterInfo.Table table, int[] col, int[] x, int[] w, boolean[] right, boolean[] counts, int sort)
		{
			this.table = table;
			this.col = col;
			this.x = x;
			this.w = w;
			this.right = right;
			this.counts = counts;
			this.sort = sort;
		}
	}

	private static final class RowCells
	{
		final TableLayout layout;
		final MonsterInfo.TRow row;
		final List<List<String>> cells;
		final List<List<String>> notes;
		final List<List<String>> pics;
		final boolean picture;
		/**
		 * In a stacked row, short fields that share a line ("Lvl 13  Exp 11.5  Type
		 * Combat"), by column; null for other rows.
		 */
		List<List<Integer>> shared;

		RowCells(TableLayout layout, MonsterInfo.TRow row, List<List<String>> cells, List<List<String>> notes,
			List<List<String>> pics, boolean picture)
		{
			this.layout = layout;
			this.row = row;
			this.cells = cells;
			this.notes = notes;
			this.pics = pics;
			this.picture = picture;
		}
	}

	/**
	 * A table's lines as last built, kept so a big table (Coins has hundreds of sources)
	 * isn't sorted and wrapped again each time the mouse moves.
	 */
	private static final class BuiltTable
	{
		final int width;
		final int sort;
		final CardFont font;
		final List<Line> lines;

		BuiltTable(int width, int sort, CardFont font, List<Line> lines)
		{
			this.width = width;
			this.sort = sort;
			this.font = font;
			this.lines = lines;
		}
	}

	private final Map<MonsterInfo.Table, BuiltTable> built = new IdentityHashMap<>();
	private boolean builtIcons;
	private boolean builtSources;
	private boolean builtNames;
	/**
	 * Item names have loaded, so sources that are items can be told apart.
	 */
	boolean namesReady;
	/**
	 * Where pictures come from, for the render under way.
	 */
	private Icons pictures;

	private void tableLines(List<Line> lines, Lookup lookup, MonsterInfo.Table table, Assets a, int textW)
	{
		final Integer chosen = lookup.getSort(table.key);
		final int sort = chosen != null ? chosen : table.defaultSort >= 0 ? table.defaultSort * 2 : -1;
		if (tableIcons != builtIcons || sourceIcons != builtSources || namesReady != builtNames)
		{
			built.clear();
			builtIcons = tableIcons;
			builtSources = sourceIcons;
			builtNames = namesReady;
		}
		BuiltTable b = built.get(table);
		if (b == null || b.width != textW || b.sort != sort || b.font != a.body)
		{
			if (built.size() > 48)
			{
				built.clear();
			}
			b = new BuiltTable(textW, sort, a.body, buildTable(table, sort, a, textW));
			built.put(table, b);
		}
		lines.addAll(b.lines);
	}

	private List<Line> buildTable(MonsterInfo.Table table, int sort, Assets a, int textW)
	{
		final List<Line> lines = new ArrayList<>();
		final CardFont f = a.body;
		final CardFont small = a.small;
		final int lh = f.lineHeight();
		final int all = table.headers != null ? table.headers.size() : table.rows.isEmpty() ? 0 : table.rows.get(0).cells.size();
		// The columns shown: picture-only columns without a heading (an item's own picture)
		// are left out when pictures are turned off
		final List<Integer> shown = new ArrayList<>();
		final List<Boolean> counted = new ArrayList<>();
		for (int c = 0; c < all; c++)
		{
			boolean pics = false;
			boolean text = false;
			boolean counts = false;
			for (MonsterInfo.TRow r : table.rows)
			{
				final List<String> p = r.icons != null && c < r.icons.size() ? r.icons.get(c) : null;
				if (p != null && !p.isEmpty())
				{
					pics = true;
					for (String one : p)
					{
						counts |= !one.split("\\|")[1].equals("0");
					}
				}
				text |= c < r.cells.size() && !r.cells.get(c).isEmpty();
			}
			final boolean blank = table.headers == null || table.headers.get(c).trim().isEmpty();
			if (pics && !text && blank && !counts && !tableIcons)
			{
				continue;
			}
			shown.add(c);
			counted.add(counts);
		}
		// Columns that won't fit at a readable width are left off the right
		final int n = Math.min(shown.size(), Math.max(1, textW / MIN_COLUMN));
		if (n == 0)
		{
			return lines;
		}
		final int[] col = new int[n];
		final boolean[] right = new boolean[n];
		final boolean[] counts = new boolean[n];
		final int[] natural = new int[n];
		final boolean picture = table.sources && sourceIcons;
		for (int k = 0; k < n; k++)
		{
			col[k] = shown.get(k);
			counts[k] = counted.get(k);
			right[k] = col[k] < table.right.length && table.right[col[k]];
		}
		// Five or more columns can't all be read side by side, so each row is laid out
		// down the card instead, like a small card of its own
		if (n >= 5 || shown.size() > n)
		{
			return buildStacked(table, sort, a, textW, shown, counted);
		}
		for (int k = 0; k < n; k++)
		{
			final int c = shown.get(k);
			final List<Integer> widths = new ArrayList<>();
			int pictures = 0;
			for (MonsterInfo.TRow r : table.rows)
			{
				if (c < r.cells.size() && !r.cells.get(c).isEmpty())
				{
					widths.add(Math.min(textW, Rich.width(f, r.cells.get(c))));
				}
				if (r.icons != null && c < r.icons.size() && r.icons.get(c) != null)
				{
					pictures = Math.max(pictures, Math.min(4, r.icons.get(c).size()));
				}
			}
			Collections.sort(widths);
			// Number columns go by their usual width, so one long "13; 18; 25; 39" level
			// wraps instead of widening the column for every row. They're never narrower than
			// their longest single word, so "30/128" is never cut short.
			int typical = widths.isEmpty() ? 0 : right[k] ? widths.get((widths.size() - 1) * 9 / 10) : widths.get(widths.size() - 1);
			if (right[k])
			{
				typical = Math.max(typical, longestWord(table, c, f));
			}
			// Pictures sit side by side, so a spell's runes fit on one line
			typical = Math.max(typical, pictures * ICON_STEP);
			if (table.headers != null)
			{
				typical = Math.max(typical, f.width(table.headers.get(c)) + (table.sortable ? 10 : 0));
			}
			if (k == 0 && picture || tableIcons && hasLead(table, c))
			{
				typical += ICON_STEP;
			}
			natural[k] = typical + CELL_GAP + 4 + (right[k] && table.sortable ? 9 : 0);
		}
		final int[] w = columns(natural, right, textW);
		for (int k = 0; k < n; k++)
		{
			// Keep every number column wide enough for its longest word, and every picture
			// column for its pictures, taking it from the text columns
			int need = right[k] ? Math.max(longestWord(table, col[k], f) + CELL_GAP + 4 + (table.sortable ? 9 : 0), 0) : 0;
			int pics = 0;
			for (MonsterInfo.TRow r : table.rows)
			{
				if (r.icons != null && col[k] < r.icons.size() && r.icons.get(col[k]) != null)
				{
					pics = Math.max(pics, Math.min(4, r.icons.get(col[k]).size()));
				}
			}
			need = Math.max(need, pics * ICON_STEP + CELL_GAP);
			if (w[k] < need)
			{
				int widest = -1;
				for (int d = 0; d < n; d++)
				{
					if (!right[d] && (widest < 0 || w[d] > w[widest]))
					{
						widest = d;
					}
				}
				if (widest >= 0 && w[widest] - (need - w[k]) >= MIN_COLUMN)
				{
					w[widest] -= need - w[k];
					w[k] = need;
				}
			}
		}
		final int[] x = new int[n];
		for (int k = 1; k < n; k++)
		{
			x[k] = x[k - 1] + w[k - 1];
		}
		final int shownSort = sort >= 0 && sort / 2 < all ? sort : -1;
		final TableLayout layout = new TableLayout(table, col, x, w, right, counts, table.sortable ? shownSort : -1);
		if (table.headers != null)
		{
			Line head = new Line(Line.Kind.THEAD, null, HEADING_RED, null, null, null, null, lh + ROW_PAD);
			head.data = layout;
			lines.add(head);
		}
		final List<MonsterInfo.TRow> rows = new ArrayList<>(table.rows);
		if (shownSort >= 0)
		{
			final int sc = shownSort / 2;
			final java.util.Comparator<MonsterInfo.TRow> by = (p, q) -> compareCells(key(p, sc), key(q, sc));
			rows.sort(shownSort % 2 == 1 ? by.reversed() : by);
		}
		final List<Line> made = new ArrayList<>();
		int tallestRow = 0;
		for (MonsterInfo.TRow r : rows)
		{
			final List<List<String>> cells = new ArrayList<>();
			final List<List<String>> notes = new ArrayList<>();
			final List<List<String>> pics = new ArrayList<>();
			// A source that's an item itself gets its picture, if that's turned on
			final boolean pic = picture && r.link != null;
			int tallest = pic ? ICON_LINE - ROW_PAD + 4 : lh;
			for (int k = 0; k < n; k++)
			{
				final int c = col[k];
				// Number columns line up under the heading, clear of its sort arrow
				final boolean lead = tableIcons && r.lead != null && c < r.lead.size() && r.lead.get(c) != null;
				final String text = c < r.cells.size() ? r.cells.get(c) : "";
				final List<String> allPics = r.icons != null && c < r.icons.size() && r.icons.get(c) != null
					? r.icons.get(c) : Collections.<String>emptyList();
				// Text with its pictures in place (a skill icon by each level) wraps as text
				final boolean rich = Rich.has(text);
				final List<String> cellPics = rich ? Collections.<String>emptyList() : allPics;
				final CardFont cf = rich ? new Rich(f, allPics, pictures, this) : f;
				// Pictures beside text (a combat icon by a level) sit small on the same line
				final int inline = !text.isEmpty() && !cellPics.isEmpty() ? cellPics.size() * (lh + 3) : 0;
				final int room = w[k] - CELL_GAP - 4 - (right[k] && table.sortable ? 9 : 0) - (k == 0 && pic || lead ? ICON_STEP : 0) - inline;
				List<String> parts = text.isEmpty() ? Collections.<String>emptyList() : wrap(text, cf, room);
				if (parts.size() > MAX_CELL_LINES)
				{
					List<String> cut = new ArrayList<>(parts.subList(0, MAX_CELL_LINES));
					cut.set(MAX_CELL_LINES - 1, fit(String.join(" ", parts.subList(MAX_CELL_LINES - 1, parts.size())), f, room));
					parts = cut;
				}
				final String note = r.notes != null && c < r.notes.size() ? r.notes.get(c) : null;
				List<String> noteParts = note == null || note.isEmpty() ? Collections.<String>emptyList() : wrap(note, small, room);
				if (noteParts.size() > 2)
				{
					noteParts = new ArrayList<>(noteParts.subList(0, 2));
					noteParts.set(1, fit(noteParts.get(1) + "...", small, room));
				}
				final List<String> p = r.icons != null && c < r.icons.size() && r.icons.get(c) != null
					? r.icons.get(c) : Collections.<String>emptyList();
				cells.add(parts);
				notes.add(noteParts);
				pics.add(p);
				int height = parts.size() * lh + noteParts.size() * (small.lineHeight() - 1);
				if (lead)
				{
					height = Math.max(height, ICON_LINE - 4);
				}
				if (!p.isEmpty() && inline == 0 && !rich)
				{
					final int perLine = Math.max(1, (w[k] - CELL_GAP) / ICON_STEP);
					height += ((p.size() + perLine - 1) / perLine) * ICON_LINE - 4;
				}
				tallest = Math.max(tallest, height);
			}
			Line row = new Line(Line.Kind.TROW, null, INK, null, null, null, null, tallest + ROW_PAD);
			row.data = new RowCells(layout, r, cells, notes, pics, pic);
			made.add(row);
			tallestRow = Math.max(tallestRow, row.height);
		}
		if (table.uniform)
		{
			// Every row as tall as the tallest, so drop lists read evenly
			for (int i = 0; i < made.size(); i++)
			{
				final Line old = made.get(i);
				final Line even = new Line(Line.Kind.TROW, null, INK, null, null, null, null, tallestRow);
				even.data = old.data;
				made.set(i, even);
			}
		}
		lines.addAll(made);
		return lines;
	}

	/**
	 * A table with too many columns, laid out row by row: the row's name (with its picture),
	 * then a "Heading: value" line for each other column. Its heading strip holds the sort
	 * buttons.
	 */
	private List<Line> buildStacked(MonsterInfo.Table table, int sort, Assets a, int textW, List<Integer> shown, List<Boolean> counted)
	{
		final List<Line> lines = new ArrayList<>();
		final CardFont f = a.body;
		final CardFont small = a.small;
		final int lh = f.lineHeight();
		final int n = shown.size();
		final int[] col = new int[n];
		final boolean[] right = new boolean[n];
		final boolean[] counts = new boolean[n];
		int labelW = 0;
		for (int k = 0; k < n; k++)
		{
			col[k] = shown.get(k);
			counts[k] = counted.get(k);
			if (k > 0 && table.headers != null)
			{
				labelW = Math.max(labelW, small.width(table.headers.get(col[k])) + 10);
			}
		}
		labelW = Math.min(labelW + 8, textW * 2 / 5);
		final int valueW = textW - 28 - labelW;
		final int shownSort = sort >= 0 ? sort : -1;
		final TableLayout layout = new TableLayout(table, col, new int[n], new int[n], right, counts, table.sortable ? shownSort : -1);
		layout.stacked = true;
		layout.labelW = labelW;
		layout.valueW = valueW;
		if (table.headers != null && table.sortable)
		{
			// Sort buttons, wrapping onto more lines as needed
			layout.chips = new Rectangle[n];
			int x = small.width("Sort by:") + 8;
			int y = 0;
			for (int k = 0; k < n; k++)
			{
				final String label = table.headers.get(col[k]).isEmpty() ? "Name" : table.headers.get(col[k]);
				final int cw = small.width(label) + 16;
				if (x + cw > textW && x > 0)
				{
					x = small.width("Sort by:") + 8;
					y += small.lineHeight() + 4;
				}
				layout.chips[k] = new Rectangle(x, y, cw, small.lineHeight() + 2);
				x += cw + 4;
			}
			Line head = new Line(Line.Kind.THEAD, null, HEADING_RED, null, null, null, null, y + small.lineHeight() + 2 + ROW_PAD);
			head.data = layout;
			lines.add(head);
		}
		final List<MonsterInfo.TRow> rows = new ArrayList<>(table.rows);
		if (shownSort >= 0)
		{
			final int sc = shownSort / 2;
			final java.util.Comparator<MonsterInfo.TRow> by = (p, q) -> compareCells(key(p, sc), key(q, sc));
			rows.sort(shownSort % 2 == 1 ? by.reversed() : by);
		}
		for (MonsterInfo.TRow r : rows)
		{
			final List<List<String>> cells = new ArrayList<>();
			final List<List<String>> notes = new ArrayList<>();
			final List<List<String>> pics = new ArrayList<>();
			final List<List<Integer>> labels = new ArrayList<>();
			int height = 0;
			for (int k = 0; k < n; k++)
			{
				final int c = col[k];
				final boolean lead = tableIcons && r.lead != null && c < r.lead.size() && r.lead.get(c) != null;
				final String text = c < r.cells.size() ? r.cells.get(c) : "";
				final List<String> p = r.icons != null && c < r.icons.size() && r.icons.get(c) != null
					? r.icons.get(c) : Collections.<String>emptyList();
				final boolean rich = Rich.has(text);
				final CardFont cf = rich ? new Rich(f, p, pictures, this) : f;
				final int room = (k == 0 ? textW - 12 : valueW) - (lead ? ICON_STEP : 0)
					- (!rich && !text.isEmpty() && !p.isEmpty() && p.size() <= 2 ? p.size() * (lh + 3) : 0);
				final List<String> parts = text.isEmpty() ? Collections.<String>emptyList() : wrap(text, cf, room);
				final String note = r.notes != null && c < r.notes.size() ? r.notes.get(c) : null;
				final List<String> noteParts = note == null || note.isEmpty() ? Collections.<String>emptyList() : wrap(note, small, room);
				cells.add(parts);
				notes.add(noteParts);
				pics.add(p);
				labels.add(Collections.<Integer>emptyList());
				height += stackedHeight(k, parts, noteParts, rich ? Collections.<String>emptyList() : p, lead, table, c, labelW, valueW, f, small);
			}
			Line row = new Line(Line.Kind.TROW, null, INK, null, null, null, null, height + 4);
			row.data = new RowCells(layout, r, cells, notes, pics, false);
			lines.add(row);
		}
		return lines;
	}

	/**
	 * How tall one part of a stacked row is: the name strip for the first column, else a
	 * field line, as tall as its wrapped label or its value, whichever is taller.
	 */
	private static int stackedHeight(int k, List<String> parts, List<String> notes, List<String> pics, boolean lead,
		MonsterInfo.Table table, int c, int labelW, int valueW, CardFont f, CardFont small)
	{
		final int lh = f.lineHeight();
		int h = parts.size() * lh + notes.size() * (small.lineHeight() - 1);
		if (!pics.isEmpty() && !inline(parts, pics))
		{
			final int perLine = Math.max(1, valueW / ICON_STEP);
			h += ((pics.size() + perLine - 1) / perLine) * ICON_LINE;
		}
		if (lead)
		{
			h = Math.max(h, ICON_LINE - 4);
		}
		if (k == 0)
		{
			return Math.max(h, lh) + 8;
		}
		if (h == 0)
		{
			// An empty field takes no line
			return 0;
		}
		final String label = table.headers == null ? "" : table.headers.get(c);
		final int labelLines = wrap(label, small, labelW - 10).size();
		return Math.max(h, labelLines * small.lineHeight()) + 6;
	}

	/**
	 * A value whose one or two pictures sit small in front of its text (a skill icon by a
	 * level), rather than full size above it.
	 */
	private static boolean inline(List<String> parts, List<String> pics)
	{
		return !parts.isEmpty() && !pics.isEmpty() && pics.size() <= 2;
	}

	private static boolean hasLead(MonsterInfo.Table table, int c)
	{
		for (MonsterInfo.TRow r : table.rows)
		{
			if (r.lead != null && c < r.lead.size() && r.lead.get(c) != null)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The widest single word in a column, so it can be given room to show whole.
	 */
	private static int longestWord(MonsterInfo.Table table, int c, CardFont f)
	{
		int most = 0;
		for (MonsterInfo.TRow r : table.rows)
		{
			if (c < r.cells.size())
			{
				for (String word : words(r.cells.get(c)))
				{
					most = Math.max(most, Rich.width(f, word));
				}
			}
		}
		return most;
	}

	private static String key(MonsterInfo.TRow r, int col)
	{
		return col < r.sort.size() ? r.sort.get(col) : "";
	}

	/**
	 * Numbers by value, before words; words alphabetically; blanks last.
	 */
	static int compareCells(String a, String b)
	{
		final boolean ea = a == null || a.trim().isEmpty();
		final boolean eb = b == null || b.trim().isEmpty();
		if (ea || eb)
		{
			return ea == eb ? 0 : ea ? 1 : -1;
		}
		final Double na = number(a);
		final Double nb = number(b);
		if (na != null && nb != null)
		{
			return Double.compare(na, nb);
		}
		if (na != null || nb != null)
		{
			return na != null ? -1 : 1;
		}
		return a.compareToIgnoreCase(b);
	}

	private static Double number(String s)
	{
		final String t = s.trim().replace(",", "");
		final java.util.regex.Matcher m = LEADING_NUMBER.matcher(t);
		if (!m.find())
		{
			return null;
		}
		try
		{
			return Double.parseDouble(m.group(1));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	/**
	 * Column widths. Number columns (level, quantity, rarity, price) and other short ones
	 * keep their full width so they're never cut short; the text columns share the rest in
	 * proportion to their text and wrap. Spare room goes to the first text column.
	 */
	static int[] columns(int[] natural, boolean[] right, int total)
	{
		final int n = natural.length;
		final int[] w = new int[n];
		int sum = 0;
		for (int v : natural)
		{
			sum += v;
		}
		int firstText = 0;
		for (int c = 0; c < n; c++)
		{
			if (!right[c])
			{
				firstText = c;
				break;
			}
		}
		if (sum <= total)
		{
			System.arraycopy(natural, 0, w, 0, n);
			w[firstText] += total - sum;
			return w;
		}
		final int cap = total / 4;
		final int small = total / Math.max(5, n + 1);
		int fixed = 0;
		int flexible = 0;
		for (int c = 0; c < n; c++)
		{
			if (right[c] || natural[c] <= small)
			{
				fixed += Math.min(cap, natural[c]);
			}
			else
			{
				flexible += natural[c];
			}
		}
		// The text columns (names) always keep at least half the width
		final double squeeze = flexible > 0 && fixed > total / 2 ? (total / 2.0) / fixed : 1.0;
		fixed = (int) (fixed * squeeze);
		final int left = Math.max(0, total - fixed);
		int used = 0;
		for (int c = 0; c < n; c++)
		{
			if (right[c] || natural[c] <= small)
			{
				w[c] = Math.max(MIN_COLUMN * 3 / 4, (int) (Math.min(cap, natural[c]) * squeeze));
			}
			else
			{
				w[c] = Math.max(MIN_COLUMN, flexible == 0 ? left / n : (int) ((long) left * natural[c] / flexible));
			}
			used += w[c];
		}
		if (used < total)
		{
			w[firstText] += total - used;
		}
		// Rounding and minimums can overshoot; take it back from the widest
		while (used > total)
		{
			int widest = 0;
			for (int c = 1; c < n; c++)
			{
				if (w[c] > w[widest])
				{
					widest = c;
				}
			}
			if (w[widest] <= MIN_COLUMN / 2)
			{
				break;
			}
			w[widest]--;
			used--;
		}
		return w;
	}

	private void lootLines(List<Line> lines, Lookup lookup, Assets a, int textW, boolean prices)
	{
		final List<Drops.Group> drops = lookup.getDrops();
		if (drops == null)
		{
			paragraph(lines, "Fetching from the wiki...", INK_MUTED, a, textW);
		}
		else if (drops.isEmpty())
		{
			paragraph(lines, "No drop table found on the wiki for this one.", INK_MUTED, a, textW);
		}
		else
		{
			dropTable(lines, drops, a, textW, prices);
		}
	}

	private static Line bar(String title, Assets a)
	{
		return new Line(Line.Kind.BAR, title, ORANGE, null, null, null, null, a.bold.lineHeight() + 8);
	}

	/**
	 * The drop table as rows: each wiki category as a heading, then each item with its
	 * quantity, rarity and Grand Exchange price.
	 */
	private void dropTable(List<Line> lines, List<Drops.Group> groups, Assets a, int width, boolean prices)
	{
		for (Drops.Group group : groups)
		{
			if (!lines.isEmpty() && lines.get(lines.size() - 1).kind != Line.Kind.BAR)
			{
				lines.add(gap(a));
			}
			else if (!lines.isEmpty())
			{
				// A little room between the stone bar and the first heading
				lines.add(new Line(Line.Kind.GAP, "", INK, null, null, null, null, 4));
			}
			for (String part : wrap(group.heading, a.bold, width))
			{
				lines.add(new Line(Line.Kind.HEADING, part, HEADING_RED, null, null, null, null, a.bold.lineHeight() + 6));
			}
			for (Drops.Item item : group.items)
			{
				StringBuilder right = new StringBuilder(item.rarity.isEmpty() ? "?" : item.rarity);
				if (prices && item.price > 1)
				{
					right.append(" · ").append(Drops.shortPrice(item.price)).append(" gp");
				}
				String r = fit(right.toString(), a.small, width / 2);
				final boolean noQuantity = item.quantity.isEmpty() || item.quantity.equals("1") || item.quantity.equalsIgnoreCase("N/A");
				String qty = noQuantity ? "" : " x" + item.quantity;
				int room = width - ICON_W - 6 - a.small.width(r) - 12;
				String name = item.name + qty;
				List<String> parts = a.small.width(name) <= room ? Collections.singletonList(name) : wrap(name, a.small, room);
				if (parts.size() > 2)
				{
					List<String> two = new ArrayList<>(parts.subList(0, 2));
					two.set(1, fit(String.join(" ", parts.subList(1, parts.size())), a.small, room));
					parts = two;
				}
				lines.add(new Line(Line.Kind.DROP, parts.get(0), INK, r, item, parts, null, ICON_ROW));
			}
		}
	}

	private void drawDrop(Graphics2D g, Assets a, Line line, Hits hits, Rectangle inner, int top, int lh, int left, int rightEdge,
		int panelX, int textArea, int stripe)
	{
		// Stripes and dividers run the full width of the parchment, edge to edge
		if (stripe % 2 == 1)
		{
			g.setColor(DROP_STRIPE);
			g.fillRect(inner.x, top, inner.width, lh);
		}
		final Rectangle area = new Rectangle(inner.x, top, inner.width, lh);
		if (mouse != null && area.contains(mouse))
		{
			g.setColor(ROW_HOVER);
			g.fillRect(inner.x, top, inner.width, lh);
		}
		g.setColor(DROP_DIVIDER);
		g.fillRect(inner.x, top + lh - 1, inner.width, 1);
		BufferedImage icon = line.item.icon;
		if (icon != null)
		{
			// At the game's own size, so the picture stays sharp
			g.drawImage(icon, left + (ICON_W - icon.getWidth()) / 2, top + (lh - icon.getHeight()) / 2, null);
		}
		final int nameLines = line.values.size();
		int base = top + (lh - nameLines * 13) / 2 + a.small.ascent();
		for (String part : line.values)
		{
			a.small.draw(g, part, left + ICON_W + 6, base, INK);
			base += 13;
		}
		a.small.draw(g, line.right, rightEdge - a.small.width(line.right), top + (lh + a.small.ascent()) / 2 - 1, INK_RARITY);
		// Right-click a drop to open its wiki page or its card
		Rectangle row = new Rectangle(inner.x, top, inner.width, lh).intersection(inner);
		if (!row.isEmpty())
		{
			hits.rows.add(row);
			hits.targets.add(new Target(line.item.name, Kind.ITEM, true));
		}
	}

	/**
	 * An icon grid like the wiki's: equal columns, each with its icon over its value.
	 */
	private void drawGrid(Graphics2D g, Assets a, Icons icons, Line line, int x, int top, int w)
	{
		// On the parchment, like the wiki's light infobox cells, to keep cards from being all
		// dark stone
		final List<MonsterInfo.Cell> cells = line.cells;
		final int n = cells.size();
		g.setColor(GRID_BAND);
		g.fillRect(x, top, w, GRID_ICON_H);
		final int valueH = line.height - GRID_ICON_H;
		g.setColor(DROP_DIVIDER);
		g.fillRect(x, top + GRID_ICON_H - 1, w, 1);
		g.fillRect(x, top + GRID_ICON_H + valueH - 1, w, 1);
		for (int i = 0; i < n; i++)
		{
			final int cx = x + w * i / n;
			final int cw = x + w * (i + 1) / n - cx;
			if (i > 0)
			{
				g.setColor(COLUMN_LINE);
				g.fillRect(cx, top, 1, line.height - 1);
			}
			final MonsterInfo.Cell cell = cells.get(i);
			BufferedImage icon = icons == null ? null : fitIcon(icons.stat(cell.icon), GRID_ICON_H - 4, GRID_ICON_H - 4);
			if (icon != null)
			{
				g.drawImage(icon, cx + (cw - icon.getWidth()) / 2, top + (GRID_ICON_H - icon.getHeight()) / 2, null);
			}
			String value = fit(cell.value, a.small, cw - 4);
			a.small.draw(g, value, cx + (cw - a.small.width(value)) / 2, top + GRID_ICON_H + 12, INK);
			if (cell.diff != null)
			{
				// Against worn gear: green for better, red for worse
				String d = fit("(" + cell.diff + ")", a.small, cw - 4);
				a.small.draw(g, d, cx + (cw - a.small.width(d)) / 2, top + GRID_ICON_H + 12 + GRID_DIFF_H,
					cell.diff.startsWith("-") ? INK_WORSE : INK_BETTER);
			}
		}
	}

	/**
	 * "Assigned by" with each master's chathead and name under it.
	 */
	private void drawMasters(Graphics2D g, Assets a, Icons icons, Line line, int x, int top, int w, int stripe, Hits hits)
	{
		g.setColor(stripe % 2 == 0 ? Stone.PANEL : Stone.PANEL_ALT);
		g.fillRect(x, top, w, line.height);
		g.setColor(Stone.DARK);
		g.fillRect(x, top + line.height - 1, w, 1);
		shadow(g, a.plain, line.text, x + 8, top + FACT_PAD / 2 + 1 + a.plain.ascent(), ORANGE);
		final int cols = Math.max(1, (w - 8) / MASTER_W);
		final int rowTop = top + FACT_PAD + FACT_LINE;
		for (int i = 0; i < line.values.size(); i++)
		{
			final String code = line.values.get(i);
			final int col = i % cols;
			final int row = i / cols;
			// Centre the whole row of masters
			final int inRow = Math.min(cols, line.values.size() - row * cols);
			final int startX = x + (w - inRow * MASTER_W) / 2;
			final int mx = startX + col * MASTER_W;
			final int my = rowTop + row * MASTER_H;
			BufferedImage head = icons == null ? null : fitIcon(icons.master(code), HEAD, HEAD);
			if (head != null)
			{
				g.drawImage(head, mx + (MASTER_W - head.getWidth()) / 2, my + (HEAD - head.getHeight()), null);
			}
			String name = fit(Masters.name(code), a.small, MASTER_W - 2);
			final Rectangle area = new Rectangle(mx, my, MASTER_W, MASTER_H);
			final boolean lit = mouse != null && area.contains(mouse);
			shadow(g, a.small, name, mx + (MASTER_W - a.small.width(name)) / 2, my + HEAD + 12, lit ? YELLOW : WHITE);
			// Each master opens on the wiki or as a card, like a row
			final Rectangle clip = g.getClipBounds();
			final Rectangle hit = clip == null ? area : area.intersection(clip);
			if (!hit.isEmpty() && hits != null)
			{
				hits.rows.add(hit);
				hits.targets.add(new Target(Masters.name(code), Kind.NPC, true));
			}
		}
	}

	/**
	 * The icon at its own size, or scaled down to fit the box if it's bigger.
	 */
	BufferedImage fitIcon(BufferedImage src, int maxW, int maxH)
	{
		if (src == null)
		{
			return null;
		}
		if (src.getWidth() <= maxW && src.getHeight() <= maxH)
		{
			return src;
		}
		BufferedImage done = scaled.get(src);
		if (done != null && done.getWidth() <= maxW && done.getHeight() <= maxH)
		{
			return done;
		}
		double s = Math.min(maxW / (double) src.getWidth(), maxH / (double) src.getHeight());
		int w = Math.max(1, (int) Math.round(src.getWidth() * s));
		int h = Math.max(1, (int) Math.round(src.getHeight() * s));
		BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = out.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		g.drawImage(src, 0, 0, w, h, null);
		g.dispose();
		if (scaled.size() > 64)
		{
			scaled.clear();
		}
		scaled.put(src, out);
		return out;
	}

	/**
	 * The tabs along the bottom, like the game's stone side-panel tabs: the open one lit red.
	 * Every tab is the same width, and the default tab is leftmost.
	 */
	private void tabs(Graphics2D g, Assets a, Lookup lookup, Hover hover, Hits hits, int top)
	{
		final Tab[] tabs = lookup.getTabs().toArray(new Tab[0]);
		final int h = FOOTER_H - 3;
		int widest = 0;
		for (Tab tab : tabs)
		{
			widest = Math.max(widest, a.small.width(tab.getLabel()));
		}
		final int w = widest + 14;
		int x = M + 2;
		for (int i = 0; i < tabs.length; i++)
		{
			final Tab tab = tabs[i];
			final String word = tab.getLabel();
			final boolean open = lookup.getTab() == tab;
			final boolean hovered = hover == Hover.tab(i);
			g.setColor(Stone.EDGE);
			g.fillRect(x, top, w, h);
			g.setColor(open ? new Color(110, 32, 22) : hovered ? Stone.PANEL_ALT : Stone.PANEL);
			g.fillRect(x + 1, top + 1, w - 2, h - 2);
			g.setColor(open ? new Color(160, 60, 40) : Stone.LIGHT);
			g.fillRect(x + 1, top + 1, w - 2, 1);
			g.fillRect(x + 1, top + 1, 1, h - 2);
			g.setColor(open ? new Color(70, 18, 12) : Stone.DARK);
			g.fillRect(x + 1, top + h - 2, w - 2, 1);
			g.fillRect(x + w - 2, top + 1, 1, h - 2);
			// Rounded top corners
			g.setColor(Stone.FILL);
			g.fillRect(x, top, 1, 1);
			g.fillRect(x + w - 1, top, 1, 1);
			shadow(g, a.small, word, x + (w - a.small.width(word)) / 2, top + h - 4, open || hovered ? WHITE : ORANGE);
			// Every tab is listed, so the hover index lines up with the tab drawn
			hits.tabs.add(new Rectangle(x, top, w, h));
			hits.tabViews.add(tab);
			x += w + 2;
		}
	}

	private void drawPicture(Graphics2D g, BufferedImage source, int x, int y, int w, int h, boolean figure, boolean item)
	{
		if (source != pictureSource || picture == null || pictureW != w || pictureH != h || pictureFigure != figure)
		{
			// The wiki's item pictures are cropped to their edges, so a solid item like a
			// chef's hat would press against the frame; items get a border of their own
			picture = CardPicture.fit(source, w, h, figure, item ? Math.max(CardPicture.PAD, Math.min(w, h) / 10) : CardPicture.PAD);
			pictureSource = source;
			pictureW = w;
			pictureH = h;
			pictureFigure = figure;
		}
		Shape clip = g.getClip();
		g.setClip(x, y, w, h);
		g.drawImage(picture.image, x + picture.x, y + picture.y, null);
		g.setClip(clip);
	}

	/**
	 * How tall the picture window is. Fit to picture follows the monster's shape between
	 * limits, so a wide dragon gets a short window and a tall giant a taller one. Compact is
	 * a fixed share; clicking it shows the picture at the panel's full width, leaving room
	 * below for the stats.
	 */
	private int artHeight(PortraitSize size, boolean expanded, BufferedImage image, boolean item)
	{
		if (size == PortraitSize.HIDDEN)
		{
			return 0;
		}
		// A tall picture made for sharing keeps the picture the card shows on screen
		final int height = (sharing || fitting) && baseHeight > 0 ? baseHeight : this.height;
		// Item pictures are small objects, so they get a smaller window and aren't blown up
		final int compact = (int) Math.round(height * (item ? ITEM_SHARE : ART_SHARE));
		final int maxFull = Math.max(compact, height - FULL_RESERVE);
		int needed = compact;
		if (image != null)
		{
			if (image != trimmedSource)
			{
				BufferedImage t = CardPicture.trim(image);
				trimmedSource = image;
				trimmedW = Math.max(1, t.getWidth());
				trimmedH = Math.max(1, t.getHeight());
			}
			final int innerW = width - 2 * M - 2 * CardPicture.PAD;
			final double scale = Math.min(innerW / (double) trimmedW, item ? 1.0 : MAX_PICTURE_SCALE);
			needed = (int) Math.round(trimmedH * scale) + 2 * CardPicture.PAD;
		}
		if (expanded)
		{
			return image == null ? compact : clamp(needed, compact, maxFull);
		}
		if (size == PortraitSize.FIT && image != null)
		{
			return item
				? clamp(needed, (int) Math.round(height * ITEM_MIN_SHARE), compact)
				: clamp(needed, (int) Math.round(height * FIT_MIN_SHARE), (int) Math.round(height * FIT_MAX_SHARE));
		}
		return compact;
	}

	private static int clamp(int v, int lo, int hi)
	{
		return Math.max(lo, Math.min(hi, v));
	}

	private List<String> wrapExamine(String examine, Assets a, int width)
	{
		if (a.plain.width(examine) <= width)
		{
			return Collections.singletonList(examine);
		}
		List<String> lines = wrap(examine, a.small, width);
		if (lines.size() > 2)
		{
			List<String> two = new ArrayList<>(lines.subList(0, 2));
			two.set(1, fit(two.get(1) + " " + lines.get(2), a.small, width));
			return two;
		}
		return lines;
	}

	/**
	 * The game's scrollbar: arrow buttons at each end, a dark track and a raised thumb.
	 */
	private static void scrollbar(Graphics2D g, Hits hits, int x, int y, int w, int h, int scroll, int maxScroll, int visible)
	{
		g.setColor(BAR_TRACK);
		g.fillRect(x, y, w, h);
		for (int i = 0; i < 2; i++)
		{
			int by = i == 0 ? y : y + h - w;
			button(g, x, by, w, w);
			g.setColor(GREY);
			for (int r = 0; r < 4; r++)
			{
				int ry = i == 0 ? by + 6 + r : by + w - 7 - r;
				g.fillRect(x + w / 2 - r, ry, r * 2 + 1, 1);
			}
		}
		int track = h - 2 * w;
		int thumbH = Math.max(12, track * visible / (visible + maxScroll));
		int thumbY = y + w + (track - thumbH) * scroll / Math.max(1, maxScroll);
		button(g, x, thumbY, w, thumbH);

		hits.scrollUp = new Rectangle(x, y, w, w);
		hits.scrollDown = new Rectangle(x, y + h - w, w, w);
		hits.scrollTrack = new Rectangle(x, y + w, w, track);
		hits.scrollThumb = new Rectangle(x, thumbY, w, thumbH);
	}

	private static void button(Graphics2D g, int x, int y, int w, int h)
	{
		g.setColor(BAR_FILL);
		g.fillRect(x, y, w, h);
		g.setColor(BAR_LIGHT);
		g.fillRect(x, y, w, 1);
		g.fillRect(x, y, 1, h);
		g.setColor(BAR_DARK);
		g.fillRect(x, y + h - 1, w, 1);
		g.fillRect(x + w - 1, y, 1, h);
	}

	/**
	 * Raised stone: outer edge, lit top-left, dark bottom-right, flat fill.
	 */
	private static void raised(Graphics2D g, int x, int y, int w, int h)
	{
		g.setColor(Stone.EDGE);
		g.drawRect(x, y, w - 1, h - 1);
		g.setColor(Stone.FILL);
		g.fillRect(x + 1, y + 1, w - 2, h - 2);
		g.setColor(Stone.LIGHT);
		g.fillRect(x + 1, y + 1, w - 2, 1);
		g.fillRect(x + 1, y + 1, 1, h - 2);
		g.setColor(Stone.DARK);
		g.fillRect(x + 1, y + h - 2, w - 2, 1);
		g.fillRect(x + w - 2, y + 1, 1, h - 2);
	}

	/**
	 * Sunken panel: dark top-left, lit bottom-right, like the game's inset boxes.
	 */
	private static void sunken(Graphics2D g, int x, int y, int w, int h, Color fill)
	{
		if (fill != null)
		{
			g.setColor(fill);
			g.fillRect(x, y, w, h);
		}
		g.setColor(Stone.DARK);
		g.fillRect(x - 1, y - 1, w + 2, 1);
		g.fillRect(x - 1, y - 1, 1, h + 2);
		g.setColor(Stone.LIGHT);
		g.fillRect(x - 1, y + h, w + 2, 1);
		g.fillRect(x + w, y - 1, 1, h + 2);
	}

	private Rectangle closeBounds(Assets a, int plateY)
	{
		if (a.close != null)
		{
			int h = Math.min(a.close.getHeight(), PLATE_H - 4);
			int w = a.close.getWidth() * h / a.close.getHeight();
			return new Rectangle(width - M - 3 - w, plateY + (PLATE_H - h) / 2, w, h);
		}
		int w = a.bold.width("x");
		return new Rectangle(width - M - 8 - w, plateY + 2, w + 4, PLATE_H - 4);
	}

	private static void drawClose(Graphics2D g, Assets a, Rectangle r, boolean hovered)
	{
		BufferedImage sprite = hovered && a.closeHovered != null ? a.closeHovered : a.close;
		if (sprite != null)
		{
			g.drawImage(sprite, r.x, r.y, r.width, r.height, null);
			return;
		}
		shadow(g, a.bold, "x", r.x + 2, r.y + 13, hovered ? WHITE : GREY);
	}

	/**
	 * Draws text the way the game does, with a one pixel black shadow.
	 */
	private static void shadow(Graphics2D g, CardFont f, String s, int x, int y, Color c)
	{
		if (f instanceof Marker)
		{
			// Found words get their band first, so it sits behind the shadow as well
			((Marker) f).band(g, s, x, y);
			f = Marker.plain(f);
		}
		f.draw(g, s, x + 1, y + 1, Color.BLACK);
		f.draw(g, s, x, y, c);
	}

	private void factRow(List<Line> lines, String label, String value, String url, Assets a, int width)
	{
		int room = Math.max(40, width - a.body.width(label) - 14);
		List<String> values = a.body.width(value) <= room ? Collections.singletonList(value) : wrap(value, a.body, room);
		lines.add(new Line(Line.Kind.FACT, label, ORANGE, url, null, values, null, FACT_PAD + Math.max(1, values.size()) * factLine(a)));
	}

	/**
	 * The step between a fact row's lines, for the chosen text size.
	 */
	private static int factLine(Assets a)
	{
		return a.body == a.plain ? FACT_LINE : Math.max(12, a.body.lineHeight() - 1);
	}

	/**
	 * A stone heading bar with + or - at its left; clicking it folds or opens the section.
	 */
	private void drawBar(Graphics2D g, Assets a, Line line, Hits hits, int x, int top, int w, int offset, boolean pinned)
	{
		final int lh = line.height;
		// Only the part inside the panel, so a bar half off the bottom doesn't cover the tabs
		final Rectangle clipped = g.getClipBounds();
		final Rectangle area = clipped == null ? new Rectangle(x, top, w, lh) : new Rectangle(x, top, w, lh).intersection(clipped);
		final boolean lit = mouse != null && area.contains(mouse);
		raised(g, x, top, w, lh);
		shadow(g, a.bold, line.text, x + w / 2 - a.bold.width(line.text) / 2, top + (lh + a.bold.ascent()) / 2 - 1, lit ? WHITE : ORANGE);
		final boolean open = !(line.data instanceof Boolean) || (Boolean) line.data;
		final int cx = x + 12;
		final int cy = top + lh / 2;
		final Color sign = lit ? WHITE : ORANGE;
		g.setColor(Color.BLACK);
		g.fillRect(cx - 3, cy, 8, 2);
		g.setColor(sign);
		g.fillRect(cx - 4, cy - 1, 8, 2);
		if (!open)
		{
			g.setColor(Color.BLACK);
			g.fillRect(cx, cy - 3, 2, 8);
			g.setColor(sign);
			g.fillRect(cx - 1, cy - 4, 2, 8);
		}
		final Bar bar = new Bar(area, line.key, offset, pinned);
		if (pinned)
		{
			// Over the rows beneath it, so it's found first
			hits.bars.add(0, bar);
		}
		else
		{
			hits.bars.add(bar);
		}
	}

	/**
	 * A small camera, for copying a picture of the card: drawn pixel by pixel in the game's
	 * style, with a dark outline, a stone body, a lens and a lit edge.
	 */
	private static final String[] CAMERA = {
		"....oooo......",
		"...oLLLLo.....",
		"oooooooooooooo",
		"oLLLLLLLLLLLLo",
		"oLBBBoooooBBDo",
		"oLBBoGGGGGoBDo",
		"oLBBoGWGGGoBDo",
		"oLBBoGGGGGoBDo",
		"oLBBBoooooBBDo",
		"oDDDDDDDDDDDDo",
		"oooooooooooooo",
	};

	private static void drawCamera(Graphics2D g, Rectangle r, boolean lit)
	{
		final int w = CAMERA[0].length();
		final int h = CAMERA.length;
		final int bx = r.x + (r.width - w) / 2;
		final int by = r.y + (r.height - h) / 2;
		for (int y = 0; y < h; y++)
		{
			for (int x = 0; x < w; x++)
			{
				final Color c;
				switch (CAMERA[y].charAt(x))
				{
					case 'o':
						c = Color.BLACK;
						break;
					case 'L':
						c = lit ? new Color(200, 190, 170) : new Color(150, 140, 120);
						break;
					case 'B':
						c = lit ? new Color(150, 140, 120) : new Color(110, 100, 82);
						break;
					case 'D':
						c = new Color(60, 52, 40);
						break;
					case 'G':
						c = lit ? new Color(255, 190, 70) : ORANGE;
						break;
					case 'W':
						c = WHITE;
						break;
					default:
						continue;
				}
				g.setColor(c);
				g.fillRect(bx + x, by + y, 1, 1);
			}
		}
	}

	/**
	 * A stone button like the tabs along the bottom: lit red when chosen.
	 */
	private static void stoneButton(Graphics2D g, Rectangle r, boolean open, boolean hovered)
	{
		g.setColor(Stone.EDGE);
		g.fillRect(r.x, r.y, r.width, r.height);
		g.setColor(open ? new Color(110, 32, 22) : hovered ? Stone.PANEL_ALT : Stone.PANEL);
		g.fillRect(r.x + 1, r.y + 1, r.width - 2, r.height - 2);
		g.setColor(open ? new Color(160, 60, 40) : Stone.LIGHT);
		g.fillRect(r.x + 1, r.y + 1, r.width - 2, 1);
		g.fillRect(r.x + 1, r.y + 1, 1, r.height - 2);
		g.setColor(open ? new Color(70, 18, 12) : Stone.DARK);
		g.fillRect(r.x + 1, r.y + r.height - 2, r.width - 2, 1);
		g.fillRect(r.x + r.width - 2, r.y + 1, 1, r.height - 2);
	}

	/**
	 * A back or forward arrow on the name bar, faint when there's nowhere to go.
	 */
	private static void historyArrow(Graphics2D g, Rectangle r, boolean left, boolean active, boolean lit)
	{
		final int cx = r.x + r.width / 2;
		final int cy = r.y + r.height / 2;
		for (int pass = 0; pass < 2; pass++)
		{
			final int o = pass == 0 ? 1 : 0;
			g.setColor(pass == 0 ? Color.BLACK : !active ? new Color(110, 100, 82) : lit ? WHITE : ORANGE);
			for (int i = 0; i < 5; i++)
			{
				final int x = left ? cx - 2 + i : cx + 2 - i;
				g.fillRect(x + o, cy - i + o, 1, i * 2 + 1);
			}
		}
	}

	/**
	 * The dropdown's arrow: pointing down when shut, up when open.
	 */
	private static void downArrow(Graphics2D g, int cx, int cy, boolean up, boolean lit)
	{
		for (int pass = 0; pass < 2; pass++)
		{
			final int o = pass == 0 ? 1 : 0;
			g.setColor(pass == 0 ? Color.BLACK : lit ? WHITE : ORANGE);
			for (int i = 0; i < 4; i++)
			{
				final int yy = up ? cy - 2 + i : cy + 1 - i;
				g.fillRect(cx - i + o, yy + o, i * 2 + 1, 1);
			}
		}
	}

	/**
	 * A line of the wiki's writing. Lines marked to justify are spread to both edges.
	 */
	private static void drawText(Graphics2D g, CardFont f, Line line, int x, int base, int width)
	{
		final String[] words = line.text.split(" ");
		if (line.right == null || words.length < 2)
		{
			f.draw(g, line.text, x, base, line.colour);
			return;
		}
		int used = 0;
		for (String word : words)
		{
			used += f.width(word);
		}
		final int gaps = words.length - 1;
		final int space = width - used;
		// A line that would need huge gaps is left as it is
		if (space > gaps * f.width(" ") * 4)
		{
			f.draw(g, line.text, x, base, line.colour);
			return;
		}
		int at = x;
		for (int i = 0; i < words.length; i++)
		{
			f.draw(g, words[i], at, base, line.colour);
			at += f.width(words[i]) + (i < gaps ? space / gaps + (i < space % gaps ? 1 : 0) : 0);
		}
	}

	private void drawHead(Graphics2D g, Assets a, Line line, Hits hits, Rectangle inner, int top, int lh, int left, boolean pinned)
	{
		final TableLayout t = (TableLayout) line.data;
		if (t.stacked)
		{
			drawSortChips(g, a, t, hits, inner, top, lh, left, pinned);
			return;
		}
		if (pinned)
		{
			// Solid behind a pinned heading, so rows don't show through
			g.setColor(new Color(214, 196, 158));
			g.fillRect(inner.x, top, inner.width, lh);
		}
		g.setColor(HEAD_BAND);
		g.fillRect(inner.x, top, inner.width, lh);
		final CardFont f = a.body;
		final int arrow = t.table.sortable ? 9 : 0;
		for (int c = 0; c < t.x.length; c++)
		{
			final int cx = left + 2 + t.x[c];
			if (c > 0)
			{
				g.setColor(COLUMN_LINE);
				g.fillRect(cx - 4, top, 1, lh);
			}
			final String text = fit(t.table.headers.get(t.col[c]), f, t.w[c] - CELL_GAP - 4 - arrow);
			final int tx = t.right[c] ? cx + Math.max(0, (t.w[c] - CELL_GAP - 4 - arrow - f.width(text)) / 2) : cx;
			final Rectangle area = new Rectangle(cx - 4, top, t.w[c], lh).intersection(inner);
			final boolean lit = t.table.sortable && mouse != null && area.contains(mouse);
			f.draw(g, text, tx, top + ROW_PAD / 2 + f.ascent(), lit ? INK : HEADING_RED);
			if (t.table.sortable)
			{
				final int ax = tx + f.width(text) + 3;
				final int ay = top + lh / 2;
				final boolean active = t.sort >= 0 && t.sort / 2 == t.col[c];
				g.setColor(active ? HEADING_RED : new Color(128, 0, 0, 90));
				final boolean down = active && t.sort % 2 == 1;
				for (int r = 0; r < 3; r++)
				{
					// A small arrow: up for the order as sorted, down when reversed
					int ry = down ? ay - 1 + r : ay + 1 - r;
					g.fillRect(ax + 2 - r, ry, r * 2 + 1, 1);
				}
				if (!area.isEmpty())
				{
					final Head head = new Head(area, t.table.key, t.col[c], t.sort);
					head.pinned = pinned;
					if (pinned)
					{
						hits.heads.add(0, head);
					}
					else
					{
						hits.heads.add(head);
					}
				}
			}
		}
		g.setColor(new Color(90, 60, 30, 90));
		g.fillRect(inner.x, top + lh - 1, inner.width, 1);
		if (pinned)
		{
			// Still catches clicks, so rows hidden under it aren't clicked by mistake
			hits.bars.add(0, new Bar(new Rectangle(inner.x, top, inner.width, lh), null, 0, true));
		}
	}

	/**
	 * A stacked table's heading strip: "Sort by:" and a button for each column.
	 */
	private void drawSortChips(Graphics2D g, Assets a, TableLayout t, Hits hits, Rectangle inner, int top, int lh, int left, boolean pinned)
	{
		if (pinned)
		{
			g.setColor(new Color(214, 196, 158));
			g.fillRect(inner.x, top, inner.width, lh);
		}
		g.setColor(HEAD_BAND);
		g.fillRect(inner.x, top, inner.width, lh);
		final CardFont f = a.small;
		final int y0 = top + ROW_PAD / 2;
		f.draw(g, "Sort by:", left + 2, y0 + f.ascent() + 1, HEADING_RED);
		for (int k = 0; k < t.chips.length; k++)
		{
			final Rectangle c = t.chips[k];
			final Rectangle area = new Rectangle(left + 2 + c.x, y0 + c.y, c.width, c.height);
			final boolean active = t.sort >= 0 && t.sort / 2 == t.col[k];
			final boolean lit = mouse != null && area.contains(mouse);
			g.setColor(active ? new Color(128, 0, 0, 70) : lit ? new Color(255, 255, 255, 60) : new Color(90, 60, 30, 40));
			g.fillRect(area.x, area.y, area.width, area.height);
			g.setColor(new Color(90, 60, 30, 110));
			g.drawRect(area.x, area.y, area.width - 1, area.height - 1);
			final String label = t.table.headers.get(t.col[k]).isEmpty() ? "Name" : t.table.headers.get(t.col[k]);
			f.draw(g, label, area.x + 4, area.y + f.ascent() + 1, active ? INK : HEADING_RED);
			if (active)
			{
				final int ax = area.x + area.width - 8;
				final int ay = area.y + area.height / 2;
				g.setColor(HEADING_RED);
				for (int r = 0; r < 3; r++)
				{
					final int ry = t.sort % 2 == 1 ? ay - 1 + r : ay + 1 - r;
					g.fillRect(ax + 2 - r, ry, r * 2 + 1, 1);
				}
			}
			final Rectangle hit = area.intersection(inner);
			if (!hit.isEmpty())
			{
				final Head head = new Head(hit, t.table.key, t.col[k], t.sort);
				head.pinned = pinned;
				if (pinned)
				{
					hits.heads.add(0, head);
				}
				else
				{
					hits.heads.add(head);
				}
			}
		}
		g.setColor(new Color(90, 60, 30, 90));
		g.fillRect(inner.x, top + lh - 1, inner.width, 1);
		if (pinned)
		{
			hits.bars.add(0, new Bar(new Rectangle(inner.x, top, inner.width, lh), null, 0, true));
		}
	}

	/**
	 * A stacked table's row as a small table of its own: the name in a strip across the
	 * top, then each other column as a line with its heading in a shaded label cell on the
	 * left and the value on the right, all lined up.
	 */
	private void drawStackedRow(Graphics2D g, Assets a, RowCells r, Hits hits, Rectangle inner, int top, int lh, int left, int stripe)
	{
		final TableLayout t = r.layout;
		final Rectangle area = new Rectangle(inner.x, top, inner.width, lh).intersection(inner);
		final CardFont f = a.body;
		final CardFont small = a.small;
		final int step = f.lineHeight();
		final Rectangle clip = g.getClipBounds();
		final int x0 = inner.x + 4;
		final int w0 = inner.width - 8;
		final int labelX = x0;
		final int valueX = x0 + t.labelW + 6;
		final int valueW = t.valueW;
		int y = top + 2;
		for (int k = 0; k < r.cells.size(); k++)
		{
			final int c = t.col[k];
			final List<String> parts = r.cells.get(k);
			final boolean rich = parts.stream().anyMatch(Rich::has);
			// Text with pictures in place draws them itself
			final List<String> pics = rich ? Collections.<String>emptyList() : r.pics.get(k);
			final CardFont tf = rich ? new Rich(f, r.pics.get(k), pictures, this) : f;
			final List<String> notes = r.notes.get(k);
			final String lead = tableIcons && r.row.lead != null && c < r.row.lead.size() ? r.row.lead.get(c) : null;
			final int h = stackedHeight(k, parts, notes, pics, lead != null, t.table, c, t.labelW, valueW, f, small);
			if (h == 0)
			{
				continue;
			}
			if (k == 0)
			{
				// The name strip, lit when hovered, as it opens the row's page
				final boolean lit = r.row.link != null && mouse != null && area.contains(mouse);
				g.setColor(lit ? new Color(150, 110, 60, 110) : HEAD_BAND);
				g.fillRect(x0, y, w0, h);
				int x = x0 + 4;
				if (lead != null && pictures != null)
				{
					final String[] part = lead.split("\\|");
					drawPicture(g, a, part.length > 2 ? pictures.wiki(part[2]) : null, x, y + (h - ICON_LINE) / 2 + 1, 0);
					x += ICON_STEP;
				}
				int base = y + (h - parts.size() * step) / 2 + f.ascent();
				for (String part : parts)
				{
					f.draw(g, part, x, base, r.row.link != null ? INK_LINK : INK);
					base += step;
				}
			}
			else
			{
				// Label cell, shaded, then the value, with lines between. Both are centred
				// down the line, so labels, pictures and text all sit level.
				g.setColor(GRID_BAND);
				g.fillRect(labelX, y, t.labelW, h);
				g.setColor(DROP_DIVIDER);
				g.fillRect(x0, y + h - 1, w0, 1);
				g.setColor(COLUMN_LINE);
				g.fillRect(labelX + t.labelW, y, 1, h);
				final String label = t.table.headers == null ? "" : t.table.headers.get(c);
				final List<String> labelLines = wrap(label, small, t.labelW - 10);
				int ly = y + (h - labelLines.size() * small.lineHeight()) / 2 + small.ascent();
				for (String part : labelLines)
				{
					small.draw(g, part, labelX + 5, ly, HEADING_RED);
					ly += small.lineHeight();
				}
				final boolean inline = inline(parts, pics);
				final int picRows = pics.isEmpty() || inline ? 0 : (pics.size() + Math.max(1, valueW / ICON_STEP) - 1) / Math.max(1, valueW / ICON_STEP);
				final int textH = parts.size() * step + notes.size() * (small.lineHeight() - 1);
				int contentH = picRows * ICON_LINE + textH;
				if (lead != null)
				{
					contentH = Math.max(contentH, ICON_LINE - 4);
				}
				int vy = y + (h - contentH) / 2;
				if (picRows > 0 && pictures != null)
				{
					final int perLine = Math.max(1, valueW / ICON_STEP);
					for (int i = 0; i < pics.size(); i++)
					{
						final String[] part = pics.get(i).split("\\|");
						int count = 0;
						try
						{
							count = part.length > 1 ? Integer.parseInt(part[1]) : 0;
						}
						catch (NumberFormatException e)
						{
							count = 0;
						}
						if (count == 0 && t.counts[k])
						{
							count = 1;
						}
						final int ix = valueX + (i % perLine) * ICON_STEP;
						final int iy = vy + (i / perLine) * ICON_LINE;
						drawPicture(g, a, part.length > 2 ? pictures.wiki(part[2]) : null, ix, iy, count);
						final Rectangle spot = new Rectangle(ix, iy, ICON_STEP, ICON_LINE);
						final Rectangle hit = clip == null ? spot : spot.intersection(clip);
						if (!hit.isEmpty() && !part[0].equals(r.row.link))
						{
							hits.rows.add(hit);
							hits.targets.add(new Target(part[0], null, true));
						}
					}
					vy += picRows * ICON_LINE;
				}
				int vx = valueX;
				if (lead != null && pictures != null)
				{
					// A picture in front of the text, both centred on the line
					final String[] part = lead.split("\\|");
					drawPicture(g, a, part.length > 2 ? pictures.wiki(part[2]) : null, vx, y + (h - ICON_LINE) / 2 + 1, 0);
					vx += ICON_STEP;
					vy = y + (h - textH) / 2;
				}
				if (inline && pictures != null)
				{
					// Small pictures on the text's first line
					for (String one : pics)
					{
						final String[] part = one.split("\\|");
						final BufferedImage icon = part.length > 2 ? fitIcon(pictures.wiki(part[2]), step, step) : null;
						if (icon != null)
						{
							g.drawImage(icon, vx + (step - icon.getWidth()) / 2, vy + (step - icon.getHeight()) / 2, null);
						}
						vx += step + 3;
					}
				}
				int base = vy + f.ascent();
				for (String part : parts)
				{
					tf.draw(g, part, vx, base, INK);
					base += step;
				}
				base += small.ascent() - f.ascent();
				for (String note : notes)
				{
					small.draw(g, note, vx, base, INK_MUTED);
					base += small.lineHeight() - 1;
				}
			}
			y += h;
		}
		// A firmer line between records
		g.setColor(new Color(90, 60, 30, 110));
		g.fillRect(inner.x, top + lh - 2, inner.width, 2);
		if (r.row.link != null && !area.isEmpty())
		{
			hits.rows.add(area);
			hits.targets.add(new Target(r.row.link, r.row.kind, r.row.card));
		}
	}

	/**
	 * A picture in a table, at most a slot's size, with a count drawn on it like the game's
	 * stack numbers.
	 */
	private void drawPicture(Graphics2D g, Assets a, BufferedImage src, int x, int y, int count)
	{
		final BufferedImage icon = fitIcon(src, ICON_STEP - 2, ICON_LINE - 2);
		if (icon != null)
		{
			g.drawImage(icon, x + (ICON_STEP - 2 - icon.getWidth()) / 2, y + (ICON_LINE - 2 - icon.getHeight()) / 2, null);
		}
		if (count > 0)
		{
			final String n = Integer.toString(count);
			a.small.draw(g, n, x + 1, y + a.small.ascent(), Color.BLACK);
			a.small.draw(g, n, x, y + a.small.ascent() - 1, YELLOW);
		}
	}

	private void drawRow(Graphics2D g, Assets a, Line line, Hits hits, Rectangle inner, int top, int lh, int left, int stripe)
	{
		final RowCells r = (RowCells) line.data;
		final TableLayout t = r.layout;
		if (t.stacked)
		{
			drawStackedRow(g, a, r, hits, inner, top, lh, left, stripe);
			return;
		}
		final Rectangle area = new Rectangle(inner.x, top, inner.width, lh).intersection(inner);
		if (stripe % 2 == 1)
		{
			g.setColor(DROP_STRIPE);
			g.fillRect(inner.x, top, inner.width, lh);
		}
		if (r.row.link != null && mouse != null && area.contains(mouse))
		{
			g.setColor(ROW_HOVER);
			g.fillRect(inner.x, top, inner.width, lh);
		}
		g.setColor(DROP_DIVIDER);
		g.fillRect(inner.x, top + lh - 1, inner.width, 1);
		final CardFont f = a.body;
		final int step = f.lineHeight();
		final int arrow = t.table.sortable ? 9 : 0;
		final Rectangle clip = g.getClipBounds();
		// A source that's an item itself, with its picture beside its name
		if (r.picture && pictures != null)
		{
			// The game's own picture for an item, else the wiki's picture of the page
			BufferedImage icon = pictures.isItem(r.row.link) ? pictures.item(r.row.link, 0) : null;
			if (icon == null)
			{
				icon = pictures.page(r.row.link);
			}
			if (icon != null)
			{
				drawPicture(g, a, icon, left + 2, top + ROW_PAD / 2 - 2, 0);
			}
		}
		for (int c = 0; c < r.cells.size(); c++)
		{
			final String lead = tableIcons && r.row.lead != null && t.col[c] < r.row.lead.size() ? r.row.lead.get(t.col[c]) : null;
			if (lead != null && pictures != null)
			{
				// The picture in front of the text, opening its own page like the row
				final String[] part = lead.split("\\|");
				final int lx = left + 2 + t.x[c];
				final int ly = top + ROW_PAD / 2 - 2;
				drawPicture(g, a, part.length > 2 ? pictures.wiki(part[2]) : null, lx, ly, 0);
			}
			final int cx = left + 2 + t.x[c] + (c == 0 && r.picture || lead != null ? ICON_STEP : 0);
			if (c > 0)
			{
				g.setColor(COLUMN_LINE);
				g.fillRect(left + 2 + t.x[c] - 4, top, 1, lh - 1);
			}
			int base = top + ROW_PAD / 2 + f.ascent();
			final boolean rich = r.cells.get(c).stream().anyMatch(Rich::has);
			final List<String> pics = rich ? Collections.<String>emptyList() : r.pics.get(c);
			final CardFont tf = rich ? new Rich(f, r.pics.get(c), pictures, this) : f;
			int textX = cx;
			if (!pics.isEmpty() && !r.cells.get(c).isEmpty())
			{
				// Small pictures in front of the text, on its first line, centred together with
				// it in a number column
				final int size = f.lineHeight();
				final int group = pics.size() * (size + 3) + f.width(r.cells.get(c).get(0));
				int px = t.right[c] ? cx + Math.max(0, (t.w[c] - CELL_GAP - 4 - arrow - group) / 2) : cx;
				for (String one : pics)
				{
					final String[] part = one.split("\\|");
					final BufferedImage icon = pictures == null || part.length < 3 ? null : fitIcon(pictures.wiki(part[2]), size, size);
					if (icon != null)
					{
						g.drawImage(icon, px + (size - icon.getWidth()) / 2, top + ROW_PAD / 2 + (size - icon.getHeight()) / 2 - 1, null);
					}
					px += size + 3;
				}
				textX = px;
			}
			else if (!pics.isEmpty() && pictures != null)
			{
				// A cell of pictures, such as a spell's runes, each with how many it takes.
				// Each opens its own page.
				final int perLine = Math.max(1, (t.w[c] - CELL_GAP) / ICON_STEP);
				final int used = Math.min(perLine, pics.size()) * ICON_STEP;
				final int startX = t.right[c] ? cx + Math.max(0, (t.w[c] - CELL_GAP - 4 - used) / 2) : cx;
				for (int i = 0; i < pics.size(); i++)
				{
					final String[] part = pics.get(i).split("\\|");
					int count = 0;
					try
					{
						count = part.length > 1 ? Integer.parseInt(part[1]) : 0;
					}
					catch (NumberFormatException e)
					{
						count = 0;
					}
					if (count == 0 && t.counts[c])
					{
						count = 1;
					}
					final int ix = startX + (i % perLine) * ICON_STEP;
					final int iy = top + ROW_PAD / 2 - 2 + (i / perLine) * ICON_LINE;
					final BufferedImage icon = part.length > 2 ? pictures.wiki(part[2]) : null;
					drawPicture(g, a, icon, ix, iy, count);
					final Rectangle spot = new Rectangle(ix, iy, ICON_STEP, ICON_LINE);
					final Rectangle hit = clip == null ? spot : spot.intersection(clip);
					if (!hit.isEmpty() && !part[0].equals(r.row.link))
					{
						hits.rows.add(hit);
						hits.targets.add(new Target(part[0], null, true));
					}
				}
				base += ((pics.size() + perLine - 1) / perLine) * ICON_LINE;
			}
			// The first column names the row's page, so it's shown as a link
			final Color colour = c == 0 && r.row.link != null ? INK_LINK : INK;
			final int room = t.w[c] - CELL_GAP - 4 - arrow;
			final int textRoom = room - (textX - cx);
			for (String part : r.cells.get(c))
			{
				final int tx = t.right[c] && textX == cx ? textX + Math.max(0, (textRoom - tf.width(part)) / 2) : textX;
				tf.draw(g, part, tx, base, colour);
				base += step;
			}
			base += a.small.ascent() - f.ascent();
			for (String note : r.notes.get(c))
			{
				final int tx = t.right[c] ? cx + Math.max(0, (room - a.small.width(note)) / 2) : cx;
				a.small.draw(g, note, tx, base, INK_MUTED);
				base += a.small.lineHeight() - 1;
			}
		}
		if (r.row.link != null && !area.isEmpty())
		{
			hits.rows.add(area);
			hits.targets.add(new Target(r.row.link, r.row.kind, r.row.card));
		}
	}


	private static Line gap(Assets a)
	{
		return new Line(Line.Kind.GAP, "", INK, null, null, null, null, a.quill.lineHeight() / 2);
	}

	private void paragraph(List<Line> lines, String text, Color colour, Assets a, int width)
	{
		if (text == null || text.trim().isEmpty())
		{
			return;
		}
		if (!lines.isEmpty())
		{
			lines.add(gap(a));
		}
		for (String line : cachedBalancedWrap(text, a.quill, width))
		{
			lines.add(line.isEmpty() ? gap(a) : new Line(Line.Kind.QUILL, line, colour, null, null, null, null, a.quill.lineHeight()));
		}
	}

	private List<String> cachedBalancedWrap(String text, CardFont font, int width)
	{
		final String key = System.identityHashCode(font) + ":" + width + ":" + text;
		List<String> lines = wrapCache.get(key);
		if (lines == null)
		{
			lines = balancedWrap(text, font, width);
			if (wrapCache.size() > 64)
			{
				wrapCache.clear();
			}
			wrapCache.put(key, lines);
		}
		return lines;
	}

	/**
	 * Wraps each paragraph to the narrowest width that needs the same number of lines, so
	 * centred text comes out even.
	 */
	static List<String> balancedWrap(String text, CardFont font, int maxWidth)
	{
		final List<String> lines = new ArrayList<>();
		for (String paragraph : text.split("\n"))
		{
			if (paragraph.trim().isEmpty())
			{
				continue;
			}
			List<String> best = wrap(paragraph, font, maxWidth);
			int lo = maxWidth / 2;
			int hi = maxWidth;
			while (best.size() > 1 && lo < hi)
			{
				int mid = (lo + hi) / 2;
				List<String> trial = wrap(paragraph, font, mid);
				if (trial.size() <= best.size())
				{
					best = trial;
					hi = mid;
				}
				else
				{
					lo = mid + 1;
				}
			}
			if (!lines.isEmpty())
			{
				lines.add("");
			}
			lines.addAll(best);
		}
		return lines;
	}

	/**
	 * The words of some text, with a picture kept with the word after it, so coins stay
	 * beside their price.
	 */
	static List<String> words(String text)
	{
		final List<String> out = new ArrayList<>();
		String held = null;
		for (String word : text.trim().split("\\s+"))
		{
			if (word.isEmpty())
			{
				continue;
			}
			if (held != null)
			{
				word = held + " " + word;
				held = null;
			}
			if (Rich.onlyMarks(word))
			{
				held = word;
				continue;
			}
			out.add(word);
		}
		if (held != null)
		{
			out.add(held);
		}
		return out;
	}

	static List<String> wrap(String text, CardFont font, int maxWidth)
	{
		final List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : words(text))
		{
			if (word.isEmpty())
			{
				continue;
			}
			String candidate = line.length() == 0 ? word : line + " " + word;
			if (font.width(candidate) <= maxWidth)
			{
				line.setLength(0);
				line.append(candidate);
				continue;
			}
			if (line.length() > 0)
			{
				lines.add(line.toString());
			}
			line.setLength(0);
			line.append(fit(word, font, maxWidth));
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}

	static String fit(String text, CardFont font, int maxWidth)
	{
		if (font.width(text) <= maxWidth)
		{
			return text;
		}
		String s = text;
		while (s.length() > 1 && font.width(s + "...") > maxWidth)
		{
			s = s.substring(0, s.length() - 1);
		}
		return s.trim() + "...";
	}
}

package com.wikipeek;

public enum PortraitSize
{
	FIT("Fit to picture"),
	COMPACT("Compact"),
	HIDDEN("Hidden");

	private final String label;

	PortraitSize(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.wikipeek;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;

/**
 * Text with small pictures in it, each marked by a private character naming which of the
 * cell's pictures goes there. Measured and drawn like text, so wrapping keeps each
 * picture by its number.
 */
final class Rich implements CardFont
{
	private static final char FIRST = '';
	private static final char LAST = '';

	private final CardFont font;
	private final List<String> icons;
	private final PanelRenderer.Icons pictures;
	private final PanelRenderer renderer;

	Rich(CardFont font, List<String> icons, PanelRenderer.Icons pictures, PanelRenderer renderer)
	{
		this.font = font;
		this.icons = icons;
		this.pictures = pictures;
		this.renderer = renderer;
	}

	static String mark(int index)
	{
		return String.valueOf((char) (FIRST + index));
	}

	static boolean has(String s)
	{
		if (s == null)
		{
			return false;
		}
		for (int i = 0; i < s.length(); i++)
		{
			final char c = s.charAt(i);
			if (c >= FIRST && c <= LAST)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * The text without its picture marks.
	 */
	static String strip(String s)
	{
		if (s == null)
		{
			return null;
		}
		return s.replaceAll("[\\uE100-\\uE10F]", "").replaceAll("\\s+", " ").trim();
	}

	private int size()
	{
		return font.lineHeight();
	}

	@Override
	public int width(String s)
	{
		int w = 0;
		int start = 0;
		for (int i = 0; i < s.length(); i++)
		{
			final char c = s.charAt(i);
			if (c >= FIRST && c <= LAST)
			{
				w += font.width(s.substring(start, i)) + size() + 2;
				start = i + 1;
			}
		}
		return w + font.width(s.substring(start));
	}

	@Override
	public int ascent()
	{
		return font.ascent();
	}

	@Override
	public int lineHeight()
	{
		return font.lineHeight();
	}

	@Override
	public int digitMiddle()
	{
		return font.digitMiddle();
	}

	/**
	 * A width for text that may hold picture marks, without needing the pictures: each
	 * mark takes a square as tall as a line.
	 */
	static int width(CardFont font, String s)
	{
		if (!has(s))
		{
			return font.width(s);
		}
		int marks = 0;
		final StringBuilder plain = new StringBuilder(s.length());
		for (int i = 0; i < s.length(); i++)
		{
			final char c = s.charAt(i);
			if (c >= FIRST && c <= LAST)
			{
				marks++;
			}
			else
			{
				plain.append(c);
			}
		}
		return font.width(plain.toString()) + marks * (font.lineHeight() + 2);
	}

	/**
	 * Whether the word is only picture marks, such as the coins before a price, which
	 * belong on the same line as the word after them.
	 */
	static boolean onlyMarks(String word)
	{
		if (word.isEmpty())
		{
			return false;
		}
		for (int i = 0; i < word.length(); i++)
		{
			final char c = word.charAt(i);
			if (c < FIRST || c > LAST)
			{
				return false;
			}
		}
		return true;
	}

	@Override
	public void draw(Graphics2D g, String s, int x, int y, Color colour)
	{
		int start = 0;
		for (int i = 0; i < s.length(); i++)
		{
			final char c = s.charAt(i);
			if (c >= FIRST && c <= LAST)
			{
				final String part = s.substring(start, i);
				font.draw(g, part, x, y, colour);
				x += font.width(part);
				final int index = c - FIRST;
				if (pictures != null && icons != null && index < icons.size())
				{
					final String[] bits = icons.get(index).split("\\|");
					final BufferedImage icon = bits.length > 2 ? renderer.fitIcon(pictures.wiki(bits[2]), size(), size()) : null;
					if (icon != null)
					{
						// Centred on the digits beside it, as the game font's ascent runs well above them
						final int top = Math.max(y - font.ascent() - 1, y - font.digitMiddle() - icon.getHeight() / 2);
						g.drawImage(icon, x + 1 + (size() - icon.getWidth()) / 2, top, null);
					}
				}
				x += size() + 2;
				start = i + 1;
			}
		}
		font.draw(g, s.substring(start), x, y, colour);
	}
}

package com.wikipeek;

import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;

/**
 * The search box's state: what's typed, the suggestions for it and which one is picked.
 * Typing happens on the input thread and drawing on the client thread, so everything goes
 * through synchronized methods and the overlay draws from a snapshot.
 */
final class SearchBox
{
	static final int MAX_SUGGESTIONS = 40;
	/**
	 * Rows shown at once; the rest are reached with the mouse wheel or the arrow keys.
	 */
	static final int VISIBLE = 8;
	static final int MAX_LENGTH = 40;

	/**
	 * A suggested page and whether it's an NPC or an item.
	 */
	static final class Suggestion
	{
		final String title;
		final Kind kind;

		Suggestion(String title, Kind kind)
		{
			this.title = title;
			this.kind = kind;
		}
	}

	static final class Snapshot
	{
		final String text;
		final List<Suggestion> suggestions;
		final int selected;
		final boolean loading;
		final int version;
		final boolean allSelected;
		/**
		 * The first suggestion shown, when there are more than fit.
		 */
		final int top;

		Snapshot(String text, List<Suggestion> suggestions, int selected, boolean loading, int version, boolean allSelected, int top)
		{
			this.top = top;
			this.allSelected = allSelected;
			this.text = text;
			this.suggestions = suggestions;
			this.selected = selected;
			this.loading = loading;
			this.version = version;
		}
	}

	private static final class Entry
	{
		final String title;
		final Kind kind;
		final String lower;
		/**
		 * The title without its bracketed part: "barbarian" for "Barbarian (Barbarian Camp)".
		 */
		final String base;
		final String[] words;

		Entry(String title, Kind kind)
		{
			this.title = title;
			this.kind = kind;
			this.lower = title.toLowerCase(Locale.ROOT);
			int bracket = lower.indexOf(" (");
			this.base = bracket > 0 ? lower.substring(0, bracket) : lower;
			this.words = base.split("[^a-z0-9']+");
		}
	}

	private boolean open;
	private String text = "";
	/**
	 * Ctrl+A: the whole text is selected, so typing or pasting replaces it.
	 */
	private boolean allSelected;
	private final java.util.Map<Kind, List<Entry>> entries = new java.util.EnumMap<>(Kind.class);
	private List<Suggestion> suggestions = Collections.emptyList();
	private int selected;
	private int version;
	private int top;
	/**
	 * Pages the wiki's own search found for {@link #onlineFor}.
	 */
	private List<String> online = Collections.emptyList();
	private String onlineFor = "";

	synchronized boolean isOpen()
	{
		return open;
	}

	synchronized void open()
	{
		open = true;
		text = "";
		allSelected = false;
		suggestions = Collections.emptyList();
		online = Collections.emptyList();
		onlineFor = "";
		selected = 0;
		top = 0;
		version++;
	}

	synchronized void close()
	{
		open = false;
		version++;
	}

	synchronized void setTitles(Kind kind, List<String> titles)
	{
		final List<Entry> list = new ArrayList<>(titles.size());
		for (String t : titles)
		{
			list.add(new Entry(t, kind));
		}
		entries.put(kind, list);
		refresh();
	}

	/**
	 * The wiki's search results for some typed text, added under the list's own matches
	 * while that text is still what's typed.
	 */
	synchronized void setOnline(String forText, List<String> titles)
	{
		if (!open || !forText.equals(text.trim()))
		{
			return;
		}
		online = titles;
		onlineFor = forText;
		final Suggestion was = suggestions.isEmpty() ? null : suggestions.get(Math.min(selected, suggestions.size() - 1));
		final int keepTop = top;
		refresh();
		// Results arriving shouldn't move what's picked or the scroll
		if (was != null)
		{
			for (int i = 0; i < suggestions.size(); i++)
			{
				if (suggestions.get(i).title.equals(was.title))
				{
					selected = i;
					top = Math.min(keepTop, Math.max(0, suggestions.size() - VISIBLE));
					break;
				}
			}
		}
	}

	synchronized void type(char c)
	{
		if (allSelected)
		{
			text = "";
			allSelected = false;
		}
		if (text.length() < MAX_LENGTH)
		{
			text = text + c;
		}
		refresh();
	}

	synchronized void backspace()
	{
		if (allSelected)
		{
			text = "";
			allSelected = false;
			refresh();
		}
		else if (!text.isEmpty())
		{
			text = text.substring(0, text.length() - 1);
			refresh();
		}
	}

	synchronized void selectAll()
	{
		if (!text.isEmpty())
		{
			allSelected = true;
			version++;
		}
	}

	/**
	 * Pastes text in, on one line, replacing the text if it's all selected.
	 */
	synchronized void paste(String pasted)
	{
		if (pasted == null)
		{
			return;
		}
		String clean = pasted.replaceAll("[\\r\\n\\t]+", " ").replaceAll("\\p{Cntrl}", "");
		if (allSelected)
		{
			text = "";
			allSelected = false;
		}
		text = (text + clean);
		if (text.length() > MAX_LENGTH)
		{
			text = text.substring(0, MAX_LENGTH);
		}
		refresh();
	}

	/**
	 * Ctrl+X: the text, then cleared. Ctrl+C just reads it.
	 */
	synchronized String cut()
	{
		final String was = text;
		text = "";
		allSelected = false;
		refresh();
		return was;
	}

	synchronized String getText()
	{
		return text;
	}

	synchronized void move(int delta)
	{
		if (!suggestions.isEmpty())
		{
			selected = Math.floorMod(selected + delta, suggestions.size());
			// Keep the picked one in view
			if (selected < top)
			{
				top = selected;
			}
			else if (selected >= top + VISIBLE)
			{
				top = selected - VISIBLE + 1;
			}
			version++;
		}
	}

	/**
	 * The mouse wheel: scrolls the list without changing what's picked.
	 */
	synchronized void scroll(int delta)
	{
		final int most = Math.max(0, suggestions.size() - VISIBLE);
		final int to = Math.max(0, Math.min(most, top + delta));
		if (to != top)
		{
			top = to;
			version++;
		}
	}

	synchronized void select(int index)
	{
		index += top;
		if (index >= 0 && index < suggestions.size() && index != selected)
		{
			selected = index;
			version++;
		}
	}

	/**
	 * What Enter looks up: the picked suggestion, or what was typed (with no kind) if there
	 * are none. Null if nothing's typed.
	 */
	synchronized Suggestion choice()
	{
		if (!suggestions.isEmpty())
		{
			return suggestions.get(Math.min(selected, suggestions.size() - 1));
		}
		return text.trim().isEmpty() ? null : new Suggestion(text.trim(), null);
	}

	synchronized Snapshot snapshot()
	{
		int lists = 0;
		for (Kind k : Kind.values())
		{
			lists += k.template != null ? 1 : 0;
		}
		return new Snapshot(text, suggestions, selected, entries.size() < lists, version, allSelected, top);
	}

	private void refresh()
	{
		final List<Entry> all = new ArrayList<>();
		for (List<Entry> list : entries.values())
		{
			all.addAll(list);
		}
		final List<Suggestion> found = new ArrayList<>(suggest(all, text));
		// Then the wiki's own search results for this text, any page at all
		if (onlineFor.equals(text.trim()))
		{
			for (String t : online)
			{
				boolean have = false;
				for (Suggestion s : found)
				{
					have |= s.title.equalsIgnoreCase(t);
				}
				if (!have && found.size() < MAX_SUGGESTIONS)
				{
					found.add(new Suggestion(t, Kind.PAGE));
				}
			}
		}
		suggestions = found;
		selected = 0;
		top = 0;
		version++;
	}

	/**
	 * The closest monster names to what's typed. Exact names first, then names starting
	 * with it, then a word starting with it, then names containing it, then near spellings
	 * ("nechrayel" finds Nechryael), allowing more slips the longer the text.
	 */
	private static List<Suggestion> suggest(List<Entry> entries, String typed)
	{
		final String q = typed.trim().toLowerCase(Locale.ROOT).replaceAll("\\s+", " ");
		if (q.isEmpty())
		{
			return Collections.emptyList();
		}
		// Close matches by spelling are only worked out if there aren't enough plain ones
		int plain = 0;
		final int slips = q.length() <= 3 ? 0 : q.length() <= 5 ? 1 : q.length() <= 8 ? 2 : 3;
		final List<Object[]> scored = new ArrayList<>();
		for (Entry e : entries)
		{
			int score = -1;
			if (e.base.equals(q) || e.lower.equals(q))
			{
				score = 0;
			}
			else if (e.base.startsWith(q))
			{
				score = 1;
			}
			else if (wordStarts(e.words, q))
			{
				score = 2;
			}
			else if (e.lower.contains(q))
			{
				score = 3;
			}
			else if (slips > 0 && plain < MAX_SUGGESTIONS)
			{
				// Against the whole name and each word in it, and against their starts for
				// a name still being typed ("grador" finds General Graardor)
				int d = near(q, e.base);
				for (String w : e.words)
				{
					d = Math.min(d, near(q, w));
				}
				if (d <= slips)
				{
					score = 4 + d;
				}
			}
			if (score >= 0)
			{
				scored.add(new Object[]{score, e});
				if (score < 4)
				{
					plain++;
				}
			}
		}
		scored.sort(Comparator.<Object[]>comparingInt(o -> (Integer) o[0])
			.thenComparingInt(o -> ((Entry) o[1]).base.length())
			.thenComparing(o -> ((Entry) o[1]).lower));
		final List<Suggestion> out = new ArrayList<>();
		for (Object[] o : scored)
		{
			out.add(new Suggestion(((Entry) o[1]).title, ((Entry) o[1]).kind));
			if (out.size() >= MAX_SUGGESTIONS)
			{
				break;
			}
		}
		return out;
	}

	private static int near(String q, String name)
	{
		int d = distance(q, name);
		for (int extra = -1; extra <= 1; extra++)
		{
			int len = q.length() + extra;
			if (len > 0 && len < name.length())
			{
				d = Math.min(d, distance(q, name.substring(0, len)));
			}
		}
		return d;
	}

	private static boolean wordStarts(String[] words, String q)
	{
		for (String w : words)
		{
			if (w.startsWith(q))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Edits needed to turn one into the other, counting a swapped pair of letters as one.
	 */
	static int distance(String a, String b)
	{
		final int n = a.length();
		final int m = b.length();
		if (Math.abs(n - m) > 3)
		{
			return Math.abs(n - m);
		}
		final int[][] d = new int[n + 1][m + 1];
		for (int i = 0; i <= n; i++)
		{
			d[i][0] = i;
		}
		for (int j = 0; j <= m; j++)
		{
			d[0][j] = j;
		}
		for (int i = 1; i <= n; i++)
		{
			for (int j = 1; j <= m; j++)
			{
				int cost = a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1;
				d[i][j] = Math.min(Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1), d[i - 1][j - 1] + cost);
				if (i > 1 && j > 1 && a.charAt(i - 1) == b.charAt(j - 2) && a.charAt(i - 2) == b.charAt(j - 1))
				{
					d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
				}
			}
		}
		return d[n][m];
	}
}

package com.wikipeek;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseWheelListener;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The item and NPC search box: a stone panel with a chatbox-style line to type in, like the
 * game's own "Enter amount" prompts, and suggestions under it that update as you type.
 * Drawn only when something on it changes, plus the blinking caret.
 */
class SearchOverlay extends Overlay implements MouseListener, MouseWheelListener
{
	private static final int WIDTH = 300;
	private static final int M = 8;
	private static final int GAP = 6;
	private static final int PLATE_H = 20;
	private static final int INPUT_H = 24;
	private static final int ROW_H = 18;
	private static final long CARET_MS = 500;
	private static final int SCROLL_W = 6;

	private static final Color ORANGE = new Color(255, 152, 31);
	private static final Color WHITE = Color.WHITE;
	private static final Color GREY = new Color(200, 190, 170);
	private static final Color CHAT_BLUE = new Color(0, 0, 255);
	private static final Color SELECTED = new Color(80, 70, 54);
	private static final Color YELLOW = new Color(255, 255, 0);
	private static final Color SELECT_FILL = new Color(0, 0, 128);

	private final Client client;
	private final WikiPeekPlugin plugin;
	private final SearchBox box;
	private final SpriteManager spriteManager;
	private final OverlayManager overlayManager;
	private final NameBarDrag nameBarDrag = new NameBarDrag();

	private CardFont bold;
	private CardFont plain;
	private CardFont small;
	private BufferedImage close;
	private BufferedImage closeHovered;
	private BufferedImage parchment;

	private BufferedImage image;
	private int drawnVersion = -1;
	private boolean drawnCaret;
	private int drawnHover = -2;
	private boolean drawnSprites;

	// Clickable areas, relative to the box
	private volatile Rectangle closeBounds = new Rectangle();
	private volatile Rectangle titleBar = new Rectangle();
	private volatile Rectangle[] rows = new Rectangle[0];

	@Inject
	SearchOverlay(Client client, WikiPeekPlugin plugin, SpriteManager spriteManager, OverlayManager overlayManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.box = plugin.getSearchBox();
		this.spriteManager = spriteManager;
		this.overlayManager = overlayManager;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!box.isOpen())
		{
			image = null;
			return null;
		}
		if (bold == null)
		{
			bold = plugin.getBold() != null ? plugin.getBold() : CardFont.of(FontManager.getRunescapeBoldFont());
			plain = plugin.getPlain() != null ? plugin.getPlain() : CardFont.of(FontManager.getRunescapeFont());
			small = plugin.getSmall() != null ? plugin.getSmall() : CardFont.of(FontManager.getRunescapeSmallFont());
		}
		if (close == null)
		{
			close = spriteManager.getSprite(SpriteID.CloseButtonsV2.BUTTON, 0);
		}
		if (closeHovered == null)
		{
			closeHovered = spriteManager.getSprite(SpriteID.CloseButtonsV2.HOVERED, 0);
		}
		if (parchment == null)
		{
			parchment = spriteManager.getSprite(SpriteID.CHAT_BACKGROUND, 0);
		}

		final SearchBox.Snapshot s = box.snapshot();
		final boolean caret = (System.currentTimeMillis() / CARET_MS) % 2 == 0;
		final int hover = hoverAt();
		final boolean sprites = close != null && parchment != null;
		if (image == null || s.version != drawnVersion || caret != drawnCaret || hover != drawnHover || sprites != drawnSprites)
		{
			image = draw(s, caret, hover);
			drawnVersion = s.version;
			drawnCaret = caret;
			drawnHover = hover;
			drawnSprites = sprites;
		}
		g.drawImage(image, 0, 0, null);
		return new Dimension(image.getWidth(), image.getHeight());
	}

	/**
	 * What the mouse is over: a suggestion's index, -1 for the close button, or -2.
	 */
	private int hoverAt()
	{
		final Point mouse = client.getMouseCanvasPosition();
		final Rectangle bounds = getBounds();
		if (mouse == null || bounds == null || !bounds.contains(mouse.getX(), mouse.getY()))
		{
			return -2;
		}
		final int x = mouse.getX() - bounds.x;
		final int y = mouse.getY() - bounds.y;
		if (closeBounds.contains(x, y))
		{
			return -1;
		}
		final Rectangle[] r = rows;
		for (int i = 0; i < r.length; i++)
		{
			if (r[i].contains(x, y))
			{
				return i;
			}
		}
		return -2;
	}

	private BufferedImage draw(SearchBox.Snapshot s, boolean caret, int hover)
	{
		final int shown = Math.min(SearchBox.VISIBLE, s.suggestions.size());
		final boolean scrolls = s.suggestions.size() > SearchBox.VISIBLE;
		final int listRows = Math.max(1, shown);
		final int height = M + PLATE_H + GAP + INPUT_H + GAP + listRows * ROW_H + M;
		final BufferedImage img = new BufferedImage(WIDTH, height, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = img.createGraphics();

		raised(g, 0, 0, WIDTH, height);

		// Name plate with the close button
		int y = M;
		sunken(g, M, y, WIDTH - 2 * M, PLATE_H, Stone.PANEL);
		final String title = "WikiPeek search";
		shadow(g, bold, title, WIDTH / 2 - bold.width(title) / 2, y + 15, ORANGE);
		Rectangle cb;
		if (close != null)
		{
			int h = Math.min(close.getHeight(), PLATE_H - 4);
			int w = close.getWidth() * h / close.getHeight();
			cb = new Rectangle(WIDTH - M - 3 - w, y + (PLATE_H - h) / 2, w, h);
			g.drawImage(hover == -1 && closeHovered != null ? closeHovered : close, cb.x, cb.y, cb.width, cb.height, null);
		}
		else
		{
			cb = new Rectangle(WIDTH - M - 14, y + 2, 12, PLATE_H - 4);
			shadow(g, bold, "x", cb.x + 2, y + 15, hover == -1 ? WHITE : GREY);
		}
		closeBounds = cb;
		titleBar = new Rectangle(M, y, cb.x - M - 2, PLATE_H);
		y += PLATE_H + GAP;

		// The line to type in, on parchment like the chatbox, with the blinking asterisk
		sunken(g, M, y, WIDTH - 2 * M, INPUT_H, new Color(201, 184, 150));
		if (parchment != null)
		{
			int pw = parchment.getWidth();
			int ph = parchment.getHeight();
			g.drawImage(parchment, M, y, M + WIDTH - 2 * M, y + INPUT_H, pw / 20, ph / 3, pw - pw / 20, ph / 3 + INPUT_H, null);
		}
		final String label = "Name: ";
		final int textY = y + (INPUT_H + plain.ascent()) / 2 - 1;
		plain.draw(g, label, M + 6, textY, Color.BLACK);
		final int textX = M + 6 + plain.width(label);
		final int room = WIDTH - 2 * M - 12 - plain.width(label) - plain.width("*");
		// Show the end of a long name, where the typing is
		String typed = s.text;
		while (typed.length() > 1 && plain.width(typed) > room)
		{
			typed = typed.substring(1);
		}
		if (s.allSelected && !typed.isEmpty())
		{
			// Ctrl+A: the text highlighted, as the game does in its own text boxes
			g.setColor(SELECT_FILL);
			g.fillRect(textX - 1, y + 4, plain.width(typed) + 2, INPUT_H - 8);
			plain.draw(g, typed, textX, textY, WHITE);
		}
		else
		{
			plain.draw(g, typed, textX, textY, CHAT_BLUE);
		}
		if (caret)
		{
			plain.draw(g, "*", textX + plain.width(typed), textY, CHAT_BLUE);
		}
		y += INPUT_H + GAP;

		// Suggestions, as rows inside a sunken stone panel like the game's lists
		final int listH = listRows * ROW_H;
		sunken(g, M, y, WIDTH - 2 * M, listH, Stone.PANEL);
		final Rectangle[] r = new Rectangle[shown];
		// Room on the right for a scroll bar when there are more than fit
		final int rowW = WIDTH - 2 * M - (scrolls ? SCROLL_W + 2 : 0);
		if (s.suggestions.isEmpty())
		{
			String note = s.loading && s.text.trim().isEmpty() ? "Fetching names from the wiki..."
				: s.text.trim().isEmpty() ? "Type a name, then press Enter"
				: "No close matches. Press Enter to search the wiki.";
			note = PanelRenderer.fit(note, small, WIDTH - 2 * M - 8);
			shadow(g, small, note, WIDTH / 2 - small.width(note) / 2, y + 13, ORANGE);
		}
		for (int i = 0; i < shown; i++)
		{
			final int at = s.top + i;
			if (at >= s.suggestions.size())
			{
				break;
			}
			final int ry = y + i * ROW_H;
			final boolean picked = at == s.selected;
			final boolean hovered = i == hover;
			if (picked || hovered)
			{
				g.setColor(picked ? SELECTED : Stone.PANEL_ALT);
				g.fillRect(M, ry, rowW, ROW_H);
			}
			final SearchBox.Suggestion sug = s.suggestions.get(at);
			// What it is (an NPC, an item, a page), small on the right
			final String tag = sug.kind.label;
			final int tagW = small.width(tag);
			shadow(g, small, tag, M + rowW - 6 - tagW, ry + 13, GREY);
			final String name = PanelRenderer.fit(sug.title, plain, rowW - 20 - tagW);
			shadow(g, plain, name, M + 6, ry + 13, picked ? WHITE : hovered ? YELLOW : ORANGE);
			r[i] = new Rectangle(M, ry, rowW, ROW_H);
		}
		if (scrolls)
		{
			// A thin bar showing how far down the list is
			final int bx = WIDTH - M - SCROLL_W;
			g.setColor(Stone.DARK);
			g.fillRect(bx, y, SCROLL_W, listH);
			final int total = s.suggestions.size();
			final int thumbH = Math.max(12, listH * SearchBox.VISIBLE / total);
			final int thumbY = y + (listH - thumbH) * s.top / Math.max(1, total - SearchBox.VISIBLE);
			g.setColor(Stone.LIGHT);
			g.fillRect(bx + 1, thumbY, SCROLL_W - 2, thumbH);
		}
		rows = r;

		g.dispose();
		return img;
	}

	private static void raised(Graphics2D g, int x, int y, int w, int h)
	{
		g.setColor(Stone.EDGE);
		g.drawRect(x, y, w - 1, h - 1);
		g.setColor(Stone.FILL);
		g.fillRect(x + 1, y + 1, w - 2, h - 2);
		g.setColor(Stone.LIGHT);
		g.fillRect(x + 1, y + 1, w - 2, 1);
		g.fillRect(x + 1, y + 1, 1, h - 2);
		g.setColor(Stone.DARK);
		g.fillRect(x + 1, y + h - 2, w - 2, 1);
		g.fillRect(x + w - 2, y + 1, 1, h - 2);
	}

	private static void sunken(Graphics2D g, int x, int y, int w, int h, Color fill)
	{
		if (fill != null)
		{
			g.setColor(fill);
			g.fillRect(x, y, w, h);
		}
		g.setColor(Stone.DARK);
		g.fillRect(x - 1, y - 1, w + 2, 1);
		g.fillRect(x - 1, y - 1, 1, h + 2);
		g.setColor(Stone.LIGHT);
		g.fillRect(x - 1, y + h, w + 2, 1);
		g.fillRect(x + w, y - 1, 1, h + 2);
	}

	private static void shadow(Graphics2D g, CardFont f, String s, int x, int y, Color c)
	{
		f.draw(g, s, x + 1, y + 1, Color.BLACK);
		f.draw(g, s, x, y, c);
	}

	// Mouse

	private java.awt.Point local(MouseEvent e)
	{
		final Rectangle bounds = getBounds();
		if (!box.isOpen() || e.isAltDown() || bounds == null || !bounds.contains(e.getPoint()))
		{
			return null;
		}
		return new java.awt.Point(e.getX() - bounds.x, e.getY() - bounds.y);
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		final java.awt.Point p = local(e);
		if (p == null || e.getButton() != MouseEvent.BUTTON1 || client.isMenuOpen())
		{
			return e;
		}
		e.consume();
		if (closeBounds.contains(p))
		{
			box.close();
			return e;
		}
		if (titleBar.contains(p))
		{
			nameBarDrag.start(this, e);
			return e;
		}
		final Rectangle[] r = rows;
		for (int i = 0; i < r.length; i++)
		{
			if (r[i].contains(p))
			{
				box.select(i);
				plugin.chooseSearch();
				return e;
			}
		}
		return e;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent e)
	{
		if (nameBarDrag.isActive())
		{
			nameBarDrag.drag(this, e, client.getCanvasWidth(), client.getCanvasHeight());
			e.consume();
		}
		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		if (nameBarDrag.finish())
		{
			overlayManager.saveOverlay(this);
			e.consume();
		}
		else if (local(e) != null && e.getButton() == MouseEvent.BUTTON1)
		{
			e.consume();
		}
		return e;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent e)
	{
		if (local(e) != null && e.getButton() == MouseEvent.BUTTON1)
		{
			e.consume();
		}
		return e;
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e)
	{
		if (local(e) != null)
		{
			box.scroll(e.getWheelRotation() > 0 ? 1 : -1);
			e.consume();
		}
		return e;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseExited(MouseEvent e)
	{
		return e;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent e)
	{
		return e;
	}
}

