package com.wikipeek;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Fetches an NPC's wiki page (infobox and drops in one go) and pictures. Everything runs on
 * the OkHttp thread pool or the shared executor, never the client thread. Results are kept
 * in memory for the session and saved to disk for about a week.
 */
@Singleton
class WikiClient
{
	private static final Logger log = LoggerFactory.getLogger(WikiClient.class);

	static final HttpUrl WIKI = HttpUrl.get("https://oldschool.runescape.wiki/");
	private static final String USER_AGENT = "WikiPeek for RuneLite - github.com/Martsssssss/wikipeek";
	private static final int PAGE_CACHE_SIZE = 100;
	private static final int IMAGE_CACHE_SIZE = 80;
	private static final int THUMB_SIZE = 400;
	private static final long MAX_IMAGE_BYTES = 2_000_000;
	private static final int MAX_CANDIDATES = 40;
	private static final Pattern DISAMBIGUATION = Pattern.compile("\\{\\{\\s*(disambig|disambiguation|dab)\\s*[|}]", Pattern.CASE_INSENSITIVE);
	private static final Pattern INFOBOX_ID = Pattern.compile("^\\|\\s*id\\d*\\s*=\\s*(.*)$", Pattern.MULTILINE);
	private static final Pattern INFOBOX_COMBAT = Pattern.compile("\\|\\s*combat\\d*\\s*=\\s*(\\d+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern HAS_DROPS = Pattern.compile("\\{\\{\\s*(DropsLine|DropsTableHead|[^{}|]*drop table)", Pattern.CASE_INSENSITIVE);
	private static final Pattern DAB_LINK = Pattern.compile("\\[\\[([^\\]|#]+)");

	/**
	 * A wiki page as saved: its title, full wikitext and lead picture. Found is false when
	 * the wiki has no page for the NPC.
	 */
	static final class Page
	{
		String title;
		String wikitext;
		/**
		 * Every drop table on the page, as the wiki renders it.
		 */
		List<Drops.Table> tables;
		/**
		 * The page's lead picture file, for when the infobox names none.
		 */
		String pageImage;
		/**
		 * The wiki's slayer task guide and strategy guide page titles, or null.
		 */
		String slayerGuide;
		String strategyGuide;
		/**
		 * For an item: where it drops, the shops that sell it and how it's made.
		 */
		WikiHtml.Article article;
		/**
		 * The page links to a "/Drop sources" page with the full list of what drops it.
		 */
		boolean dropSourcesPage;
		boolean found;
	}

	private final OkHttpClient http;
	private final OkHttpClient httpNoRedirects;
	private final Gson gson;
	private final DiskCache disk;
	private final ScheduledExecutorService executor;

	private final Map<String, Page> pages = Collections.synchronizedMap(new LinkedHashMap<String, Page>(32, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, Page> eldest)
		{
			return size() > PAGE_CACHE_SIZE;
		}
	});

	private final Map<String, BufferedImage> images = Collections.synchronizedMap(new LinkedHashMap<String, BufferedImage>(32, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, BufferedImage> eldest)
		{
			return size() > IMAGE_CACHE_SIZE;
		}
	});

	@Inject
	WikiClient(OkHttpClient okHttpClient, Gson gson, DiskCache disk, ScheduledExecutorService executor)
	{
		this.http = okHttpClient;
		this.httpNoRedirects = okHttpClient.newBuilder().followRedirects(false).build();
		this.gson = gson;
		this.disk = disk;
		this.executor = executor;
	}

	void clearMemory()
	{
		pages.clear();
		images.clear();
		titles.clear();
	}

	/**
	 * The wiki page for an NPC, from memory, then disk, then the wiki. The callback gets
	 * null if the wiki couldn't be reached. Runs off the client thread.
	 */
	private final Map<Kind, List<String>> titles = new java.util.concurrent.ConcurrentHashMap<>();

	/**
	 * Every NPC page (each page with a monster infobox) or every item page on the wiki, for
	 * suggestions in the search box. From memory, then disk (kept a week), then a few
	 * requests to the wiki. The callback gets an empty list if the wiki couldn't be reached.
	 */
	void titles(Kind kind, Consumer<List<String>> callback)
	{
		final List<String> known = titles.get(kind);
		if (known != null)
		{
			callback.accept(known);
			return;
		}
		executor.execute(() ->
		{
			final String saved = disk.readText(kind.titlesFile);
			if (saved != null)
			{
				try
				{
					String[] list = gson.fromJson(saved, String[].class);
					if (list != null && list.length > 0)
					{
						List<String> l = Collections.unmodifiableList(java.util.Arrays.asList(list));
						titles.put(kind, l);
						callback.accept(l);
						return;
					}
				}
				catch (RuntimeException e)
				{
					log.debug("Saved {} list is unreadable", kind, e);
				}
			}
			collectTitles(kind.template, new ArrayList<>(), null).handle((list, e) ->
			{
				if (e != null || list == null || list.isEmpty())
				{
					log.debug("Could not fetch the {} list", kind, e);
					callback.accept(Collections.<String>emptyList());
					return null;
				}
				List<String> l = Collections.unmodifiableList(list);
				titles.put(kind, l);
				disk.writeText(kind.titlesFile, gson.toJson(list));
				callback.accept(l);
				return null;
			});
		});
	}

	/**
	 * Pages using an infobox, 500 at a time, following the API's continue token.
	 */
	private CompletableFuture<List<String>> collectTitles(String template, List<String> so, String from)
	{
		final HttpUrl.Builder b = WIKI.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "query")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.addQueryParameter("list", "embeddedin")
			.addQueryParameter("eititle", template)
			.addQueryParameter("einamespace", "0")
			.addQueryParameter("eilimit", "500");
		if (from != null)
		{
			b.addQueryParameter("eicontinue", from);
		}
		return getJson(b.build()).thenCompose(root ->
		{
			JsonObject query = root != null && root.has("query") ? root.getAsJsonObject("query") : null;
			if (query != null && query.has("embeddedin") && query.get("embeddedin").isJsonArray())
			{
				for (JsonElement el : query.getAsJsonArray("embeddedin"))
				{
					String t = string(el.getAsJsonObject(), "title", null);
					if (t != null)
					{
						so.add(t);
					}
				}
			}
			String next = null;
			if (root != null && root.has("continue") && root.get("continue").isJsonObject())
			{
				next = string(root.getAsJsonObject("continue"), "eicontinue", null);
			}
			// A safety stop well above the wiki's count, in case the token never ends
			if (next == null || so.size() > 20000)
			{
				return CompletableFuture.completedFuture(so);
			}
			return collectTitles(template, so, next);
		});
	}

	/**
	 * Wiki pages whose titles start with what's typed, redirects followed to their pages
	 * ("fight caves/strategies" to TzHaar Fight Cave/Strategies), then the best few pages
	 * from the wiki's full search. The callback gets an empty list if the wiki can't be
	 * reached.
	 */
	void searchTitles(String typed, Consumer<List<String>> callback)
	{
		final HttpUrl prefix = WIKI.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "query")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.addQueryParameter("generator", "prefixsearch")
			.addQueryParameter("gpssearch", typed)
			.addQueryParameter("gpsnamespace", "0")
			.addQueryParameter("gpslimit", "20")
			.addQueryParameter("redirects", "1")
			.build();
		final HttpUrl full = WIKI.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "query")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.addQueryParameter("list", "search")
			.addQueryParameter("srsearch", typed)
			.addQueryParameter("srnamespace", "0")
			.addQueryParameter("srlimit", "10")
			.addQueryParameter("srprop", "")
			.build();
		getJson(prefix).thenCombine(getJson(full), (a, b) ->
		{
			final List<String> out = new ArrayList<>();
			final JsonObject qa = a != null && a.has("query") ? a.getAsJsonObject("query") : null;
			if (qa != null && qa.has("pages") && qa.get("pages").isJsonArray())
			{
				// The generator's pages come unordered; each carries its place in the results
				final List<JsonObject> pages = new ArrayList<>();
				for (JsonElement el : qa.getAsJsonArray("pages"))
				{
					pages.add(el.getAsJsonObject());
				}
				pages.sort(java.util.Comparator.comparingInt(p -> p.has("index") ? p.get("index").getAsInt() : 999));
				for (JsonObject p : pages)
				{
					final String t = string(p, "title", null);
					if (t != null && !p.has("missing") && !out.contains(t))
					{
						out.add(t);
					}
				}
			}
			final JsonObject qb = b != null && b.has("query") ? b.getAsJsonObject("query") : null;
			if (qb != null && qb.has("search") && qb.get("search").isJsonArray())
			{
				for (JsonElement el : qb.getAsJsonArray("search"))
				{
					final String t = string(el.getAsJsonObject(), "title", null);
					if (t != null && !out.contains(t))
					{
						out.add(t);
					}
				}
			}
			return out;
		}).handle((list, e) ->
		{
			callback.accept(list == null ? Collections.<String>emptyList() : list);
			return null;
		});
	}

	/**
	 * Runs a task a little later, off the client thread.
	 */
	void later(Runnable task, long millis)
	{
		executor.schedule(task, millis, java.util.concurrent.TimeUnit.MILLISECONDS);
	}

	void page(int id, String name, int combat, Consumer<Page> callback)
	{
		cached("npc7-" + id, () -> fetch(id, name, combat).thenCompose(page -> guides(page, id, combat)), callback);
	}

	/**
	 * The wiki page for a monster typed in by name, such as a slayer task. The callback gets
	 * null if the wiki couldn't be reached.
	 */
	void search(String query, Kind kind, Consumer<Page> callback)
	{
		final String q = query.trim();
		final String key = (kind == Kind.ITEM ? "finditem10-" : "find6-") + DiskCache.hash(q.toLowerCase(Locale.ROOT));
		if (kind == Kind.ITEM)
		{
			cached(key, () -> find(q, kind).thenCompose(this::withClueSources).thenCompose(this::withDropSources), callback);
		}
		else
		{
			cached(key, () -> find(q, kind).thenCompose(page -> guides(page, -1, 0)), callback);
		}
	}

	/**
	 * Any wiki page by its title, for pages that aren't monsters or items (a shop, a place,
	 * an NPC you can't fight). The callback gets null if the wiki couldn't be reached.
	 */
	void anyPage(String title, Consumer<Page> callback)
	{
		// Monsters get their guide links and items their full sources, as when opened in game
		cached("page5-" + DiskCache.hash(title.trim().toLowerCase(Locale.ROOT)),
			() -> parse(title.trim()).thenApply(page -> page != null ? page : notFound(title)).thenCompose(page ->
			{
				if (page.found && Infobox.has(page.wikitext))
				{
					return guides(page, -1, 0);
				}
				if (page.found && Infobox.hasItem(page.wikitext))
				{
					return withClueSources(page).thenCompose(this::withDropSources);
				}
				return CompletableFuture.completedFuture(page);
			}), callback);
	}

	/**
	 * An object's wiki page, from its ID.
	 */
	void object(int id, String name, Consumer<Page> callback)
	{
		cached("object5-" + id, () -> fetch("object", id, name, 0), callback);
	}

	/**
	 * An item's wiki page, from its ID. The callback gets null if the wiki couldn't be
	 * reached.
	 */
	void itemPage(int id, String name, Consumer<Page> callback)
	{
		cached("item11-" + id, () -> resolveTitle("item", id, name)
			.handle((title, e) -> title == null ? name : title)
			.thenCompose(this::parse)
			.thenApply(page -> page != null && Infobox.hasItem(page.wikitext) ? page : notFound(name))
			.thenCompose(this::withClueSources)
			.thenCompose(this::withDropSources), callback);
	}

	/**
	 * Items dropped by too many monsters to list (Coins, Bones...) keep their drop sources
	 * on a "/Drop sources" page of their own. When the page points there, that list is
	 * fetched too and put in place of the note.
	 */
	private CompletableFuture<Page> withDropSources(Page page)
	{
		if (page == null || !page.found || page.article == null)
		{
			return CompletableFuture.completedFuture(page);
		}
		WikiHtml.Section sources = null;
		WikiHtml.Block note = null;
		for (WikiHtml.Section s : page.article.sections)
		{
			if (s.title != null && s.title.equalsIgnoreCase("item sources"))
			{
				sources = s;
				for (WikiHtml.Block b : s.blocks)
				{
					if ("p".equals(b.type) && b.text != null && b.text.toLowerCase(Locale.ROOT).contains("drop sources"))
					{
						note = b;
					}
				}
			}
		}
		if (sources == null || (note == null && !page.dropSourcesPage))
		{
			return CompletableFuture.completedFuture(page);
		}
		final WikiHtml.Section section = sources;
		final WikiHtml.Block replaced = note;
		return parse(page.title + "/Drop sources").handle((sub, e) ->
		{
			if (sub == null || sub.article == null)
			{
				return page;
			}
			// The full list's tables, with any sub-headings that label them
			final List<WikiHtml.Block> full = new ArrayList<>();
			for (WikiHtml.Section s : sub.article.sections)
			{
				for (WikiHtml.Block b : s.blocks)
				{
					if ("h".equals(b.type) || ("table".equals(b.type) && isDrops(b)))
					{
						full.add(b);
					}
				}
			}
			while (!full.isEmpty() && "h".equals(full.get(full.size() - 1).type))
			{
				full.remove(full.size() - 1);
			}
			if (full.stream().noneMatch(b -> "table".equals(b.type)))
			{
				return page;
			}
			// In place of the page's shortened list (or its note pointing to the full one)
			int at = replaced != null ? section.blocks.indexOf(replaced) : -1;
			for (int i = 0; i < section.blocks.size(); i++)
			{
				final WikiHtml.Block b = section.blocks.get(i);
				if ("table".equals(b.type) && isDrops(b))
				{
					if (at < 0 || i < at)
					{
						at = i;
					}
				}
			}
			section.blocks.removeIf(b -> b == replaced || ("table".equals(b.type) && isDrops(b)));
			section.blocks.addAll(Math.max(0, Math.min(at, section.blocks.size())), full);
			return page;
		});
	}

	private static final java.util.regex.Pattern CLUE_STEP = java.util.regex.Pattern.compile("^(Clue scroll \\([a-z]+\\)) - ");

	/**
	 * Each clue scroll step has its own page ("Clue scroll (hard) - A crate in the Lumber
	 * Yard"), which says nothing of where clues come from. That's on the tier's page, so its
	 * Item sources section is added.
	 */
	private CompletableFuture<Page> withClueSources(Page page)
	{
		if (page == null || !page.found || page.article == null || page.title == null)
		{
			return CompletableFuture.completedFuture(page);
		}
		final Matcher m = CLUE_STEP.matcher(page.title);
		if (!m.find())
		{
			return CompletableFuture.completedFuture(page);
		}
		return parse(m.group(1)).handle((tier, e) ->
		{
			if (tier != null && tier.article != null)
			{
				for (WikiHtml.Section s : tier.article.sections)
				{
					if (s.title != null && s.title.equalsIgnoreCase("item sources"))
					{
						page.article.sections.add(s);
					}
				}
			}
			return page;
		});
	}

	private static boolean isDrops(WikiHtml.Block b)
	{
		return b.table != null && b.table.cls != null && b.table.cls.contains("item-drops");
	}

	private static boolean fits(Kind kind, String wikitext)
	{
		return kind == Kind.ITEM ? Infobox.hasItem(wikitext) : Infobox.has(wikitext);
	}

	/**
	 * From memory, then disk, then the wiki. Pages the wiki doesn't have are only kept in
	 * memory, so a page added later is found next session.
	 */
	private void cached(String key, java.util.function.Supplier<CompletableFuture<Page>> fetcher, Consumer<Page> callback)
	{
		final Page inMemory = pages.get(key);
		if (inMemory != null)
		{
			callback.accept(inMemory);
			return;
		}
		executor.execute(() ->
		{
			Page saved = load(key);
			if (saved != null)
			{
				pages.put(key, saved);
				callback.accept(saved);
				return;
			}
			fetcher.get().handle((page, e) ->
			{
				if (e != null || page == null)
				{
					log.debug("Could not fetch the wiki page for {}", key, e);
					callback.accept(null);
					return null;
				}
				pages.put(key, page);
				if (page.found)
				{
					disk.writeText(key + ".json", gson.toJson(page));
				}
				callback.accept(page);
				return null;
			});
		});
	}

	private Page load(String key)
	{
		final String json = disk.readText(key + ".json");
		if (json == null)
		{
			return null;
		}
		try
		{
			Page page = gson.fromJson(json, Page.class);
			if (page != null && page.found && page.wikitext != null && page.tables != null)
			{
				return page;
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Saved page {} is unreadable", key, e);
		}
		return null;
	}

	/**
	 * Finds a monster's page from a typed name: the page of that name, else the wiki's
	 * search results, else the name's disambiguation page, taking the first page that has a
	 * monster infobox.
	 */
	private CompletableFuture<Page> find(String query, Kind kind)
	{
		final HttpUrl searchUrl = WIKI.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "query")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.addQueryParameter("list", "search")
			.addQueryParameter("srsearch", query)
			.addQueryParameter("srnamespace", "0")
			.addQueryParameter("srlimit", "10")
			.build();
		return getJson(searchUrl).thenCompose(root ->
		{
			final List<String> titles = new ArrayList<>();
			titles.add(query);
			JsonObject q = root != null && root.has("query") ? root.getAsJsonObject("query") : null;
			if (q != null && q.has("search") && q.get("search").isJsonArray())
			{
				for (JsonElement el : q.getAsJsonArray("search"))
				{
					String t = string(el.getAsJsonObject(), "title", null);
					if (t != null && !titles.contains(t))
					{
						titles.add(t);
					}
				}
			}
			return pagesOf(titles).thenCompose(found ->
			{
				for (String t : titles)
				{
					Fetched f = found.get(t);
					if (f != null && fits(kind, f.text) && !DISAMBIGUATION.matcher(f.text).find())
					{
						return parse(f.title);
					}
				}
				// A name shared by several monsters: the first one on its disambiguation page
				Fetched exact = found.get(query);
				if (exact != null && DISAMBIGUATION.matcher(exact.text).find())
				{
					final List<String> linked = new ArrayList<>();
					Matcher link = DAB_LINK.matcher(exact.text);
					while (link.find() && linked.size() < MAX_CANDIDATES)
					{
						String l = link.group(1).trim().replace('_', ' ');
						if (!l.isEmpty() && !l.contains(":"))
						{
							linked.add(Character.toUpperCase(l.charAt(0)) + l.substring(1));
						}
					}
					return pagesOf(linked).thenCompose(candidates ->
					{
						for (String t : linked)
						{
							Fetched f = candidates.get(t);
							if (f != null && fits(kind, f.text))
							{
								return parse(f.title);
							}
						}
						return CompletableFuture.completedFuture(notFound(query));
					});
				}
				return CompletableFuture.completedFuture(notFound(query));
			});
		}).thenApply(page -> page == null ? notFound(query) : page);
	}

	private static Page notFound(String name)
	{
		Page none = new Page();
		none.title = name;
		none.found = false;
		return none;
	}

	/**
	 * Adds the wiki's slayer task guide ("Slayer task/Abyssal demons") and strategy guide
	 * ("General Graardor/Strategies") to a page, where the wiki has them. A failure here
	 * never stops the page showing.
	 */
	private CompletableFuture<Page> guides(Page page, int id, int combat)
	{
		if (page == null || !page.found)
		{
			return CompletableFuture.completedFuture(page);
		}
		final List<String> titles = new ArrayList<>();
		final Infobox box = Infobox.read(page.wikitext, id, combat);
		final String cat = box == null ? "" : box.get("cat").split(",")[0].trim();
		if (!cat.isEmpty() && !cat.equalsIgnoreCase("no") && !cat.equalsIgnoreCase("none"))
		{
			titles.add("Slayer task/" + cat);
			titles.add("Slayer task/" + Character.toUpperCase(cat.charAt(0)) + cat.substring(1).toLowerCase(Locale.ROOT));
		}
		final String strategies = page.title + "/Strategies";
		titles.add(strategies);
		return existing(titles).handle((found, e) ->
		{
			if (found != null)
			{
				for (String t : titles)
				{
					if (t.startsWith("Slayer task/") && found.containsKey(t) && page.slayerGuide == null)
					{
						page.slayerGuide = found.get(t);
					}
				}
				page.strategyGuide = found.get(strategies);
			}
			return page;
		});
	}

	/**
	 * Which of these pages exist, as asked-for title to the real title after redirects.
	 */
	private CompletableFuture<Map<String, String>> existing(List<String> titles)
	{
		final HttpUrl url = WIKI.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "query")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("titles", String.join("|", titles))
			.build();
		return getJson(url).thenApply(root ->
		{
			final Map<String, String> out = new LinkedHashMap<>();
			JsonObject query = root != null && root.has("query") ? root.getAsJsonObject("query") : null;
			if (query == null || !query.has("pages"))
			{
				return out;
			}
			final Map<String, String> back = new LinkedHashMap<>();
			for (String t : titles)
			{
				back.put(t, t);
			}
			for (String key : new String[]{"normalized", "redirects"})
			{
				if (query.has(key) && query.get(key).isJsonArray())
				{
					for (JsonElement el : query.getAsJsonArray(key))
					{
						JsonObject o = el.getAsJsonObject();
						String from = string(o, "from", null);
						String to = string(o, "to", null);
						if (from != null && to != null)
						{
							back.put(to, back.getOrDefault(from, from));
						}
					}
				}
			}
			for (JsonElement el : query.getAsJsonArray("pages"))
			{
				JsonObject p = el.getAsJsonObject();
				String title = string(p, "title", null);
				if (title != null && !p.has("missing") && !p.has("invalid"))
				{
					out.put(back.getOrDefault(title, title), title);
				}
			}
			return out;
		});
	}

	/**
	 * Finds the page about this exact NPC. Many NPCs share a name (several Foresters, dozens
	 * of Guards), so the page is chosen in this order: the page the wiki gives for the NPC's
	 * ID if it lists that ID; any page linked from the name's disambiguation page that lists
	 * the ID; a page for the same name with the same combat level. If none fits, the page
	 * comes back as not found rather than another NPC's.
	 */
	private CompletableFuture<Page> fetch(int id, String name, int combat)
	{
		return fetch("npc", id, name, combat);
	}

	/**
	 * The page for an NPC or object by its ID: the page the wiki's lookup gives if it lists
	 * the ID, else the one its disambiguation page leads to that does.
	 */
	private CompletableFuture<Page> fetch(String type, int id, String name, int combat)
	{
		return resolveTitle(type, id, name)
			.handle((title, e) -> title == null ? name : title)
			.thenCompose(first -> parse(first).thenCompose(firstPage ->
			{
				if (firstPage != null && infoboxIds(firstPage.wikitext).contains(id))
				{
					return CompletableFuture.completedFuture(firstPage);
				}
				final List<String> disambiguations = new ArrayList<>();
				if (firstPage != null && DISAMBIGUATION.matcher(firstPage.wikitext).find())
				{
					disambiguations.add(first);
				}
				disambiguations.add(name + " (disambiguation)");
				return pagesOf(disambiguations).thenCompose(dabPages ->
				{
					Set<String> candidates = new LinkedHashSet<>();
					for (Fetched dab : dabPages.values())
					{
						Matcher link = DAB_LINK.matcher(dab.text);
						while (link.find() && candidates.size() < MAX_CANDIDATES)
						{
							String linked = link.group(1).trim().replace('_', ' ');
							if (!linked.isEmpty() && !linked.toLowerCase(Locale.ROOT).endsWith("(disambiguation)") && !linked.contains(":"))
							{
								candidates.add(Character.toUpperCase(linked.charAt(0)) + linked.substring(1));
							}
						}
					}
					candidates.remove(first);
					return pagesOf(new ArrayList<>(candidates)).thenCompose(more ->
					{
						Map<String, Fetched> all = new LinkedHashMap<>();
						if (firstPage != null)
						{
							all.put(first, new Fetched(firstPage.title, firstPage.wikitext));
						}
						all.putAll(more);
						Fetched picked = pick(all, id, name, combat);
						if (picked == null && firstPage != null && !DISAMBIGUATION.matcher(firstPage.wikitext).find())
						{
							// The page the wiki's lookup gave, for an NPC whose page doesn't
							// list its ID (often ones you can't fight)
							return CompletableFuture.completedFuture(firstPage);
						}
						if (picked == null)
						{
							Page none = new Page();
							none.title = name;
							none.found = false;
							return CompletableFuture.completedFuture(none);
						}
						if (firstPage != null && picked.title.equals(firstPage.title))
						{
							return CompletableFuture.completedFuture(firstPage);
						}
						return parse(picked.title).thenApply(page ->
						{
							if (page == null)
							{
								throw new IllegalStateException("The wiki page " + picked.title + " went missing");
							}
							return page;
						});
					});
				});
			}));
	}

	/**
	 * A page's wikitext (for the infobox), its rendered drop tables and its lead picture,
	 * in one request. Null if the page doesn't exist.
	 */
	private CompletableFuture<Page> parse(String title)
	{
		final HttpUrl apiUrl = WIKI.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "parse")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("page", title)
			.addQueryParameter("prop", "text|wikitext|properties")
			.addQueryParameter("disablelimitreport", "1")
			.addQueryParameter("disableeditsection", "1")
			.addQueryParameter("disabletoc", "1")
			.build();
		return getJson(apiUrl).thenApply(root ->
		{
			if (root == null || !root.has("parse") || !root.get("parse").isJsonObject())
			{
				// A page that doesn't exist comes back as an error instead
				return null;
			}
			JsonObject parse = root.getAsJsonObject("parse");
			Page page = new Page();
			page.title = string(parse, "title", title);
			page.wikitext = string(parse, "wikitext", "");
			final String html = string(parse, "text", "");
			page.tables = Drops.fromHtml(html);
			// Every page's write-up and tables, for the About text and full page sections
			{
				page.article = WikiHtml.read(html);
				final String own = "/w/" + page.title.replace(' ', '_') + "/Drop_sources\"";
				page.dropSourcesPage = html.contains(own) || html.contains(own.replace("'", "%27"));
			}
			if (parse.has("properties") && parse.get("properties").isJsonObject())
			{
				JsonObject props = parse.getAsJsonObject("properties");
				page.pageImage = string(props, "page_image_free", string(props, "page_image", null));
			}
			page.found = true;
			return page;
		});
	}

	/**
	 * Of the pages that could be this NPC, the one that lists its ID, or else one with the
	 * same name and combat level (preferring one with drops). Null if neither.
	 */
	static Fetched pick(Map<String, Fetched> pages, int id, String name, int combat)
	{
		for (Fetched page : pages.values())
		{
			if (!DISAMBIGUATION.matcher(page.text).find() && infoboxIds(page.text).contains(id))
			{
				return page;
			}
		}
		if (combat <= 0 || name == null)
		{
			return null;
		}
		final String lower = name.toLowerCase(Locale.ROOT);
		Fetched withoutDrops = null;
		for (Map.Entry<String, Fetched> entry : pages.entrySet())
		{
			Fetched page = entry.getValue();
			if (DISAMBIGUATION.matcher(page.text).find()
				|| !(entry.getKey().toLowerCase(Locale.ROOT).startsWith(lower) || page.title.toLowerCase(Locale.ROOT).startsWith(lower)))
			{
				continue;
			}
			Matcher m = INFOBOX_COMBAT.matcher(page.text);
			while (m.find())
			{
				if (Integer.parseInt(m.group(1)) == combat)
				{
					if (HAS_DROPS.matcher(page.text).find())
					{
						return page;
					}
					if (withoutDrops == null)
					{
						withoutDrops = page;
					}
					break;
				}
			}
		}
		return withoutDrops;
	}

	/**
	 * Every ID listed in the page's infobox (id, id1, id2... for pages with versions).
	 */
	static Set<Integer> infoboxIds(String wikitext)
	{
		final Set<Integer> ids = new HashSet<>();
		if (wikitext == null)
		{
			return ids;
		}
		Matcher m = INFOBOX_ID.matcher(wikitext);
		while (m.find())
		{
			ids.addAll(Infobox.ids(m.group(1)));
		}
		return ids;
	}

	/**
	 * Finds the page for an NPC's ID with Special:Lookup.
	 */
	private CompletableFuture<String> resolveTitle(String type, int id, String name)
	{
		final HttpUrl lookupUrl = WIKI.newBuilder()
			.addPathSegment("w")
			.addPathSegment("Special:Lookup")
			.addQueryParameter("type", type)
			.addQueryParameter("id", Integer.toString(id))
			.addQueryParameter("name", name)
			.build();

		final CompletableFuture<String> future = new CompletableFuture<>();
		httpNoRedirects.newCall(request(lookupUrl)).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				future.completeExceptionally(e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					String location = r.header("Location");
					HttpUrl target = location == null ? null : r.request().url().resolve(location);
					String title = target == null ? null : titleFromUrl(target);
					// No ID match sends us to a search page, so fall back to the name
					future.complete(title == null || title.startsWith("Special:") ? name : title);
				}
			}
		});
		return future;
	}

	/**
	 * A page's title and wikitext.
	 */
	static final class Fetched
	{
		final String title;
		final String text;

		Fetched(String title, String text)
		{
			this.title = title;
			this.text = text;
		}
	}

	/**
	 * The full wikitext of up to 50 pages in one request, keyed by the title
	 * as asked for (following redirects). Pages that don't exist are left out.
	 */
	private CompletableFuture<Map<String, Fetched>> pagesOf(List<String> titles)
	{
		if (titles.isEmpty())
		{
			return CompletableFuture.completedFuture(Collections.<String, Fetched>emptyMap());
		}
		final List<String> asked = titles.size() > 50 ? titles.subList(0, 50) : titles;
		final HttpUrl apiUrl = WIKI.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "query")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("prop", "revisions")
			.addQueryParameter("rvprop", "content")
			.addQueryParameter("rvslots", "main")
			.addQueryParameter("titles", String.join("|", asked))
			.build();
		return getJson(apiUrl).thenApply(root ->
		{
			Map<String, Fetched> out = new LinkedHashMap<>();
			JsonObject query = root != null && root.has("query") ? root.getAsJsonObject("query") : null;
			if (query == null || !query.has("pages"))
			{
				return out;
			}
			// Map the wiki's titles back to the ones asked for, through normalising and redirects
			Map<String, String> back = new LinkedHashMap<>();
			for (String t : asked)
			{
				back.put(t, t);
			}
			for (String key : new String[]{"normalized", "redirects"})
			{
				if (query.has(key) && query.get(key).isJsonArray())
				{
					for (JsonElement el : query.getAsJsonArray(key))
					{
						JsonObject o = el.getAsJsonObject();
						String from = string(o, "from", null);
						String to = string(o, "to", null);
						if (from != null && to != null)
						{
							back.put(to, back.getOrDefault(from, from));
						}
					}
				}
			}
			for (JsonElement el : query.getAsJsonArray("pages"))
			{
				JsonObject page = el.getAsJsonObject();
				String content = revisionContent(page);
				String title = string(page, "title", null);
				if (title != null && content != null)
				{
					out.put(back.getOrDefault(title, title), new Fetched(title, content));
				}
			}
			return out;
		});
	}

	/**
	 * Full-size URLs of wiki files, by file name as asked for (so "White dagger.png"), or
	 * scaled to a width if width is above 0. Files the wiki doesn't have are left out.
	 */
	void fileUrls(List<String> files, int width, Consumer<Map<String, String>> callback)
	{
		if (files.isEmpty())
		{
			callback.accept(Collections.<String, String>emptyMap());
			return;
		}
		final List<String> titles = new ArrayList<>();
		for (String f : files)
		{
			titles.add("File:" + f);
		}
		final HttpUrl.Builder b = WIKI.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "query")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("prop", "imageinfo")
			.addQueryParameter("iiprop", "url")
			.addQueryParameter("titles", String.join("|", titles.size() > 50 ? titles.subList(0, 50) : titles));
		if (width > 0)
		{
			b.addQueryParameter("iiurlwidth", Integer.toString(width));
		}
		getJson(b.build()).handle((root, e) ->
		{
			final Map<String, String> out = new LinkedHashMap<>();
			JsonObject query = root != null && root.has("query") ? root.getAsJsonObject("query") : null;
			if (query != null && query.has("pages"))
			{
				for (JsonElement el : query.getAsJsonArray("pages"))
				{
					JsonObject file = el.getAsJsonObject();
					String title = string(file, "title", "");
					if (file.has("missing") || !file.has("imageinfo") || !title.startsWith("File:"))
					{
						continue;
					}
					JsonArray info = file.getAsJsonArray("imageinfo");
					if (info.size() == 0)
					{
						continue;
					}
					JsonObject i = info.get(0).getAsJsonObject();
					String url = width > 0 ? string(i, "thumburl", null) : null;
					if (url == null)
					{
						url = string(i, "url", null);
					}
					url = absolute(url);
					if (url != null)
					{
						out.put(sameFile(title.substring(5)), url);
					}
				}
			}
			// Hand back under the names asked for
			final Map<String, String> asked = new LinkedHashMap<>();
			for (String f : files)
			{
				String url = out.get(sameFile(f));
				if (url != null)
				{
					asked.put(f, url);
				}
			}
			callback.accept(asked);
			return null;
		});
	}

	/**
	 * A file name as the wiki compares them: spaces for underscores, first letter capital.
	 */
	private static String sameFile(String name)
	{
		String s = name.replace('_', ' ').trim();
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}

	/**
	 * A picture from the wiki, from memory, then disk, then the wiki. The callback runs off
	 * the client thread and gets null on failure.
	 */
	void loadImage(String url, Consumer<BufferedImage> callback)
	{
		final BufferedImage cached = images.get(url);
		if (cached != null)
		{
			callback.accept(cached);
			return;
		}
		final HttpUrl httpUrl = HttpUrl.parse(url);
		if (httpUrl == null || !WIKI.host().equals(httpUrl.host()))
		{
			callback.accept(null);
			return;
		}
		final String file = "img-" + DiskCache.hash(url);
		executor.execute(() ->
		{
			BufferedImage saved = decode(disk.read(file));
			if (saved != null)
			{
				images.put(url, saved);
				callback.accept(saved);
				return;
			}
			http.newCall(request(httpUrl)).enqueue(new Callback()
			{
				@Override
				public void onFailure(Call call, IOException e)
				{
					callback.accept(null);
				}

				@Override
				public void onResponse(Call call, Response response)
				{
					BufferedImage image = null;
					try (Response r = response)
					{
						ResponseBody body = r.body();
						if (r.isSuccessful() && body != null && body.contentLength() <= MAX_IMAGE_BYTES)
						{
							byte[] bytes = body.bytes();
							image = decode(bytes);
							if (image != null)
							{
								disk.write(file, bytes);
							}
						}
					}
					catch (IOException | RuntimeException e)
					{
						log.debug("Could not load picture {}", url, e);
					}
					if (image != null)
					{
						images.put(url, image);
					}
					callback.accept(image);
				}
			});
		});
	}

	private static BufferedImage decode(byte[] bytes)
	{
		if (bytes == null || bytes.length == 0 || bytes.length > MAX_IMAGE_BYTES)
		{
			return null;
		}
		try
		{
			synchronized (ImageIO.class)
			{
				return ImageIO.read(new ByteArrayInputStream(bytes));
			}
		}
		catch (IOException | RuntimeException e)
		{
			return null;
		}
	}

	private CompletableFuture<JsonObject> getJson(HttpUrl url)
	{
		final CompletableFuture<JsonObject> future = new CompletableFuture<>();
		http.newCall(request(url)).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				future.completeExceptionally(e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					ResponseBody body = r.body();
					if (!r.isSuccessful() || body == null)
					{
						future.completeExceptionally(new IOException("HTTP " + r.code() + " for " + url));
						return;
					}
					future.complete(gson.fromJson(body.charStream(), JsonObject.class));
				}
				catch (RuntimeException e)
				{
					future.completeExceptionally(e);
				}
			}
		});
		return future;
	}

	private static String revisionContent(JsonObject page)
	{
		if (!page.has("revisions") || !page.get("revisions").isJsonArray())
		{
			return null;
		}
		JsonArray revisions = page.getAsJsonArray("revisions");
		if (revisions.size() == 0 || !revisions.get(0).isJsonObject())
		{
			return null;
		}
		JsonObject revision = revisions.get(0).getAsJsonObject();
		if (revision.has("slots") && revision.get("slots").isJsonObject())
		{
			JsonObject slots = revision.getAsJsonObject("slots");
			if (slots.has("main") && slots.get("main").isJsonObject())
			{
				return string(slots.getAsJsonObject("main"), "content", null);
			}
		}
		return string(revision, "content", null);
	}

	private static String absolute(String src)
	{
		if (src == null || src.isEmpty() || src.startsWith("data:"))
		{
			return null;
		}
		HttpUrl resolved = WIKI.resolve(src);
		return resolved == null ? null : resolved.toString();
	}

	private static String string(JsonObject obj, String key, String fallback)
	{
		JsonElement el = obj.get(key);
		return el == null || el.isJsonNull() || !el.isJsonPrimitive() ? fallback : el.getAsString();
	}

	/**
	 * Turns a wiki article URL like /w/Key_(Olaf%27s_Quest) into a page title.
	 */
	static String titleFromUrl(HttpUrl url)
	{
		List<String> segments = url.pathSegments();
		if (segments.size() < 2 || !"w".equals(segments.get(0)))
		{
			return null;
		}
		String title = String.join("/", segments.subList(1, segments.size())).replace('_', ' ').trim();
		return title.isEmpty() ? null : title;
	}

	static String pageUrl(String title)
	{
		return WIKI.newBuilder().addPathSegment("w").addPathSegments(title.replace(' ', '_')).build().toString();
	}

	/**
	 * A wiki file at about the panel's size. Special:FilePath follows file redirects and
	 * hands back a thumbnail when the file is bigger.
	 */
	static String fileUrl(String file)
	{
		return WIKI.newBuilder()
			.addPathSegment("w")
			.addPathSegment("Special:FilePath")
			.addPathSegment(file.trim().replace(' ', '_'))
			.addQueryParameter("width", Integer.toString(THUMB_SIZE))
			.build()
			.toString();
	}

	/**
	 * A picture file for something with no picture on its page (a table, a crate), found by
	 * searching the wiki's files for its name. The callback gets the file name, or null.
	 */
	void fileFor(String name, Consumer<String> callback)
	{
		final HttpUrl url = WIKI.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "query")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.addQueryParameter("list", "search")
			.addQueryParameter("srnamespace", "6")
			.addQueryParameter("srlimit", "20")
			.addQueryParameter("srsearch", "intitle:\"" + name.replace("\"", "") + "\"")
			.build();
		getJson(url).handle((root, e) ->
		{
			final JsonObject q = root != null && root.has("query") ? root.getAsJsonObject("query") : null;
			String best = null;
			int bestScore = Integer.MAX_VALUE;
			if (q != null && q.has("search") && q.get("search").isJsonArray())
			{
				final String lower = name.toLowerCase(Locale.ROOT);
				for (JsonElement el : q.getAsJsonArray("search"))
				{
					final String title = string(el.getAsJsonObject(), "title", "");
					final String file = title.startsWith("File:") ? title.substring(5) : title;
					final String f = file.toLowerCase(Locale.ROOT);
					if (!f.endsWith(".png") || f.contains("icon") || f.contains("chathead") || f.contains("map"))
					{
						continue;
					}
					// The plain picture first ("Table.png"), then a version of it ("Table
					// (Seers' Village).png"), then anything else with its name
					final String bare = f.substring(0, f.length() - 4);
					final int score = bare.equals(lower) ? 0 : bare.startsWith(lower + " (") ? 1 : bare.startsWith(lower) ? 2 : 3;
					if (score < bestScore)
					{
						best = file;
						bestScore = score;
					}
				}
			}
			callback.accept(best);
			return null;
		});
	}

	/**
	 * The full-size lead picture of one page, following redirects ("Zombies" to Zombie), as
	 * an address, or null when it has none.
	 */
	void leadPicture(String title, Consumer<String> callback)
	{
		final HttpUrl url = WIKI.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "query")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("prop", "pageimages")
			.addQueryParameter("piprop", "original")
			.addQueryParameter("titles", title)
			.build();
		getJson(url).handle((root, e) ->
		{
			String src = null;
			final JsonObject query = root != null && root.has("query") ? root.getAsJsonObject("query") : null;
			if (query != null && query.has("pages") && query.get("pages").isJsonArray())
			{
				for (JsonElement el : query.getAsJsonArray("pages"))
				{
					final JsonObject page = el.getAsJsonObject();
					if (src == null && page.has("original") && page.get("original").isJsonObject())
					{
						src = string(page.getAsJsonObject("original"), "source", null);
					}
				}
			}
			callback.accept(src);
			return null;
		});
	}

	/**
	 * Each page's small lead picture (a monster's, a chest's), up to 50 pages at a time.
	 * The callback gets a map of title to picture address, missing pages left out.
	 */
	void pageImages(List<String> titles, Consumer<Map<String, String>> callback)
	{
		final HttpUrl url = WIKI.newBuilder()
			.addPathSegment("api.php")
			.addQueryParameter("action", "query")
			.addQueryParameter("format", "json")
			.addQueryParameter("formatversion", "2")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("prop", "pageimages")
			.addQueryParameter("piprop", "thumbnail")
			.addQueryParameter("pithumbsize", "64")
			.addQueryParameter("pilimit", "50")
			.addQueryParameter("titles", String.join("|", titles))
			.build();
		getJson(url).handle((root, e) ->
		{
			final Map<String, String> out = new java.util.HashMap<>();
			final JsonObject query = root != null && root.has("query") ? root.getAsJsonObject("query") : null;
			if (query != null)
			{
				// Titles the wiki changed (redirects, first letters) map back to what was asked
				final Map<String, String> asked = new java.util.HashMap<>();
				for (String key : new String[]{"normalized", "redirects"})
				{
					if (query.has(key) && query.get(key).isJsonArray())
					{
						for (JsonElement el : query.getAsJsonArray(key))
						{
							final JsonObject o = el.getAsJsonObject();
							final String from = string(o, "from", null);
							final String to = string(o, "to", null);
							if (from != null && to != null)
							{
								asked.put(to, asked.getOrDefault(from, from));
							}
						}
					}
				}
				if (query.has("pages") && query.get("pages").isJsonArray())
				{
					for (JsonElement el : query.getAsJsonArray("pages"))
					{
						final JsonObject page = el.getAsJsonObject();
						final String title = string(page, "title", null);
						if (title == null || !page.has("thumbnail"))
						{
							continue;
						}
						final String src = string(page.getAsJsonObject("thumbnail"), "source", null);
						if (src != null)
						{
							out.put(asked.getOrDefault(title, title), src);
						}
					}
				}
			}
			callback.accept(out);
			return null;
		});
	}

	/**
	 * A picture the wiki's page links to directly ("/images/Air_rune.png").
	 */
	static String imageUrl(String src)
	{
		final HttpUrl url = WIKI.resolve(src);
		return url == null ? null : url.toString();
	}

	static String searchUrl(String name)
	{
		return WIKI.newBuilder()
			.addPathSegment("w")
			.addPathSegment("Special:Search")
			.addQueryParameter("search", name)
			.build()
			.toString();
	}

	private static Request request(HttpUrl url)
	{
		return new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.build();
	}
}

package com.wikipeek;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * A wiki page's rendered HTML read into plain parts: the opening paragraphs, then each
 * section with its paragraphs, list items, sub-headings and tables. Links are kept as page
 * titles so rows can open the wiki or a card. Saved to disk with the page, so it's all plain
 * fields.
 */
final class WikiHtml
{
	static final class Cell
	{
		String text;
		/**
		 * The wiki page the cell links to, or null.
		 */
		String link;
		/**
		 * The text of that first link, so the rest of the cell can be told apart from it
		 * ("Cave bug" and "Level 96").
		 */
		String linkText;
		/**
		 * Pictures in the cell that link to a page, as "Title|count" (a spell's runes: "Air
		 * rune|2"). Count is 0 when none is shown.
		 */
		List<String> icons;
		/**
		 * The text with a mark where each of {@link #icons} sits, for text with pictures
		 * in it; null otherwise.
		 */
		String rich;
		/**
		 * The wiki's own sort value (data-sort-value), or null.
		 */
		String sort;
		boolean th;
	}

	static final class Table
	{
		String cls;
		List<String> headers = new ArrayList<>();
		List<List<Cell>> rows = new ArrayList<>();
	}

	static final class Block
	{
		/**
		 * "p" paragraph, "li" list item, "h" sub-heading or "table".
		 */
		String type;
		String text;
		String link;
		Table table;
		/**
		 * For a sub-heading under another (a setup's "Inventory"), the one above it.
		 */
		String parent;
	}

	static final class Section
	{
		String title;
		List<Block> blocks = new ArrayList<>();
	}

	static final class Article
	{
		List<String> lead = new ArrayList<>();
		/**
		 * Data tables before the first heading (a shop's stock).
		 */
		List<Table> leadTables = new ArrayList<>();
		/**
		 * The first good-sized picture in the page's text, for pages with no infobox picture
		 * (Table, Door).
		 */
		String image;
		List<Section> sections = new ArrayList<>();
	}

	private static final Pattern TAB = Pattern.compile("<div class=\"tabbertab\"[^>]*?data-title=\"([^\"]*)\"[^>]*>");
	private static final int MAX_ROWS = 2500;
	private static final Pattern TAB_HEADING = Pattern.compile("<h([2-4])(\\s[^>]*)?>(.*?)</h\\1>", Pattern.DOTALL | Pattern.CASE_INSENSITIVE);
	private static final Pattern DL_ITEM = Pattern.compile("<(dt|dd)[^>]*>(.*?)(?=<dt[\\s>]|<dd[\\s>]|</dl>|$)", Pattern.DOTALL | Pattern.CASE_INSENSITIVE);
	private static final Pattern STORAGE_INSIDE = Pattern.compile("class=\"[^\"]*\\b(inventorytable|runepouchtable|equipment)\\b");
	private static final Pattern STORED = Pattern.compile("<a\\s[^>]*?href=\"/w/([^\"#?]+)[^\"]*\"[^>]*>\\s*<img[^>]*?src=\"([^\"]+)\"", Pattern.CASE_INSENSITIVE);
	private static final Pattern TITLE_ATTR = Pattern.compile("title=\"([^\"]*)\"");
	private static final Pattern SLOT = Pattern.compile("equipment-([a-z0-9]+)");
	private static final Pattern AMOUNT = Pattern.compile("inv-quantity-text[^>]*>\\s*([0-9,]+)");
	private static final Pattern OPEN = Pattern.compile("<(h[2-4]|p|ul|ol|dl|table)(\\s[^>]*)?>", Pattern.CASE_INSENSITIVE);
	private static final Pattern ROW = Pattern.compile("<tr[\\s>]", Pattern.CASE_INSENSITIVE);
	private static final Pattern CELL = Pattern.compile("<t([dh])(\\s[^>]*)?>(.*?)(?=<t[dh][\\s>]|</tr>|$)", Pattern.DOTALL | Pattern.CASE_INSENSITIVE);
	private static final Pattern LINK = Pattern.compile("<a\\s[^>]*href=\"/w/([^\"#?]+)[^\"]*\"[^>]*>(.*?)</a>", Pattern.DOTALL);
	private static final Pattern CLASS = Pattern.compile("class=\"([^\"]*)\"");
	private static final Pattern SPAN = Pattern.compile("colspan=\"?(\\d+)");
	private static final Pattern ROWSPAN = Pattern.compile("rowspan=\"?(\\d+)");
	private static final Pattern BREAK = Pattern.compile("<br\\s*/?>", Pattern.CASE_INSENSITIVE);
	private static final Pattern NEXT_ITEM = Pattern.compile("</li>\\s*<li[^>]*>", Pattern.CASE_INSENSITIVE);
	private static final Pattern SORT = Pattern.compile("data-sort-value=\"([^\"]*)\"");
	private static final Pattern NESTED_TABLE = Pattern.compile("<table.*?</table>", Pattern.DOTALL);
	private static final Pattern PICTURE = Pattern.compile("<img[^>]*?src=\"(/images/[^\"?]+)[^\"]*\"[^>]*?width=\"(\\d+)\"");
	private static final Pattern LI = Pattern.compile("<li[\\s>]", Pattern.CASE_INSENSITIVE);

	private WikiHtml()
	{
	}

	static Article read(String html)
	{
		final Article out = new Article();
		if (html == null)
		{
			return out;
		}
		// Formulas come as MathML; they read better as plain text
		html = MathText.formulas(html);
		// The wiki's tabs (a shop's stock with and without Karamja gloves, a boss's gear
		// setups) are shown one after another, each under its tab's name
		html = tabs(html);
		final Matcher picture = PICTURE.matcher(html);
		while (picture.find())
		{
			if (Integer.parseInt(picture.group(2)) >= 50)
			{
				out.image = picture.group(1);
				break;
			}
		}
		Section section = null;
		String parent = null;
		final Matcher m = OPEN.matcher(html);
		int from = 0;
		while (from < html.length() && m.find(from))
		{
			final String tag = m.group(1).toLowerCase(Locale.ROOT);
			final String attrs = m.group(2) == null ? "" : m.group(2);
			final int end = close(html, tag, m.end());
			final String inner = html.substring(m.end(), Math.max(m.end(), end - tag.length() - 3));
			from = Math.max(end, m.end());
			final String cls = cls(attrs);
			if (tag.equals("h2"))
			{
				parent = null;
				section = new Section();
				section.title = Drops.text(inner);
				out.sections.add(section);
				continue;
			}
			if (tag.equals("h3") || tag.equals("h4"))
			{
				if (section != null)
				{
					final String title = Drops.text(inner);
					add(section, "h", title, null);
					if (tag.equals("h3"))
					{
						parent = title;
					}
					else
					{
						section.blocks.get(section.blocks.size() - 1).parent = parent;
					}
				}
				continue;
			}
			if (tag.equals("p"))
			{
				final String text = Drops.text(inner);
				if (text.isEmpty())
				{
					continue;
				}
				if (section == null)
				{
					out.lead.add(text);
				}
				else
				{
					add(section, "p", text, null);
				}
				continue;
			}
			if (tag.equals("dl"))
			{
				// ";Term" and ":indented" lines: each term as a sub-heading, the rest as text
				final Matcher d = DL_ITEM.matcher(inner);
				while (d.find())
				{
					final String text = Drops.text(BREAK.matcher(d.group(2)).replaceAll(" "));
					if (text.isEmpty())
					{
						continue;
					}
					if (section == null)
					{
						out.lead.add(text);
					}
					else
					{
						add(section, d.group(1).equalsIgnoreCase("dt") ? "h" : "p", text, null);
					}
				}
				continue;
			}
			if (tag.equals("table") && !cls.contains("wikitable") && !isStorage(cls) && !cls.contains("questdetails")
				&& STORAGE_INSIDE.matcher(inner).find())
			{
				// A plain table holding an inventory or a worn-equipment picture: look inside
				from = m.end();
				continue;
			}
			if (tag.equals("table") && cls.contains("questdetails"))
			{
				if (section == null)
				{
					section = new Section();
					section.title = "Details";
					out.sections.add(section);
				}
				questDetails(inner, section);
				continue;
			}
			if (tag.equals("table") && isStorage(cls))
			{
				final Table t = storage(inner, cls);
				if (section != null && !t.rows.isEmpty())
				{
					Block b = new Block();
					b.type = "table";
					b.table = t;
					section.blocks.add(b);
				}
				continue;
			}
			if (section == null)
			{
				if (tag.equals("table") && cls.contains("wikitable"))
				{
					final Table t = table(inner, cls);
					if (!t.rows.isEmpty())
					{
						out.leadTables.add(t);
					}
				}
				continue;
			}
			if (tag.equals("table"))
			{
				// Only the wiki's data tables; infoboxes, navboxes and message boxes are left out
				if (cls.contains("wikitable"))
				{
					final Table t = table(inner, cls);
					if (!t.rows.isEmpty())
					{
						Block b = new Block();
						b.type = "table";
						b.table = t;
						section.blocks.add(b);
					}
				}
				continue;
			}
			if (tag.equals("ul") || tag.equals("ol"))
			{
				if (cls.contains("gallery") || cls.contains("references") || cls.contains("toc"))
				{
					continue;
				}
				for (String li : LI.split(NESTED_TABLE.matcher(inner).replaceAll("")))
				{
					if (li.contains("id=\"cite_note") || li.contains("mw-cite-backlink"))
					{
						// A footnote ("^ The player must..."), not part of the text
						continue;
					}
					final String text = Drops.text(BREAK.matcher(li.startsWith(">") ? li.substring(1) : li).replaceAll(" "));
					if (!text.isEmpty())
					{
						add(section, "li", text, firstLink(li));
					}
				}
			}
		}
		nameRepeats(out);
		return out;
	}

	/**
	 * Sub-headings under another ("Equipment" under both Melee and Ranged) are named with the
	 * heading above them, so each says which it is.
	 */
	private static void nameRepeats(Article article)
	{
		for (Section s : article.sections)
		{
			final java.util.Map<String, Integer> seen = new java.util.HashMap<>();
			for (Block b : s.blocks)
			{
				if ("h".equals(b.type) && b.text != null)
				{
					seen.merge(b.text.toLowerCase(Locale.ROOT), 1, Integer::sum);
				}
			}
			for (Block b : s.blocks)
			{
				// Sub-headings all look alike on a card, so one under another is named after it
				// when that stays short, and always when its own name repeats
				if ("h".equals(b.type) && b.text != null && b.parent != null && !b.parent.equalsIgnoreCase(b.text)
					&& !b.text.startsWith(b.parent + ":")
					&& (seen.getOrDefault(b.text.toLowerCase(Locale.ROOT), 0) > 1 || b.parent.length() + b.text.length() <= 46))
				{
					b.text = b.parent + ": " + b.text;
				}
			}
		}
		// Whole sections of the same name (rare outside tabs) are numbered
		final java.util.Map<String, Integer> titles = new java.util.HashMap<>();
		for (Section s : article.sections)
		{
			if (s.title == null)
			{
				continue;
			}
			final int n = titles.merge(s.title.toLowerCase(Locale.ROOT), 1, Integer::sum);
			if (n > 1)
			{
				s.title = s.title + " (" + n + ")";
			}
		}
	}

	/**
	 * The wiki's tabs, each tab's content kept in place under its name. Headings inside a
	 * tab become sub-headings named after it ("Ranged: Inventory"), so they stay under the
	 * section the tabs are in and say which tab they belong to.
	 */
	static String tabs(String html)
	{
		final List<int[]> found = new ArrayList<>();
		final Matcher t = TAB.matcher(html);
		while (t.find())
		{
			found.add(new int[]{t.start(), t.end()});
		}
		if (found.isEmpty())
		{
			return html;
		}
		final boolean named = found.size() > 1;
		// From the last tab back, so earlier positions stay right
		for (int i = found.size() - 1; i >= 0; i--)
		{
			final int start = found.get(i)[0];
			final int open = found.get(i)[1];
			final Matcher tm = TAB.matcher(html.substring(start, open));
			final String title = tm.find() ? tm.group(1) : "";
			final int end = close(html, "div", open);
			final int innerEnd = Math.max(open, end - "</div>".length());
			String inner = html.substring(open, innerEnd);
			final Matcher h = TAB_HEADING.matcher(inner);
			final StringBuffer sb = new StringBuffer();
			while (h.find())
			{
				final String text = named && !title.isEmpty() ? title + ": " + h.group(3) : h.group(3);
				h.appendReplacement(sb, Matcher.quoteReplacement("<h4>" + text + "</h4>"));
			}
			h.appendTail(sb);
			inner = sb.toString();
			html = html.substring(0, start) + (named && !title.isEmpty() ? "<h4>" + title + "</h4>" : "") + inner + html.substring(innerEnd);
		}
		return html;
	}

	private static boolean isStorage(String cls)
	{
		for (String c : cls.split("\\s+"))
		{
			if (c.equals("inventorytable") || c.equals("runepouchtable") || c.equals("equipment"))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * An inventory, rune pouch or worn-equipment picture as a list: each item with its
	 * picture and amount, or each worn item with its slot.
	 */
	private static Table storage(String html, String cls)
	{
		final Table t = new Table();
		t.cls = "wikitable storage";
		final boolean worn = !cls.contains("inventorytable") && !cls.contains("runepouchtable");
		final boolean pouch = cls.contains("runepouchtable");
		if (worn)
		{
			t.headers.add("");
			t.headers.add("Worn");
			t.headers.add("Slot");
		}
		else
		{
			t.headers.add("");
			t.headers.add(pouch ? "Rune pouch" : "Item");
			t.headers.add("Amount");
		}
		final java.util.Map<String, long[]> amounts = new java.util.LinkedHashMap<>();
		final java.util.Map<String, String[]> about = new java.util.HashMap<>();
		final Matcher m = STORED.matcher(html);
		while (m.find())
		{
			final String page = decode(m.group(1)).replace('_', ' ');
			final Matcher tt = TITLE_ATTR.matcher(m.group(0));
			final String shown = tt.find() ? Drops.text(tt.group(1)) : "";
			String src = m.group(2);
			final int q = src.indexOf('?');
			if (q > 0)
			{
				src = src.substring(0, q);
			}
			// The slot is the class of the box the picture sits in ("equipment-head")
			String slot = "";
			if (worn)
			{
				// The nearest slot box before the picture, past its inner wrappers
				final Matcher sm = SLOT.matcher(html.substring(Math.max(0, m.start() - 400), m.start()));
				while (sm.find())
				{
					final String c = sm.group(1);
					if (!c.equals("plinkp") && !c.equals("blank") && !c.equals("div") && !c.equals("right")
						&& !c.equals("left") && !c.equals("center"))
					{
						slot = slotName(c);
					}
				}
			}
			// The amount written on the slot, if any (16000 runes)
			long amount = 1;
			final int next = html.indexOf("<img", m.end());
			final String after = html.substring(m.end(), next < 0 ? html.length() : next);
			final Matcher am = AMOUNT.matcher(after);
			if (am.find())
			{
				try
				{
					amount = Long.parseLong(am.group(1).replace(",", ""));
				}
				catch (NumberFormatException e)
				{
					amount = 1;
				}
			}
			final String key = worn ? slot + "|" + page : page;
			amounts.computeIfAbsent(key, k -> new long[1])[0] += worn ? 1 : amount;
			about.put(key, new String[]{page, shown.isEmpty() ? page : shown, src, slot});
		}
		for (java.util.Map.Entry<String, long[]> e : amounts.entrySet())
		{
			final String[] a = about.get(e.getKey());
			final Cell pic = new Cell();
			pic.text = "";
			pic.icons = new ArrayList<>();
			pic.icons.add(a[0] + "|0|" + a[2]);
			final Cell name = new Cell();
			name.text = a[1];
			name.link = a[0];
			name.linkText = a[1];
			final List<Cell> row = new ArrayList<>();
			if (worn)
			{
				final Cell slot = new Cell();
				slot.text = a[3];
				row.add(pic);
				row.add(name);
				row.add(slot);
			}
			else
			{
				final Cell amount = new Cell();
				amount.text = String.format(Locale.ROOT, "%,d", e.getValue()[0]);
				amount.sort = Long.toString(e.getValue()[0]);
				row.add(pic);
				row.add(name);
				row.add(amount);
			}
			t.rows.add(row);
		}
		return t;
	}

	private static String slotName(String cls)
	{
		switch (cls)
		{
			case "head":
				return "Head";
			case "cape":
				return "Cape";
			case "neck":
				return "Neck";
			case "ammo":
			case "ammo2":
				return "Ammo";
			case "weapon":
				return "Weapon";
			case "torso":
			case "body":
				return "Body";
			case "shield":
				return "Shield";
			case "legs":
				return "Legs";
			case "hands":
			case "gloves":
				return "Hands";
			case "feet":
			case "boots":
				return "Feet";
			case "ring":
				return "Ring";
			default:
				return Character.toUpperCase(cls.charAt(0)) + cls.substring(1);
		}
	}

	/**
	 * A quest's details box: each row's heading as a sub-heading, its text and lists under it.
	 */
	private static void questDetails(String html, Section section)
	{
		for (String tr : ROW.split(NESTED_TABLE.matcher(html).replaceAll("")))
		{
			final Matcher c = CELL.matcher(tr);
			while (c.find())
			{
				final String cell = c.group(3);
				if (c.group(1).equalsIgnoreCase("h"))
				{
					final String text = Drops.text(cell);
					if (!text.isEmpty())
					{
						add(section, "h", text, null);
					}
					continue;
				}
				// Text before any list, then each list item
				final int list = cell.toLowerCase(Locale.ROOT).indexOf("<ul");
				final String before = Drops.text(BREAK.matcher(list < 0 ? cell : cell.substring(0, list)).replaceAll(" "));
				if (!before.isEmpty())
				{
					add(section, "p", before, firstLink(list < 0 ? cell : cell.substring(0, list)));
				}
				if (list >= 0)
				{
					for (String li : LI.split(cell.substring(list)))
					{
						final String text = Drops.text(BREAK.matcher(li.startsWith(">") ? li.substring(1) : li).replaceAll(" "));
						if (!text.isEmpty())
						{
							add(section, "li", text, firstLink(li));
						}
					}
				}
			}
		}
	}

	private static void add(Section s, String type, String text, String link)
	{
		Block b = new Block();
		b.type = type;
		b.text = text;
		b.link = link;
		s.blocks.add(b);
	}

	/**
	 * Where the element opened just before {@code from} closes, counting nested ones of the
	 * same tag. Returns the index just past the closing tag, or the end of the text.
	 */
	private static int close(String html, String tag, int from)
	{
		final String lower = tag.toLowerCase(Locale.ROOT);
		final Pattern p = Pattern.compile("<(/?)" + lower + "(?=[\\s>])[^>]*>", Pattern.CASE_INSENSITIVE);
		final Matcher m = p.matcher(html);
		int depth = 1;
		int at = from;
		while (m.find(at))
		{
			depth += m.group(1).isEmpty() ? 1 : -1;
			at = m.end();
			if (depth == 0)
			{
				return m.end();
			}
		}
		return html.length();
	}

	private static String cls(String attrs)
	{
		final Matcher c = CLASS.matcher(attrs);
		return c.find() ? c.group(1) : "";
	}

	private static Table table(String html, String cls)
	{
		final Table t = new Table();
		t.cls = cls;
		// Tables inside cells (rare) would confuse the rows, so they're dropped
		final String body = NESTED_TABLE.matcher(html).replaceAll("");
		boolean headed = false;
		// Heading columns that run down into a second heading row
		final List<Boolean> tall = new ArrayList<>();
		// Body cells still running down from rows above: column to {cell, rows left}
		final java.util.Map<Integer, Object[]> carry = new java.util.HashMap<>();
		final java.util.Map<Integer, Object[]> fresh = new java.util.HashMap<>();
		for (String tr : ROW.split(body))
		{
			final List<Cell> cells = new ArrayList<>();
			final List<int[]> spans = new ArrayList<>();
			boolean allTh = true;
			final Matcher c = CELL.matcher(tr);
			while (c.find())
			{
				final String attrs = c.group(2) == null ? "" : c.group(2);
				final Cell cell = new Cell();
				cell.th = c.group(1).equalsIgnoreCase("h");
				// Line breaks and list items inside a cell keep a gap between them
				cell.text = Drops.text(NEXT_ITEM.matcher(BREAK.matcher(c.group(3)).replaceAll(" ")).replaceAll(", "));
				cell.text = cell.text.replaceAll(MathText.XML + "[A-Za-z0-9+/=]*", "")
					.replace(MathText.START, "").replace(MathText.END, "").replace(MathText.LINE, "; ");
				cell.link = firstLink(c.group(3));
				cell.linkText = cell.link == null ? null : firstLinkText(c.group(3));
				cell.icons = icons(c.group(3));
				if (cell.icons != null && !cell.text.isEmpty())
				{
					// Text with small pictures in it (a skill icon by each level): the
					// pictures are kept in place as marks, so each sits by its own number
					final String rich = Drops.text(NEXT_ITEM.matcher(BREAK.matcher(marked(c.group(3))).replaceAll(" ")).replaceAll(", "));
					if (Rich.has(rich))
					{
						cell.rich = rich.replace(" ,", ",");
					}
				}
				final Matcher s = SORT.matcher(attrs);
				cell.sort = s.find() ? s.group(1) : sortInside(c.group(3));
				allTh &= cell.th;
				cells.add(cell);
				final Matcher span = SPAN.matcher(attrs);
				final int extra = span.find() ? Math.min(10, Integer.parseInt(span.group(1))) - 1 : 0;
				final Matcher rowspan = ROWSPAN.matcher(attrs);
				spans.add(new int[]{extra + 1, rowspan.find() ? Integer.parseInt(rowspan.group(1)) : 1});
				for (int i = 0; i < extra; i++)
				{
					Cell blank = new Cell();
					blank.text = "";
					blank.th = cell.th;
					if (cell.th && !headed)
					{
						// A spanned heading belongs over the last column it covers, where the
						// name sits after its picture
						blank.text = cell.text;
						cell.text = "";
					}
					cells.add(blank);
				}
			}
			if (cells.isEmpty())
			{
				continue;
			}
			// A body cell running down several rows (a shared rarity, an arrow between
			// inputs and outputs) is carried into the rows below, so their columns line up
			if (!(allTh && !headed) && !(allTh && t.rows.isEmpty()))
			{
				final List<Cell> merged = new ArrayList<>();
				int k = 0;
				for (int[] sp : spans)
				{
					while (carry.containsKey(merged.size()))
					{
						takeCarry(carry, merged);
					}
					final int col = merged.size();
					for (int i = 0; i < sp[0] && k < cells.size(); i++, k++)
					{
						merged.add(cells.get(k));
					}
					if (sp[1] > 1)
					{
						for (int i = 0; i < sp[0]; i++)
						{
							fresh.put(col + i, new Object[]{merged.get(Math.min(col + i, merged.size() - 1)), Math.min(sp[1], 50) - 1});
						}
					}
				}
				while (carry.containsKey(merged.size()))
				{
					takeCarry(carry, merged);
				}
				carry.putAll(fresh);
				fresh.clear();
				cells.clear();
				cells.addAll(merged);
			}
			if (allTh && !headed)
			{
				for (Cell cell : cells)
				{
					t.headers.add(cell.text);
				}
				for (int[] sp : spans)
				{
					for (int i = 0; i < sp[0]; i++)
					{
						tall.add(sp[1] > 1);
					}
				}
				headed = true;
				continue;
			}
			if (allTh && t.rows.isEmpty())
			{
				// A second heading row ("Level" and "XP" under "Magic") fills the columns
				// not taken by headings from the row above
				int col = 0;
				int k = 0;
				for (int[] sp : spans)
				{
					while (col < tall.size() && tall.get(col))
					{
						col++;
					}
					final String text = cells.get(k).text;
					for (int i = 0; i < sp[0] && col < t.headers.size(); i++, col++)
					{
						if (i == 0 && !text.isEmpty())
						{
							t.headers.set(col, text);
						}
					}
					k += sp[0];
				}
				continue;
			}
			headed = true;
			if (t.rows.size() < MAX_ROWS)
			{
				t.rows.add(cells);
			}
		}
		return t;
	}

	private static final Pattern IMG = Pattern.compile("<img\\b[^>]*>", Pattern.CASE_INSENSITIVE);
	private static final Pattern SRC = Pattern.compile("\\ssrc=\"([^\"]+)\"");
	private static final Pattern ALT = Pattern.compile("\\salt=\"([^\"]*)\"");
	private static final Pattern WIDTH = Pattern.compile("\\swidth=\"(\\d+)\"");
	private static final Pattern HREF = Pattern.compile("\\shref=\"/w/([^\"#?]+)");
	private static final Pattern QTY_BEFORE = Pattern.compile("<sup>\\s*([0-9,]+)\\s*</sup>\\s*(?:<span[^>]*>\\s*)*$", Pattern.CASE_INSENSITIVE);
	/**
	 * Pictures wider than this are illustrations, not icons, and are left out.
	 */
	private static final int MAX_ICON_W = 64;

	/**
	 * A small picture in a cell: where its HTML starts and ends, and "title|amount|address|f",
	 * the last part there when the picture names a file rather than a page.
	 */
	private static final class Pic
	{
		final int start;
		final int end;
		final String icon;

		Pic(int start, int end, String icon)
		{
			this.start = start;
			this.end = end;
			this.icon = icon;
		}
	}

	/**
	 * Every small picture in some HTML, with the page it links to. One linked to its own
	 * file, or not linked at all (the skill icons down the side of a level table), is named
	 * by its alt text or its file's name ("Ranged icon.png" is Ranged).
	 */
	private static List<Pic> pictures(String html)
	{
		final List<Pic> out = new ArrayList<>();
		final Matcher m = IMG.matcher(html);
		while (m.find() && out.size() < 8)
		{
			final String tag = m.group();
			final Matcher src = SRC.matcher(tag);
			if (!src.find())
			{
				continue;
			}
			final Matcher w = WIDTH.matcher(tag);
			if (w.find() && Integer.parseInt(w.group(1)) > MAX_ICON_W)
			{
				continue;
			}
			String address = src.group(1);
			final int q = address.indexOf('?');
			if (q > 0)
			{
				address = address.substring(0, q);
			}
			// The link around the picture, if any
			final int openA = html.lastIndexOf("<a ", m.start());
			final int closeA = html.lastIndexOf("</a>", m.start());
			final boolean linked = openA >= 0 && openA > closeA;
			String title = null;
			boolean file = true;
			if (linked)
			{
				final int tagEnd = html.indexOf('>', openA);
				final Matcher h = HREF.matcher(html.substring(openA, tagEnd < 0 ? m.start() : tagEnd + 1));
				if (h.find())
				{
					final String target = decode(h.group(1)).replace('_', ' ');
					if (!target.contains(":"))
					{
						title = target;
						file = false;
					}
				}
			}
			if (title == null)
			{
				final Matcher alt = ALT.matcher(tag);
				title = label(alt.find() ? alt.group(1) : "", address);
			}
			if (title.isEmpty())
			{
				continue;
			}
			int start = linked ? openA : m.start();
			String amount = "0";
			final String before = html.substring(Math.max(0, start - 200), start);
			final Matcher qty = QTY_BEFORE.matcher(before);
			if (qty.find())
			{
				amount = qty.group(1).replace(",", "");
				start -= before.length() - qty.start();
			}
			out.add(new Pic(start, m.end(), title + "|" + amount + "|" + address + (file ? "|f" : "")));
		}
		return out;
	}

	/**
	 * A name for a picture that links nowhere useful: its alt text, else its file's name
	 * without "icon" and the like.
	 */
	static String label(String alt, String address)
	{
		String name = alt == null ? "" : Drops.text(alt).trim();
		if (name.isEmpty() || name.matches("(?i).*\\.(png|gif|jpg|jpeg|svg|webp)"))
		{
			name = name.isEmpty() ? address.substring(address.lastIndexOf('/') + 1) : name;
			name = decode(name).replace('_', ' ');
			name = name.replaceAll("(?i)\\.(png|gif|jpg|jpeg|svg|webp)$", "");
		}
		return name.replaceAll("(?i)\\s+(icon|detail|chathead|sprite)$", "").trim();
	}

	/**
	 * The HTML with each picture swapped for a mark naming which of the cell's pictures it
	 * is, matching {@link #icons}.
	 */
	private static String marked(String html)
	{
		final StringBuilder out = new StringBuilder();
		int at = 0;
		int n = 0;
		for (Pic p : pictures(html))
		{
			if (p.start < at)
			{
				continue;
			}
			out.append(html, at, p.start);
			out.append(Rich.mark(n++));
			at = p.end;
		}
		out.append(html.substring(at));
		return out.toString();
	}

	private static List<String> icons(String html)
	{
		List<String> out = null;
		for (Pic p : pictures(html))
		{
			if (out == null)
			{
				out = new ArrayList<>();
			}
			out.add(p.icon);
		}
		return out;
	}

	private static void takeCarry(java.util.Map<Integer, Object[]> carry, List<Cell> into)
	{
		final int col = into.size();
		final Object[] c = carry.get(col);
		into.add((Cell) c[0]);
		final int left = (Integer) c[1] - 1;
		if (left <= 0)
		{
			carry.remove(col);
		}
		else
		{
			carry.put(col, new Object[]{c[0], left});
		}
	}

	private static String sortInside(String html)
	{
		final Matcher s = SORT.matcher(html);
		return s.find() ? s.group(1) : null;
	}

	/**
	 * The first ordinary wiki page linked from this HTML, as a title, skipping files and
	 * special pages.
	 */
	static String firstLink(String html)
	{
		final Matcher a = LINK.matcher(html);
		while (a.find())
		{
			String title = decode(a.group(1)).replace('_', ' ');
			if (title.contains(":") || Drops.text(a.group(2)).isEmpty())
			{
				continue;
			}
			return title;
		}
		return null;
	}

	/**
	 * The shown text of the first ordinary link, matching {@link #firstLink}.
	 */
	static String firstLinkText(String html)
	{
		final Matcher a = LINK.matcher(html);
		while (a.find())
		{
			final String text = Drops.text(a.group(2));
			if (decode(a.group(1)).contains(":") || text.isEmpty())
			{
				continue;
			}
			return text;
		}
		return null;
	}

	private static String decode(String s)
	{
		try
		{
			return java.net.URLDecoder.decode(s.replace("+", "%2B"), "UTF-8");
		}
		catch (java.io.UnsupportedEncodingException | IllegalArgumentException e)
		{
			return s;
		}
	}
}

package com.wikipeek;

import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Keybind;

@ConfigGroup(WikiPeekConfig.GROUP)
public interface WikiPeekConfig extends Config
{
	String GROUP = "wikipeek";

	@ConfigSection(
		name = "Opening cards",
		description = "Where the WikiPeek option appears, and the search box",
		position = 0
	)
	String opening = "opening";

