	@Override
	protected void startUp()
	{
		loadExamines();
		quill = loadFont("quill8.json", 4);
		bold = loadFont("bold12.json", 3);
		plain = loadFont("plain12.json", 3);
		small = loadFont("plain11.json", 3);
		for (StatIcon icon : StatIcon.values())
		{
			if (icon.getSkill() != null)
			{
				BufferedImage image = skillIconManager.getSkillImage(icon.getSkill(), false);
				if (image != null)
				{
					statIcons.put(icon, image);
				}
			}
		}
		overlayManager.add(overlay);
		overlayManager.add(searchOverlay);
		mouseManager.registerMouseListener(overlay);
		mouseManager.registerMouseWheelListener(overlay);
		mouseManager.registerMouseListener(searchOverlay);
		mouseManager.registerMouseWheelListener(searchOverlay);
		keyManager.registerKeyListener(this);
		// The data folder is set up off the client thread
		executor.execute(() ->
		{
			try
			{
				disk.init(getPluginDirectory());
			}
			catch (IOException | RuntimeException e)
			{
				log.warn("WikiPeek has no data folder, so nothing will be saved between sessions", e);
			}
		});
	}

	@Override
	protected void shutDown()
	{
		closeExtras();
		searchBox.close();
		overlayManager.remove(overlay);
		overlayManager.remove(searchOverlay);
		mouseManager.unregisterMouseListener(overlay);
		mouseManager.unregisterMouseWheelListener(overlay);
		mouseManager.unregisterMouseListener(searchOverlay);
		mouseManager.unregisterMouseWheelListener(searchOverlay);
		keyManager.unregisterKeyListener(this);
		lookup = null;
		overlay.reset();
		wiki.clearMemory();
		statIcons.clear();
		statIconsAsked.set(false);
		chatheads.clear();
		chatheadsAsked.clear();
	}

	private BitmapFont loadFont(String resource, int lineSpacing)
	{
		try (InputStream in = WikiPeekPlugin.class.getResourceAsStream(resource))
		{
			if (in == null)
			{
				return null;
			}
			BitmapFont.Data data = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), BitmapFont.Data.class);
			return data == null || data.glyphs == null ? null : new BitmapFont(data, lineSpacing);
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Could not load font {}, using the standard font instead", resource, e);
			return null;
		}
	}

