	/**
	 * Cards opened alongside the first, newest last. At most a few, the oldest making way.
	 */
	private final List<PanelOverlay> extras = new java.util.concurrent.CopyOnWriteArrayList<>();
	private static final int MAX_EXTRAS = 4;
	private int extrasMade;

	/**
	 * A new card beside the one it was opened from, a little down and to the right.
	 */
	private PanelOverlay newCard(PanelOverlay from)
	{
		if (extras.size() >= MAX_EXTRAS)
		{
			closeExtra(extras.get(0));
		}
		final PanelOverlay card = new PanelOverlay(client, this, config, spriteManager, overlayManager, tooltipManager);
		card.makeExtra("WikiPeekCard" + (++extrasMade));
		final java.awt.Rectangle at = from.getBounds();
		if (at != null)
		{
			card.setPreferredLocation(new java.awt.Point(at.x + 30, at.y + 30));
		}
		final java.awt.Dimension size = from.getPreferredSize();
		if (size != null)
		{
			card.setPreferredSize(size);
		}
		extras.add(card);
		front = card;
		overlayManager.add(card);
		// First in line for the mouse, as it's drawn on top
		mouseManager.registerMouseListener(0, card);
		mouseManager.registerMouseWheelListener(0, card);
		return card;
	}

	void closeExtra(PanelOverlay card)
	{
		if (extras.remove(card))
		{
			overlayManager.remove(card);
			mouseManager.unregisterMouseListener(card);
			mouseManager.unregisterMouseWheelListener(card);
		}
	}

	private void closeExtras()
	{
		for (PanelOverlay card : extras)
		{
			closeExtra(card);
		}
	}

