	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!WikiPeekConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}
		settingsVersion.incrementAndGet();
		if ("clearSavedData".equals(event.getKey()) && config.clearSavedData())
		{
			executor.execute(() ->
			{
				disk.clear();
				wiki.clearMemory();
				clientThread.invokeLater(() -> configManager.setConfiguration(WikiPeekConfig.GROUP, "clearSavedData", false));
			});
		}
		else if ("defaultTab".equals(event.getKey()))
		{
			Lookup open = lookup;
			if (open != null && open.kind == Kind.NPC)
			{
				open.setTab(config.defaultTab().tab());
			}
		}
	}

	/**
	 * Adds the lookup option to NPCs that can be attacked. It only opens the pop-out; nothing
	 * is sent to the game.
	 */
	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		final MenuEntry entry = event.getMenuEntry();
		if (entry.getType() == MenuAction.WALK)
		{
			addSearchEntry();
			return;
		}
		if (isItemExamine(entry))
		{
			if (held(config.itemKey()))
			{
				addItemEntry(entry, event.getTarget());
			}
			return;
		}
		if (entry.getType() == MenuAction.EXAMINE_OBJECT)
		{
			if (held(config.objectKey()))
			{
				addObjectEntry(entry, event.getTarget());
			}
			return;
		}
		if (entry.getType() != MenuAction.EXAMINE_NPC || !held(config.lookupKey()))
		{
			return;
		}
		final NPC npc = entry.getNpc();
		if (npc == null)
		{
			return;
		}
		NPCComposition comp = npc.getTransformedComposition();
		if (comp == null)
		{
			comp = npc.getComposition();
		}
		if (comp == null)
		{
			return;
		}
		final String name = comp.getName() == null ? "" : Text.removeTags(comp.getName());
		if (name.isEmpty() || "null".equalsIgnoreCase(name))
		{
			return;
		}
		final int id = comp.getId();
		final int combat = comp.getCombatLevel();
		client.getMenu().createMenuEntry(-1)
			.setOption(OPTION)
			.setTarget(event.getTarget())
			.setType(MenuAction.RUNELITE)
			.setDeprioritized(true)
			.onClick(e -> open(id, name, combat));
	}

	/**
	 * An item's Examine option, in the inventory, bank, equipment or on the ground.
	 */
	private static boolean isItemExamine(MenuEntry entry)
	{
		if (entry.getOption() == null || !"examine".equalsIgnoreCase(Text.removeTags(entry.getOption()).trim()))
		{
			return false;
		}
		return entry.getType() == MenuAction.EXAMINE_ITEM_GROUND || entry.getType() == MenuAction.EXAMINE_ITEM || entry.getItemId() > 0
			|| widgetItem(entry) > 0;
	}

	/**
	 * The item in the widget a menu entry is on, or -1. With the bank open, the inventory's
	 * items are widget options rather than item options, so this is where their ID is.
	 */
	private static int widgetItem(MenuEntry entry)
	{
		final Widget w = entry.getWidget();
		return w == null ? -1 : w.getItemId();
	}

	/**
	 * Adds the lookup option beside an item's Examine. Client-side only, like the NPC one.
	 */
	private void addItemEntry(MenuEntry entry, String target)
	{
		int id;
		if (entry.getType() == MenuAction.EXAMINE_ITEM_GROUND)
		{
			id = entry.getIdentifier();
		}
		else if (entry.getItemId() > 0)
		{
			id = entry.getItemId();
		}
		else
		{
			id = widgetItem(entry);
		}
		if (id <= 0)
		{
			return;
		}
		// Noted items and bank placeholders look up the item itself
		id = itemManager.canonicalize(id);
		final ItemComposition comp = itemManager.getItemComposition(id);
		final String name = comp == null ? null : comp.getMembersName();
		if (name == null || name.isEmpty() || "null".equalsIgnoreCase(name))
		{
			return;
		}
		final int itemId = id;
		client.getMenu().createMenuEntry(-1)
			.setOption(OPTION)
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.setDeprioritized(true)
			.onClick(e -> openItem(itemId, name));
	}

	/**
	 * WikiPeek search on the ground's right-click menu, for looking up something that isn't
	 * nearby, such as a slayer task before setting off.
	 */
	private void addSearchEntry()
	{
		if (!held(config.searchKey()))
		{
			return;
		}
		client.getMenu().createMenuEntry(-1)
			.setOption(OPTION + " search")
			.setTarget("")
			.setType(MenuAction.RUNELITE)
			.setDeprioritized(true)
			.onClick(e -> openSearch());
	}

	/**
	 * Opens the search box, loading the wiki's lists of NPCs and items for its suggestions.
	 */
	void openSearch()
	{
		searchBox.open();
		for (Kind kind : Kind.values())
		{
			if (kind.template != null)
			{
				wiki.titles(kind, titles -> searchBox.setTitles(kind, titles));
			}
		}
	}

	/**
	 * After a short pause in typing, asks the wiki for every page matching what's typed, so
	 * any page can be found, not only those on the lists.
	 */
	private void searchChanged()
	{
		final String typed = searchBox.getText().trim();
		if (typed.length() < 2)
		{
			return;
		}
		wiki.later(() ->
		{
			if (searchBox.isOpen() && typed.equals(searchBox.getText().trim()))
			{
				wiki.searchTitles(typed, titles -> searchBox.setOnline(typed, titles));
			}
		}, SEARCH_PAUSE_MS);
	}

	/**
	 * Looks up the picked suggestion, or what was typed if nothing matched (an NPC of that
	 * name, else an item).
	 */
	void chooseSearch()
	{
		final SearchBox.Suggestion choice = searchBox.choice();
		if (choice != null)
		{
			searchBox.close();
			if (choice.kind == null)
			{
				// Typed text: the wiki's best match
				search(choice.title, null, targetCard());
			}
			else
			{
				// A page from the lists: open exactly that page
				openPage(choice.title, targetCard(), null);
			}
		}
	}

	/**
	 * Where a card opened from the game goes: a new card beside any already open, if
	 * multiple cards are turned on, else the first card.
	 */
	private PanelOverlay targetCard()
	{
		if (!config.multipleWindows() || lookup == null)
		{
			return overlay;
		}
		return newCard(extras.isEmpty() ? overlay : extras.get(extras.size() - 1));
	}

	/**
	 * Brings a card to the front, drawn over the others and first to get the mouse.
	 */
	void toFront(PanelOverlay card)
	{
		if (front == card)
		{
			return;
		}
		front = card;
		clientThread.invokeLater(() ->
		{
			overlayManager.remove(card);
			overlayManager.add(card);
			mouseManager.unregisterMouseListener(card);
			mouseManager.unregisterMouseWheelListener(card);
			mouseManager.registerMouseListener(0, card);
			mouseManager.registerMouseWheelListener(0, card);
		});
	}

	/**
	 * The card drawn on top of the others.
	 */
	private volatile PanelOverlay front;

	/**
	 * Opens exactly this wiki page as whichever card fits it: a monster, an item, or any
	 * other page. {@code from} is the card it was opened from, for going back.
	 */
	private void openPage(String title, PanelOverlay card, Lookup from)
	{
		final Lookup wait = new Lookup(Kind.NPC, -1, title, 0, pageTabs());
		wait.openedFrom(from);
		card.show(wait);
		loadStatIcons();
		wiki.anyPage(title, page ->
		{
			if (card.current() != wait)
			{
				return;
			}
			if (page != null && page.found && Infobox.has(page.wikitext))
			{
				final Lookup l = new Lookup(Kind.NPC, -1, page.title, 0, npcTabs());
				l.openedFrom(from);
				card.show(l);
				show(l, page, -1, 0);
			}
			else if (page != null && page.found && Infobox.hasItem(page.wikitext))
			{
				final Lookup l = new Lookup(Kind.ITEM, -1, page.title, 0, itemTabs());
				l.openedFrom(from);
				card.show(l);
				showItem(l, page, -1);
			}
			else
			{
				showGeneric(wait, page, -1);
			}
		});
	}

	private boolean held(ModifierKey key)
	{
		switch (key)
		{
			case SHIFT:
				return client.isKeyPressed(KeyCode.KC_SHIFT);
			case CTRL:
				return client.isKeyPressed(KeyCode.KC_CONTROL);
			case ALT:
				return client.isKeyPressed(KeyCode.KC_ALT);
			case OFF:
				return false;
			case NONE:
			default:
				return true;
		}
	}

	/**
	 * Objects' examine text from examining them in the game, by object ID, for objects whose
	 * wiki page doesn't give it. Kept for the session.
	 */
	private final Map<Integer, String> objectExamines = new ConcurrentHashMap<>();
	private int examiningObject = -1;

	@Subscribe
	public void onMenuOptionClicked(net.runelite.api.events.MenuOptionClicked event)
	{
		examiningObject = event.getMenuAction() == MenuAction.EXAMINE_OBJECT ? event.getId() : -1;
	}

	@Subscribe
	public void onChatMessage(net.runelite.api.events.ChatMessage event)
	{
		if (event.getType() == ChatMessageType.OBJECT_EXAMINE && examiningObject > 0 && objectExamines.size() < 5000)
		{
			final int id = examiningObject;
			objectExamines.put(id, Text.removeTags(event.getMessage()));
			examiningObject = -1;
			saveExamines();
			// A card open for this object shows it straight away
			refreshObject(overlay.current(), id);
			for (PanelOverlay card : extras)
			{
				refreshObject(card.current(), id);
			}
		}
	}

	private static final String EXAMINES_FILE = "examines.json";

	/**
	 * Objects' examine text seen in the game, kept on this computer so a door or table only
	 * ever needs examining once.
	 */
	private void loadExamines()
	{
		executor.execute(() ->
		{
			try
			{
				final String json = disk.readText(EXAMINES_FILE);
				if (json != null)
				{
					final com.google.gson.JsonObject saved = gson.fromJson(json, com.google.gson.JsonObject.class);
					if (saved != null)
					{
						for (Map.Entry<String, com.google.gson.JsonElement> e : saved.entrySet())
						{
							objectExamines.putIfAbsent(Integer.parseInt(e.getKey()), e.getValue().getAsString());
						}
					}
				}
			}
			catch (RuntimeException e)
			{
				log.debug("Could not read saved examine text", e);
			}
		});
	}

	private void saveExamines()
	{
		executor.execute(() ->
		{
			final Map<String, String> out = new java.util.HashMap<>();
			for (Map.Entry<Integer, String> e : objectExamines.entrySet())
			{
				out.put(Integer.toString(e.getKey()), e.getValue());
			}
			disk.writeText(EXAMINES_FILE, gson.toJson(out));
		});
	}

	/**
	 * With "Block clicks behind card" on, while the mouse is over a card the game's own
	 * options under it are cleared each frame, so nothing behind lights up or shows its
	 * hover text ("Chop down Tree").
	 */
	@Subscribe
	public void onPostMenuSort(net.runelite.api.events.PostMenuSort event)
	{
		if (!config.blockBehind() || client.isMenuOpen() || !overCard())
		{
			return;
		}
		final List<MenuEntry> kept = new ArrayList<>();
		for (MenuEntry entry : client.getMenu().getMenuEntries())
		{
			if (entry.getType() == MenuAction.CANCEL)
			{
				kept.add(entry);
			}
		}
		client.getMenu().setMenuEntries(kept.toArray(new MenuEntry[0]));
	}

	private void refreshObject(Lookup l, int id)
	{
		if (l != null && l.objectId == id && l.getPage() != null)
		{
			executor.execute(() -> showGeneric(l, l.getPage(), id));
		}
	}

	/**
	 * Adds WikiPeek beside an object's Examine. Client-side only.
	 */
	private void addObjectEntry(MenuEntry entry, String target)
	{
		final int id = entry.getIdentifier();
		final String name = Text.removeTags(target == null ? "" : target).trim();
		if (id <= 0 || name.isEmpty() || "null".equalsIgnoreCase(name))
		{
			return;
		}
		client.getMenu().createMenuEntry(-1)
			.setOption(OPTION)
			.setTarget(target)
			.setType(MenuAction.RUNELITE)
			.setDeprioritized(true)
			.onClick(e -> openObject(id, name));
	}

	/**
	 * Right-clicking a row or drop on the card offers its wiki page and, where there's one to
	 * show, its own card.
	 */
	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		// The top card under the mouse: extra cards are on top, newest first
		PanelRenderer.Target found = null;
		PanelOverlay source = overlay;
		for (int i = extras.size() - 1; i >= 0 && found == null; i--)
		{
			found = extras.get(i).targetUnderMouse();
			source = extras.get(i);
		}
		if (found == null)
		{
			found = overlay.targetUnderMouse();
			source = overlay;
		}
		final PanelRenderer.Target target = found;
		final PanelOverlay from = source;
		if (config.blockBehind() && overCard())
		{
			// Over a card, right-click only offers the card's own options
			final List<MenuEntry> kept = new ArrayList<>();
			for (MenuEntry entry : client.getMenu().getMenuEntries())
			{
				if (entry.getType() == MenuAction.CANCEL)
				{
					kept.add(entry);
				}
			}
			client.getMenu().setMenuEntries(kept.toArray(new MenuEntry[0]));
		}
		if (target == null && overCard())
		{
			return;
		}
		if (target == null)
		{
			itemFallback(event);
			return;
		}
		final String shown = "<col=ff9040>" + target.title + "</col>";
		if (target.card)
		{
			client.getMenu().createMenuEntry(-1)
				.setOption(OPTION)
				.setTarget(shown)
				.setType(MenuAction.RUNELITE)
				.onClick(e -> openTarget(target, from));
		}
		client.getMenu().createMenuEntry(-1)
			.setOption("Wiki")
			.setTarget(shown)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> LinkBrowser.browse(WikiClient.pageUrl(target.title)));
	}

	private boolean overCard()
	{
		if (overlay.isUnderMouse())
		{
			return true;
		}
		for (PanelOverlay card : extras)
		{
			if (card.isUnderMouse())
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Items whose menu has no Examine option the usual way (the inventory while the bank is
	 * open) still get WikiPeek, from the item any of their options is on.
	 */
	private void itemFallback(MenuOpened event)
	{
		if (!held(config.itemKey()))
		{
			return;
		}
		int id = -1;
		String target = null;
		for (MenuEntry entry : event.getMenuEntries())
		{
			if (OPTION.equals(entry.getOption()))
			{
				// Already added beside Examine
				return;
			}
			if (id <= 0 && entry.getType() != MenuAction.EXAMINE_ITEM_GROUND)
			{
				final int item = entry.getItemId() > 0 ? entry.getItemId() : widgetItem(entry);
				if (item > 0 && item != ItemID.BLANKOBJECT)
				{
					id = item;
					target = entry.getTarget();
				}
			}
		}
		if (id <= 0)
		{
			return;
		}
		final int itemId = itemManager.canonicalize(id);
		final ItemComposition comp = itemManager.getItemComposition(itemId);
		final String name = comp == null ? null : comp.getMembersName();
		if (name == null || name.isEmpty() || "null".equalsIgnoreCase(name))
		{
			return;
		}
		client.getMenu().createMenuEntry(1)
			.setOption(OPTION)
			.setTarget(target == null || target.isEmpty() ? "<col=ff9040>" + name + "</col>" : target)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> openItem(itemId, name));
	}

	/**
	 * Opens a card for a page linked from another card.
	 */
	void openTarget(PanelRenderer.Target target, PanelOverlay from)
	{
		// On the client thread, where the card's pictures and icons are fetched
		clientThread.invoke(() ->
		{
			if (config.multipleWindows())
			{
				openPage(target.title, newCard(from), null);
			}
			else
			{
				// On the same card, with back leading to the one it came from
				openPage(target.title, from, from.current());
			}
		});
	}

	/**
	 * Opens the pop-out for an NPC and starts fetching its page. Called on the client thread;
	 * the fetching runs elsewhere.
	 */
	void open(int id, String name, int combat)
	{
		final Lookup l = new Lookup(Kind.NPC, id, name, combat, npcTabs());
		targetCard().show(l);
		loadStatIcons();
		wiki.page(id, name, combat, page -> show(l, page, id, combat));
	}

	/**
	 * Opens a card for an object in the world, from its ID. Client thread.
	 */
	void openObject(int id, String name)
	{
		final Lookup l = new Lookup(Kind.NPC, -1, name, 0, pageTabs());
		l.objectId = id;
		targetCard().show(l);
		loadStatIcons();
		wiki.object(id, name, page -> showGeneric(l, page, id));
	}

	private List<Tab> npcTabs()
	{
		final Tab first = config.defaultTab().tab();
		final List<Tab> tabs = new ArrayList<>();
		tabs.add(first);
		tabs.add(first == Tab.LOOT ? Tab.INFO : Tab.LOOT);
		return tabs;
	}

	private static List<Tab> pageTabs()
	{
		final List<Tab> tabs = new ArrayList<>();
		tabs.add(Tab.INFO);
		return tabs;
	}

	private static List<Tab> itemTabs()
	{
		final List<Tab> tabs = new ArrayList<>();
		tabs.add(Tab.INFO);
		tabs.add(Tab.STATS);
		tabs.add(Tab.LOOT);
		tabs.add(Tab.SOURCES);
		return tabs;
	}

	/**
	 * Opens the pop-out for an item. Called on the client thread.
	 */
	void openItem(int id, String name)
	{
		final Lookup l = new Lookup(Kind.ITEM, id, name, 0, itemTabs());
		targetCard().show(l);
		loadStatIcons();
		wiki.itemPage(id, name, page -> showItem(l, page, id));
	}

	/**
	 * Opens the card for a name typed in or a link on a card. Its name bar shows the wiki
	 * page's title once found, and the infobox shows the page's first version.
	 */
	void search(String query, Kind kind)
	{
		search(query, kind, overlay);
	}

	private void search(String query, Kind kind, PanelOverlay card)
	{
		search(query, kind == null ? Kind.NPC : kind, 0, card);
	}

	/**
	 * Looks a page up as one kind, then the other, then as any wiki page (a shop, a place,
	 * an NPC you can't fight), shown on the given card.
	 */
	private void search(String query, Kind kind, int attempt, PanelOverlay card)
	{
		final boolean item = kind == Kind.ITEM;
		if (attempt >= 2)
		{
			final Lookup l = new Lookup(Kind.NPC, -1, query, 0, pageTabs());
			card.show(l);
			loadStatIcons();
			wiki.anyPage(query, page -> showGeneric(l, page, -1));
			return;
		}
		final Lookup l = new Lookup(kind, -1, query, 0, item ? itemTabs() : npcTabs());
		card.show(l);
		loadStatIcons();
		wiki.search(query, kind, page ->
		{
			if (page != null && !page.found)
			{
				if (card.current() == l)
				{
					search(query, item ? Kind.NPC : Kind.ITEM, attempt + 1, card);
				}
				return;
			}
			if (page != null && page.found)
			{
				l.setName(page.title);
			}
			if (item)
			{
				showItem(l, page, -1);
			}
			else
			{
				show(l, page, -1, 0);
			}
		});
	}

	/**
	 * Fills an item's pop-out from its wiki page: Info, Stats if it's worn, Sources, and its
	 * picture. The GE price is read on the client thread.
	 */
	private void showItem(Lookup l, WikiClient.Page page, int id)
	{
		if (config.tableIcons())
		{
			// Item names, to tell which drop sources are items with pictures
			itemNames();
		}
		final String name = l.getName();
		if (page == null)
		{
			l.failed(Lookup.State.ERROR, WikiClient.searchUrl(name));
			return;
		}
		if (!page.found)
		{
			l.failed(Lookup.State.NOT_FOUND, WikiClient.searchUrl(name));
			return;
		}
		final Infobox box;
		final Infobox bonuses;
		final MonsterInfo sources;
		final MonsterInfo loot;
		final boolean full = config.itemDetail() == ItemDetail.FULL;
		int itemId = id;
		try
		{
			box = Infobox.readItem(page.wikitext, id);
			bonuses = Infobox.readBonuses(page.wikitext, box == null ? null : box.getVersion());
			sources = ItemInfo.sources(page.article);
			loot = ItemInfo.loot(page.article);
			if (itemId <= 0 && box != null)
			{
				for (int i : Infobox.ids(box.get("id")))
				{
					itemId = itemId <= 0 ? i : Math.min(itemId, i);
				}
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Could not read the wiki page for {}", name, e);
			l.failed(Lookup.State.ERROR, WikiClient.pageUrl(page.title));
			return;
		}
		final int priceId = itemId;
		final boolean tradeable = box != null && box.get("tradeable").equalsIgnoreCase("yes");
		clientThread.invoke(() ->
		{
			long price = 0;
			if (priceId > 0 && tradeable)
			{
				try
				{
					price = itemManager.getItemPrice(priceId);
				}
				catch (RuntimeException e)
				{
					log.debug("No price for {}", priceId, e);
				}
			}
			MonsterInfo stats;
			try
			{
				stats = compared(bonuses, priceId);
			}
			catch (RuntimeException e)
			{
				log.debug("Could not compare {} with worn gear", priceId, e);
				stats = ItemInfo.stats(bonuses, null, null);
			}
			l.readyItem(ItemInfo.info(box, page.article, price, full, page.wikitext), stats, loot, sources, WikiClient.pageUrl(page.title));
		});
		// The wiki's detailed picture of the item, else its infobox picture
		String file = page.pageImage;
		if (file == null && box != null)
		{
			file = box.imageFile();
		}
		if (file != null)
		{
			wiki.loadImage(WikiClient.fileUrl(file), image ->
			{
				if (image != null)
				{
					l.setImage(image);
				}
			});
		}
	}

	/**
	 * The Stats tab, with each bonus compared against what's worn in the same slot if that's
	 * turned on. A two-handed weapon is compared against the weapon and shield together, and
	 * a shield against a worn two-handed weapon it would replace. Client thread only.
	 */
	private MonsterInfo compared(Infobox bonuses, int itemId)
	{
		if (bonuses == null || !config.compareGear() || itemId <= 0)
		{
			return ItemInfo.stats(bonuses, null, null);
		}
		final ItemStats stats = itemManager.getItemStats(itemId);
		final ItemEquipmentStats mine = stats == null ? null : stats.getEquipment();
		final ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (mine == null || worn == null)
		{
			return ItemInfo.stats(bonuses, null, null);
		}
		final int weaponSlot = 3;
		final int shieldSlot = 5;
		final List<Integer> slots = new ArrayList<>();
		slots.add(mine.getSlot());
		if (mine.isTwoHanded())
		{
			slots.add(shieldSlot);
		}
		else if (mine.getSlot() == shieldSlot)
		{
			final ItemEquipmentStats weapon = wornStats(worn, weaponSlot);
			if (weapon != null && weapon.isTwoHanded())
			{
				slots.add(weaponSlot);
			}
		}
		final double[] diff = values(mine);
		final List<String> names = new ArrayList<>();
		for (int slot : slots)
		{
			final Item item = worn.getItem(slot);
			if (item == null || item.getId() <= 0)
			{
				continue;
			}
			if (item.getId() == itemId)
			{
				return ItemInfo.stats(bonuses, null, "This, as you're wearing it");
			}
			final ItemEquipmentStats other = wornStats(worn, slot);
			if (other != null)
			{
				final double[] theirs = values(other);
				for (int i = 0; i < diff.length; i++)
				{
					diff[i] -= theirs[i];
				}
			}
			final ItemComposition comp = itemManager.getItemComposition(item.getId());
			if (comp != null && comp.getName() != null)
			{
				names.add(comp.getName());
			}
		}
		return ItemInfo.stats(bonuses, diff, names.isEmpty() ? "Nothing equipped" : String.join(" and ", names));
	}

	private ItemEquipmentStats wornStats(ItemContainer worn, int slot)
	{
		final Item item = worn.getItem(slot);
		if (item == null || item.getId() <= 0)
		{
			return null;
		}
		final ItemStats stats = itemManager.getItemStats(item.getId());
		return stats == null ? null : stats.getEquipment();
	}

	/**
	 * Bonuses in the Stats tab's order.
	 */
	private static double[] values(ItemEquipmentStats s)
	{
		return new double[]{
			s.getAstab(), s.getAslash(), s.getAcrush(), s.getAmagic(), s.getArange(),
			s.getDstab(), s.getDslash(), s.getDcrush(), s.getDmagic(), s.getDrange(),
			s.getStr(), s.getRstr(), s.getMdmg(), s.getPrayer()};
	}

	/**
	 * Fills the pop-out from a wiki page: the infobox for this NPC's version, its drops and
	 * its picture. Runs off the client thread.
	 */
	private void show(Lookup l, WikiClient.Page page, int id, int combat)
	{
		show(l, page, id, combat, null);
	}

	/**
	 * Fills a card for any other wiki page: an NPC you can't fight, a shop, a place or an
	 * object, from its infobox and write-up.
	 */
	private void showGeneric(Lookup l, WikiClient.Page page, int id)
	{
		showGeneric(l, page, id, null);
	}

	private void showGeneric(Lookup l, WikiClient.Page page, int id, Infobox.Choice forced)
	{
		final String name = l.getName();
		if (page == null)
		{
			l.failed(Lookup.State.ERROR, WikiClient.searchUrl(name));
			return;
		}
		if (!page.found)
		{
			l.failed(Lookup.State.NOT_FOUND, WikiClient.searchUrl(name));
			return;
		}
		final Infobox box;
		final MonsterInfo info;
		try
		{
			box = forced != null ? Infobox.readAny(page.wikitext, forced) : Infobox.readAny(page.wikitext, id);
			// An object's examine the wiki doesn't have, from examining it in the game
			String examined = l.objectId > 0 ? objectExamines.get(l.objectId) : null;
			if (examined == null && l.objectId > 0)
			{
				// The game only gives an object's examine text when it's examined; once it
				// has been, it's remembered and shown here
				examined = "Not examined yet: examine it once to keep its description here.";
			}

			info = ItemInfo.generic(box, page.article, config.itemDetail() == ItemDetail.FULL, examined);
			l.generic = true;
			// Pages that aren't monsters have only an Info tab
			for (Tab t : new ArrayList<>(l.getTabs()))
			{
				if (t != Tab.INFO)
				{
					l.removeTab(t);
				}
			}
			l.setPage(page);
			final List<Infobox.Choice> choices = Infobox.choicesAny(page.wikitext);
			if (config.versionStyle() != VersionStyle.OFF && choices.size() > 1 && box != null)
			{
				final List<String> labels = new ArrayList<>();
				for (Infobox.Choice c : choices)
				{
					labels.add(c.label);
				}
				l.setVersions(labels, Math.max(0, box.choiceIndex(choices)));
			}
		}
		catch (RuntimeException e)
		{
			log.debug("Could not read the wiki page for {}", name, e);
			l.failed(Lookup.State.ERROR, WikiClient.pageUrl(page.title));
			return;
		}
		l.setName(page.title);
		l.ready(info, WikiClient.pageUrl(page.title));
		// The version's own picture first (an object's), then the page's, then the first
		// picture in its text
		String file = box != null ? box.imageFile() : null;
		if (file == null)
		{
			file = page.pageImage;
		}
		if (file == null && page.title != null && page.title.startsWith(SLAYER_TASK))
		{
			// A slayer task page has only small icons, so it borrows the monster's picture
			wiki.leadPicture(page.title.substring(SLAYER_TASK.length()), found ->
			{
				if (found != null)
				{
					wiki.loadImage(found, image ->
					{
						if (image != null)
						{
							l.setImage(image);
						}
					});
				}
			});
		}
		else if (file == null && (page.article == null || page.article.image == null))
		{
			// Nothing on the page at all: look for a picture file with its name
			wiki.fileFor(l.objectId > 0 && name != null ? name : page.title, found ->
			{
				if (found != null)
				{
					wiki.loadImage(WikiClient.fileUrl(found), image ->
					{
						if (image != null)
						{
							l.setImage(image);
						}
					});
				}
			});
		}
		if (file == null && page.article != null && page.article.image != null)
		{
			final String direct = WikiClient.imageUrl(page.article.image);
			if (direct != null)
			{
				wiki.loadImage(direct, image ->
				{
					if (image != null)
					{
						l.setImage(image);
					}
				});
			}
		}
		if (file != null)
		{
			wiki.loadImage(WikiClient.fileUrl(file), image ->
			{
				if (image != null)
				{
					l.setImage(image);
				}
			});
		}
	}

	/**
	 * Shows another of the monsters an NPC's page covers (another Barbarian, say), from the
	 * page already fetched.
	 */
	void showVersion(Lookup l, int index)
	{
		final WikiClient.Page page = l.getPage();
		if (page == null || l.kind != Kind.NPC)
		{
			return;
		}
		if (l.generic)
		{
			final List<Infobox.Choice> any = Infobox.choicesAny(page.wikitext);
			if (any.size() > 1)
			{
				final Infobox.Choice choice = any.get(Math.floorMod(index, any.size()));
				executor.execute(() ->
				{
					l.resetScroll();
					showGeneric(l, page, -1, choice);
				});
			}
			return;
		}
		final List<Infobox.Choice> choices = Infobox.choices(page.wikitext);
		if (choices.size() < 2)
		{
			return;
		}
		final Infobox.Choice choice = choices.get(Math.floorMod(index, choices.size()));
		executor.execute(() ->
		{
			l.setDrops(null);
			l.resetScroll();
			show(l, page, -1, 0, choice);
		});
	}

	private void show(Lookup l, WikiClient.Page page, int id, int combat, Infobox.Choice forced)
	{
		final String name = l.getName();
		if (page == null)
		{
			l.failed(Lookup.State.ERROR, WikiClient.searchUrl(name));
			return;
		}
		if (!page.found)
		{
			l.failed(Lookup.State.NOT_FOUND, WikiClient.searchUrl(name));
			return;
		}
		if (!Infobox.has(page.wikitext))
		{
			// An NPC you can't fight, such as a slayer master or shopkeeper
			showGeneric(l, page, id);
			return;
		}
		final MonsterInfo info;
		final List<Drops.Group> drops;
		final String picture;
		try
		{
			final Infobox box = forced != null ? Infobox.read(page.wikitext, forced) : Infobox.read(page.wikitext, id, combat);
			// The page's other monsters, to switch between like the wiki's tabs
			final List<Infobox.Choice> choices = Infobox.choices(page.wikitext);
			l.setPage(page);
			if (config.versionStyle() != VersionStyle.OFF && choices.size() > 1 && box != null)
			{
				final List<String> labels = new ArrayList<>();
				for (Infobox.Choice c : choices)
				{
					labels.add(c.label);
				}
				l.setVersions(labels, Math.max(0, box.choiceIndex(choices)));
			}
			info = MonsterInfo.of(box,
				page.slayerGuide == null ? null : WikiClient.pageUrl(page.slayerGuide),
				page.strategyGuide == null ? null : WikiClient.pageUrl(page.strategyGuide));
			// The wiki's write-up after Basics, and with Full detail the rest of the page,
			// folded, after the stats
			final MonsterInfo.Section about = ItemInfo.about(page.article);
			if (about != null)
			{
				info.sections.add(Math.min(1, info.sections.size()), about);
			}
			if (config.itemDetail() == ItemDetail.FULL)
			{
				info.sections.addAll(ItemInfo.folded(page.article, true));
			}
			// A search has no level of its own, so its drops follow the infobox version shown
			int level = forced != null ? 0 : combat;
			if (level <= 0 && box != null)
			{
				try
				{
					level = Integer.parseInt(box.get("combat").trim());
				}
				catch (NumberFormatException e)
				{
					level = 0;
				}
			}
			drops = Drops.forNpc(page.tables, page.wikitext, box, level, name);
			// This version's own picture, so a Barbarian shows the one you clicked
			String file = box != null ? box.imageFile() : null;
			if (file == null)
			{
				file = page.pageImage;
			}
			picture = file == null ? null : WikiClient.fileUrl(file);
		}
		catch (RuntimeException e)
		{
			log.debug("Could not read the wiki page for {}", name, e);
			l.failed(Lookup.State.ERROR, WikiClient.pageUrl(page.title));
			return;
		}
		l.ready(info, WikiClient.pageUrl(page.title));
		loadChatheads(info);
		dressDrops(l, drops);
		if (picture != null)
		{
			wiki.loadImage(picture, image ->
			{
				if (image != null)
				{
					l.setImage(image);
				}
			});
		}
	}

	// Icons

	@Override
	public BufferedImage stat(StatIcon icon)
	{
		return statIcons.get(icon);
	}

	@Override
	public BufferedImage master(String code)
	{
		return chatheads.get(code);
	}

	/**
	 * Item pictures for tables, by "name|count". Looked up on the client thread the first
	 * time each is asked for; null until then, or if no item has that name.
	 */
	private final Map<String, BufferedImage> itemIcons = new ConcurrentHashMap<>();
	private final Set<String> itemIconsAsked = ConcurrentHashMap.newKeySet();

	/**
	 * Pictures from the wiki for tables, by their address, fetched once and kept.
	 */
	private final Map<String, BufferedImage> wikiIcons = new ConcurrentHashMap<>();
	private final Set<String> wikiIconsAsked = ConcurrentHashMap.newKeySet();

	@Override
	public BufferedImage wiki(String src)
	{
		if (src == null || !src.startsWith("/images/"))
		{
			return null;
		}
		final BufferedImage done = wikiIcons.get(src);
		if (done != null || wikiIconsAsked.size() > 3000 || !wikiIconsAsked.add(src))
		{
			return done;
		}
		wiki.loadImage(WikiClient.imageUrl(src), image ->
		{
			if (image != null)
			{
				wikiIcons.put(src, image);
				iconsVersion.incrementAndGet();
			}
		});
		return null;
	}

	/**
	 * Small lead pictures of pages (drop sources), asked for in batches.
	 */
	private final Map<String, BufferedImage> pagePictures = new ConcurrentHashMap<>();
	private final Set<String> pagePicturesAsked = ConcurrentHashMap.newKeySet();
	private final Set<String> pagePicturesWaiting = ConcurrentHashMap.newKeySet();
	private final AtomicBoolean pagePicturesQueued = new AtomicBoolean();

	@Override
	public BufferedImage page(String title)
	{
		if (title == null || title.isEmpty())
		{
			return null;
		}
		final BufferedImage done = pagePictures.get(title);
		if (done != null || pagePicturesAsked.size() > 4000 || !pagePicturesAsked.add(title))
		{
			return done;
		}
		pagePicturesWaiting.add(title);
		// Gathered for a moment, so a whole table is asked for in a few requests
		if (pagePicturesQueued.compareAndSet(false, true))
		{
			executor.schedule(this::askPagePictures, 150, java.util.concurrent.TimeUnit.MILLISECONDS);
		}
		return null;
	}

	private void askPagePictures()
	{
		pagePicturesQueued.set(false);
		final List<String> all = new ArrayList<>(pagePicturesWaiting);
		pagePicturesWaiting.removeAll(all);
		for (int i = 0; i < all.size(); i += 50)
		{
			wiki.pageImages(all.subList(i, Math.min(all.size(), i + 50)), found ->
			{
				for (Map.Entry<String, String> e : found.entrySet())
				{
					wiki.loadImage(e.getValue(), image ->
					{
						if (image != null)
						{
							pagePictures.put(e.getKey(), image);
							iconsVersion.incrementAndGet();
						}
					});
				}
			});
		}
	}

	@Override
	public boolean isItem(String name)
	{
		final Map<String, Integer> ids = itemIds;
		return name != null && ids != null && ids.containsKey(name.toLowerCase(Locale.ROOT));
	}

	/**
	 * Makes sure every item's name is known, for pictures by name. Client thread.
	 */
	private void itemNames()
	{
		clientThread.invokeLater(() ->
		{
			if (itemIds == null)
			{
				itemIds = allItemIds();
				iconsVersion.incrementAndGet();
			}
		});
	}

	@Override
	public BufferedImage item(String name, int quantity)
	{
		if (name == null || name.isEmpty())
		{
			return null;
		}
		final String key = name.toLowerCase(Locale.ROOT) + "|" + quantity;
		final BufferedImage done = itemIcons.get(key);
		if (done != null || itemIconsAsked.size() > 2000 || !itemIconsAsked.add(key))
		{
			return done;
		}
		clientThread.invokeLater(() ->
		{
			if (itemIds == null)
			{
				itemIds = allItemIds();
			}
			Integer id = name.equalsIgnoreCase("Coins") ? Integer.valueOf(ItemID.COINS) : itemIds.get(name.toLowerCase(Locale.ROOT));
			if (id == null)
			{
				return;
			}
			final AsyncBufferedImage image = itemManager.getImage(id, Math.max(1, quantity), quantity > 1);
			if (image == null)
			{
				return;
			}
			final Runnable store = () ->
			{
				itemIcons.put(key, image);
				iconsVersion.incrementAndGet();
			};
			image.onLoaded(store);
			store.run();
		});
		return null;
	}

	/**
	 * The wiki's style and defence icons, fetched once a session (and saved to disk).
	 */
	private void loadStatIcons()
	{
		if (!statIconsAsked.compareAndSet(false, true))
		{
			return;
		}
		final List<String> files = new ArrayList<>();
		for (StatIcon icon : StatIcon.values())
		{
			if (icon.getFile() != null)
			{
				files.add(icon.getFile());
			}
		}
		wiki.fileUrls(files, 0, urls ->
		{
			if (urls.isEmpty())
			{
				// Try again next time a pop-out opens
				statIconsAsked.set(false);
				return;
			}
			for (StatIcon icon : StatIcon.values())
			{
				String url = icon.getFile() == null ? null : urls.get(icon.getFile());
				if (url != null)
				{
					wiki.loadImage(url, image ->
					{
						if (image != null)
						{
							statIcons.put(icon, image);
							iconsVersion.incrementAndGet();
						}
					});
				}
			}
		});
	}

	private void loadChatheads(MonsterInfo info)
	{
		final List<String> files = new ArrayList<>();
		final Map<String, String> codes = new HashMap<>();
		for (MonsterInfo.Section section : info.sections)
		{
			for (String code : section.masters)
			{
				if (chatheadsAsked.add(code))
				{
					files.add(Masters.file(code));
					codes.put(Masters.file(code), code);
				}
			}
		}
		if (files.isEmpty())
		{
			return;
		}
		wiki.fileUrls(files, CHATHEAD_WIDTH, urls ->
		{
			for (Map.Entry<String, String> file : codes.entrySet())
			{
				String url = urls.get(file.getKey());
				if (url == null)
				{
					// No chathead: the name is shown on its own. Allow another try later.
					chatheadsAsked.remove(file.getValue());
					continue;
				}
				wiki.loadImage(url, image ->
				{
					if (image != null)
					{
						chatheads.put(file.getValue(), image);
						iconsVersion.incrementAndGet();
					}
				});
			}
		});
	}

	// Drops

	/**
	 * Gives each drop its Grand Exchange price and the game's picture of it, then puts the
	 * table on the pop-out. Runs on the client thread, where every item can be looked up by
	 * name (client.getItemDefinition asserts it's on the client thread).
	 */
	private void dressDrops(Lookup l, List<Drops.Group> groups)
	{
		if (groups.isEmpty())
		{
			// Nothing to show on a Loot tab
			l.setDrops(groups);
			l.removeTab(Tab.LOOT);
			return;
		}
		clientThread.invoke(() ->
		{
			if (client.getGameState().ordinal() < GameState.LOGIN_SCREEN.ordinal())
			{
				// The game hasn't loaded its items yet; try again shortly
				return false;
			}
			if (itemIds == null)
			{
				itemIds = allItemIds();
			}
			for (Drops.Group group : groups)
			{
				for (Drops.Item item : group.items)
				{
					try
					{
						dressDrop(l, item);
					}
					catch (RuntimeException e)
					{
						// A missing price or picture never stops the table showing
						log.debug("Could not price or picture {}", item.name, e);
					}
				}
			}
			l.setDrops(groups);
			return true;
		});
	}

	private Map<String, Integer> allItemIds()
	{
		final Map<String, Integer> ids = new HashMap<>();
		for (int id = 0; id < client.getItemCount(); id++)
		{
			final ItemComposition item = client.getItemDefinition(id);
			// Skip noted copies and bank placeholders: the first plain item with a name wins
			if (item == null || item.getNote() != -1 || item.getPlaceholderTemplateId() != -1)
			{
				continue;
			}
			final String itemName = item.getMembersName();
			if (itemName != null && !itemName.isEmpty() && !"null".equalsIgnoreCase(itemName))
			{
				ids.putIfAbsent(itemName.toLowerCase(Locale.ROOT), id);
			}
		}
		return ids;
	}

	private void dressDrop(Lookup l, Drops.Item item)
	{
		final String name = item.name;
		if (name == null || name.isEmpty() || name.equalsIgnoreCase("Nothing"))
		{
			return;
		}
		final String key = name.toLowerCase(Locale.ROOT);
		int id = -1;
		if (name.equalsIgnoreCase("Coins"))
		{
			id = ItemID.COINS;
			item.price = 1;
		}
		else if (SHARED_TABLE_ICONS.containsKey(key))
		{
			id = SHARED_TABLE_ICONS.get(key);
		}
		else
		{
			for (ItemPrice price : itemManager.search(name))
			{
				if (price.getName().equalsIgnoreCase(name))
				{
					id = price.getId();
					item.price = itemManager.getWikiPrice(price);
					break;
				}
			}
		}
		if (id < 0)
		{
			// Untradeable: find it by name among every item in the game
			Integer known = itemIds.get(key);
			if (known != null)
			{
				id = known;
			}
		}
		if (id < 0)
		{
			log.debug("No picture for drop {}", name);
			return;
		}
		// The stack picture for the most that can drop: a pile of coins, a bundle of arrows
		final AsyncBufferedImage icon = itemManager.getImage(id, Drops.maxQuantity(item.quantity), false);
		if (icon == null)
		{
			return;
		}
		icon.onLoaded(() ->
		{
			item.icon = icon;
			l.changed();
		});
	}

	// Keys

	/**
	 * The card whose find bar is open, if any.
	 */
	private volatile PanelOverlay findCard;

	/**
	 * The card being searched with its find bar, or null when no find bar is open.
	 */
	private Lookup finding()
	{
		final PanelOverlay card = findCard;
		final Lookup l = card == null ? null : card.current();
		return l != null && l.isFinding() ? l : null;
	}

	/**
	 * The card the mouse is over, the one on top when they overlap, or null.
	 */
	private PanelOverlay cardUnderMouse()
	{
		final PanelOverlay top = front;
		if (top != null && top.current() != null && top.isUnderMouse())
		{
			return top;
		}
		for (int i = extras.size() - 1; i >= 0; i--)
		{
			final PanelOverlay card = extras.get(i);
			if (card.current() != null && card.isUnderMouse())
			{
				return card;
			}
		}
		return overlay.current() != null && overlay.isUnderMouse() ? overlay : null;
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
		final Lookup f = finding();
		if (f != null)
		{
			final char c = e.getKeyChar();
			if (c >= ' ' && c != KeyEvent.CHAR_UNDEFINED && c != 127)
			{
				f.setFind(f.getFind() + c);
			}
			e.consume();
			return;
		}
		if (!searchBox.isOpen())
		{
			return;
		}
		final char c = e.getKeyChar();
		if (c >= ' ' && c != KeyEvent.CHAR_UNDEFINED && c != 127)
		{
			searchBox.type(c);
			searchChanged();
		}
		// While the search box is open, typing goes to it and not the game
		e.consume();
	}

	/**
	 * Shift, Ctrl and Alt always reach the game. If the box kept a Ctrl release (after
	 * Ctrl+F, say), the game would think Ctrl was still held, and every click would walk
	 * instead of run.
	 */
	private static boolean modifier(KeyEvent e)
	{
		switch (e.getKeyCode())
		{
			case KeyEvent.VK_SHIFT:
			case KeyEvent.VK_CONTROL:
			case KeyEvent.VK_ALT:
			case KeyEvent.VK_ALT_GRAPH:
			case KeyEvent.VK_META:
				return true;
			default:
				return false;
		}
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		if (modifier(e))
		{
			return;
		}
		final Lookup f = finding();
		if (f != null)
		{
			findKey(f, e);
			e.consume();
			return;
		}
		if (searchBox.isOpen())
		{
			if (config.searchHotkey().matches(e))
			{
				searchBox.close();
				e.consume();
				return;
			}
			if (e.isControlDown())
			{
				switch (e.getKeyCode())
				{
					case KeyEvent.VK_A:
						searchBox.selectAll();
						break;
					case KeyEvent.VK_C:
						copy(searchBox.getText());
						break;
					case KeyEvent.VK_X:
						copy(searchBox.cut());
						searchChanged();
						break;
					case KeyEvent.VK_V:
						searchBox.paste(pasted());
						searchChanged();
						break;
					default:
						break;
				}
				e.consume();
				return;
			}
			switch (e.getKeyCode())
			{
				case KeyEvent.VK_ESCAPE:
					searchBox.close();
					break;
				case KeyEvent.VK_ENTER:
					chooseSearch();
					break;
				case KeyEvent.VK_BACK_SPACE:
					searchBox.backspace();
					searchChanged();
					break;
				case KeyEvent.VK_UP:
					searchBox.move(-1);
					break;
				case KeyEvent.VK_DOWN:
					searchBox.move(1);
					break;
				default:
					break;
			}
			e.consume();
			return;
		}
		if (config.searchHotkey().matches(e))
		{
			// Over a card, the hotkey finds words on that card instead of opening the search
			final PanelOverlay card = cardUnderMouse();
			if (card != null)
			{
				card.current().openFind();
				findCard = card;
			}
			else
			{
				openSearch();
			}
			e.consume();
			return;
		}
		if (e.getKeyCode() == KeyEvent.VK_ESCAPE && (lookup != null || !extras.isEmpty()))
		{
			close();
			closeExtras();
			e.consume();
		}
	}

	/**
	 * Puts a picture on the clipboard and says so in the chat.
	 */
	void copyImage(BufferedImage image, String name)
	{
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new ImageSelection(image), null);
			clientThread.invokeLater(() -> client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
				"WikiPeek: a picture of the " + name + " card has been copied. Paste it anywhere to share it.", null));
		}
		catch (IllegalStateException | SecurityException e)
		{
			log.debug("Clipboard unavailable", e);
		}
	}

	/**
	 * A picture on the clipboard.
	 */
	private static final class ImageSelection implements java.awt.datatransfer.Transferable
	{
		private final BufferedImage image;

		ImageSelection(BufferedImage image)
		{
			this.image = image;
		}

		@Override
		public DataFlavor[] getTransferDataFlavors()
		{
			return new DataFlavor[]{DataFlavor.imageFlavor};
		}

		@Override
		public boolean isDataFlavorSupported(DataFlavor flavor)
		{
			return DataFlavor.imageFlavor.equals(flavor);
		}

		@Override
		public Object getTransferData(DataFlavor flavor) throws UnsupportedFlavorException
		{
			if (!isDataFlavorSupported(flavor))
			{
				throw new UnsupportedFlavorException(flavor);
			}
			return image;
		}
	}

	private static void copy(String text)
	{
		if (text == null || text.isEmpty())
		{
			return;
		}
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(text), null);
		}
		catch (IllegalStateException | SecurityException e)
		{
			log.debug("Clipboard unavailable", e);
		}
	}

	private static String pasted()
	{
		try
		{
			Clipboard clipboard = Toolkit.getDefaultToolkit().getSystemClipboard();
			if (clipboard.isDataFlavorAvailable(DataFlavor.stringFlavor))
			{
				return (String) clipboard.getData(DataFlavor.stringFlavor);
			}
		}
		catch (IllegalStateException | SecurityException | UnsupportedFlavorException | IOException e)
		{
			log.debug("Clipboard unavailable", e);
		}
		return null;
	}

	/**
	 * A key pressed while a card's find bar is open.
	 */
	private void findKey(Lookup f, KeyEvent e)
	{
		final String text = f.getFind();
		if (config.searchHotkey().matches(e) || e.getKeyCode() == KeyEvent.VK_ESCAPE)
		{
			f.closeFind();
			findCard = null;
			return;
		}
		if (e.isControlDown())
		{
			switch (e.getKeyCode())
			{
				case KeyEvent.VK_V:
				{
					final String pasted = pasted();
					if (pasted != null)
					{
						f.setFind(text + pasted.replaceAll("\\s+", " "));
					}
					break;
				}
				case KeyEvent.VK_A:
				case KeyEvent.VK_BACK_SPACE:
					f.setFind("");
					break;
				case KeyEvent.VK_C:
					copy(text);
					break;
				default:
					break;
			}
			return;
		}
		switch (e.getKeyCode())
		{
			case KeyEvent.VK_ENTER:
			case KeyEvent.VK_F3:
				f.stepFind(e.isShiftDown() ? -1 : 1);
				break;
			case KeyEvent.VK_DOWN:
				f.stepFind(1);
				break;
			case KeyEvent.VK_UP:
				f.stepFind(-1);
				break;
			case KeyEvent.VK_BACK_SPACE:
				if (!text.isEmpty())
				{
					f.setFind(text.substring(0, text.length() - 1));
				}
				break;
			default:
				break;
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		if (finding() != null && !modifier(e))
		{
			e.consume();
			return;
		}
		if (searchBox.isOpen() && !modifier(e))
		{
			e.consume();
		}
	}
}

